def _inline_button_style(text: str) -> str:
    """Choose a native Telegram button color for every bot inline button."""
    value = text.casefold()
    if value.startswith("on:"):
        return "success"
    if value.startswith("off:"):
        return "danger"
    if any(word in value for word in (
        "dislike", "delete", "remove", "cancel", "clear", "ban", "mute",
        "kick", "danger", "report", "disable",
    )):
        return "danger"
    if any(word in value for word in (
        "like", "save", "add", "enable", "confirm", "your groups", "profile",
        "join", "preview", "back",
    )):
        return "success"
    return "primary"


def _clean_inline_button_text(text: str) -> str:
    """Keep inline labels text-only; Telegram emoji icons are intentionally disabled."""
    preserved_symbols = {"◉"}
    cleaned = "".join(
        char for char in text
        if char in preserved_symbols
        or unicodedata.category(char) not in {"So", "Sk"}
        and ord(char) not in {0xFE0E, 0xFE0F, 0x200D}
    )
    return " ".join(cleaned.split())


