def _resolve_button_custom_emoji_id(text: str, callback_data: str = "") -> str | None:
    t = text.strip().casefold()
    cb = callback_data.strip().casefold()
    if "back to main" in t or cb == "home":
        return "5416117059207572332"
    if "management" in t or cb == "group_management":
        return "5341715473882955310"
    if "report" in t:
        return "6266995104687330978"
    if "support" in t or cb.startswith("support_stars"):
        return "5267500801240092311"
    if "friends" in t or cb == "friends":
        return "6264720734820505831"
    if "updates" in t:
        return "6264510702329797113"
    if "profile" in t or cb == "profile":
        return "5395444784611480792"
    if "games" in t or cb == "games":
        return "5361741454685256344"
    if "leaderboard" in t or cb.startswith("leaderboard"):
        return "5440539497383087970"
    if t in _CUSTOM_BUTTON_EMOJI_IDS:
        return _CUSTOM_BUTTON_EMOJI_IDS[t]
    if cb == "store":
        return "5051235720279098750"
    if cb == "admin_panel":
        return "4958479549265347295"
    if cb.startswith("your_chats"):
        return "5282843764451195532"
    if cb.startswith("contest:"):
        return "5461151367559141950"
    return None


def InlineKeyboardButton(*args, **kwargs):
    """Keep button styling consistent across all menus and generated actions."""
    if "text" in kwargs:
        kwargs["text"] = _clean_inline_button_text(str(kwargs["text"]))
    if kwargs.get("pay"):
        kwargs["style"] = None
    else:
        raw_style = kwargs.get("style")
        if raw_style in ("none", "default"):
            kwargs["style"] = None
        elif raw_style is None:
            kwargs["style"] = _inline_button_style(str(kwargs.get("text", "")))
    if not kwargs.get("pay") and kwargs.get("icon_custom_emoji_id") is None:
        auto_emoji = _resolve_button_custom_emoji_id(
            str(kwargs.get("text", "")),
            str(kwargs.get("callback_data", "")),
        )
        if auto_emoji:
            kwargs["icon_custom_emoji_id"] = auto_emoji
    return TelegramInlineKeyboardButton(*args, **kwargs)


