# ─── Broadcast (Coupon Adda style) + Bot Stats ────────────────────────────────
sbc_waiting: set[int] = set()
sbc_storage: dict[int, tuple[int, int]] = {}


def _sbc_admin_cb(callback: CallbackQuery) -> bool:
    return bool(callback.from_user and callback.from_user.id in ADMIN_IDS
                and callback.message and callback.message.chat.type == ChatType.PRIVATE)


@router.callback_query(F.data == "sbc:open")
async def sbc_open(callback: CallbackQuery) -> None:
    if not _sbc_admin_cb(callback):
        await callback.answer("Private owner panel only.", show_alert=True); return
    sbc_waiting.add(callback.from_user.id)
    await callback.answer()
    await callback.message.answer(
        "📢 <b>Send broadcast message (text/photo/video):</b>", parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="❌ Cancel", callback_data="sbc:cancel", style="danger")]]))


def _sbc_filter(message: Message) -> bool:
    return bool(message.from_user and message.chat.type == ChatType.PRIVATE
                and message.from_user.id in sbc_waiting)


@router.message(_sbc_filter)
async def sbc_preview(message: Message) -> None:
    sbc_waiting.discard(message.from_user.id)
    if message.text and message.text.strip().casefold() == "/cancel":
        await message.answer("❌ <b>Broadcast Cancelled.</b>", parse_mode="HTML"); return
    sbc_storage[message.from_user.id] = (message.chat.id, message.message_id)
    await message.answer("❓ <b>Confirm broadcast to all users?</b>", parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(text="✅ Confirm", callback_data="sbc:confirm", style="success"),
            InlineKeyboardButton(text="❌ Cancel", callback_data="sbc:cancel", style="danger")]]))


@router.callback_query(F.data == "sbc:cancel")
async def sbc_cancel(callback: CallbackQuery) -> None:
    sbc_waiting.discard(callback.from_user.id)
    sbc_storage.pop(callback.from_user.id, None)
    await callback.answer()
    try:
        await callback.message.edit_text("❌ <b>Broadcast Cancelled.</b>", parse_mode="HTML")
    except TelegramBadRequest:
        pass


@router.callback_query(F.data == "sbc:confirm")
async def sbc_confirm(callback: CallbackQuery) -> None:
    if not _sbc_admin_cb(callback):
        await callback.answer("Private owner panel only.", show_alert=True); return
    src = sbc_storage.pop(callback.from_user.id, None)
    if not src:
        await callback.answer("❌ No message found.", show_alert=True); return
    await callback.answer()
    status = await callback.message.edit_text("🚀 <b>Broadcasting…</b>", parse_mode="HTML")
    rows = await db.execute_fetchall("SELECT user_id FROM users ORDER BY user_id")
    uids = [int(r["user_id"]) for r in rows]
    total = len(uids); success = skip = 0
    sem = asyncio.Semaphore(25); lk = asyncio.Lock()

    async def _send(uid: int) -> None:
        nonlocal success, skip
        async with sem:
            try:
                await bot.copy_message(uid, src[0], src[1])
                async with lk: success += 1
            except Exception:
                async with lk: skip += 1

    for i in range(0, total, 100):
        await asyncio.gather(*[_send(u) for u in uids[i:i + 100]])
        try:
            await status.edit_text(f"🚀 <b>Broadcasting…</b>\n✅ Sent: {success}/{total}\n⛔ Skipped: {skip}", parse_mode="HTML")
        except Exception:
            pass
    await bot.send_message(callback.message.chat.id,
        f"✅ <b>Broadcast Done!</b>\n✅ Sent: {success}\n⛔ Skipped (blocked/inactive): {skip}", parse_mode="HTML")


@router.callback_query(F.data == "sst:open")
async def sst_open(callback: CallbackQuery) -> None:
    if not _sbc_admin_cb(callback):
        await callback.answer("Private owner panel only.", show_alert=True); return
    await callback.answer()
    r = (await db.execute_fetchall(
        "SELECT COUNT(*) total, COALESCE(SUM(seyu_gems),0) gems, "
        "COALESCE(SUM(CASE WHEN seyu_gems>0 THEN 1 ELSE 0 END),0) holders FROM users"))[0]
    await callback.message.answer(
        "📊 <b>Bot Stats</b>\n\n"
        f"👥 Total Users: <b>{int(r['total']):,}</b>\n"
        f"💎 Total Seyu Gems (all users): <b>{int(r['gems']):,}</b>\n"
        f"🧑‍💼 Users with Gems: <b>{int(r['holders']):,}</b>",
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="🔄 Refresh", callback_data="sst:open")]]))


