class ComprehensiveAuditMiddleware(BaseMiddleware):
    """Detailed tracking for user messages, commands, start clicks, and buttons."""

    async def __call__(self, handler, event, data):
        if isinstance(event, Message):
            c = event.chat
            if event.from_user and event.from_user.username:
                u_clean = event.from_user.username.casefold()
                username_to_user_id[u_clean] = event.from_user.id
                if c.type in {ChatType.GROUP, ChatType.SUPERGROUP}:
                    group_username_to_user_id[(c.id, u_clean)] = event.from_user.id

            if c.type in {ChatType.GROUP, ChatType.SUPERGROUP}:
                if event.from_user and not event.from_user.is_bot:
                    last_user_message_id[(c.id, event.from_user.id)] = event.message_id
                text_preview = (event.text or event.caption or "").strip()
                text_lower = text_preview.lower()
                is_directed = (
                    text_preview.startswith("/")
                    or text_preview.startswith("!")
                    or (bot_username and f"@{bot_username.lower()}" in text_lower)
                    or "seyuki" in text_lower
                    or "destroyer" in text_lower
                    or (
                        event.reply_to_message
                        and event.reply_to_message.from_user
                        and event.reply_to_message.from_user.id == bot.id
                    )
                )
                if not is_directed:
                    return await handler(event, data)

            start_time = time.monotonic()
            u = event.from_user
            user_str = "Unknown"
            if u:
                uname = f"@{u.username} " if u.username else ""
                user_str = f"{uname}(ID: {u.id}, Name: {u.first_name})"
            chat_str = f"{c.type}:{c.id}" + (f" ({c.title})" if c.title else "")
            text_preview = (event.text or event.caption or "").strip()
            if not text_preview:
                if event.photo:
                    text_preview = "[Photo]"
                elif event.video:
                    text_preview = "[Video]"
                elif event.voice:
                    text_preview = "[Voice]"
                elif event.sticker:
                    text_preview = "[Sticker]"
                else:
                    text_preview = f"[{getattr(event, 'content_type', 'Media')}]"
            action_str = f"MSG: {text_preview}"
            log.info("📩 [USER MSG] From: %s | Chat: %s | Text: '%s'", user_str, chat_str, text_preview[:120])
            try:
                result = await handler(event, data)
                elapsed = time.monotonic() - start_time
                if elapsed > 1.5:
                    log.warning("⚠️ [DELAY WARNING] %s took %.2fs! | User: %s", action_str[:60], elapsed, user_str)
                else:
                    log.info("⚡ [HANDLED] %s done in %.3fs", action_str[:60], elapsed)
                return result
            except Exception as exc:
                elapsed = time.monotonic() - start_time
                log.exception("❌ [HANDLER ERROR] %s failed after %.2fs: %s (%s)", action_str[:60], elapsed, type(exc).__name__, exc)
                raise

        elif isinstance(event, CallbackQuery):
            start_time = time.monotonic()
            u = event.from_user
            user_str = "Unknown"
            chat_str = "Unknown"
            if u:
                uname = f"@{u.username} " if u.username else ""
                user_str = f"{uname}(ID: {u.id}, Name: {u.first_name})"
            if event.message and event.message.chat:
                c = event.message.chat
                chat_str = f"{c.type}:{c.id}" + (f" ({c.title})" if c.title else "")
            data_val = event.data or "empty"
            action_str = f"BTN: {data_val}"
            log.info("🔘 [BUTTON CLICK] From: %s | Chat: %s | Data: '%s'", user_str, chat_str, data_val)
            try:
                result = await handler(event, data)
                elapsed = time.monotonic() - start_time
                if elapsed > 1.5:
                    log.warning("⚠️ [DELAY WARNING] %s took %.2fs! | User: %s", action_str[:60], elapsed, user_str)
                else:
                    log.info("⚡ [HANDLED] %s done in %.3fs", action_str[:60], elapsed)
                return result
            except Exception as exc:
                elapsed = time.monotonic() - start_time
                log.exception("❌ [HANDLER ERROR] %s failed after %.2fs: %s (%s)", action_str[:60], elapsed, type(exc).__name__, exc)
                raise

        return await handler(event, data)


router.message.outer_middleware(ComprehensiveAuditMiddleware())
router.callback_query.outer_middleware(ComprehensiveAuditMiddleware())

