def load_music_autoplay_settings() -> dict[int, bool]:
    res = defaultdict(lambda: True)
    try:
        if AUTOPLAY_SETTINGS_FILE.is_file():
            import json
            data = json.loads(AUTOPLAY_SETTINGS_FILE.read_text(encoding="utf-8"))
            for k, v in data.items():
                res[int(k)] = bool(v)
    except Exception:
        pass
    return res


def save_music_autoplay_settings() -> None:
    try:
        import json
        AUTOPLAY_SETTINGS_FILE.parent.mkdir(parents=True, exist_ok=True)
        data = {str(k): bool(v) for k, v in music_autoplay.items()}
        AUTOPLAY_SETTINGS_FILE.write_text(json.dumps(data), encoding="utf-8")
    except Exception:
        pass


