async def ensure_surprise_gift_schema() -> None:
    await db.executescript(
        """
        CREATE TABLE IF NOT EXISTS surprise_gifts(
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          access_code TEXT NOT NULL UNIQUE,
          target_chat_ids TEXT NOT NULL,
          target_user_id INTEGER NOT NULL,
          target_username TEXT NOT NULL DEFAULT '',
          message_text TEXT NOT NULL DEFAULT '',
          media_type TEXT,
          media_file_id TEXT,
          media_caption TEXT NOT NULL DEFAULT '',
          is_claimed INTEGER NOT NULL DEFAULT 0,
          claimed_by INTEGER,
          claimed_at TEXT,
          sent_message_ids TEXT DEFAULT '{}',
          created_at TEXT NOT NULL
        );
        CREATE INDEX IF NOT EXISTS idx_surprise_gifts_code ON surprise_gifts(access_code);
        CREATE INDEX IF NOT EXISTS idx_surprise_gifts_user ON surprise_gifts(target_user_id);
        CREATE TABLE IF NOT EXISTS surprise_presets(
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          preset_name TEXT NOT NULL DEFAULT '',
          target_user_id INTEGER NOT NULL,
          target_username TEXT NOT NULL DEFAULT '',
          target_chat_ids TEXT NOT NULL DEFAULT '[]',
          message_text TEXT NOT NULL DEFAULT '',
          media_type TEXT,
          media_file_id TEXT,
          media_caption TEXT NOT NULL DEFAULT '',
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL
        );
        """
    )
    await db.commit()


async def ensure_contest_schema() -> None:
    await db.executescript(
        """
        CREATE TABLE IF NOT EXISTS contests(
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          code TEXT NOT NULL UNIQUE,
          created_by INTEGER NOT NULL,
          duration_minutes INTEGER NOT NULL,
          created_at INTEGER NOT NULL,
          expires_at INTEGER NOT NULL,
          status TEXT NOT NULL DEFAULT 'active'
            CHECK(status IN ('active', 'expired', 'announced')),
          winner_count INTEGER,
          announced_at INTEGER
        );
        CREATE INDEX IF NOT EXISTS contests_status_expiry_idx
          ON contests(status, expires_at);
        CREATE TABLE IF NOT EXISTS contest_participants(
          contest_id INTEGER NOT NULL,
          user_id INTEGER NOT NULL,
          first_name TEXT NOT NULL DEFAULT '',
          username TEXT NOT NULL DEFAULT '',
          joined_at INTEGER NOT NULL,
          PRIMARY KEY(contest_id, user_id)
        );
        CREATE INDEX IF NOT EXISTS contest_participants_contest_idx
          ON contest_participants(contest_id, joined_at, user_id);
        CREATE TABLE IF NOT EXISTS contest_winners(
          contest_id INTEGER NOT NULL,
          user_id INTEGER NOT NULL,
          winner_rank INTEGER NOT NULL,
          announced_at INTEGER NOT NULL,
          PRIMARY KEY(contest_id, user_id)
        );
        CREATE INDEX IF NOT EXISTS contest_winners_contest_idx
          ON contest_winners(contest_id, winner_rank);
        CREATE TABLE IF NOT EXISTS ai_trainers(
          user_id INTEGER PRIMARY KEY,
          username TEXT NOT NULL DEFAULT '',
          first_name TEXT NOT NULL DEFAULT '',
          added_by INTEGER NOT NULL DEFAULT 0,
          added_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
        );
        CREATE TABLE IF NOT EXISTS ai_trainer_rules(
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          trainer_user_id INTEGER NOT NULL,
          rule_type TEXT NOT NULL DEFAULT 'rule',
          trigger_text TEXT NOT NULL DEFAULT '',
          response_text TEXT NOT NULL DEFAULT '',
          raw_instruction TEXT NOT NULL DEFAULT '',
          created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
          expires_at TEXT NOT NULL
        );
        CREATE INDEX IF NOT EXISTS idx_ai_trainer_rules_uid ON ai_trainer_rules(trainer_user_id);
        CREATE INDEX IF NOT EXISTS idx_ai_trainer_rules_exp ON ai_trainer_rules(expires_at);
        """
    )
    await db.commit()


async def contest_db_fetchone(
    query: str, params: tuple[object, ...] = ()
) -> aiosqlite.Row | None:
    cursor = await db.execute(query, params)
    return await cursor.fetchone()


def contest_time_label(timestamp: int | float | None) -> str:
    if not timestamp:
        return "unknown"
    return datetime.fromtimestamp(
        float(timestamp), tz=ZoneInfo("Asia/Kolkata")
    ).strftime("%d %b %Y, %I:%M %p")


def contest_remaining_label(expires_at: int | float) -> str:
    seconds = max(0, int(float(expires_at) - time.time()))
    minutes, seconds = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)
    if hours:
        return f"{hours}h {minutes}m"
    if minutes:
        return f"{minutes}m {seconds}s"
    return f"{seconds}s"


def normalize_contest_code(value: str) -> str:
    return re.sub(r"[^A-Z0-9]", "", value.upper())


def mask_contest_value(value: str) -> str:
    clean = str(value or "").strip()
    if not clean:
        return "hidden"
    if len(clean) <= 4:
        return f"{clean[:1]}***"
    return f"{clean[:2]}***{clean[-2:]}"


