async def create_contest(created_by: int, duration_minutes: int) -> tuple[int, str]:
    duration_minutes = max(1, min(10080, int(duration_minutes)))
    now = int(time.time())
    for _ in range(8):
        code = f"SYK{secrets.token_hex(4).upper()}"
        try:
            cursor = await db.execute(
                """INSERT INTO contests(
                     code, created_by, duration_minutes, created_at, expires_at
                   ) VALUES(?,?,?,?,?)""",
                (code, created_by, duration_minutes, now, now + duration_minutes * 60),
            )
            await db.commit()
            return int(cursor.lastrowid), code
        except Exception as error:
            if "UNIQUE" not in str(error).upper():
                raise
    raise RuntimeError("Could not generate a unique contest code.")


async def contest_participant_count(contest_id: int) -> int:
    row = await contest_db_fetchone(
        "SELECT COUNT(*) AS count FROM contest_participants WHERE contest_id=?",
        (contest_id,),
    )
    return int(row["count"] or 0)


async def expire_contest(contest_id: int, notify: bool = True) -> bool:
    async with contest_locks[contest_id]:
        row = await contest_db_fetchone(
            "SELECT * FROM contests WHERE id=?", (contest_id,)
        )
        if not row or row["status"] != "active":
            return False
        if int(row["expires_at"]) > int(time.time()):
            return False
        await db.execute(
            "UPDATE contests SET status='expired' WHERE id=? AND status='active'",
            (contest_id,),
        )
        await db.commit()
    if notify:
        count = await contest_participant_count(contest_id)
        try:
            await bot.send_message(
                int(row["created_by"]),
                f"<b>Contest expired</b>\n\n"
                f"Code: <code>{html.escape(str(row['code']))}</code>\n"
                f"Joined users: <b>{count:,}</b>\n\n"
                "Choose how many winners to announce.",
                reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                    [InlineKeyboardButton(
                        text="Select Winners",
                        callback_data=f"contest:select:{contest_id}",
                        style="primary",
                    )],
                    [InlineKeyboardButton(
                        text="Download User List",
                        callback_data=f"contest:export:{contest_id}",
                    )],
                    [InlineKeyboardButton(
                        text="Contest Admin Panel",
                        callback_data="contest:admin_panel",
                    )],
                ]),
            )
        except (TelegramBadRequest, TelegramForbiddenError):
            log.info("Contest expiry notification could not reach admin %s", row["created_by"])
    return True


async def purge_old_contests() -> int:
    cutoff = int(time.time()) - CONTEST_RETENTION_SECONDS
    async with contest_cleanup_lock:
        old_contests = await db.execute_fetchall(
            """SELECT id FROM contests
               WHERE status!='active'
                 AND COALESCE(announced_at, expires_at, created_at)<=?""",
            (cutoff,),
        )
        if not old_contests:
            return 0
        await db.execute(
            """DELETE FROM contest_winners
               WHERE contest_id IN (
                 SELECT id FROM contests
                 WHERE status!='active'
                   AND COALESCE(announced_at, expires_at, created_at)<=?
               )""",
            (cutoff,),
        )
        await db.execute(
            """DELETE FROM contest_participants
               WHERE contest_id IN (
                 SELECT id FROM contests
                 WHERE status!='active'
                   AND COALESCE(announced_at, expires_at, created_at)<=?
               )""",
            (cutoff,),
        )
        await db.execute(
            """DELETE FROM contests
               WHERE status!='active'
                 AND COALESCE(announced_at, expires_at, created_at)<=?""",
            (cutoff,),
        )
        await db.commit()
    removed = len(old_contests)
    log.info("Purged %s contest record(s) older than 24 hours", removed)
    return removed


async def contest_expiry_loop() -> None:
    while True:
        await asyncio.sleep(30)
        try:
            rows = await db.execute_fetchall(
                "SELECT id FROM contests WHERE status='active' AND expires_at<=?",
                (int(time.time()),),
            )
            for row in rows:
                await expire_contest(int(row["id"]))
            await purge_old_contests()
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("Contest expiry sweep failed")


async def contest_admin_panel_text() -> str:
    await purge_old_contests()
    rows = await db.execute_fetchall(
        """SELECT c.*, COUNT(cp.user_id) AS participant_count
           FROM contests AS c
           LEFT JOIN contest_participants AS cp ON cp.contest_id=c.id
           GROUP BY c.id
           ORDER BY c.id DESC
           LIMIT 20"""
    )
    if not rows:
        return "<b>Contest Management</b>\n\nNo contests have been created yet."
    lines = ["<b>Contest Management</b>", ""]
    for row in rows:
        status = str(row["status"]).title()
        if row["status"] == "active":
            if int(row["expires_at"]) <= int(time.time()):
                await expire_contest(int(row["id"]), notify=False)
                status = "Expired"
            else:
                status = f"Active — {contest_remaining_label(row['expires_at'])} left"
        lines.append(
            f"<b>{html.escape(str(row['code']))}</b> — {status}\n"
            f"Joined: <b>{int(row['participant_count']):,}</b> | "
            f"Expires: {contest_time_label(row['expires_at'])}"
        )
    return "\n".join(lines)


