async def add_nextgen_key(value: str) -> bool:
    if not credential_storage_available():
        raise RuntimeError(
            "Set the SESSION_SECRET Replit Secret before storing credentials."
        )
    if any(item["value"] == value for item in nextgen_key_pool):
        return False
    cursor = await db.execute(
        "INSERT INTO nextgen_api_keys(ciphertext) VALUES(?)",
        (encrypt_credential(value),),
    )
    await db.commit()
    nextgen_key_pool.append({
        "id": int(cursor.lastrowid),
        "value": value,
        "enabled": True,
        "failure_count": 0,
        "cooldown_until": 0.0,
        "last_error": "",
        "source": "Encrypted Admin Panel",
    })
    return True


async def update_nextgen_key_health(
    key: dict[str, object],
    *,
    success: bool,
    reason: str = "",
) -> None:
    if key.get("id") is None:
        if success:
            key["failure_count"] = 0
            key["last_error"] = ""
        elif mongo_limit_error(reason):
            schedule_admin_alert(
                "nextgen-limit:secret",
                "NextGen API quota or rate limit detected for the key from "
                "Replit Secrets. The key is temporarily unavailable; check the "
                "NextGen provider before relying on it again.",
            )
        return
    if success:
        failures = 0
        cooldown_until = 0.0
        safe_reason = ""
    else:
        failures = int(key.get("failure_count", 0)) + 1
        cooldown_until = time.monotonic() + min(900, 30 * failures)
        safe_reason = reason[:80]
    key["failure_count"] = failures
    key["cooldown_until"] = cooldown_until
    key["last_error"] = safe_reason
    await db.execute(
        """UPDATE nextgen_api_keys SET failure_count=?, cooldown_until=?,
        last_error=?, updated_at=CURRENT_TIMESTAMP WHERE id=?""",
        (failures, cooldown_until, safe_reason, int(key["id"])),
    )
    await db.commit()
    if not success and mongo_limit_error(reason):
        enabled = sum(1 for item in nextgen_key_pool if item.get("enabled"))
        cooling = sum(
            1 for item in nextgen_key_pool
            if item.get("enabled")
            and float(item.get("cooldown_until", 0)) > time.monotonic()
        )
        schedule_admin_alert(
            f"nextgen-limit:{key.get('id') or 'secret'}",
            f"NextGen API limit detected for key "
            f"{'#' + str(key.get('id')) if key.get('id') is not None else 'from Replit Secrets'}. "
            f"The key is cooling down. {cooling}/{enabled} enabled keys are cooling down.",
        )


def nextgen_candidate_keys() -> list[dict[str, object]]:
    now = time.monotonic()
    return [
        item for item in nextgen_key_pool
        if bool(item.get("enabled")) and float(item.get("cooldown_until", 0)) <= now
    ]


RUNTIME_DEFAULTS: dict[str, object] = {
    "openrouter_model": MODEL,
    "gemini_model": GEMINI_MODEL,
    "provider_order": PROVIDER_ORDER,
    "provider_fallbacks": True,
    "chat_mode": True,
    "ai_sticker_percent": 5,
    "global_custom_commands": "{}",
    "daily_zone_template_path": str(DAILY_ZONE_TEMPLATE_PATH),
    "music_template_path": str(MUSIC_TEMPLATE_DEFAULT_PATH),
}


async def load_runtime_settings() -> None:
    runtime_settings.clear()
    runtime_settings.update(RUNTIME_DEFAULTS)
    rows = await db.execute_fetchall("SELECT key, value FROM runtime_settings")
    for row in rows:
        key = str(row["key"])
        if key not in RUNTIME_DEFAULTS:
            continue
        if isinstance(RUNTIME_DEFAULTS[key], bool):
            runtime_settings[key] = str(row["value"]) == "1"
        elif isinstance(RUNTIME_DEFAULTS[key], int):
            try:
                runtime_settings[key] = int(row["value"])
            except ValueError:
                continue
        else:
            runtime_settings[key] = str(row["value"])
    if not str(runtime_settings.get("daily_zone_template_path", "") or "").strip():
        runtime_settings["daily_zone_template_path"] = str(DAILY_ZONE_TEMPLATE_PATH)


def validate_runtime_setting(key: str, value: str) -> object:
    value = value.strip()
    if key == "openrouter_model":
        if (
            not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]*/[A-Za-z0-9][A-Za-z0-9._:+-]*", value)
            or ".." in value
            or len(value) > 120
        ):
            raise ValueError("Model must be a provider/model identifier (maximum 120 characters).")
        return value
    if key == "gemini_model":
        if (
            not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]*", value)
            or ".." in value
            or len(value) > 100
        ):
            raise ValueError("Gemini model must be a public model identifier.")
        return value
    if key == "provider_order":
        if not value:
            return ""
        providers = [item.strip() for item in value.split(",") if item.strip()]
        if not providers or len(providers) > 8:
            raise ValueError("Enter 1 to 8 provider names separated by commas, or blank to clear.")
        if any(
            len(provider) > 64
            or not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9 ._-]*", provider)
            for provider in providers
        ):
            raise ValueError(
                "Provider names may use letters, numbers, spaces, dot, underscore, and hyphen."
            )
        return ",".join(dict.fromkeys(providers))
    if key in {"provider_fallbacks", "chat_mode"}:
        if value.casefold() not in {"0", "1", "on", "off", "true", "false"}:
            raise ValueError("Value must be on or off.")
        return value.casefold() in {"1", "on", "true"}
    if key == "ai_sticker_percent":
        if not value.isdigit() or not 0 <= int(value) <= 100:
            raise ValueError("Sticker percentage must be from 0 to 100.")
        return int(value)
    raise ValueError("This setting is not editable.")


async def set_runtime_setting(key: str, value: object) -> None:
    if key not in RUNTIME_DEFAULTS:
        raise ValueError("This setting is not editable.")
    stored = "1" if isinstance(value, bool) and value else "0" if isinstance(value, bool) else str(value)
    await db.execute(
        """INSERT INTO runtime_settings(key, value) VALUES(?,?)
        ON CONFLICT(key) DO UPDATE SET value=excluded.value, updated_at=CURRENT_TIMESTAMP""",
        (key, stored),
    )
    await db.commit()
    runtime_settings[key] = value


async def discover_voice_assistants() -> None:
    legacy = Path("./data/seyuki_user.session")
    managed = VOICE_SESSION_DIRECTORY / "seyuki_user.session"
    if legacy.exists() and not managed.exists():
        VOICE_SESSION_DIRECTORY.mkdir(parents=True, exist_ok=True)
        for legacy_file in legacy.parent.glob("seyuki_user.session*"):
            suffix = legacy_file.name.removeprefix("seyuki_user")
            legacy_file.replace(VOICE_SESSION_DIRECTORY / f"seyuki_user{suffix}")
    VOICE_SESSION_DIRECTORY.mkdir(parents=True, exist_ok=True)
    session_files = sorted(VOICE_SESSION_DIRECTORY.glob("*.session"))
    for session_file in session_files:
        basename = session_file.stem
        if not re.fullmatch(r"[a-z0-9][a-z0-9_-]{2,63}", basename):
            log.warning("Ignoring unsafe voice session filename: %s", session_file.name)
            continue
        default_name = "Default assistant" if basename == "seyuki_user" else "Voice assistant"
        await db.execute(
            """INSERT OR IGNORE INTO voice_assistants
            (session_basename, display_name, priority) VALUES(?,?,?)""",
            (basename, default_name, 10 if basename == "seyuki_user" else 100),
        )
    await db.commit()


async def discover_default_voice_assistant() -> None:
    """Compatibility wrapper for startup callers from older deployments."""
    await discover_voice_assistants()


def assistant_session_path(basename: str) -> Path:
    if not re.fullmatch(r"[a-z0-9][a-z0-9_-]{2,63}", basename):
        raise ValueError("Invalid internally generated session name.")
    managed = (VOICE_SESSION_DIRECTORY / basename).resolve()
    root = VOICE_SESSION_DIRECTORY.resolve()
    if managed.parent != root:
        raise ValueError("Session path escaped the managed directory.")
    return managed


def _write_users_json() -> None:
    path = Path(USERS_JSON_PATH)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(".json.tmp")
    temporary.write_text(
        json.dumps(users_json, ensure_ascii=False, indent=2, sort_keys=True),
        encoding="utf-8",
    )
    temporary.replace(path)


async def save_users_json() -> None:
    async with users_json_lock:
        await asyncio.to_thread(_write_users_json)


def _write_pending_sticker(
    content_hash: str,
    pending: tuple[bytes, int, str, str | None],
    reference: tuple[int, int],
) -> None:
    PENDING_STICKER_DIR.mkdir(parents=True, exist_ok=True)
    sticker_path = PENDING_STICKER_DIR / f"{content_hash}.webp"
    metadata_path = PENDING_STICKER_DIR / f"{content_hash}.json"
    sticker_path.write_bytes(pending[0])
    metadata_path.write_text(
        json.dumps({
            "user_id": pending[1],
            "first_name": pending[2],
            "username": pending[3],
            "chat_id": reference[0],
            "message_id": reference[1],
        }, ensure_ascii=False),
        encoding="utf-8",
    )


async def persist_pending_sticker(
    content_hash: str,
    pending: tuple[bytes, int, str, str | None],
    reference: tuple[int, int],
) -> None:
    await asyncio.to_thread(_write_pending_sticker, content_hash, pending, reference)


def _read_pending_sticker(
    content_hash: str,
) -> tuple[tuple[bytes, int, str, str | None], tuple[int, int]] | None:
    try:
        metadata = json.loads(
            (PENDING_STICKER_DIR / f"{content_hash}.json").read_text(encoding="utf-8")
        )
        sticker_bytes = (PENDING_STICKER_DIR / f"{content_hash}.webp").read_bytes()
        pending = (
            sticker_bytes,
            int(metadata["user_id"]),
            str(metadata.get("first_name") or "User"),
            metadata.get("username"),
        )
        return pending, (int(metadata["chat_id"]), int(metadata["message_id"]))
    except (OSError, KeyError, TypeError, ValueError, json.JSONDecodeError):
        return None


async def restore_pending_sticker(
    content_hash: str,
) -> tuple[tuple[bytes, int, str, str | None], tuple[int, int]] | None:
    return await asyncio.to_thread(_read_pending_sticker, content_hash)


def _delete_pending_sticker_files(content_hash: str) -> None:
    for suffix in (".webp", ".json"):
        try:
            (PENDING_STICKER_DIR / f"{content_hash}{suffix}").unlink()
        except FileNotFoundError:
            pass


async def delete_pending_sticker_files(content_hash: str) -> None:
    await asyncio.to_thread(_delete_pending_sticker_files, content_hash)


async def load_users_json() -> None:
    global users_json
    path = Path(USERS_JSON_PATH)
    if path.exists():
        try:
            loaded = json.loads(path.read_text(encoding="utf-8"))
            if isinstance(loaded, dict):
                users_json = {
                    str(user_id): data
                    for user_id, data in loaded.items()
                    if isinstance(data, dict)
                }
        except (OSError, json.JSONDecodeError) as error:
            log.warning("users.json could not be loaded: %s", type(error).__name__)
    # Restore any users/profiles missing from the SQLite file after an update.
    for user_id, record in users_json.items():
        await db.execute(
            """INSERT INTO users(user_id, first_name, username, blocked)
            VALUES(?,?,?,?) ON CONFLICT(user_id) DO NOTHING""",
            (
                int(user_id),
                str(record.get("first_name") or ""),
                str(record.get("username") or ""),
                int(bool(record.get("blocked"))),
            ),
        )
        if any(record.get(field) is not None for field in ("custom_name", "age", "gender")):
            await db.execute(
                """INSERT INTO profiles(user_id, custom_name, age, gender)
                VALUES(?,?,?,?) ON CONFLICT(user_id) DO NOTHING""",
                (
                    int(user_id),
                    record.get("custom_name"),
                    record.get("age"),
                    record.get("gender"),
                ),
            )
    cursor = await db.execute(
        """SELECT u.user_id, u.first_name, u.username, u.blocked,
        p.custom_name, p.age, p.gender FROM users u
        LEFT JOIN profiles p ON p.user_id=u.user_id"""
    )
    for row in await cursor.fetchall():
        users_json[str(row["user_id"])] = {
            "user_id": row["user_id"],
            "first_name": row["first_name"],
            "username": row["username"],
            "blocked": bool(row["blocked"]),
            "custom_name": row["custom_name"],
            "age": row["age"],
            "gender": row["gender"],
        }
    await db.commit()
    await save_users_json()


async def remember_user(message: Message) -> None:
    if not message.from_user:
        return
    user_id = message.from_user.id
    first_name = message.from_user.full_name or message.from_user.first_name
    username = message.from_user.username or ""
    now = time.monotonic()
    cached = user_seen_cache.get(user_id)
    if (
        cached
        and now - cached[0] < 60
        and cached[1] == first_name
        and cached[2] == username
    ):
        return
    user_seen_cache[user_id] = (now, first_name, username)
    if len(user_seen_cache) > 60000:
        cutoff = now - 60
        for cached_user_id, cached_value in tuple(user_seen_cache.items()):
            if cached_value[0] < cutoff:
                user_seen_cache.pop(cached_user_id, None)
    await db.execute(
        """INSERT INTO users(user_id, first_name, username) VALUES(?,?,?)
        ON CONFLICT(user_id) DO UPDATE SET first_name=excluded.first_name,
        username=excluded.username, last_seen_at=CURRENT_TIMESTAMP""",
        (
            user_id,
            first_name,
            username,
        ),
    )
    await db.commit()
    user_profile_cache.pop(user_id, None)
    record = users_json.setdefault(str(user_id), {})
    new_values = {
        "user_id": user_id,
        "first_name": first_name,
        "username": username,
        "blocked": bool(record.get("blocked", False)),
        "custom_name": record.get("custom_name"),
        "age": record.get("age"),
        "gender": record.get("gender"),
    }
    if record != new_values:
        users_json[str(user_id)] = new_values
        # SQLite is the live source of truth for normal activity. Avoid
        # rewriting the complete users.json file for every new user; the
        # compatibility mirror is rebuilt during startup and still persists
        # immediately for profile/blocking changes.


group_admin_cache: dict[int, tuple[bool, float]] = {}
GROUP_ADMIN_CACHE_TTL = 600.0


async def bot_is_group_admin(chat_id: int) -> bool:
    """Return True when the bot is currently an admin of the group (cached)."""
    now = time.time()
    cached = group_admin_cache.get(chat_id)
    if cached is not None and now - cached[1] < GROUP_ADMIN_CACHE_TTL:
        return cached[0]
    try:
        member = await bot.get_chat_member(chat_id, bot.id)
        is_admin = member.status in {
            ChatMemberStatus.ADMINISTRATOR,
            ChatMemberStatus.CREATOR,
        }
    except Exception:
        is_admin = False
    group_admin_cache[chat_id] = (is_admin, now)
    return is_admin


