@router.my_chat_member()
async def bot_group_membership_changed(event: ChatMemberUpdated) -> None:
    if event.chat.type not in {ChatType.GROUP, ChatType.SUPERGROUP}:
        return
    bot_member_cache.pop(event.chat.id, None)
    for cache_key in tuple(group_admin_cache):
        cid = cache_key[0] if isinstance(cache_key, tuple) else cache_key
        if cid == event.chat.id:
            group_admin_cache.pop(cache_key, None)
    status = event.new_chat_member.status
    if status in {"administrator", "creator"}:
        await remember_group_chat(event.chat.id, event.chat.title, event.chat.username)
        await db.execute(
            """UPDATE managed_groups
               SET admin_since=COALESCE(admin_since, CURRENT_TIMESTAMP)
               WHERE chat_id=?""",
            (event.chat.id,),
        )
        await db.commit()
        log.info("Registered managed group %s (%s)", event.chat.id, event.chat.title)
    elif status in {"left", "kicked"}:
        await db.execute("DELETE FROM managed_groups WHERE chat_id=?", (event.chat.id,))
        await db.commit()


async def group_admin(chat_id: int, user_id: int) -> bool:
    cache_key = (chat_id, user_id)
    cached = group_admin_cache.get(cache_key)
    if cached and time.monotonic() - cached[0] < GROUP_PERMISSION_CACHE_SECONDS:
        return cached[1]
    try:
        member = await bot.get_chat_member(chat_id, user_id)
        result = member.status in {"creator", "administrator"}
        group_admin_cache[cache_key] = (time.monotonic(), result)
        return result
    except TelegramBadRequest:
        group_admin_cache[cache_key] = (time.monotonic(), False)
        return False


async def group_menu_callback_allowed(callback: CallbackQuery) -> bool:
    """Only group admins/owners may use the menu opened from group /start."""
    message = callback.message
    if not message:
        return True
    if message.chat.type in {ChatType.GROUP, ChatType.SUPERGROUP}:
        leaderboard_callback = str(callback.data or "").startswith("leaderboard")
        if (
            not leaderboard_callback
            and callback.from_user.id not in ADMIN_IDS
            and not await group_admin(
            message.chat.id, callback.from_user.id
            )
        ):
            await callback.answer(
                "Only group admins and the bot owner can use this menu.",
                show_alert=True,
            )
            return False
    # Main-menu callbacks historically edit a text message directly. The
    # welcome/main surface is now often a photo, so proxy that same edit flow
    # onto the media caption instead of breaking every nested button.
    if is_menu_media_message(message):
        object.__setattr__(callback, "message", MenuMessageProxy(message))
    return True


