async def music_auth_enabled(chat_id: int) -> bool:
    cursor = await db.execute(
        "SELECT music_auth_enabled FROM group_settings WHERE chat_id=?",
        (chat_id,),
    )
    row = await cursor.fetchone()
    return bool(row and row["music_auth_enabled"])


async def music_action_allowed_for_user(chat_id: int, user_id: int) -> bool:
    # Group admins and bot owners always retain control. Regular users only
    # gain music access when an admin explicitly enables authorization mode
    # and authorizes them for this group.
    if user_id in ADMIN_IDS:
        return True
    if await group_admin(chat_id, user_id):
        return True
    return await music_auth_enabled(chat_id) and await music_user_authorized(
        chat_id,
        user_id,
    )


async def resolve_music_auth_target(
    message: Message,
    raw_target: str | None,
) -> tuple[int, str, str]:
    target_user = getattr(message.reply_to_message, "from_user", None)
    target_text = (raw_target or "").strip()
    if target_user is None and target_text:
        if target_text.startswith("@"):
            target_text = target_text[1:]
        if target_text.isdigit():
            try:
                member = await bot.get_chat_member(
                    message.chat.id,
                    int(target_text),
                )
                target_user = member.user
            except (TelegramBadRequest, TelegramForbiddenError) as error:
                raise ValueError("That user is not a member of this group.") from error
        else:
            cursor = await db.execute(
                """SELECT user_id, username, first_name
                   FROM group_members
                   WHERE chat_id=? AND username=?
                   ORDER BY last_seen_at DESC LIMIT 1""",
                (message.chat.id, target_text.casefold()),
            )
            row = await cursor.fetchone()
            if row is not None:
                try:
                    member = await bot.get_chat_member(
                        message.chat.id,
                        int(row["user_id"]),
                    )
                    target_user = member.user
                except (TelegramBadRequest, TelegramForbiddenError) as error:
                    raise ValueError(
                        "That username is not a current group member."
                    ) from error
            else:
                for _, runtime in eligible_voice_runtimes():
                    client = runtime.get("client")
                    if client is None:
                        continue
                    try:
                        entity = await client.get_entity(target_text)
                    except Exception:
                        continue
                    if isinstance(entity, tl_types.User):
                        try:
                            member = await bot.get_chat_member(
                                message.chat.id,
                                int(entity.id),
                            )
                            target_user = member.user
                            break
                        except (TelegramBadRequest, TelegramForbiddenError):
                            continue
    if target_user is None:
        raise ValueError(
            "Reply to the user, mention @username, or provide a numeric user ID."
        )
    if target_user.is_bot:
        raise ValueError("Bots cannot be authorized for music.")
    return (
        int(target_user.id),
        target_user.username or "",
        target_user.full_name or target_user.first_name or str(target_user.id),
    )


@router.message(Command("auth"))
async def authorize_music_user(message: Message) -> None:
    if message.chat.type not in {ChatType.GROUP, ChatType.SUPERGROUP}:
        return
    if not message.from_user:
        return
    actor_is_owner = message.from_user.id in ADMIN_IDS
    actor_is_admin = actor_is_owner or await group_admin(
        message.chat.id,
        message.from_user.id,
    )
    if not actor_is_admin:
        return
    parts = (message.text or "").split(maxsplit=2)
    if len(parts) < 2 or parts[1].casefold() not in {"on", "off"}:
        await message.answer(
            "<b>Usage:</b> <code>/auth on</code> or <code>/auth off</code> "
            "to lock or unlock music for this group.\n"
            "Reply to a user with the same command, or use "
            "<code>/auth on @username</code> or "
            "<code>/auth on USER_ID</code>."
        )
        return
    mode = parts[1].casefold()
    raw_target = parts[2] if len(parts) > 2 else None
    has_target = bool((raw_target or "").strip()) or (
        message.reply_to_message is not None
    )
    if not has_target:
        await db.execute(
            "INSERT INTO group_settings(chat_id, music_auth_enabled) VALUES(?,?) "
            "ON CONFLICT(chat_id) DO UPDATE SET music_auth_enabled=excluded.music_auth_enabled",
            (message.chat.id, 1 if mode == "on" else 0),
        )
        await db.commit()
        if mode == "on":
            await message.answer(
                "<b>Music authorization enabled.</b>\n"
                "Only group admins and users explicitly authorized with "
                "<code>/auth on</code> may use music commands."
            )
        else:
            await message.answer(
                "<b>Music authorization disabled.</b>\n"
                "Only group admins and the bot owner may use music commands. "
                "Use <code>/auth on</code> to authorize selected users."
            )
        return
    try:
        user_id, username, display_name = await resolve_music_auth_target(
            message,
            raw_target,
        )
    except ValueError as error:
        await message.answer(f"<b>Auth failed:</b> {html.escape(str(error))}")
        return
    if mode == "on":
        await db.execute(
            "INSERT INTO group_settings(chat_id, music_auth_enabled) VALUES(?,1) "
            "ON CONFLICT(chat_id) DO UPDATE SET music_auth_enabled=1",
            (message.chat.id,),
        )
        await db.execute(
            """INSERT INTO music_authorized_users
               (chat_id, user_id, username, first_name)
               VALUES(?,?,?,?)
               ON CONFLICT(chat_id, user_id) DO UPDATE SET
               username=excluded.username,
               first_name=excluded.first_name,
               updated_at=CURRENT_TIMESTAMP""",
            (message.chat.id, user_id, username.casefold(), display_name),
        )
        await db.commit()
        await message.answer(
            f"Music access enabled for <a href=\"tg://user?id={user_id}\">"
            f"{html.escape(display_name)}</a>."
        )
        return
    await db.execute(
        "DELETE FROM music_authorized_users WHERE chat_id=? AND user_id=?",
        (message.chat.id, user_id),
    )
    await db.commit()
    await message.answer(
        f"Music access disabled for <a href=\"tg://user?id={user_id}\">"
        f"{html.escape(display_name)}</a>."
    )

def forwarded_origin_chat_id(message: object) -> int | None:
    origin = getattr(message, "forward_origin", None)
    origin_chat = getattr(origin, "chat", None)
    origin_id = getattr(origin_chat, "id", None)
    if origin_id is None:
        legacy_chat = getattr(message, "forward_from_chat", None)
        origin_id = getattr(legacy_chat, "id", None)
    try:
        return int(origin_id) if origin_id is not None else None
    except (TypeError, ValueError):
        return None


def is_linked_discussion_forward(
    message: object,
    linked_chat_id: int | None,
) -> bool:
    if linked_chat_id is None:
        return False
    return forwarded_origin_chat_id(message) == int(linked_chat_id)


def forwarding_lock_should_preserve(
    message: object,
    is_admin: bool,
    linked_chat_id: int | None,
) -> bool:
    return bool(
        is_admin
        or is_linked_discussion_forward(message, linked_chat_id)
    )


async def linked_discussion_chat_id(chat_id: int) -> int | None:
    cached = linked_discussion_chat_cache.get(chat_id)
    if cached and time.monotonic() - cached[0] < LINKED_DISCUSSION_CACHE_TTL_SECONDS:
        return cached[1]
    linked_id: int | None = None
    try:
        group_chat = await bot.get_chat(chat_id)
        raw_linked_id = getattr(group_chat, "linked_chat_id", None)
        if raw_linked_id is not None:
            linked_id = int(raw_linked_id)
    except (TelegramBadRequest, TelegramForbiddenError, TypeError, ValueError):
        pass
    linked_discussion_chat_cache[chat_id] = (time.monotonic(), linked_id)
    return linked_id


def is_linked_discussion_channel_message(
    message: object,
    linked_chat_id: int | None,
) -> bool:
    """Preserve channel posts automatically delivered into discussion groups."""
    sender_chat = getattr(message, "sender_chat", None)
    sender_chat_id = getattr(sender_chat, "id", None)
    try:
        sender_chat_id = int(sender_chat_id) if sender_chat_id is not None else None
    except (TypeError, ValueError):
        sender_chat_id = None

    if linked_chat_id is not None:
        if sender_chat_id == int(linked_chat_id):
            return True
        if forwarded_origin_chat_id(message) == int(linked_chat_id):
            return True

    # Telegram marks linked-channel posts with this flag. Keep them safe even
    # when get_chat() temporarily does not expose linked_chat_id.
    return bool(getattr(message, "is_automatic_forward", False))


async def should_preserve_linked_channel_message(message: Message) -> bool:
    if message.chat.type not in {ChatType.GROUP, ChatType.SUPERGROUP}:
        return False
    linked_id = await linked_discussion_chat_id(message.chat.id)
    return is_linked_discussion_channel_message(message, linked_id)


async def acknowledge_callback(callback: CallbackQuery) -> None:
    """Answer each Telegram callback exactly once, even for nested renderers."""
    callback_id = str(callback.id)
    if callback_id in answered_callback_ids:
        return
    answered_callback_ids.add(callback_id)
    try:
        await callback.answer()
    except TelegramBadRequest:
        pass


