async def get_group_features(chat_id: int) -> dict[str, object]:
    cached = group_features_cache.get(chat_id)
    if cached and time.monotonic() - cached[0] < GROUP_FEATURES_CACHE_TTL_SECONDS:
        return dict(cached[1])
    cursor = await db.execute("SELECT * FROM group_features WHERE chat_id=?", (chat_id,))
    row = await cursor.fetchone()
    if row is None:
        await db.execute("INSERT OR IGNORE INTO group_features(chat_id) VALUES(?)", (chat_id,))
        await db.commit()
        cursor = await db.execute("SELECT * FROM group_features WHERE chat_id=?", (chat_id,))
        row = await cursor.fetchone()
    if row is None:
        raise RuntimeError(f"Could not load group feature settings for chat {chat_id}")
    settings = dict(row)
    group_features_cache[chat_id] = (time.monotonic(), settings)
    return dict(settings)


async def update_group_feature(chat_id: int, field: str, value: object) -> None:
    allowed = {
        "welcome_enabled", "welcome_text", "welcome_media_type", "welcome_media_id",
        "welcome_buttons", "banned_enabled", "banned_words", "banned_action",
        "banned_mute_minutes",
        "banned_mute_enabled",
        "spam_enabled", "spam_action", "spam_warn_limit", "adult_enabled", "adult_action",
        "adult_warn_limit",
        "botlink_locked", "forwarding_locked", "report_enabled",
        "filters_enabled", "url_locked", "mention_locked", "filters", "blacklist_words",
        "commands_locked", "custom_commands",
    }
    if field not in allowed:
        raise ValueError("Unsupported group feature")
    await db.execute(
        f"INSERT INTO group_features(chat_id, {field}) VALUES(?,?) "
        f"ON CONFLICT(chat_id) DO UPDATE SET {field}=excluded.{field}",
        (chat_id, value),
    )
    await db.commit()
    group_features_cache.pop(chat_id, None)


def selected_actions(raw: str, feature: str = "spam") -> list[str]:
    allowed = ["mute", "ban"] if feature == "spam" else (
        ["delete", "warn", "mute", "kick", "ban"] if feature in {"banned", "adult"}
        else ["delete", "warn", "mute"]
    )
    try:
        values = json.loads(raw or "[]")
        values = values if isinstance(values, list) else [values]
    except json.JSONDecodeError:
        values = [part.strip() for part in str(raw).split(",")]
    return [str(value) for value in values if str(value) in allowed]


BANNED_ACTION_PRESETS = {
    "delete_ban": ["delete", "ban"],
    "delete_mute": ["delete", "mute"],
    "delete_warn": ["delete", "warn"],
}


def selected_banned_preset(raw: str) -> str | None:
    actions = set(selected_actions(raw, "banned"))
    for preset, preset_actions in BANNED_ACTION_PRESETS.items():
        if actions == set(preset_actions):
            return preset
    # Preserve old single-action settings when opening the new preset UI.
    if actions == {"ban"}:
        return "delete_ban"
    if actions == {"mute"}:
        return "delete_mute"
    if actions == {"warn"}:
        return "delete_warn"
    return None


def feature_action_keyboard(chat_id: int, feature: str, enabled: bool, action: str) -> InlineKeyboardMarkup:
    if feature == "spam":
        actions = ["mute", "ban"]
        selected = set(selected_actions(action, feature))
        action_rows = [
            [
                InlineKeyboardButton(
                    text=f"{'ON' if item in selected else 'OFF'}: {item.title()}",
                    callback_data=f"gf_action:{feature}:{chat_id}:{item}",
                    style="success" if item in selected else "danger",
                )
            ]
            for item in actions
        ]
        rows = [
            [InlineKeyboardButton(
                text=f"{'Disable' if enabled else 'Enable'} Anti-Spam",
                callback_data=f"gf_toggle:{feature}:{chat_id}",
                style="success" if enabled else "danger",
            )],
            *action_rows,
            [InlineKeyboardButton(text="Edit Warning Settings", callback_data=f"gf_edit:{feature}:{chat_id}")],
            [InlineKeyboardButton(text="Back to Group", callback_data=f"group_select:{chat_id}")],
        ]
    elif feature == "banned":
        presets = [
            ("delete_ban", "Delete + Ban"),
            ("delete_mute", "Delete + Mute"),
            ("delete_warn", "Delete + Warn"),
        ]
        selected = selected_banned_preset(action)
        action_rows = [
            [InlineKeyboardButton(
                text=f"{'ON' if item == selected else 'OFF'}: {label}",
                callback_data=f"gf_action:{feature}:{chat_id}:{item}",
                style="success" if item == selected else "danger",
            )]
            for item, label in presets
        ]
        rows = [
            [InlineKeyboardButton(
                text=f"{'Disable' if enabled else 'Enable'} Banned Words",
                callback_data=f"gf_toggle:{feature}:{chat_id}",
                style="success" if enabled else "danger",
            )],
            *action_rows,
            [
                InlineKeyboardButton(text="Add Words", callback_data=f"gf_banned_words:{chat_id}:add"),
                InlineKeyboardButton(text="Remove Words", callback_data=f"gf_banned_words:{chat_id}:remove"),
            ],
            [InlineKeyboardButton(text="List Words", callback_data=f"gf_banned_words:{chat_id}:list")],
            [InlineKeyboardButton(text="Set Mute Time", callback_data=f"gf_banned_mute_time:{chat_id}", style="primary")],
            [InlineKeyboardButton(text="Back to Group", callback_data=f"group_select:{chat_id}")],
        ]
    else:
        actions = ["delete", "warn", "mute", "kick", "ban"] if feature in {"banned", "adult"} else ["delete", "warn", "mute"]
        rows = [
            [InlineKeyboardButton(text=f"{'Turn off' if enabled else 'Turn on'}", callback_data=f"gf_toggle:{feature}:{chat_id}")],
            [InlineKeyboardButton(text=f"Action: {action}", callback_data=f"gf_action:{feature}:{chat_id}")],
            [InlineKeyboardButton(text="Edit settings", callback_data=f"gf_edit:{feature}:{chat_id}")],
            [InlineKeyboardButton(text="Back to Group", callback_data=f"group_select:{chat_id}")],
        ]
    return InlineKeyboardMarkup(inline_keyboard=rows)


