def safe_url(url: str) -> bool:
    return bool(re.fullmatch(r"https?://[^\s<>\"]+", url, re.I))


async def resolve_group_target(message: Message, args: list[str]) -> int | None:
    if message.reply_to_message and message.reply_to_message.from_user:
        return message.reply_to_message.from_user.id
    if args and args[0].lstrip("-").isdigit():
        return int(args[0])
    if args and args[0].startswith("@"):
        username = args[0].lstrip("@").strip()
        u_cf = username.casefold()
        cached_id = group_username_to_user_id.get((message.chat.id, u_cf)) or username_to_user_id.get(u_cf)
        if cached_id:
            return cached_id
        cursor = await db.execute(
            "SELECT user_id FROM group_members WHERE chat_id=? AND username=?",
            (message.chat.id, u_cf),
        )
        row = await cursor.fetchone()
        if row:
            uid = int(row["user_id"])
            username_to_user_id[u_cf] = uid
            group_username_to_user_id[(message.chat.id, u_cf)] = uid
            return uid
        # MTProto can resolve an ordinary public Telegram username even when
        # the Bot API cannot. Moderation methods still receive the numeric ID.
        if mtproto_client is not None:
            try:
                resolved = await mtproto_client.get_entity(username)
                resolved_id = getattr(resolved, "id", None)
                if resolved_id and hasattr(resolved, "first_name"):
                    resolved_username = getattr(resolved, "username", None) or username
                    await db.execute(
                        """INSERT INTO group_members(chat_id,user_id,username,first_name)
                        VALUES(?,?,?,?) ON CONFLICT(chat_id,user_id) DO UPDATE SET
                        username=excluded.username, first_name=excluded.first_name,
                        last_seen_at=CURRENT_TIMESTAMP""",
                        (
                            message.chat.id,
                            int(resolved_id),
                            resolved_username.casefold(),
                            getattr(resolved, "first_name", "") or "",
                        ),
                    )
                    await db.commit()
                    return int(resolved_id)
            except Exception as exc:
                log.info("MTProto username lookup failed for @%s: %s", username, exc)
        # Keep Bot API getChat as a fallback for public bot accounts and chats.
        try:
            resolved = await bot.get_chat(f"@{username}")
            if resolved.type == ChatType.PRIVATE and resolved.id:
                await db.execute(
                    """INSERT INTO group_members(chat_id,user_id,username,first_name)
                    VALUES(?,?,?,?) ON CONFLICT(chat_id,user_id) DO UPDATE SET
                    username=excluded.username, first_name=excluded.first_name,
                    last_seen_at=CURRENT_TIMESTAMP""",
                    (
                        message.chat.id,
                        resolved.id,
                        (resolved.username or username).casefold(),
                        resolved.first_name or resolved.full_name or "",
                    ),
                )
                await db.commit()
                return int(resolved.id)
        except TelegramBadRequest:
            pass
    for entity in message.entities or []:
        if entity.type == "text_mention" and getattr(entity, "user", None):
            return int(entity.user.id)
    return None


def format_table_box(rows: list[tuple[str, str]], w_left: int = 15, w_right: int = 16) -> str:
    top = "╭" + "─" * (w_left + 2) + "┬" + "─" * (w_right + 2) + "╮"
    mid = "├" + "─" * (w_left + 2) + "┼" + "─" * (w_right + 2) + "┤"
    bot = "╰" + "─" * (w_left + 2) + "┴" + "─" * (w_right + 2) + "╯"
    lines = [top]
    for i, (k, v) in enumerate(rows):
        k_str = str(k).strip()[:w_left].ljust(w_left)
        v_str = str(v).strip()
        if len(v_str) > w_right:
            v_str = v_str[:w_right - 1] + "…"
        v_str = v_str.rjust(w_right)
        lines.append(f"│ {k_str} │ {v_str} │")
        if i < len(rows) - 1:
            lines.append(mid)
    lines.append(bot)
    return "\n".join(lines)


async def send_group_user_info(message: Message, args: list[str]) -> None:
    target_id = await resolve_group_target(message, args)
    if not target_id:
        await message.reply("Reply to a user's message or tag them with /info @username.")
        return
    try:
        member = await bot.get_chat_member(message.chat.id, target_id)
        user = member.user
        status = str(member.status).replace("_", " ").title()
    except TelegramBadRequest:
        cursor = await db.execute(
            "SELECT user_id, first_name, username FROM group_members WHERE chat_id=? AND user_id=?",
            (message.chat.id, target_id),
        )
        row = await cursor.fetchone()
        if not row:
            await message.reply("I couldn't find that user in this group.")
            return
        user = None
        status = "Unknown"
        first_name = str(row["first_name"] or "")
        username = str(row["username"] or "")
    if user is not None:
        first_name = user.full_name or user.first_name or ""
        username = user.username or ""
    profile = await get_profile(target_id)
    username_text = f"@{username}" if username else "Not set"
    profile_name = str(profile.get("custom_name") or "").strip()
    age = profile.get("age")
    gender = str(profile.get("gender") or "").strip()

    lines = [
        "<blockquote>",
        '<tg-emoji emoji-id="5462910521739063094">👤</tg-emoji> <b>USER INFORMATION</b>',
        "━━━━━━━━━━━━━━━━━━━━━━",
        f'<tg-emoji emoji-id="5454014806950429357">⚡</tg-emoji> <b>User ID │</b> <code>{target_id}</code>',
        f'<tg-emoji emoji-id="6266995104687330978">👑</tg-emoji> <b>Full Name │</b> <b>{html.escape(first_name or "Not set")}</b>',
        f'<tg-emoji emoji-id="4958489311726011319">✨</tg-emoji> <b>Username │</b> <b>{html.escape(username_text)}</b>',
        f'<tg-emoji emoji-id="5440539497383087970">🛡️</tg-emoji> <b>Group Status │</b> <b>{html.escape(status)}</b>',
    ]
    if profile_name:
        lines.append(f'<tg-emoji emoji-id="5462910521739063094">👤</tg-emoji> <b>Profile Name │</b> <b>{html.escape(profile_name)}</b>')
    if age:
        lines.append(f'<tg-emoji emoji-id="5373236586760651455">⏱️</tg-emoji> <b>Age │</b> <b>{html.escape(str(age))}</b>')
    if gender:
        lines.append(f'<tg-emoji emoji-id="5256047523620995497">🎭</tg-emoji> <b>Gender │</b> <b>{html.escape(gender)}</b>')
    lines.extend([
        "━━━━━━━━━━━━━━━━━━━━━━",
        "</blockquote>",
    ])
    await message.reply("\n".join(lines))


async def group_command_is_locked(message: Message) -> bool:
    if message.chat.type not in {ChatType.GROUP, ChatType.SUPERGROUP} or not message.from_user:
        return False
    settings = await get_group_features(message.chat.id)
    if not settings["commands_locked"] or await group_admin(message.chat.id, message.from_user.id):
        return False
    if await bot_can(message.chat.id, "can_delete_messages"):
        try:
            await message.delete()
        except TelegramBadRequest:
            pass
    return True


