def group_rules_page_text(page: int) -> str:
    total_pages = max(
        1,
        (len(GROUP_RULE_ITEMS) + GROUP_RULES_PAGE_SIZE - 1)
        // GROUP_RULES_PAGE_SIZE,
    )
    page = max(0, min(page, total_pages - 1))
    start = page * GROUP_RULES_PAGE_SIZE
    end = min(start + GROUP_RULES_PAGE_SIZE, len(GROUP_RULE_ITEMS))
    numbered = "\n".join(
        f"<b>{index}.</b> {rule}"
        for index, rule in enumerate(GROUP_RULE_ITEMS[start:end], start + 1)
    )
    notes = ""
    if page == total_pages - 1:
        notes = (
            "\n\n<b>Other controls</b>\n"
            "<code>/m</code> replays today's approved Daily Zone media. "
            "It expires at India midnight.\n"
            "Admins can configure custom media commands from "
            "Group Management → Set Command.\n\n"
            "Info and sticker commands are available to everyone. Other "
            "management commands require admin/owner permission."
        )
    return (
        "<blockquote>"
        "<b>Group Management Rules</b>\n"
        f"<i>Rules {start + 1}–{end} of {len(GROUP_RULE_ITEMS)} · "
        f"Page {page + 1}/{total_pages}</i>\n\n"
        f"{numbered}"
        f"{notes}"
        "</blockquote>"
    )
async def save_message(user_id: int, role: str, content: str) -> None:
    try:
        await db.execute(
            "INSERT INTO user_messages(user_id, role, content) VALUES(?,?,?)",
            (user_id, role, content[:4000]),
        )
        # Automatic 1-month memory retention: prune only records strictly older than 30 days
        if random.random() < 0.05:
            await db.execute(
                "DELETE FROM user_messages WHERE user_id=? AND created_at < datetime('now', '-30 days')",
                (user_id,),
            )
            await db.execute(
                "DELETE FROM user_memory_facts WHERE user_id=? AND updated_at < datetime('now', '-30 days')",
                (user_id,),
            )
        await db.commit()
    except Exception as e:
        log.warning("save_message error: %s", e)


async def user_memory(user_id: int) -> str:
    # 1. User Profile details
    profile = await get_profile(user_id)
    profile_parts = []
    if profile.get("custom_name"):
        profile_parts.append(f"Preferred name/Nickname: {profile['custom_name']}")
    if profile.get("age"):
        profile_parts.append(f"Age: {profile['age']}")
    if profile.get("gender"):
        profile_parts.append(f"Gender: {profile['gender']}")

    # 2. Long-term facts learned in the last 30 days
    facts_cursor = await db.execute(
        """SELECT fact FROM user_memory_facts
        WHERE user_id=? AND updated_at >= datetime('now', '-30 days')
        ORDER BY updated_at DESC LIMIT 30""",
        (user_id,),
    )
    facts = [str(row["fact"])[:220] for row in await facts_cursor.fetchall()]

    # 3. Earlier conversation highlights from past days/weeks (within 30 days)
    earlier_cursor = await db.execute(
        """SELECT role, content FROM user_messages
        WHERE user_id=? AND created_at >= datetime('now', '-30 days')
        AND created_at < datetime('now', '-1 day')
        ORDER BY id DESC LIMIT 20""",
        (user_id,),
    )
    earlier_rows = [
        row for row in reversed(await earlier_cursor.fetchall())
        if not looks_like_internal_ai_text(str(row["content"]))
    ]
    if not earlier_rows:
        fallback_cursor = await db.execute(
            """SELECT role, content FROM user_messages
            WHERE user_id=? AND created_at >= datetime('now', '-30 days')
            ORDER BY id DESC LIMIT 25 OFFSET 8""",
            (user_id,),
        )
        earlier_rows = [
            row for row in reversed(await fallback_cursor.fetchall())
            if not looks_like_internal_ai_text(str(row["content"]))
        ]

    sections = []
    if profile_parts:
        sections.append("User Profile: " + ", ".join(profile_parts))
    if facts:
        sections.append("Remembered Facts (Persisted for 30 days): " + " | ".join(facts))
    if earlier_rows:
        sections.append(
            "Earlier 30-Day Conversation History: "
            + " | ".join(f"{row['role']}: {row['content'][:180]}" for row in earlier_rows)
        )
    return "\n".join(sections)


async def get_profile(user_id: int) -> dict[str, object]:
    cached = user_profile_cache.get(user_id)
    if cached and time.monotonic() - cached[0] < USER_PROFILE_CACHE_TTL_SECONDS:
        return dict(cached[1])
    cursor = await db.execute(
        """SELECT u.user_id, u.first_name, u.username, u.seyu_gems,
        p.custom_name, p.age, p.gender
        FROM users u LEFT JOIN profiles p ON p.user_id=u.user_id WHERE u.user_id=?""",
        (user_id,),
    )
    row = await cursor.fetchone()
    profile = dict(row) if row else {"user_id": user_id, "first_name": "", "username": ""}
    user_profile_cache[user_id] = (time.monotonic(), profile)
    return dict(profile)


async def update_profile(
    user_id: int,
    *,
    custom_name: str | None = None,
    age: int | None = None,
    gender: str | None = None,
    clear_age: bool = False,
    clear_gender: bool = False,
) -> None:
    current = await get_profile(user_id)
    await db.execute(
        """INSERT INTO profiles(user_id, custom_name, age, gender) VALUES(?,?,?,?)
        ON CONFLICT(user_id) DO UPDATE SET custom_name=excluded.custom_name,
        age=excluded.age, gender=excluded.gender""",
        (
            user_id,
            custom_name if custom_name is not None else current.get("custom_name"),
            None if clear_age else (age if age is not None else current.get("age")),
            None if clear_gender else (gender if gender is not None else current.get("gender")),
        ),
    )
    await db.commit()
    user_profile_cache.pop(user_id, None)
    profile = await get_profile(user_id)
    users_json[str(user_id)] = {
        "user_id": user_id,
        "first_name": profile.get("first_name") or "",
        "username": profile.get("username") or "",
        "blocked": bool(users_json.get(str(user_id), {}).get("blocked", False)),
        "custom_name": profile.get("custom_name"),
        "age": profile.get("age"),
        "gender": profile.get("gender"),
    }
    await save_users_json()


def _clean_memory_value(value: str, limit: int = 160) -> str:
    cleaned = re.sub(r"\s+", " ", value).strip(" \t\r\n.,!?;:")
    cleaned = re.sub(r"\s+(?:hai|hoon|hain|tha|thi|the)$", "", cleaned, flags=re.IGNORECASE).strip()
    return cleaned[:limit]


async def remember_message_facts(user_id: int, text: str) -> None:
    """Persist explicit, useful user facts into SQLite DB (retained for 30 days)."""
    facts: list[tuple[str, str]] = []

    # Preferred Name
    name_m = re.search(
        r"(?:my name is|call me|mera naam|mujhe\s+([A-Za-z\u0900-\u097F]+)\s+(?:bulao|kehte))\s*([^.!?\n]{1,60})?",
        text,
        re.IGNORECASE,
    )
    if name_m:
        val = name_m.group(2) or name_m.group(1) or ""
        v = _clean_memory_value(val, 50)
        if v:
            facts.append(("preferred_name", f"Preferred name: {v}"))

    # Age
    age_m = re.search(
        r"(?:i am|i'm|meri age|meri umar|main)\s+(\d{1,3})\s*(?:years?\s*old|years?|saal)?",
        text,
        re.IGNORECASE,
    )
    if age_m and 6 <= int(age_m.group(1)) <= 105:
        age = int(age_m.group(1))
        facts.append(("age", f"Age: {age}"))
        await update_profile(user_id, age=age)

    # Birthday
    bday_m = re.search(
        r"(?:mera birthday|mera bday|mera janamdin|my birthday is on|my bday is)\s*(?:on|ko|hai)?\s*([^.!?\n]{1,60})",
        text,
        re.IGNORECASE,
    )
    if bday_m:
        facts.append(("birthday", f"Birthday: {_clean_memory_value(bday_m.group(1))}"))

    # Location / City
    loc_m = re.search(
        r"(?:i live in|i am from|i'm from|main\s+([^.!?\n]{1,40})\s+se hoon|main\s+([^.!?\n]{1,40})\s+(?:me|mein)\s+(?:rehta|rehti)\s+hoon|mera ghar\s+([^.!?\n]{1,40})\s+(?:me|mein)\s+hai)",
        text,
        re.IGNORECASE,
    )
    if loc_m:
        val = next((g for g in loc_m.groups() if g is not None), "")
        if val:
            facts.append(("location", f"Location: {_clean_memory_value(val)}"))

    # Profession / Studies / Job
    prof_m = re.search(
        r"(?:main\s+([^.!?\n]{1,50})\s+(?:ki padhai|ki coaching|ki preparation|ki tayari)\s*(?:kar raha|kar rahi)\s*hoon|i work as\s+([^.!?\n]{1,50})|main\s+(?:ek\s+)?(software engineer|engineer|doctor|developer|coder|programmer|student|teacher|trader|designer|police|lawyer|freelancer|businessman|ca|upsc aspirant)\s*(?:hoon)?)",
        text,
        re.IGNORECASE,
    )
    if prof_m:
        val = next((g for g in prof_m.groups() if g is not None), "")
        if val:
            facts.append(("profession", f"Work/Study: {_clean_memory_value(val)}"))

    # Friends
    friend_m = re.search(
        r"(?:my friends? are|my friend is|mera dost|meri dost|mere dost|meri saheli)\s*(?:is|are|hai|hain)?\s*([^.!?\n]{1,100})",
        text,
        re.IGNORECASE,
    )
    if friend_m:
        names = re.split(r",|\band\b|\baur\b", friend_m.group(1), flags=re.IGNORECASE)
        for friend in names[:6]:
            friend_name = _clean_memory_value(friend, 60)
            if friend_name:
                fact_key = "friend:" + hashlib.sha1(friend_name.casefold().encode("utf-8")).hexdigest()[:16]
                facts.append((fact_key, f"Friend: {friend_name}"))

    # Family & Relationships
    rel_m = re.search(
        r"(?:meri girlfriend|mera boyfriend|meri gf|mera bf|meri crush|meri wife|mera husband|meri patni|mera pati|meri behen|mera bhai|mere mummy|mere papa)\s*(?:ka naam|hai)?\s*([^.!?\n]{1,80})",
        text,
        re.IGNORECASE,
    )
    if rel_m:
        facts.append(("relationship", f"Relationship: {_clean_memory_value(rel_m.group(0))}"))

    # Pets
    pet_m = re.search(
        r"(?:mera pet|mere paas\s+((?:dog|cat|kutta|billi|puppy|kitty)[^.!?\n]{0,60}))",
        text,
        re.IGNORECASE,
    )
    if pet_m:
        facts.append(("pet", f"Pet: {_clean_memory_value(pet_m.group(0))}"))

    # Health / Mood / Feelings
    health_m = re.search(
        r"(?:meri tabiyat\s+(?:kharab|theek nahi)|mujhe\s+(?:bukhar|fever|cold|headache|sir dard)|aaj mood\s+(?:off|kharab))",
        text,
        re.IGNORECASE,
    )
    if health_m:
        facts.append(("health", f"Health/Condition: {_clean_memory_value(health_m.group(0))}"))

    # Exam / Important Events / Milestones
    event_m = re.search(
        r"(?:kal mera exam|aaj mera exam|mera exam|kal interview|aaj interview|meri flight|maine nayi\s+[^.!?\n]{1,50}|maine new\s+[^.!?\n]{1,50})",
        text,
        re.IGNORECASE,
    )
    if event_m:
        facts.append(("event", f"Current event: {_clean_memory_value(event_m.group(0))}"))

    # Hobbies
    hobby_m = re.search(
        r"(?:my hobb(?:y|ies)(?: is| are)?|mera hobby|meri hobby)\s+([^.!?\n]{1,100})",
        text,
        re.IGNORECASE,
    )
    if hobby_m:
        facts.append(("hobby", f"Hobby: {_clean_memory_value(hobby_m.group(1))}"))

    # Likes & Favorites
    fav_m = re.search(
        r"(?:i like|i love|mujhe\s+([^.!?\n]{1,80})\s+(?:bohot\s+)?pasand hai|mera fav(?:ourite)?\s+([^.!?\n]{1,80})\s+(?:is|hai))",
        text,
        re.IGNORECASE,
    )
    if fav_m:
        val = next((g for g in fav_m.groups() if g is not None), "")
        if val:
            val_clean = _clean_memory_value(val)
            fact_key = f"likes:{hashlib.sha1(val_clean.casefold().encode('utf-8')).hexdigest()[:16]}"
            facts.append((fact_key, f"Likes/Favorite: {val_clean}"))

    # Dislikes
    dis_m = re.search(
        r"(?:i dislike|i hate|mujhe\s+([^.!?\n]{1,80})\s+pasand\s+nahi)",
        text,
        re.IGNORECASE,
    )
    if dis_m:
        val_clean = _clean_memory_value(dis_m.group(1))
        fact_key = f"dislikes:{hashlib.sha1(val_clean.casefold().encode('utf-8')).hexdigest()[:16]}"
        facts.append((fact_key, f"Dislikes: {val_clean}"))

    for fact_key, fact in facts:
        await db.execute(
            """INSERT INTO user_memory_facts(user_id, fact_key, fact, updated_at)
            VALUES(?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(user_id, fact_key) DO UPDATE SET
            fact=excluded.fact, updated_at=CURRENT_TIMESTAMP""",
            (user_id, fact_key, fact[:220]),
        )
    if facts:
        await db.commit()


async def ai_reply(
    chat_id: int,
    user_id: int,
    name: str,
    text: str,
) -> str:
    history_key = (chat_id, user_id)
    language_mode = detect_language_mode(text)

    # 1. Check if user is an authorized AI Trainer teaching ˹Dᴇsᴛʀᴏʏᴇʀ ꭙ ᴍᴜsɪᴄ ᴀssɪsᴛᴀɴᴛ
    trainer_authorized = await is_authorized_ai_trainer(user_id)
    if trainer_authorized:
        train_parsed = parse_trainer_instruction(text)
        if train_parsed:
            rtype, trigger, response = train_parsed
            await save_ai_trainer_rule(
                trainer_user_id=user_id,
                rule_type=rtype,
                trigger_text=trigger,
                response_text=response,
                raw_instruction=text,
            )
            if rtype == "qa" and trigger:
                confirmation = (
                    f"Ji Master! Maine seekh liya aur 30 dino ke liye save kar liya! ✨\n\n"
                    f"<blockquote>"
                    f"<b>Trigger :</b> <i>\"{html.escape(trigger)}\"</i>\n"
                    f"<b>Trained Reply :</b> <i>\"{html.escape(response)}\"</i>\n"
                    f"<b>Retention :</b> <i>30 Days Active Memory</i> ⏳"
                    f"</blockquote>\n"
                    f"Ab se jab bhi koi ye bolega ya puchega, mai strictly yahi bolungi! ❤️"
                )
            else:
                confirmation = (
                    f"Ji Master! Maine aapki ye baat 30 dino ke liye apne dimag me save kar li hai! 💖\n\n"
                    f"<blockquote><i>\"{html.escape(response)}\"</i></blockquote>\n"
                    f"Mai bilkul waise hi follow karungi jaisa aapne sikhaya! ✨"
                )
            chat_histories[history_key].append({"role": "user", "content": text})
            chat_histories[history_key].append({"role": "assistant", "content": confirmation})
            return confirmation

    # 2. Check if this message triggers any active trained rule taught by an AI trainer
    trained_reply = await match_trained_rule_reply(text)
    if trained_reply:
        chat_histories[history_key].append({"role": "user", "content": text})
        chat_histories[history_key].append({"role": "assistant", "content": trained_reply})
        return trained_reply

    direct = direct_question_reply(text, language_mode, user_id=user_id)
    if direct:
        chat_histories[history_key].append({"role": "user", "content": text})
        chat_histories[history_key].append({"role": "assistant", "content": direct})
        return direct

    # Retrieve previous assistant reply for quick context reply
    previous = ""
    try:
        prev_cur = await db.execute(
            """SELECT content FROM user_messages
            WHERE user_id=? AND role='assistant'
            ORDER BY id DESC LIMIT 1""",
            (user_id,),
        )
        p_row = await prev_cur.fetchone()
        if p_row:
            previous = str(p_row["content"])
    except Exception:
        pass
    if not previous and chat_histories[history_key]:
        previous = next(
            (item["content"] for item in reversed(chat_histories[history_key]) if item["role"] == "assistant"),
            "",
        )

    quick = instant_context_reply(text, previous, language_mode)
    if quick:
        chat_histories[history_key].append({"role": "user", "content": text})
        chat_histories[history_key].append({"role": "assistant", "content": quick})
        return quick

    feeling = detect_feeling(text)
    chat_histories[history_key].append({"role": "user", "content": text})

    # Load recent conversation turns directly from SQLite DB (persisted up to 30 days)
    # This prevents context loss across bot reboots or when switching chats
    recent_dialogue: list[dict[str, str]] = []
    busy_phrases = ("network is busy", "network busy hai", "please try again in a moment", "thodi der baad try karo")
    try:
        past_cur = await db.execute(
            """SELECT role, content FROM user_messages
            WHERE user_id=? AND created_at >= datetime('now', '-30 days')
            ORDER BY id DESC LIMIT 30""",
            (user_id,),
        )
        for r in reversed(await past_cur.fetchall()):
            c = str(r["content"]).strip()
            role = str(r["role"]).strip().lower()
            if not c or looks_like_internal_ai_text(c):
                continue
            if any(bp in c.lower() for bp in busy_phrases):
                continue
            if role == "user" and c.startswith(("/", "!")):
                continue
            if role not in {"user", "assistant"}:
                continue
            if recent_dialogue and recent_dialogue[-1]["role"] == role:
                recent_dialogue[-1]["content"] += f"\n{c}"
            else:
                recent_dialogue.append({"role": role, "content": c})
    except Exception:
        pass

    # Ensure dialogue starts with 'user' (Gemini requirement)
    while recent_dialogue and recent_dialogue[0]["role"] != "user":
        recent_dialogue.pop(0)

    # Ensure the current user message is cleanly at the end
    if not recent_dialogue or recent_dialogue[-1]["role"] != "user":
        recent_dialogue.append({"role": "user", "content": text})
    else:
        recent_dialogue[-1]["content"] = text

    trainer_rules_ctx = await format_trained_rules_for_prompt()
    messages = [{
        "role": "system",
        "content": system_prompt(
            name[:100],
            feeling,
            await user_memory(user_id),
            language_mode,
            user_id=user_id,
            trainer_rules=trainer_rules_ctx,
            is_trainer=trainer_authorized,
        ),
    }]
    messages.extend(recent_dialogue)
    openrouter_payload = {
        "model": str(runtime_settings.get("openrouter_model", MODEL)),
        "messages": messages,
        "temperature": 0.72,
        "max_tokens": 120,
        "presence_penalty": 0.22,
        "frequency_penalty": 0.28,
        "reasoning": {"exclude": True},
        "provider": {
            "allow_fallbacks": bool(runtime_settings.get("provider_fallbacks", True)),
        },
    }
    provider_order = str(runtime_settings.get("provider_order", "")).strip()
    if provider_order:
        openrouter_payload["provider"]["order"] = [
            provider.strip() for provider in provider_order.split(",") if provider.strip()
        ]

    def sanitize_content(content: str) -> str:
        content = str(content or "").strip()
        content = re.sub(
            r"<think\b[^>]*>.*?</think\s*>",
            "",
            content,
            flags=re.IGNORECASE | re.DOTALL,
        ).strip()
        if not content or looks_like_internal_ai_text(content):
            return ""
        _nm = re.escape(name.strip()[:100])
        if _nm:
            content = re.sub(rf"^(?:{_nm}\s*[,!:]\s*)+", "", content, flags=re.IGNORECASE).strip()
        lines = [line.strip() for line in content.splitlines() if line.strip()]
        if len(lines) > 3:
            lines = lines[:3]
        return "\n".join(lines)[:600]

    def extract_content(response: httpx.Response) -> str:
        return sanitize_content(
            response.json()["choices"][0]["message"].get("content") or ""
        )

    async def request_openrouter(key: str) -> str:
        response = await http.post(
            "/chat/completions",
            json=openrouter_payload,
            headers={"Authorization": f"Bearer {key}"},
        )
        response.raise_for_status()
        return extract_content(response)

    async def request_gemini(key: str) -> str:
        gemini_messages = []
        for item in messages:
            if item["role"] == "system":
                continue
            gemini_messages.append({
                "role": "model" if item["role"] == "assistant" else "user",
                "parts": [{"text": str(item["content"])}],
            })
        fingerprint = gemini_key_fingerprint(key)
        cached = gemini_model_cache.get(fingerprint)
        preferred = str(runtime_settings.get("gemini_model", GEMINI_MODEL)).strip()
        models = available_gemini_models(
            key,
            list(dict.fromkeys([preferred, *(cached[1] if cached else [])])),
        )
        if not models:
            fingerprint = gemini_key_fingerprint(key)
            for cache_key in [
                item for item in gemini_model_cooldowns
                if item[0] == fingerprint
            ]:
                gemini_model_cooldowns.pop(cache_key, None)
            models = await discover_gemini_chat_models(key)
        last_error: Exception | None = None
        for model in models:
            try:
                response = await http.post(
                    f"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent",
                    headers={"x-goog-api-key": key, "Content-Type": "application/json"},
                    json={
                        "systemInstruction": {"parts": [{"text": str(messages[0]["content"])}]},
                        "contents": gemini_messages,
                        "generationConfig": {
                            "temperature": 0.72,
                            "maxOutputTokens": 120,
                        },
                    },
                )
                response.raise_for_status()
                parts = response.json()["candidates"][0]["content"]["parts"]
                content = sanitize_content(
                    "".join(str(part.get("text") or "") for part in parts)
                )
                if content:
                    if model != str(runtime_settings.get("gemini_model", GEMINI_MODEL)):
                        await set_runtime_setting("gemini_model", model)
                    log.info("Gemini reply generated by model %s", model)
                    return content[:1200]
                cool_down_gemini_model(key, model, 500)
            except httpx.HTTPStatusError as error:
                last_error = error
                status = error.response.status_code
                if status in {401, 403}:
                    raise
                cool_down_gemini_model(key, model, status)
                log.warning(
                    "Gemini model %s failed with HTTP %s; trying next model",
                    model,
                    status,
                )
            except (httpx.HTTPError, KeyError, IndexError, TypeError) as error:
                last_error = error
                cool_down_gemini_model(key, model, 500)
                log.warning(
                    "Gemini model %s failed: %s; trying next model",
                    model,
                    type(error).__name__,
                )
            if len(models) == 1 and not cached:
                discovered = await discover_gemini_chat_models(key)
                for discovered_model in available_gemini_models(key, discovered):
                    if discovered_model not in models:
                        models.append(discovered_model)
        if last_error:
            raise last_error
        raise httpx.RequestError(
            "No available Gemini chat model",
            request=httpx.Request("POST", "https://generativelanguage.googleapis.com"),
        )

    airouter_payload = {
        "model": AIROUTER_MODEL,
        "messages": [
            {**messages[0], "content": str(messages[0]["content"]) + "\n\nIMPORTANT: Reply short like a real girl texting - max 1-2 short sentences (~20 words). Never say you are an AI."},
            *messages[1:],
        ],
        "temperature": 0.72,
        "max_tokens": 1000,
    }

    async def request_airouter(key: str, model: str = AIROUTER_MODEL) -> str:
        payload = dict(airouter_payload)
        payload["model"] = model
        response = await http.post(
            f"{AIROUTER_BASE_URL}/chat/completions",
            json=payload,
            headers={"Authorization": f"Bearer {key}", "Content-Type": "application/json"},
            timeout=httpx.Timeout(40.0, connect=8.0, read=40.0),
        )
        response.raise_for_status()
        return extract_content(response)[:300]

    async with ai_gate:
        candidates = ai_candidate_keys()
        for key in candidates:
            provider = str(key.get("provider"))
            try:
                if provider != "airouter":
                    continue
                try:
                    content = await request_airouter(str(key["value"]))
                except (httpx.TimeoutException, httpx.TransportError):
                    await asyncio.sleep(1.0)
                    try:
                        content = await request_airouter(str(key["value"]), model="google/gemini-2.5-flash-lite")
                    except Exception:
                        content = await request_airouter(str(key["value"]))
                except httpx.HTTPStatusError as _err:
                    if _err.response.status_code in {429, 500, 502, 503, 504}:
                        await asyncio.sleep(1.5)
                        content = await request_airouter(str(key["value"]), model="google/gemini-2.5-flash-lite")
                    else:
                        raise
                if not content:
                    await update_ai_key_health(
                        key, success=False, reason="empty response"
                    )
                    log.warning("%s returned an empty AI response", provider)
                    continue
                await update_ai_key_health(key, success=True)
                chat_histories[history_key].append({"role": "assistant", "content": content})
                return content
            except httpx.HTTPStatusError as error:
                status = error.response.status_code
                reason = error.response.text[:300]
                await update_ai_key_health(
                    key, success=False, status=status, reason=reason
                )
                log.warning("%s AI request failed with HTTP %s: %s; rotating", provider, status, reason)
            except (httpx.HTTPError, KeyError, IndexError, TypeError) as error:
                await update_ai_key_health(
                    key, success=False, reason=type(error).__name__
                )
                log.warning("%s AI request failed: %s; rotating", provider, type(error).__name__)
    return (
        "Abhi network busy hai, thodi der baad try karo."
        if language_mode in {"hinglish", "hindi"}
        else "The network is busy right now. Please try again in a moment."
    )


def music_duration_text(seconds: int) -> str:
    seconds = max(0, seconds)
    return f"{seconds // 60}:{seconds % 60:02d}"


def music_timer_text(seconds: int) -> str:
    seconds = max(0, int(seconds))
    return f"{seconds // 60:02d}:{seconds % 60:02d}"


def music_progress_button_text(
    elapsed: int | None,
    duration: int,
) -> str:
    total = max(0, int(duration))
    current = min(max(0, int(elapsed or 0)), total)
    slots = 10
    position = (
        min(slots, max(0, round(current / total * slots)))
        if total
        else 0
    )
    bar = "—" * position + "◉" + "—" * (slots - position - 1)
    return (
        f"{music_timer_text(current)} {bar} "
        f"{music_timer_text(total)}"
    )


def music_normalize(value: object) -> str:
    return re.sub(
        r"[^a-z0-9]+",
        " ",
        html.unescape(str(value)).casefold(),
    ).strip()


def music_search_duration_seconds(value: object) -> int:
    parts = str(value or "").strip().split(":")
    if not parts or not all(part.isdigit() for part in parts):
        return 0
    try:
        seconds = 0
        for part in parts:
            seconds = seconds * 60 + int(part)
        return seconds
    except ValueError:
        return 0


def music_youtube_web_search(
    query: str,
    limit: int,
) -> list[dict[str, object]]:
    """Read YouTube's public search page in the same order users see."""
    from urllib.parse import quote
    from urllib.request import Request, urlopen

    request = Request(
        "https://www.youtube.com/results?search_query=" + quote(query),
        headers={
            "User-Agent": (
                "Mozilla/5.0 (X11; Linux x86_64) "
                "AppleWebKit/537.36 Chrome/131 Safari/537.36"
            ),
            "Accept-Language": "en-US,en;q=0.9",
        },
    )
    with urlopen(request, timeout=15) as response:
        document = response.read().decode("utf-8", "ignore")
    marker = "var ytInitialData = "
    start = document.find(marker)
    if start < 0:
        return []
    payload, _ = json.JSONDecoder().raw_decode(
        document[start + len(marker):]
    )
    videos: list[dict[str, object]] = []

    def collect(value: object) -> None:
        if len(videos) >= limit:
            return
        if isinstance(value, dict):
            renderer = value.get("videoRenderer")
            if isinstance(renderer, dict):
                video_id = str(renderer.get("videoId") or "").strip()
                title_data = renderer.get("title")
                title = ""
                if isinstance(title_data, dict):
                    simple_title = title_data.get("simpleText")
                    runs = title_data.get("runs")
                    if isinstance(simple_title, str):
                        title = simple_title
                    elif isinstance(runs, list) and runs:
                        first_run = runs[0]
                        if isinstance(first_run, dict):
                            title = str(first_run.get("text") or "")
                if video_id and title:
                    owner_data = renderer.get("ownerText")
                    uploader = ""
                    if isinstance(owner_data, dict):
                        runs = owner_data.get("runs")
                        if isinstance(runs, list) and runs:
                            first_run = runs[0]
                            if isinstance(first_run, dict):
                                uploader = str(first_run.get("text") or "")
                    thumbnail_data = renderer.get("thumbnail")
                    thumbnails = (
                        thumbnail_data.get("thumbnails", [])
                        if isinstance(thumbnail_data, dict)
                        else []
                    )
                    thumbnail = ""
                    if isinstance(thumbnails, list) and thumbnails:
                        last_thumbnail = thumbnails[-1]
                        if isinstance(last_thumbnail, dict):
                            thumbnail = str(last_thumbnail.get("url") or "")
                    length_data = renderer.get("lengthText")
                    length = (
                        length_data.get("simpleText")
                        if isinstance(length_data, dict)
                        else ""
                    )
                    videos.append(
                        {
                            "id": video_id,
                            "title": title,
                            "uploader": uploader,
                            "duration": music_search_duration_seconds(length),
                            "webpage_url": (
                                f"https://www.youtube.com/watch?v={video_id}"
                            ),
                            "thumbnail": thumbnail,
                        }
                    )
                    if len(videos) >= limit:
                        return
            for child in value.values():
                collect(child)
                if len(videos) >= limit:
                    return
        elif isinstance(value, list):
            for child in value:
                collect(child)
                if len(videos) >= limit:
                    return

    collect(payload)
    return videos


def music_python_search(query: str, limit: int) -> list[dict[str, object]]:
    if VideosSearch is None:
        return []

    import httpx as search_httpx

    original_post = search_httpx.post

    def compatible_post(*args, **kwargs):
        proxies = kwargs.pop("proxies", None)
        if isinstance(proxies, dict):
            kwargs["proxy"] = (
                proxies.get("https://")
                or proxies.get("http://")
                or None
            )
        return original_post(*args, **kwargs)

    with music_search_compat_lock:
        search_httpx.post = compatible_post
        component_handler = None
        original_video_component = None
        try:
            # Some YouTube results omit the channel browse id. The installed
            # youtubesearchpython handler concatenates that None value and
            # aborts the complete search instead of returning the result.
            try:
                from youtubesearchpython.core.constants import videoElementKey
                from youtubesearchpython.handlers.componenthandler import (
                    ComponentHandler,
                )

                component_handler = ComponentHandler
                original_video_component = ComponentHandler._getVideoComponent

                def safe_video_component(self, element, shelfTitle=None):
                    patched = copy.deepcopy(element)
                    video = patched.get(videoElementKey, {})
                    owner_text = (
                        video.get("ownerText", {})
                        if isinstance(video, dict)
                        else {}
                    )
                    runs = (
                        owner_text.get("runs", [])
                        if isinstance(owner_text, dict)
                        else []
                    )
                    if runs and isinstance(runs[0], dict):
                        navigation = runs[0].setdefault("navigationEndpoint", {})
                        browse = (
                            navigation.setdefault("browseEndpoint", {})
                            if isinstance(navigation, dict)
                            else {}
                        )
                        if isinstance(browse, dict) and not isinstance(
                            browse.get("browseId"),
                            str,
                        ):
                            browse["browseId"] = ""
                    return original_video_component(self, patched, shelfTitle)

                ComponentHandler._getVideoComponent = safe_video_component
            except (ImportError, AttributeError):
                component_handler = None
            payload = VideosSearch(query, limit=limit).result()
        finally:
            if component_handler is not None and original_video_component is not None:
                component_handler._getVideoComponent = original_video_component
            search_httpx.post = original_post

    entries: list[dict[str, object]] = []
    for item in payload.get("result", []) if isinstance(payload, dict) else []:
        if not isinstance(item, dict) or not item.get("id") or not item.get("title"):
            continue
        thumbnails = item.get("thumbnails")
        thumbnail = ""
        if isinstance(thumbnails, list) and thumbnails:
            candidate = thumbnails[-1]
            if isinstance(candidate, dict):
                thumbnail = str(candidate.get("url") or "")
        channel = item.get("channel")
        uploader = (
            str(channel.get("name") or "")
            if isinstance(channel, dict)
            else ""
        )
        video_id = str(item["id"])
        entries.append(
            {
                "id": video_id,
                "title": str(item["title"]),
                "uploader": uploader,
                "duration": music_search_duration_seconds(item.get("duration")),
                "webpage_url": str(
                    item.get("link")
                    or f"https://www.youtube.com/watch?v={video_id}"
                ),
                "thumbnail": thumbnail,
            }
        )
    return entries


def music_flat_search(prefix: str, query: str, limit: int) -> list[dict[str, object]]:
    if prefix == "ytsearch":
        try:
            entries = music_youtube_web_search(query, limit)
            if entries:
                return entries
        except Exception as error:
            log.info("YouTube web search unavailable: %s", type(error).__name__)
        try:
            entries = music_python_search(query, limit)
            if entries:
                return entries
        except Exception as error:
            log.info("Python YouTube search unavailable: %s", type(error).__name__)
    # Do not use yt-dlp as a search provider. YouTube can return an
    # anti-bot challenge for search metadata even when its public results page
    # is available, and that fallback also makes result rank unpredictable.
    return []


MUSIC_SEARCH_STOP_WORDS = {
    "song",
    "music",
    "track",
    "full",
    "audio",
    "video",
    "official",
}
MUSIC_ALTERNATIVE_MARKERS = (
    "cover",
    "remix",
    "mashup",
    "karaoke",
    "lofi",
    "slowed",
    "reverb",
    "sped up",
    "nightcore",
    "live",
    "instrumental",
    "tribute",
    "status",
    "shorts",
    "short video",
    "acoustic",
    "reprise",
    "8d",
    "vocals only",
    "without music",
    "slow",
    "vocal breakdown",
    "behind the scenes",
)
MUSIC_NONCANONICAL_PRESENTATION_MARKERS = (
    " lyric ",
    " lyrics ",
    " lyrical ",
    " audio version ",
    " hq audio ",
)


def music_search_words(value: object) -> set[str]:
    return {
        word
        for word in music_normalize(value).split()
        if word not in MUSIC_SEARCH_STOP_WORDS
    }


class MusicInputError(ValueError):
    """A user-provided music input cannot be played as requested."""


MUSIC_YOUTUBE_HOSTS = {
    "youtube.com",
    "www.youtube.com",
    "m.youtube.com",
    "music.youtube.com",
    "youtu.be",
    "www.youtu.be",
}


def music_is_youtube_url(value: str) -> bool:
    try:
        parsed = urlparse(value.strip())
    except ValueError:
        return False
    host = parsed.netloc.casefold().split(":", 1)[0]
    return parsed.scheme.casefold() in {"http", "https"} and host in MUSIC_YOUTUBE_HOSTS


def music_cache_key(*values: object) -> str:
    normalized = "\x1f".join(music_normalize(value) for value in values)
    return hashlib.sha256(normalized.encode("utf-8")).hexdigest()


def safe_copy_track(track: dict[str, object] | None) -> dict[str, object] | None:
    """Safely clone track dictionaries without unpicklable asyncio primitives (Futures, Events)."""
    if not isinstance(track, dict):
        return None
    cleaned: dict[str, object] = {}
    for k, v in track.items():
        if isinstance(v, (asyncio.Event, asyncio.Future, asyncio.Task)):
            continue
        if k == "_prefetch_event":
            continue
        if k == "_fallback_track" and isinstance(v, dict):
            cleaned[k] = safe_copy_track(v)
        elif k == "_fallback_tracks" and isinstance(v, list):
            cleaned[k] = [safe_copy_track(t) for t in v if isinstance(t, dict)]
        else:
            try:
                cleaned[k] = copy.deepcopy(v)
            except Exception:
                if isinstance(v, (str, int, float, bool, type(None))):
                    cleaned[k] = v
                elif isinstance(v, list):
                    cleaned[k] = list(v)
                elif isinstance(v, dict):
                    cleaned[k] = dict(v)
    return cleaned


def music_search_cache_get(
    key: str,
) -> tuple[bool, dict[str, object] | None]:
    cached = music_search_cache.get(key)
    if cached is None:
        return False, None
    created_at, track = cached
    if time.monotonic() - created_at >= MUSIC_SEARCH_CACHE_TTL_SECONDS:
        music_search_cache.pop(key, None)
        return False, None
    # Track dictionaries contain nested fallback candidates. A shallow copy
    # lets one group's preparation state leak into another group's playback.
    return True, safe_copy_track(track) if track is not None else None


def music_search_cache_put(
    key: str,
    track: dict[str, object] | None,
) -> None:
    if len(music_search_cache) >= MUSIC_SEARCH_CACHE_MAX_ENTRIES:
        oldest_key = min(
            music_search_cache,
            key=lambda cache_key: music_search_cache[cache_key][0],
        )
        music_search_cache.pop(oldest_key, None)
    music_search_cache[key] = (
        time.monotonic(),
        safe_copy_track(track) if track is not None else None,
    )


def music_youtube_video_url(value: str) -> tuple[str, str]:
    try:
        parsed = urlparse(value.strip())
    except ValueError as error:
        raise MusicInputError("That YouTube URL is not valid.") from error
    if (
        parsed.scheme.casefold() not in {"http", "https"}
        or parsed.netloc.casefold().split(":", 1)[0] not in MUSIC_YOUTUBE_HOSTS
    ):
        raise MusicInputError(
            "Please send a valid YouTube video URL from youtube.com or youtu.be."
        )
    query = parse_qs(parsed.query)
    if parsed.path.casefold().startswith("/playlist") or query.get("list"):
        raise MusicInputError(
            "YouTube playlists are not supported here. Send one video URL."
        )
    host = parsed.netloc.casefold().split(":", 1)[0]
    video_id = ""
    if host in {"youtu.be", "www.youtu.be"}:
        video_id = parsed.path.strip("/").split("/", 1)[0]
    elif parsed.path.casefold().startswith("/watch"):
        video_id = query.get("v", [""])[0]
    else:
        path_parts = [part for part in parsed.path.split("/") if part]
        if len(path_parts) >= 2 and path_parts[0].casefold() in {
            "shorts",
            "embed",
            "live",
        }:
            video_id = path_parts[1]
    if not re.fullmatch(r"[A-Za-z0-9_-]{11}", video_id):
        raise MusicInputError(
            "That YouTube URL does not contain a single valid video."
        )
    return video_id, f"https://www.youtube.com/watch?v={video_id}"


async def resolve_youtube_url_track(
    value: str,
    requested_by: int,
    requested_name: str,
) -> dict[str, object]:
    video_id, canonical_url = music_youtube_video_url(value)
    cache_key = f"youtube-direct:{canonical_url}"
    found, cached = music_search_cache_get(cache_key)
    if found:
        if cached is None:
            raise LookupError("That YouTube video could not be read.")
        cached.update(
            requested_by=requested_by,
            requested_name=requested_name[:100],
        )
        return cached

    title = "YouTube Music"
    artist = "YouTube"
    thumbnail = f"https://i.ytimg.com/vi/{video_id}/hqdefault.jpg"
    duration = 240

    # Fast oEmbed lookup (takes < 0.5s, avoids YouTube bot blocks and hangs)
    try:
        async with httpx.AsyncClient(timeout=3.0) as oclient:
            o_resp = await oclient.get(
                "https://www.youtube.com/oembed",
                params={"url": canonical_url, "format": "json"}
            )
            if o_resp.status_code == 200:
                odata = o_resp.json()
                if odata.get("title"):
                    title = html.unescape(str(odata["title"]).strip())
                if odata.get("author_name"):
                    artist = html.unescape(str(odata["author_name"]).strip())
                if odata.get("thumbnail_url"):
                    thumbnail = str(odata["thumbnail_url"])
    except Exception as oerr:
        log.info("Fast YouTube oEmbed lookup skipped: %s", oerr)

    track = {
        "id": video_id,
        "title": title[:160],
        "artist": artist[:160],
        "duration": duration,
        "url": canonical_url,
        "webpage_url": canonical_url,
        "thumbnail": thumbnail,
        "source": "YouTube",
        "direct_url": True,
        "requested_by": requested_by,
        "requested_name": requested_name[:100],
        "query": value.strip(),
    }
    music_search_cache_put(cache_key, track)
    return track


def music_youtube_score(
    entry: dict[str, object],
    query: str,
    target_title: str,
    target_artist: str,
    target_duration: int,
    index: int,
) -> int:
    title = music_normalize(entry.get("title", ""))
    uploader = music_normalize(entry.get("uploader", ""))
    query_words = music_search_words(query)
    target_title_words = music_search_words(target_title)
    normalized_artist = music_normalize(target_artist)
    artist_groups = [
        group.strip()
        for group in re.split(r",|&|\bfeat(?:uring)?\b", normalized_artist)
        if group.strip()
    ]
    artist_words = {
        word for word in normalized_artist.split() if len(word) >= 3
    }
    if not title or not query_words:
        return -10_000

    title_words = set(title.split())
    overlap = len(query_words.intersection(title_words)) / len(query_words)
    query_text = " ".join(sorted(query_words))
    query_ratio = SequenceMatcher(None, query_text, title).ratio()
    target_ratio = (
        SequenceMatcher(None, music_normalize(target_title), title).ratio()
        if target_title
        else 0.0
    )
    title_match = max(query_ratio, target_ratio)
    if overlap < 0.45 and title_match < 0.62:
        return -10_000

    score = int(100 * title_match)
    if query_words.issubset(title_words) and (
        len(query_words) > 1 or len(title_words - query_words) == 0
    ):
        extra_words = len(title_words - query_words)
        if extra_words <= max(8, len(query_words) * 3):
            score += 70 - min(35, extra_words * 4)
    if target_title_words and (
        target_title_words == title_words
        or (
            len(target_title_words) > 1
            and target_title_words.issubset(title_words)
        )
    ):
        score += 80
    score += int(45 * overlap)

    if artist_words:
        haystack = f"{title} {uploader}"
        compact_haystack = "".join(haystack.split())
        matching_groups = [
            group
            for group in artist_groups
            if group in haystack
            or group.replace(" ", "") in compact_haystack
        ]
        official_uploader = any(
            marker in uploader
            for marker in (
                "t series",
                "vevo",
                "sony music",
                "zee music",
                "saregama",
                "coke studio",
            )
        )
        strong_title_match = bool(
            target_title_words
            and target_title_words.issubset(title_words)
            and overlap >= 0.55
        )
        if artist_groups and not matching_groups and not (
            official_uploader or strong_title_match
        ):
            return -10_000
        artist_matches = sum(
            word in set(haystack.split()) for word in artist_words
        )
        if matching_groups and artist_matches == 0:
            artist_matches = 1
        score += min(48, artist_matches * 12)

    try:
        duration = int(float(entry.get("duration") or 0))
    except (TypeError, ValueError):
        duration = 0
    if target_duration and duration:
        score += max(0, 45 - abs(target_duration - duration))

    if any(
        marker in uploader
        for marker in (
            "t series",
            "vevo",
            "sony music",
            "zee music",
            "saregama",
            "coke studio",
        )
    ):
        score += 90
    if artist_groups and any(
        group in uploader or group.replace(" ", "") in "".join(uploader.split())
        for group in artist_groups
    ):
        score += 45
    if any(
        marker in title
        for marker in ("official", "full video", "full song", "official audio", "lyrical")
    ):
        score += 18

    lowered = f" {title} "
    if any(marker in lowered for marker in MUSIC_NONCANONICAL_PRESENTATION_MARKERS):
        score -= 45
    for marker in MUSIC_ALTERNATIVE_MARKERS:
        if f" {marker} " in lowered and marker not in music_normalize(query):
            return -10_000
    score += max(0, 20 - index * 2)
    return score


def music_jiosaavn_download_urls(item: dict[str, object]) -> list[str]:
    more_info = item.get("more_info")
    nested = more_info if isinstance(more_info, dict) else {}
    raw_urls = (
        item.get("downloadUrl")
        or item.get("download_url")
        or nested.get("downloadUrl")
        or nested.get("download_url")
    )
    candidates: list[str] = []
    if isinstance(raw_urls, list):
        for raw in raw_urls:
            if isinstance(raw, dict):
                link = raw.get("link") or raw.get("url")
            else:
                link = raw
            if isinstance(link, str) and link.startswith(("http://", "https://")):
                candidates.append(link)
    elif isinstance(raw_urls, dict):
        link = raw_urls.get("link") or raw_urls.get("url")
        if isinstance(link, str) and link.startswith(("http://", "https://")):
            candidates.append(link)
    elif isinstance(raw_urls, str) and raw_urls.startswith(("http://", "https://")):
        candidates.append(raw_urls)
    return candidates


def music_jiosaavn_download_url(item: dict[str, object]) -> str | None:
    candidates = music_jiosaavn_download_urls(item)
    return candidates[-1] if candidates else None


def music_jiosaavn_image_url(item: dict[str, object]) -> str:
    raw_image = item.get("image") or item.get("image_url")
    if isinstance(raw_image, list):
        for candidate in reversed(raw_image):
            if isinstance(candidate, dict):
                link = candidate.get("link") or candidate.get("url")
                if isinstance(link, str) and link.startswith(("http://", "https://")):
                    return link
    if isinstance(raw_image, dict):
        link = raw_image.get("link") or raw_image.get("url")
        if isinstance(link, str):
            return link
    if isinstance(raw_image, str):
        return raw_image
    more_info = item.get("more_info")
    if isinstance(more_info, dict):
        return music_jiosaavn_image_url(more_info)
    return ""


def music_jiosaavn_score(
    item: dict[str, object],
    query: str,
    index: int,
) -> int:
    title = music_normalize(item.get("name", ""))
    artist = music_normalize(item.get("primaryArtists", ""))
    wanted = music_search_words(query)
    title_words = set(title.split())
    if not title or not wanted:
        return -10_000
    overlap = len(wanted.intersection(title_words)) / len(wanted)
    ratio = SequenceMatcher(None, music_normalize(query), title).ratio()
    if overlap < 0.45 and ratio < 0.62:
        return -10_000
    score = int(120 * max(overlap, ratio))
    if wanted.issubset(title_words):
        score += 55
    if artist:
        score += min(25, len(artist.split()) * 5)
    if any(
        marker in title
        for marker in ("cover", "remix", "karaoke", "slowed", "reverb", "instrumental")
    ):
        score -= 100
    return score - index * 3


def resolve_jiosaavn_track(
    results: list[object],
    query: str,
    requested_by: int,
    requested_name: str,
) -> dict[str, object] | None:
    ranked: list[tuple[int, dict[str, object], str, int]] = []
    for index, raw_item in enumerate(results):
        if not isinstance(raw_item, dict):
            continue
        url = music_jiosaavn_download_url(raw_item)
        if not url:
            continue
        title = html.unescape(str(raw_item.get("name") or "").strip())
        if not title:
            continue
        try:
            duration = int(raw_item.get("duration") or 0)
        except (TypeError, ValueError):
            duration = 0
        if not MUSIC_MIN_DURATION_SECONDS <= duration <= MUSIC_MAX_DURATION_SECONDS:
            continue
        score = music_jiosaavn_score(raw_item, query, index)
        if score >= 95:
            ranked.append((score, raw_item, title, duration))
    if not ranked:
        return None
    _, item, title, duration = max(ranked, key=lambda candidate: candidate[0])
    return {
        "id": str(item.get("id") or item.get("url") or title),
        "title": title[:160],
        "artist": html.unescape(
            str(item.get("primaryArtists") or "").strip()
        )[:160] or "JioSaavn",
        "duration": duration,
        "url": music_jiosaavn_download_url(item),
        "webpage_url": str(item.get("url") or ""),
        "download_urls": music_jiosaavn_download_urls(item),
        "thumbnail": music_jiosaavn_image_url(item),
        "source": "JioSaavn",
        "requested_by": requested_by,
        "requested_name": requested_name[:100],
        "query": query,
    }


async def lookup_jiosaavn_track(
    query: str,
    requested_by: int,
    requested_name: str,
) -> dict[str, object] | None:
    """Fetch a fresh JioSaavn fallback without coupling it to YouTube search."""
    clean_query = re.sub(r"\s+", " ", query).strip()
    if not clean_query:
        return None
    try:
        response = await music_http.get(
            "/search/songs",
            params={"query": clean_query[:MUSIC_MAX_QUERY_LENGTH], "limit": 10},
        )
        response.raise_for_status()
        payload = response.json()
        data = payload.get("data", {}) if isinstance(payload, dict) else {}
        results = data.get("results", []) if isinstance(data, dict) else []
        return resolve_jiosaavn_track(
            results if isinstance(results, list) else [],
            clean_query,
            requested_by,
            requested_name,
        )
    except (httpx.HTTPError, ValueError, TypeError):
        log.info("Fresh JioSaavn fallback lookup failed")
        return None


async def resolve_youtube_track(
    query: str,
    target_title: str,
    target_artist: str,
    target_duration: int,
    requested_by: int,
    requested_name: str,
) -> dict[str, object] | None:
    cache_key = music_cache_key(
        "youtube-search-rank5-v3",
        query,
        target_title,
        target_artist,
        target_duration,
    )
    found, cached = music_search_cache_get(cache_key)
    if found:
        if cached is None:
            return None
        cached.update(
            requested_by=requested_by,
            requested_name=requested_name[:100],
        )
        return cached

    # JioSaavn gives us the canonical song title first. Search that exact
    # title once, like the original GitHub bot's first-result flow; the raw
    # user query is already represented by target_title when metadata lookup
    # is unavailable.
    # Keep the exact user query and YouTube's returned order. Do not replace
    # it with JioSaavn's canonical title or apply spelling corrections.
    raw_query = query.strip() or target_title.strip()
    search_queries = [raw_query]
    candidates_by_url: dict[str, tuple[int, dict[str, object]]] = {}
    for search_query in search_queries:
        try:
            async with music_search_gate:
                entries = await run_music_blocking(
                    music_flat_search,
                    "ytsearch",
                    search_query,
                    5,
                )
        except Exception as error:
            log.info(
                "YouTube music search unavailable for query: %s",
                type(error).__name__,
            )
            continue
        for index, entry in enumerate(entries):
            try:
                duration = int(float(entry.get("duration") or 0))
            except (TypeError, ValueError):
                duration = 0
            title = str(entry.get("title") or "").strip()
            video_id = str(entry.get("id") or "").strip()
            url = str(
                entry.get("webpage_url")
                or entry.get("original_url")
                or (
                    f"https://www.youtube.com/watch?v={video_id}"
                    if video_id
                    else ""
                )
            ).strip()
            if not (
                title
                and url.startswith(("https://www.youtube.com/", "https://youtu.be/"))
                and MUSIC_MIN_DURATION_SECONDS
                <= duration
                <= MUSIC_MAX_DURATION_SECONDS
            ):
                continue
            score = music_youtube_score(
                entry,
                query,
                target_title,
                target_artist,
                target_duration,
                index,
            )
            previous = candidates_by_url.get(url)
            if previous is None or score > previous[0]:
                candidates_by_url[url] = (score, entry)

    if not candidates_by_url:
        return None
    ranked_candidates = list(candidates_by_url.values())
    # Keep YouTube's returned order. The first result is the user's requested
    # search rank; do not replace it with a score- or view-based alternative.
    best_score, entry = ranked_candidates[0]
    if best_score < 70:
        # The original GitHub flow played the best available first result.
        # Rejecting it here created a false "no playable recording" error for
        # valid songs when YouTube metadata was incomplete or localized.
        log.info(
            "Using best available YouTube result despite weak metadata score: %s",
            best_score,
        )
    duration = int(float(entry.get("duration") or 0))
    video_id = str(entry.get("id") or "").strip()
    url = str(
        entry.get("webpage_url")
        or entry.get("original_url")
        or f"https://www.youtube.com/watch?v={video_id}"
    )
    def make_track(
        candidate: dict[str, object],
        search_rank: int,
    ) -> dict[str, object]:
        candidate_id = str(candidate.get("id") or "").strip()
        candidate_url = str(
            candidate.get("webpage_url")
            or candidate.get("original_url")
            or f"https://www.youtube.com/watch?v={candidate_id}"
        )
        candidate_duration = int(float(candidate.get("duration") or 0))
        return {
            "id": candidate_id or candidate_url,
            "title": html.unescape(str(candidate["title"]).strip())[:160],
            "artist": html.unescape(
                str(candidate.get("uploader") or "").strip()
            )[:160] or "YouTube",
            "duration": candidate_duration,
            "url": candidate_url,
            "webpage_url": candidate_url,
            "thumbnail": str(
                candidate.get("thumbnail")
                or (
                    f"https://i.ytimg.com/vi/{candidate_id}/hqdefault.jpg"
                    if candidate_id
                    else ""
                )
            ),
            "source": "YouTube",
            "requested_by": requested_by,
            "requested_name": requested_name[:100],
            "query": query,
            "search_rank": search_rank,
        }

    track = make_track(entry, 1)
    fallback_tracks = [
        make_track(candidate, rank)
        for rank, (_candidate_score, candidate) in enumerate(
            ranked_candidates[1:5],
            start=2,
        )
    ]
    if fallback_tracks:
        track["_fallback_tracks"] = fallback_tracks
    log.info(
        "Selected YouTube rank 1 result: %s [%s]",
        track.get("title", "unknown"),
        track.get("id", "unknown"),
    )
    music_search_cache_put(cache_key, track)
    return dict(track)


async def music_direct_url_available(url: str) -> bool:
    """Check that a direct music URL can return bytes before queueing it."""
    try:
        async with music_http.stream(
            "GET",
            url,
            headers={"Accept": "*/*", "Range": "bytes=0-1023"},
        ) as response:
            if response.status_code not in {200, 206}:
                return False
            first_chunk = await anext(response.aiter_bytes(1024), b"")
            return bool(first_chunk)
    except (httpx.HTTPError, OSError):
        return False


async def _resolve_music_track_uncached(
    query: str,
    requested_by: int,
    requested_name: str,
    is_video: bool = False,
) -> dict[str, object]:
    clean_query = re.sub(r"\s+", " ", query).strip()
    if not clean_query:
        raise ValueError("Song name must be between 1 and 120 characters.")
    if music_is_youtube_url(clean_query):
        url_track = await resolve_youtube_url_track(
            clean_query,
            requested_by,
            requested_name,
        )
        if is_video:
            url_track["is_video"] = True
            url_track.pop("_fallback_track", None)
            url_track.pop("_fallback_tracks", None)
        return url_track
    async def load_jiosaavn_metadata() -> tuple[list[object], str, str, int]:
        try:
            response = await music_http.get(
                "/search/songs",
                params={"query": clean_query, "limit": 10},
            )
            response.raise_for_status()
            payload = response.json()
            data = payload.get("data", {}) if isinstance(payload, dict) else {}
            results = data.get("results", []) if isinstance(data, dict) else []
            found_results = results if isinstance(results, list) else []
            found_title = clean_query
            found_artist = ""
            found_duration = 0
            first = found_results[0] if found_results else {}
            if isinstance(first, dict):
                found_title = (
                    html.unescape(str(first.get("name", "")).strip())
                    or found_title
                )
                found_artist = html.unescape(
                    str(first.get("primaryArtists", "")).strip()
                )
                try:
                    found_duration = int(first.get("duration") or 0)
                except (TypeError, ValueError):
                    found_duration = 0
            return found_results, found_title, found_artist, found_duration
        except (httpx.HTTPError, ValueError, TypeError):
            log.info("JioSaavn search unavailable; trying YouTube search")
            return [], clean_query, "", 0

    if is_video:
        yt_v = await resolve_youtube_track(clean_query, clean_query, "", 0, requested_by, requested_name)
        if yt_v:
            yt_v["is_video"] = True
            yt_v.pop("_fallback_track", None)
            yt_v.pop("_fallback_tracks", None)
            return yt_v
        try:
            _, jtitle, jartist, jdur = await load_jiosaavn_metadata()
            if jtitle and jtitle != clean_query:
                better_q = f"{jtitle} {jartist}".strip()
                yt_v2 = await resolve_youtube_track(better_q, jtitle, jartist, jdur, requested_by, requested_name)
                if yt_v2:
                    yt_v2["is_video"] = True
                    yt_v2.pop("_fallback_track", None)
                    yt_v2.pop("_fallback_tracks", None)
                    return yt_v2
        except Exception:
            pass
        raise LookupError("No playable video found on YouTube.")
    if re.match(r"^https?://", clean_query, flags=re.IGNORECASE):
        raise MusicInputError(
            "Only direct YouTube video URLs are supported by the URL play mode."
        )
    if len(clean_query) > MUSIC_MAX_QUERY_LENGTH:
        raise ValueError("Song name must be between 1 and 120 characters.")

    jiosaavn_task = load_jiosaavn_metadata()
    youtube_task = resolve_youtube_track(
        clean_query,
        clean_query,
        "",
        0,
        requested_by,
        requested_name,
    )
    youtube_result, jiosaavn_result = await asyncio.gather(
        youtube_task,
        jiosaavn_task,
        return_exceptions=True,
    )
    if isinstance(youtube_result, Exception):
        log.info(
            "YouTube music search failed: %s",
            type(youtube_result).__name__,
        )
        youtube_track = None
    else:
        youtube_track = youtube_result
    if isinstance(jiosaavn_result, Exception):
        log.info(
            "JioSaavn music search failed: %s",
            type(jiosaavn_result).__name__,
        )
        jiosaavn_results = []
        jiosaavn_title = clean_query
        jiosaavn_artist = ""
    else:
        (
            jiosaavn_results,
            jiosaavn_title,
            jiosaavn_artist,
            _,
        ) = jiosaavn_result
    jiosaavn_track = resolve_jiosaavn_track(
        jiosaavn_results,
        clean_query,
        requested_by,
        requested_name,
    )
    if youtube_track is not None:
        # YouTube's uploader is usually a label/channel, not the singer.
        # Prefer the canonical JioSaavn artist metadata so Auto Find searches
        # for the singer's other songs (for example, Arijit Singh) rather than
        # searching the publishing channel.
        if jiosaavn_artist and (
            music_search_words(jiosaavn_title)
            & music_search_words(str(youtube_track.get("title") or ""))
        ):
            youtube_track["artist"] = jiosaavn_artist[:160]
        if jiosaavn_track is not None:
            youtube_track["_fallback_track"] = jiosaavn_track
        return youtube_track

    if jiosaavn_track is not None:
        source_urls = [
            str(source_url)
            for source_url in jiosaavn_track.get("download_urls", [])
            if str(source_url).strip()
        ]
        availability = await asyncio.gather(
            *(
                music_direct_url_available(source_url)
                for source_url in source_urls
            ),
            return_exceptions=True,
        )
        for source_url, available in zip(source_urls, availability):
            if available is True:
                jiosaavn_track["url"] = str(source_url)
                return jiosaavn_track
        log.info("JioSaavn returned an unavailable direct audio URL; trying fallbacks")
    raise LookupError("No playable song was found.")


def music_rebind_requester(
    track: dict[str, object],
    requested_by: int,
    requested_name: str,
) -> dict[str, object]:
    rebound = safe_copy_track(track) or {}
    rebound["requested_by"] = requested_by
    rebound["requested_name"] = requested_name[:100]
    fallback = rebound.get("_fallback_track")
    if isinstance(fallback, dict):
        fallback["requested_by"] = requested_by
        fallback["requested_name"] = requested_name[:100]
    fallbacks = rebound.get("_fallback_tracks")
    if isinstance(fallbacks, list):
        for candidate in fallbacks:
            if isinstance(candidate, dict):
                candidate["requested_by"] = requested_by
                candidate["requested_name"] = requested_name[:100]
    return rebound


async def resolve_music_track(
    query: str,
    requested_by: int,
    requested_name: str,
    is_video: bool = False,
) -> dict[str, object]:
    """Share an in-flight search when several groups request the same song."""
    clean_query = re.sub(r"\s+", " ", query).strip()
    res_tag = "resolve-video-v3" if is_video else "resolve-rank5-v3"
    resolution_key = music_cache_key(res_tag, clean_query)
    task = music_resolution_tasks.get(resolution_key)
    if task is None or task.done():
        task = asyncio.create_task(
            _resolve_music_track_uncached(
                clean_query,
                requested_by,
                requested_name,
                is_video=is_video,
            )
        )
        music_resolution_tasks[resolution_key] = task
    try:
        track = await asyncio.shield(task)
        asyncio.create_task(music_title_card_bytes(track))
        return music_rebind_requester(track, requested_by, requested_name)
    finally:
        if task.done() and music_resolution_tasks.get(resolution_key) is task:
            music_resolution_tasks.pop(resolution_key, None)


MUSIC_RECOMMENDATION_TITLE_STOP_WORDS = {
    "audio",
    "best",
    "full",
    "hd",
    "official",
    "song",
    "songs",
    "video",
    "lyrics",
    "lyric",
    "lyrical",
    "version",
    "original",
    "music",
}


def music_recommendation_title_tokens(value: object) -> list[str]:
    normalized = music_normalize(value)
    return [
        word
        for word in normalized.split()
        if word not in MUSIC_RECOMMENDATION_TITLE_STOP_WORDS
    ]


def music_same_song_family(
    current_title: object,
    candidate_title: object,
    artist: object = "",
) -> bool:
    """Reject another upload, lyric video, or short title variant."""
    current_tokens = music_recommendation_title_tokens(current_title)
    candidate_tokens = music_recommendation_title_tokens(candidate_title)
    if not current_tokens or not candidate_tokens:
        return False
    artist_words = set(music_normalize(artist).split())
    current_core = [word for word in current_tokens if word not in artist_words]
    candidate_core = [word for word in candidate_tokens if word not in artist_words]
    if len(current_core) >= 2 and len(candidate_core) >= 2:
        current_prefix = set(current_core[:3])
        candidate_prefix = set(candidate_core[:3])
        current_pairs = {
            tuple(current_core[index : index + 2])
            for index in range(min(5, len(current_core) - 1))
        }
        candidate_pairs = {
            tuple(candidate_core[index : index + 2])
            for index in range(min(3, len(candidate_core) - 1))
        }
        if (
            current_pairs.intersection(candidate_pairs)
            or (
            set(current_core[:2]).issubset(set(candidate_core[:3]))
            and set(candidate_core[:2]).issubset(set(current_core[:3]))
            )
        ) or (
            current_prefix.issubset(set(candidate_core))
            or candidate_prefix.issubset(set(current_core))
        ):
            return True
    overlap = len(set(current_core) & set(candidate_core))
    smaller = min(len(set(current_core)), len(set(candidate_core)))
    return overlap >= 3 and smaller > 0 and overlap / smaller >= 0.65


def music_auto_find_queries(track: dict[str, object]) -> list[str]:
    """Find the artist's other tracks before using a broad mood fallback."""
    title = re.sub(r"\s+", " ", str(track.get("title") or "")).strip()
    artist = re.sub(r"\s+", " ", str(track.get("artist") or "")).strip()
    if not title:
        return []
    queries: list[str] = []
    if artist:
        queries.extend([
            f"{artist} other songs official",
            f"{artist} popular songs",
            f"{artist} best songs playlist",
        ])
    # If the artist has no usable recommendation, choose a broadly popular
    # emotional track instead of returning another upload of the current song.
    queries.extend([
        "popular Hindi sad songs official audio",
        "best popular sad songs playlist",
    ])
    return list(dict.fromkeys(query[:MUSIC_MAX_QUERY_LENGTH] for query in queries))


async def resolve_music_recommendation(
    current_track: dict[str, object],
    requested_by: int,
    requested_name: str,
    queued_tracks: list[dict[str, object]],
) -> dict[str, object] | None:
    """Find one playable recommendation without returning the current song."""
    current_id = str(current_track.get("id") or "").strip()
    current_url = str(
        current_track.get("webpage_url") or current_track.get("url") or ""
    ).strip()
    current_title = current_track.get("title", "")
    current_artist = current_track.get("artist", "")
    queued_keys = {
        (
            str(item.get("id") or "").strip(),
            str(item.get("webpage_url") or item.get("url") or "").strip(),
            music_normalize(item.get("title", "")),
        )
        for item in queued_tracks
    }
    candidates: list[dict[str, object]] = []
    seen_urls: set[str] = set()
    for query in music_auto_find_queries(current_track):
        try:
            async with music_search_gate:
                entries = await run_music_blocking(
                    music_flat_search,
                    "ytsearch",
                    query,
                    8,
                )
        except Exception as error:
            log.info(
                "Auto Find YouTube search unavailable: %s",
                type(error).__name__,
            )
            continue
        for entry in entries:
            if not isinstance(entry, dict):
                continue
            video_id = str(entry.get("id") or "").strip()
            url = str(
                entry.get("webpage_url")
                or entry.get("original_url")
                or (f"https://www.youtube.com/watch?v={video_id}" if video_id else "")
            ).strip()
            title = str(entry.get("title") or "").strip()
            if not title or not url or url in seen_urls:
                continue
            if video_id and video_id == current_id:
                continue
            if current_url and url == current_url:
                continue
            title_words = music_search_words(title)
            # Do not queue another upload, lyric video, cover, or remix of the
            # currently playing song, even when the YouTube title is longer.
            if music_same_song_family(current_title, title, current_artist):
                continue
            if any(
                marker in f" {music_normalize(title)} "
                for marker in (
                    " cover ",
                    " remix ",
                    " mashup ",
                    " karaoke ",
                    " slowed ",
                    " reverb ",
                    " lyrics ",
                    " lyrical ",
                    " instrumental ",
                )
            ):
                continue
            try:
                duration = int(float(entry.get("duration") or 0))
            except (TypeError, ValueError):
                duration = 0
            if not MUSIC_MIN_DURATION_SECONDS <= duration <= MUSIC_DIRECT_URL_MAX_DURATION_SECONDS:
                continue
            candidate = {
                "id": video_id or url,
                "title": title,
                "url": url,
                "webpage_url": url,
                "duration": duration,
                "thumbnail": str(entry.get("thumbnail") or ""),
                "uploader": str(entry.get("uploader") or ""),
            }
            candidate_key = (
                str(candidate["id"]),
                url,
                music_normalize(title),
            )
            if candidate_key in queued_keys or any(
                music_same_song_family(
                    queued.get("title", ""),
                    title,
                    queued.get("artist", ""),
                )
                for queued in queued_tracks
            ):
                continue
            seen_urls.add(url)
            candidates.append(candidate)
        if len(candidates) >= 4:
            break

    for candidate in candidates:
        # Search results already contain a valid video id, title, duration, and
        # thumbnail. Do not perform a second yt-dlp metadata lookup here:
        # YouTube can allow search but reject repeated direct metadata probes
        # with "Sign in to confirm you're not a bot". The normal local buffer
        # path (or the configured NextGen provider) will validate/download the
        # audio when the queued item is prepared.
        candidate["source"] = "YouTube"
        candidate["requested_by"] = requested_by
        candidate["requested_name"] = requested_name[:100]
        candidate["query"] = str(candidate.get("title") or "")
        fallback = await lookup_jiosaavn_track(
            str(candidate.get("title") or ""),
            requested_by,
            requested_name,
        )
        if fallback is not None:
            candidate["_fallback_track"] = fallback
        return candidate
    return None


def music_prepared_cache_key(track: dict[str, object]) -> str:
    source = str(track.get("source") or "music").casefold()
    identity = str(
        track.get("id")
        or track.get("webpage_url")
        or track.get("url")
        or track.get("title")
        or ""
    ).strip()
    media_kind = "video" if track.get("is_video") else "audio"
    return f"{source}:{media_kind}:{identity}"


def music_release_prepared_cache(track: dict[str, object]) -> bool:
    cache_key = track.pop("_cache_key", None)
    if not isinstance(cache_key, str):
        return False
    entry = music_prepared_cache.get(cache_key)
    if entry is None:
        return False
    entry["refs"] = max(0, int(entry.get("refs", 0)) - 1)
    entry["last_used"] = time.monotonic()
    return True


def music_evict_prepared_cache() -> None:
    total_bytes = sum(
        int(entry.get("size", 0)) for entry in music_prepared_cache.values()
    )
    while (
        len(music_prepared_cache) > MUSIC_PREPARED_CACHE_MAX_ENTRIES
        or total_bytes > MUSIC_PREPARED_CACHE_MAX_BYTES
    ):
        candidates = [
            (key, entry)
            for key, entry in music_prepared_cache.items()
            if int(entry.get("refs", 0)) <= 0
        ]
        if not candidates:
            return
        cache_key, entry = min(
            candidates,
            key=lambda item: float(item[1].get("last_used", 0.0)),
        )
        music_prepared_cache.pop(cache_key, None)
        total_bytes -= int(entry.get("size", 0))
        path = Path(str(entry.get("path", "")))
        try:
            path.unlink(missing_ok=True)
            if (
                path.parent.parent == MUSIC_BUFFER_DIRECTORY
                and path.parent.name.startswith("download-")
            ):
                path.parent.rmdir()
        except OSError as error:
            log.debug(
                "Prepared music cache eviction cleanup failed: %s",
                type(error).__name__,
            )


def music_register_prepared_cache(
    track: dict[str, object],
    prepared_path: str,
) -> None:
    inherited_key = track.get("_cache_key")
    if isinstance(inherited_key, str) and inherited_key in music_prepared_cache:
        track["local_path"] = prepared_path
        return
    path = Path(prepared_path)
    try:
        size = path.stat().st_size
    except OSError:
        return
    cache_key = music_prepared_cache_key(track)
    old_entry = music_prepared_cache.get(cache_key)
    if old_entry is not None and str(old_entry.get("path")) == prepared_path:
        old_entry["refs"] = int(old_entry.get("refs", 0)) + 1
        old_entry["last_used"] = time.monotonic()
    else:
        if old_entry is not None:
            old_path = Path(str(old_entry.get("path", "")))
            old_path.unlink(missing_ok=True)
        music_prepared_cache[cache_key] = {
            "path": prepared_path,
            "size": size,
            "refs": 1,
            "last_used": time.monotonic(),
        }
    track["_cache_key"] = cache_key
    track["local_path"] = prepared_path
    music_evict_prepared_cache()


def cleanup_music_track(track: dict[str, object] | None) -> None:
    if not track:
        return
    local_path = track.pop("local_path", None)
    cache_owned = music_release_prepared_cache(track)
    if not local_path:
        if cache_owned:
            music_evict_prepared_cache()
        return
    if cache_owned:
        music_evict_prepared_cache()
        return
    try:
        path = Path(str(local_path))
        path.unlink(missing_ok=True)
        if (
            path.parent.parent == MUSIC_BUFFER_DIRECTORY
            and path.parent.name.startswith("download-")
        ):
            path.parent.rmdir()
    except OSError as error:
        log.warning("Music buffer cleanup failed: %s", type(error).__name__)


def cleanup_all_music_buffers() -> None:
    for track in list(music_current.values()):
        cleanup_music_track(track)
    for queue in list(music_queues.values()):
        for track in queue:
            cleanup_music_track(track)
    if MUSIC_BUFFER_DIRECTORY.is_dir():
        for path in (
            list(MUSIC_BUFFER_DIRECTORY.glob("track-*.audio"))
            + list(MUSIC_BUFFER_DIRECTORY.glob("mp3-*.mp3"))
        ):
            try:
                path.unlink(missing_ok=True)
            except OSError:
                pass
        for directory in MUSIC_BUFFER_DIRECTORY.glob("download-*"):
            if not directory.is_dir():
                continue
            for path in directory.iterdir():
                try:
                    path.unlink(missing_ok=True)
                except OSError:
                    pass
            try:
                directory.rmdir()
            except OSError:
                pass
    music_prepared_cache.clear()


def cancel_music_prefetch(chat_id: int) -> None:
    task = music_prefetch_tasks.pop(chat_id, None)
    if task is not None and not task.done():
        task.cancel()


async def prefetch_music_queue(chat_id: int) -> None:
    current_task = asyncio.current_task()
    try:
        while True:
            async with music_locks[chat_id]:
                queue = music_queues.get(chat_id)
                track = next(
                    (
                        item for item in queue or ()
                        if not item.get("_prefetch_done")
                    ),
                    None,
                )
            if track is None:
                return

            track["_prefetch_started"] = True
            try:
                async with music_buffer_gate:
                    await prepare_music_track(track)
            except asyncio.CancelledError:
                raise
            except Exception as error:
                track["_prefetch_error"] = voice_error_diagnostic(error)
                log.warning(
                    "Music queue prefetch failed for chat %s: %s",
                    chat_id,
                    type(error).__name__,
                )
            finally:
                track["_prefetch_done"] = True
                prefetch_event = track.get("_prefetch_event")
                if isinstance(prefetch_event, asyncio.Event):
                    prefetch_event.set()
    finally:
        if music_prefetch_tasks.get(chat_id) is current_task:
            music_prefetch_tasks.pop(chat_id, None)


def ensure_music_prefetch(chat_id: int) -> None:
    task = music_prefetch_tasks.get(chat_id)
    if task is None or task.done():
        music_prefetch_tasks[chat_id] = asyncio.create_task(
            prefetch_music_queue(chat_id)
        )


async def prepare_music_track(track: dict[str, object]) -> str:
    existing_path = track.get("local_path")
    if existing_path and Path(str(existing_path)).is_file():
        return str(existing_path)
    cache_key = music_prepared_cache_key(track)
    preparation_lock = music_preparation_locks[cache_key]
    async with preparation_lock:
        existing_path = track.get("local_path")
        if existing_path and Path(str(existing_path)).is_file():
            return str(existing_path)
        cached = music_prepared_cache.get(cache_key)
        cached_path = Path(str(cached.get("path", ""))) if cached else None
        if (
            cached
            and cached_path
            and cached_path.is_file()
        ):
            cached["refs"] = int(cached.get("refs", 0)) + 1
            cached["last_used"] = time.monotonic()
            track["_cache_key"] = cache_key
            track["local_path"] = str(cached_path)
            return str(cached_path)
        track.pop("_cache_key", None)
        prepared = await _prepare_music_track_uncached(track)
        inherited_key = track.get("_cache_key")
        if not (
            isinstance(inherited_key, str)
            and inherited_key in music_prepared_cache
        ):
            music_register_prepared_cache(track, prepared)
        return prepared


async def prepare_jiosaavn_fallback_for_track(
    track: dict[str, object],
) -> str | None:
    """Try a fresh direct source before slower or blocked YouTube paths."""
    fallback = track.get("_fallback_track")
    if not isinstance(fallback, dict):
        fallback = await lookup_jiosaavn_track(
            str(track.get("title") or ""),
            int(track.get("requested_by") or 0),
            str(track.get("requested_name") or "Player"),
        )
        if fallback is not None:
            track["_fallback_track"] = fallback
    if not isinstance(fallback, dict):
        return None
    try:
        prepared = await prepare_music_track(fallback)
    except Exception as error:
        log.info(
            "JioSaavn fallback preparation failed: %s",
            type(error).__name__,
        )
        return None
    track["local_path"] = prepared
    if isinstance(fallback.get("_cache_key"), str):
        track["_cache_key"] = fallback["_cache_key"]
    return prepared


async def prepare_shruti_music_track(track: dict[str, object]) -> str:
    """Download the selected YouTube result to a stable local audio file."""
    video_id = str(track.get("id") or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9_-]{11}", video_id):
        raise ValueError("Shruti API requires a valid YouTube video id.")
    if not shruti_configured():
        raise ValueError("Shruti API is not configured.")

    is_video = bool(track.get("is_video"))
    handle, raw_path = tempfile.mkstemp(
        prefix="track-",
        suffix=".mp4" if is_video else ".audio",
        dir=MUSIC_BUFFER_DIRECTORY,
    )
    os.close(handle)
    path = Path(raw_path)
    downloaded = 0
    max_bytes = MUSIC_MAX_BUFFER_BYTES * 4 if is_video else MUSIC_MAX_BUFFER_BYTES
    try:
        async with music_http.stream(
            "GET",
            f"{SHRUTI_API_URL}/download",
            params={
                "url": video_id,
                "type": "video" if is_video else "audio",
                "api_key": SHRUTI_API_KEY,
            },
            headers={
                "Accept": "*/*",
                "User-Agent": "Seyuki-Telegram-Bot/1.0",
            },
            timeout=httpx.Timeout(
                SHRUTI_API_TIMEOUT_SECONDS,
                connect=10.0,
            ),
        ) as response:
            response.raise_for_status()
            content_type = response.headers.get("content-type", "").casefold()
            if "application/json" in content_type or "text/html" in content_type:
                raise ValueError("Shruti API returned a non-media response.")
            content_length = int(response.headers.get("content-length") or 0)
            if content_length > max_bytes:
                raise ValueError("Shruti media file is too large.")
            with path.open("wb") as output:
                async for chunk in response.aiter_bytes(256 * 1024):
                    if not chunk:
                        continue
                    downloaded += len(chunk)
                    if downloaded > max_bytes:
                        raise ValueError("Shruti media file is too large.")
                    output.write(chunk)
        if downloaded < MUSIC_MIN_BUFFER_BYTES:
            raise ValueError("Shruti media download was incomplete.")
        track["local_path"] = str(path)
        return str(path)
    except Exception:
        path.unlink(missing_ok=True)
        raise


def adopt_prepared_youtube_candidate(
    track: dict[str, object],
    candidate: dict[str, object],
    prepared_path: str,
) -> None:
    """Make the now-playing card describe the candidate that actually played."""
    for field in (
        "id",
        "title",
        "artist",
        "duration",
        "url",
        "webpage_url",
        "thumbnail",
        "source",
        "query",
        "search_rank",
    ):
        if field in candidate:
            track[field] = candidate[field]
    track["local_path"] = prepared_path
    track.pop("_fallback_tracks", None)


async def prepare_youtube_candidate(track: dict[str, object]) -> str:
    """Prepare one ordered YouTube result without trying another rank."""
    if shruti_configured():
        try:
            return await prepare_shruti_music_track(track)
        except (ValueError, httpx.HTTPError) as provider_error:
            log.info(
                "Shruti API rejected YouTube rank %s (%s): %s",
                track.get("search_rank", 1),
                track.get("title", "unknown"),
                voice_error_detail(provider_error),
            )
    if nextgen_configured():
        try:
            return await prepare_nextgen_music_track(track)
        except (ValueError, httpx.HTTPError) as provider_error:
            try:
                return await prepare_downloadable_music_track(track)
            except Exception as local_error:
                raise local_error from provider_error
    return await prepare_downloadable_music_track(track)


async def _prepare_music_track_uncached(track: dict[str, object]) -> str:
    existing_path = track.get("local_path")
    if existing_path and Path(str(existing_path)).is_file():
        return str(existing_path)
    MUSIC_BUFFER_DIRECTORY.mkdir(parents=True, exist_ok=True)
    if track.get("is_video"):
        if shruti_configured():
            try:
                return await prepare_shruti_music_track(track)
            except (ValueError, httpx.HTTPError) as error:
                log.info(
                    "Shruti API video preparation failed for %s: %s",
                    track.get("title", "unknown"),
                    voice_error_detail(error),
                )
        return await prepare_downloadable_music_track(track)
    if track.get("source") == "JioSaavn":
        return await prepare_jiosaavn_music_track(track)
    if track.get("source") == "YouTube":
        # Keep the primary YouTube path aligned with ShrutixMusic: download
        # the selected video ID to a complete local file before PyTgCalls
        # receives it. Other providers remain recovery paths.
        if shruti_configured():
            try:
                return await prepare_shruti_music_track(track)
            except (ValueError, httpx.HTTPError) as error:
                log.info(
                    "Shruti API preparation failed for %s: %s",
                    track.get("title", "unknown"),
                    voice_error_detail(error),
                )
        if await prepare_jiosaavn_fallback_for_track(track) is not None:
            return str(track["local_path"])
    if track.get("source") == "YouTube":
        last_error: Exception | None = None
        if nextgen_configured():
            try:
                return await prepare_nextgen_music_track(track)
            except (ValueError, httpx.HTTPError) as error:
                last_error = error
                log.info(
                    "NextGen rejected YouTube rank %s (%s): %s",
                    track.get("search_rank", 1),
                    track.get("title", "unknown"),
                    voice_error_detail(error),
                )
        try:
            return await prepare_downloadable_music_track(track)
        except Exception as error:
            last_error = error
        candidates = track.get("_fallback_tracks", [])
        if isinstance(candidates, list):
            for candidate in candidates:
                if not isinstance(candidate, dict):
                    continue
                rank = int(candidate.get("search_rank") or 0)
                log.info(
                    "Trying YouTube rank %s after rank %s failed: %s",
                    rank,
                    track.get("search_rank", 1),
                    track.get("title", "unknown"),
                )
                try:
                    prepared = await prepare_youtube_candidate(candidate)
                    adopt_prepared_youtube_candidate(track, candidate, prepared)
                    log.info(
                        "Selected YouTube rank %s result: %s [%s]",
                        rank,
                        candidate.get("title", "unknown"),
                        candidate.get("id", "unknown"),
                    )
                    return prepared
                except Exception as error:
                    last_error = error
        if last_error is not None:
            raise last_error
        raise ValueError("No YouTube result could be prepared.")
    return await prepare_direct_music_track(track)


async def prepare_downloadable_music_track(track: dict[str, object]) -> str:
    """Download a YouTube result locally without provider coupling."""
    cookie_files = sorted(
        path for path in YOUTUBE_COOKIE_DIR.glob("*.txt") if path.is_file()
    )
    if not cookie_files:
        # AviaxMusic uses Netscape cookies for its yt-dlp fallback. Do not
        # invoke yt-dlp without them: YouTube currently returns a bot-check
        # page from this runtime, which only creates noisy false failures.
        raise ValueError("YouTube local fallback is not configured.")

    download_directory = Path(
        tempfile.mkdtemp(prefix="download-", dir=MUSIC_BUFFER_DIRECTORY)
    )
    output_template = str(download_directory / "track.%(ext)s")
    try:
        def download() -> None:
            options = {
                "format": ("best[height<=720]/best" if track.get("is_video") else "bestaudio"),
                "outtmpl": output_template,
                "quiet": True,
                "no_warnings": True,
                "noplaylist": True,
                "socket_timeout": 20,
                "retries": 3,
                "fragment_retries": 3,
                "cookiefile": str(cookie_files[0]),
                "logger": _QuietYoutubeLogger(),
            }
            with YoutubeDL(options) as downloader:
                downloader.download([str(track["url"])])

        await run_music_blocking(download)
        files = [
            path
            for path in download_directory.glob("track.*")
            if path.is_file() and not path.name.endswith(".part")
        ]
        if not files:
            raise ValueError("Music audio download was empty.")
        path = max(files, key=lambda candidate: candidate.stat().st_size)
        size = path.stat().st_size
        if not MUSIC_MIN_BUFFER_BYTES <= size <= MUSIC_MAX_BUFFER_BYTES:
            raise ValueError("Music audio file size is invalid.")
        track["local_path"] = str(path)
        return str(path)
    except Exception as error:
        for path in download_directory.iterdir():
            path.unlink(missing_ok=True)
        download_directory.rmdir()
        raise ValueError("YouTube local fallback failed.") from None


async def prepare_jiosaavn_music_track(track: dict[str, object]) -> str:
    """Try every fresh direct URL returned for a JioSaavn result."""
    raw_urls = track.get("download_urls")
    urls = list(raw_urls) if isinstance(raw_urls, list) else []
    first_url = str(track.get("url") or "").strip()
    if first_url:
        urls.insert(0, first_url)
    unique_urls = list(dict.fromkeys(url for url in urls if str(url).strip()))
    last_error: Exception = ValueError("Music source returned no audio URL.")
    for source_url in unique_urls:
        candidate = dict(track)
        candidate["url"] = str(source_url)
        try:
            prepared = await prepare_direct_music_track(candidate)
            track["local_path"] = prepared
            track["url"] = str(source_url)
            return prepared
        except Exception as error:
            last_error = error
            log.info(
                "Direct music URL failed; trying another result (%s)",
                type(error).__name__,
            )
    raise last_error


class NextGenKeyFailure(ValueError):
    """The current NextGen key should be retired temporarily."""


async def prepare_nextgen_music_track(track: dict[str, object]) -> str:
    video_id = str(track.get("id") or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9_-]{11}", video_id):
        raise ValueError("NextGen API requires a valid YouTube video id.")
    candidates = nextgen_candidate_keys()
    if not candidates:
        raise ValueError("NextGen API has no available keys.")
    last_error: Exception | None = None
    for key in candidates:
        try:
            return await prepare_nextgen_music_track_with_key(track, key, video_id)
        except NextGenKeyFailure as error:
            last_error = error
            await update_nextgen_key_health(
                key,
                success=False,
                reason=str(error) or "request failure",
            )
            log.warning("NextGen key rotation after an API failure; trying another key.")
        except (ValueError, httpx.HTTPError) as error:
            last_error = error
            raise
    raise ValueError("NextGen API request failed.") from last_error


async def prepare_nextgen_music_track_with_key(
    track: dict[str, object],
    key: dict[str, object],
    video_id: str,
) -> str:
    endpoint = f"{NEXTGEN_API_URL}/song/{video_id}"
    api_link = ""
    deadline = time.monotonic() + NEXTGEN_API_MAX_WAIT_SECONDS
    for attempt in range(NEXTGEN_API_RETRIES):
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            break
        request_timeout = min(12.0, max(2.0, remaining))
        try:
            response = await music_http.get(
                endpoint,
                params={"api": str(key["value"])},
                headers={"Accept": "application/json"},
                timeout=httpx.Timeout(
                    request_timeout,
                    connect=min(6.0, request_timeout),
                ),
            )
            if response.status_code in {402, 429}:
                raise NextGenKeyFailure("NextGen API quota or rate limit reached.")
            if response.status_code in {401, 403, 408, 409}:
                raise NextGenKeyFailure("NextGen API key request failed.")
            if response.status_code >= 500:
                raise NextGenKeyFailure("NextGen API key request failed.")
            if response.status_code >= 400:
                raise ValueError("NextGen API rejected this video.")
            response.raise_for_status()
            payload = response.json()
        except NextGenKeyFailure:
            raise
        except httpx.HTTPError as error:
            raise NextGenKeyFailure("NextGen API key request failed.") from error
        except ValueError as error:
            if attempt + 1 == NEXTGEN_API_RETRIES:
                raise ValueError("NextGen API request failed.") from error
            if "rejected this video" in str(error):
                raise
            await asyncio.sleep(min(NEXTGEN_API_POLL_SECONDS, max(0.1, remaining)))
            continue

        status = str(payload.get("status") or "").casefold()
        link = payload.get("link")
        if status == "done" and isinstance(link, str) and link.startswith(
            ("http://", "https://")
        ):
            api_link = link
            break
        if status not in {"downloading", "processing", "queued"}:
            if status in {"error", "failed", "failure", "limit", "quota"}:
                raise NextGenKeyFailure("NextGen API quota or rate limit reached.")
            raise ValueError("NextGen API did not return a playable audio link.")
        if attempt + 1 < NEXTGEN_API_RETRIES:
            await asyncio.sleep(
                min(NEXTGEN_API_POLL_SECONDS, max(0.1, deadline - time.monotonic()))
            )

    if not api_link:
        raise ValueError("NextGen API audio conversion timed out.")

    # Keep PyTgCalls on a stable local file. Probing a short-lived remote CDN
    # URL while joining the voice chat causes failures and playback stalls.
    handle, raw_path = tempfile.mkstemp(
        prefix="track-",
        suffix=(".mp4" if track.get("is_video") else ".audio"),
        dir=MUSIC_BUFFER_DIRECTORY,
    )
    os.close(handle)
    path = Path(raw_path)
    downloaded = 0
    try:
        async with music_http.stream(
            "GET",
            api_link,
            headers={"Accept": "audio/*", "User-Agent": "Seyuki-Telegram-Bot/1.0"},
        ) as response:
            response.raise_for_status()
            content_length = int(response.headers.get("content-length") or 0)
            if content_length > MUSIC_MAX_BUFFER_BYTES:
                raise ValueError("Music file is too large.")
            with path.open("wb") as output:
                async for chunk in response.aiter_bytes(256 * 1024):
                    if not chunk:
                        continue
                    downloaded += len(chunk)
                    if downloaded > MUSIC_MAX_BUFFER_BYTES:
                        raise ValueError("Music file is too large.")
                    output.write(chunk)
        if downloaded < MUSIC_MIN_BUFFER_BYTES:
            raise ValueError("NextGen audio download was incomplete.")
        track["local_path"] = str(path)
        await update_nextgen_key_health(key, success=True)
        return str(path)
    except Exception:
        path.unlink(missing_ok=True)
        raise


async def prepare_direct_music_track(track: dict[str, object]) -> str:
    handle, raw_path = tempfile.mkstemp(
        prefix="track-",
        suffix=(".mp4" if track.get("is_video") else ".audio"),
        dir=MUSIC_BUFFER_DIRECTORY,
    )
    os.close(handle)
    path = Path(raw_path)
    downloaded = 0
    try:
        async with music_http.stream(
            "GET",
            str(track["url"]),
            headers={"Accept": "*/*", "User-Agent": "Seyuki-Telegram-Bot/1.0"},
        ) as response:
            response.raise_for_status()
            content_length = int(response.headers.get("content-length") or 0)
            if content_length > MUSIC_MAX_BUFFER_BYTES:
                raise ValueError("Music file is too large.")
            with path.open("wb") as output:
                async for chunk in response.aiter_bytes(256 * 1024):
                    downloaded += len(chunk)
                    if downloaded > MUSIC_MAX_BUFFER_BYTES:
                        raise ValueError("Music file is too large.")
                    output.write(chunk)
        if downloaded < MUSIC_MIN_BUFFER_BYTES:
            raise ValueError("Music source returned incomplete audio.")
        track["local_path"] = str(path)
        return str(path)
    except Exception:
        path.unlink(missing_ok=True)
        raise


def music_download_filename(track: dict[str, object]) -> str:
    title = re.sub(r"[^A-Za-z0-9._ -]+", "", str(track.get("title", "")))
    title = re.sub(r"\s+", " ", title).strip()[:70]
    return f"{title or 'seyuki-song'}.mp3"


async def convert_music_track_to_mp3(track: dict[str, object]) -> Path:
    existing_path = track.get("local_path")
    source_track: dict[str, object] | None = None
    if existing_path and Path(str(existing_path)).is_file():
        source_path = Path(str(existing_path))
    else:
        source_track = dict(track)
        source_track.pop("_prefetch_event", None)
        source_track.pop("local_path", None)
        async with music_buffer_gate:
            source_path = Path(await prepare_music_track(source_track))

    handle, raw_path = tempfile.mkstemp(
        prefix="mp3-",
        suffix=".mp3",
        dir=MUSIC_BUFFER_DIRECTORY,
    )
    os.close(handle)
    output_path = Path(raw_path)
    try:
        def convert() -> None:
            result = subprocess.run(
                [
                    "ffmpeg",
                    "-y",
                    "-loglevel",
                    "error",
                    "-i",
                    str(source_path),
                    "-vn",
                    "-codec:a",
                    "libmp3lame",
                    "-b:a",
                    "192k",
                    str(output_path),
                ],
                capture_output=True,
                text=True,
                timeout=180,
            )
            if result.returncode != 0:
                raise RuntimeError("FFmpeg could not convert this song to MP3.")

        await run_music_blocking(convert)
        if not output_path.is_file() or output_path.stat().st_size < MUSIC_MIN_BUFFER_BYTES:
            raise RuntimeError("The converted MP3 file was incomplete.")
        return output_path
    except Exception:
        output_path.unlink(missing_ok=True)
        raise
    finally:
        if source_track is not None:
            cleanup_music_track(source_track)


async def send_music_mp3(
    chat_id: int,
    message: Message,
    track: dict[str, object],
) -> None:
    mp3_path: Path | None = None
    try:
        async with music_download_locks[chat_id]:
            mp3_path = await convert_music_track_to_mp3(track)
            await message.answer_audio(
                audio=FSInputFile(
                    str(mp3_path),
                    filename=music_download_filename(track),
                ),
                caption=(
                    f"🎵 {html.escape(str(track['title']))}\n"
                    "˹Dᴇsᴛʀᴏʏᴇʀ ꭙ ᴍᴜsɪᴄ ᴀssɪsᴛᴀɴᴛ MP3 download"
                ),
            )
    except (OSError, RuntimeError, ValueError, httpx.HTTPError) as error:
        log.warning(
            "Music MP3 download failed for chat %s: %s",
            chat_id,
            type(error).__name__,
        )
        try:
            await message.answer(
                "The MP3 download failed. Please try again later."
            )
        except Exception:
            pass
    finally:
        if mp3_path is not None:
            mp3_path.unlink(missing_ok=True)
        if music_download_tasks.get(chat_id) is asyncio.current_task():
            music_download_tasks.pop(chat_id, None)


def clean_song_title_for_lyrics(title: str) -> str:
    t = re.sub(
        r"(?i)\b(official|video|audio|lyrics?|full song|hd|4k|remix|lofi|version|teaser|trailer|feat|ft)\b",
        "",
        title,
    )
    t = re.sub(r"[|/\\\[\]\(\)\-_:•]", " ", t)
    return re.sub(r"\s+", " ", t).strip()


async def fetch_synced_lyrics(title: str, artist: str = "") -> str | None:
    query = clean_song_title_for_lyrics(title)
    if not query:
        return None
    try:
        url = f"https://lrclib.net/api/search?q={urllib.parse.quote_plus(query)}"
        async with httpx.AsyncClient(timeout=4.0) as client:
            resp = await client.get(url, headers={"User-Agent": "SeyukiBot/1.0"})
            if resp.status_code == 200:
                data = resp.json()
                for item in data:
                    if item.get("syncedLyrics"):
                        return str(item["syncedLyrics"])
    except Exception as e:
        log.debug("LRCLIB lyrics fetch failed for '%s': %s", query, e)
    return None


def parse_lrc_to_ass(
    lrc_text: str | None,
    start_sec: float,
    duration: float,
    ass_out_path: Path,
) -> bool:
    if not lrc_text:
        return False
    pattern = re.compile(r"\[(\d+):(\d+(?:\.\d+)?)\](.*)")
    entries = []
    for line in lrc_text.splitlines():
        line = line.strip()
        m = pattern.match(line)
        if m:
            mins = int(m.group(1))
            secs = float(m.group(2))
            t = mins * 60 + secs
            text = m.group(3).strip()
            if text:
                entries.append((t, text))
    if not entries:
        return False
    entries.sort(key=lambda x: x[0])

    end_sec = start_sec + duration
    matched = []
    for i, (t, text) in enumerate(entries):
        if t + 2.0 >= start_sec and t <= end_sec:
            next_t = entries[i + 1][0] if i + 1 < len(entries) else t + 4.0
            next_t = min(next_t, t + 5.5)
            rel_start = max(0.0, t - start_sec)
            rel_end = min(duration, next_t - start_sec)
            if rel_end > rel_start:
                matched.append((rel_start, rel_end, text))

    if not matched:
        return False

    def fmt_time(s: float) -> str:
        h = int(s // 3600)
        m = int((s % 3600) // 60)
        sec = s % 60
        return f"{h}:{m:02d}:{sec:05.2f}"

    lines = [
        "[Script Info]",
        "ScriptType: v4.00+",
        "PlayResX: 1080",
        "PlayResY: 1920",
        "",
        "[V4+ Styles]",
        "Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding",
        "Style: Default,Arial,48,&H00FFFFFF,&H000000FF,&H00000000,&H80000000,-1,0,0,0,100,100,0,0,1,3,2,2,40,40,420,1",
        "",
        "[Events]",
        "Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text",
    ]
    for s, e, txt in matched:
        clean_txt = txt.replace("{", "").replace("}", "")
        lines.append(f"Dialogue: 0,{fmt_time(s)},{fmt_time(e)},Default,,0,0,0,,{clean_txt}")

    try:
        with open(ass_out_path, "w", encoding="utf-8") as f:
            f.write("\n".join(lines))
        return True
    except Exception:
        return False


def create_reel_base_frame(
    artwork_bytes: bytes | None,
    title: str,
    requester: str,
    out_path: Path,
) -> None:
    W, H = 1080, 1920
    if artwork_bytes:
        try:
            art_img = Image.open(io.BytesIO(artwork_bytes)).convert("RGB")
        except Exception:
            art_img = Image.new("RGB", (720, 720), (28, 28, 38))
    else:
        art_img = Image.new("RGB", (720, 720), (28, 28, 38))

    bg = art_img.copy().resize((W, H), Image.Resampling.LANCZOS)
    bg = bg.filter(ImageFilter.GaussianBlur(radius=32))
    enhancer = ImageEnhance.Brightness(bg)
    bg = enhancer.enhance(0.40)

    card_size = 720
    card = art_img.copy().resize((card_size, card_size), Image.Resampling.LANCZOS)
    mask = Image.new("L", (card_size, card_size), 0)
    draw_mask = ImageDraw.Draw(mask)
    draw_mask.rounded_rectangle([(0, 0), (card_size, card_size)], radius=36, fill=255)

    card_x = (W - card_size) // 2
    card_y = 380
    bg.paste(card, (card_x, card_y), mask)

    draw = ImageDraw.Draw(bg)
    draw.rounded_rectangle(
        [(card_x, card_y), (card_x + card_size, card_y + card_size)],
        radius=36,
        outline=(255, 255, 255, 120),
        width=3,
    )

    draw.text((W // 2, 260), "🎵  DESTROYER MUSIC REEL  🎵", fill=(210, 230, 255), anchor="mm")
    clean_title = title[:46] + ("..." if len(title) > 46 else "")
    draw.text((W // 2, 1160), clean_title, fill=(255, 255, 255), anchor="mm")
    draw.text((W // 2, 1220), f"Requested by {requester[:30]}", fill=(185, 185, 195), anchor="mm")

    bg.save(out_path, format="PNG")


async def render_music_reel_file(
    source_audio_path: Path,
    base_frame_path: Path,
    ass_sub_path: Path | None,
    start_sec: int,
    duration: int,
    output_path: Path,
) -> None:
    def convert() -> None:
        filter_complex = (
            "[1:a]showwaves=s=800x120:mode=line:colors=0x00f0ff|0xff00ff:scale=cbrt[wave];"
            "[0:v][wave]overlay=x=(W-w)/2:y=1400[v1]"
        )
        if ass_sub_path and ass_sub_path.is_file():
            escaped_path = str(ass_sub_path.resolve()).replace("\\", "/").replace(":", "\\:")
            filter_complex += f";[v1]ass='{escaped_path}'[vout]"
        else:
            filter_complex += ";[v1]copy[vout]"

        cmd = [
            "ffmpeg", "-y",
            "-loop", "1", "-i", str(base_frame_path),
            "-ss", str(start_sec), "-t", str(duration), "-i", str(source_audio_path),
            "-filter_complex", filter_complex,
            "-map", "[vout]", "-map", "1:a",
            "-c:v", "libx264", "-preset", "ultrafast", "-crf", "24", "-pix_fmt", "yuv420p",
            "-c:a", "aac", "-b:a", "192k",
            "-shortest",
            str(output_path),
        ]
        res = subprocess.run(cmd, capture_output=True, text=True, timeout=120)
        if res.returncode != 0:
            raise RuntimeError(f"FFmpeg reel rendering failed: {res.stderr[-300:]}")

    await run_music_blocking(convert)


async def handle_music_download_request(
    message: Message,
    query: str | None = None,
) -> None:
    if message.chat.type not in {ChatType.GROUP, ChatType.SUPERGROUP}:
        await message.answer("❌ Yeh command sirf group Voice Chat ke liye hai.")
        return
    if not message.from_user or message.from_user.is_bot:
        return

    chat_id = message.chat.id
    status_msg = None
    temp_files: list[Path] = []
    try:
        track = None
        # 1. If explicit query given in command: /d [song name]
        if query:
            status_msg = await message.reply(
                '<tg-emoji emoji-id="5462956611033117422">💿</tg-emoji> <b>Searching Track...</b>\n\n'
                f'<blockquote><tg-emoji emoji-id="4958562566688211974">🎵</tg-emoji> <code>{html.escape(query)}</code>\n'
                f'<tg-emoji emoji-id="6267107057304868214">⚡️</tg-emoji> <i>Fetching best HD audio stream</i></blockquote>'
            )
            user_name = message.from_user.full_name or message.from_user.first_name or "User"
            track = await resolve_music_track(query, message.from_user.id, user_name)
        else:
            # 2. Check current playing song in this chat
            async with music_locks[chat_id]:
                current_track = music_current.get(chat_id)
                if current_track:
                    track = dict(current_track)

            if not track:
                await message.reply(
                    '<tg-emoji emoji-id="5454350746407419714">❌</tg-emoji> <b>Currently voice chat me koi song play nahi ho raha hai!</b>\n\n'
                    '<blockquote>'
                    '👉 Playing song download karne ke liye use reply karke <code>/d</code> bhejein,\n'
                    '👉 Ya direct gaana download karne ke liye: <code>/d [song name]</code> likhein.'
                    '</blockquote>'
                )
                return

            status_msg = await message.reply(
                '<tg-emoji emoji-id="6267107057304868214">⚡️</tg-emoji> <i>Preparing instant audio download...</i>'
            )

        # 3. Get audio source path
        MUSIC_BUFFER_DIRECTORY.mkdir(parents=True, exist_ok=True)
        source_path_str = None
        local_path = track.get("local_path")
        if local_path and Path(str(local_path)).is_file():
            source_path_str = str(local_path)
        else:
            source_path_str = await prepare_music_track(track)

        if not source_path_str or not Path(source_path_str).is_file():
            raise RuntimeError("Audio stream could not be loaded.")

        src_file = Path(source_path_str)

        # 4. Fast packaging to m4a (instant stream copy)
        clean_title = re.sub(r"[^\w\s-]", "", str(track.get("title") or "Song")).strip()[:45] or "Song"
        artist_name = str(track.get("artist") or track.get("uploader") or "˹Dᴇsᴛʀᴏʏᴇʀ ꭙ Bʜꫝɪ Music").strip()[:45]
        duration_sec = int(track.get("duration") or 0)
        dur_str = f"{music_duration_text(duration_sec)} Min" if duration_sec else "Audio"

        out_audio = MUSIC_BUFFER_DIRECTORY / f"dl-{secrets.token_hex(6)}.m4a"
        temp_files.append(out_audio)

        def export_audio():
            cmd_copy = ["ffmpeg", "-y", "-loglevel", "error", "-i", str(src_file), "-vn", "-c:a", "copy", str(out_audio)]
            p = subprocess.run(cmd_copy, timeout=15)
            if p.returncode != 0 or not out_audio.is_file() or out_audio.stat().st_size < 1000:
                cmd_enc = ["ffmpeg", "-y", "-loglevel", "error", "-i", str(src_file), "-vn", "-c:a", "aac", "-b:a", "192k", str(out_audio)]
                subprocess.run(cmd_enc, timeout=30, check=True)

        await run_music_blocking(export_audio)

        if not (out_audio.is_file() and out_audio.stat().st_size > 5000):
            raise RuntimeError("Audio export resulted in an empty file.")

        # 5. Extract cover art for thumbnail
        thumb_path = None
        art_bytes = track.get("art_bytes")
        if isinstance(art_bytes, (bytes, bytearray)) and len(art_bytes) > 100:
            thumb_file = MUSIC_BUFFER_DIRECTORY / f"thumb-{secrets.token_hex(6)}.jpg"
            temp_files.append(thumb_file)
            try:
                thumb_file.write_bytes(bytes(art_bytes))
                thumb_path = thumb_file
            except Exception:
                thumb_path = None

        # 6. Send Audio with Stylish Blockquote & Premium Emojis
        user_mention = html.escape(message.from_user.full_name or message.from_user.first_name)
        user_id = message.from_user.id
        user_link = f'<a href="tg://user?id={user_id}">{user_mention}</a>'

        raw_song_title = str(track.get("title") or clean_title)
        clean_song_title = clean_music_title(raw_song_title, max_len=60)
        song_title = html.escape(clean_song_title)

        title_url = str(track.get("webpage_url") or track.get("url") or "")
        if title_url.startswith(("http://", "https://")):
            song_link = f'<a href="{html.escape(title_url, quote=True)}">{song_title}</a>'
        else:
            song_link = song_title

        dur_text = f"{music_duration_text(duration_sec)} Minutes" if duration_sec else "Audio Stream"
        seyuki_brand = f'<a href="https://t.me/{bot_username}">˹Dᴇsᴛʀᴏʏᴇʀ ꭙ ᴍᴜsɪᴄ ᴀssɪsᴛᴀɴᴛ</a>' if bot_username else "˹Dᴇsᴛʀᴏʏᴇʀ ꭙ ᴍᴜsɪᴄ ᴀssɪsᴛᴀɴᴛ"

        caption = (
            f'<tg-emoji emoji-id="5462956611033117422">💿</tg-emoji> <b>Downloaded Track</b> <tg-emoji emoji-id="4958489311726011319">✨</tg-emoji>\n\n'
            f'<tg-emoji emoji-id="4958562566688211974">🎵</tg-emoji> <b>Track :</b> {song_link}\n\n'
            f'<blockquote>'
            f'<tg-emoji emoji-id="5373236586760651455">⏱️</tg-emoji> <b>Duration :</b> <code>{dur_text}</code>\n'
            f'<tg-emoji emoji-id="6266995104687330978">👑</tg-emoji> <b>Downloaded By :</b> {user_link}\n'
            f'<tg-emoji emoji-id="6267107057304868214">⚡️</tg-emoji> <b>Audio Quality :</b> <i>320kbps • {seyuki_brand} HD</i>'
            f'</blockquote>'
        )

        await message.reply_audio(
            audio=FSInputFile(str(out_audio), filename=f"{clean_title}.m4a"),
            title=str(track.get("title") or clean_title),
            performer=artist_name,
            duration=duration_sec,
            thumbnail=FSInputFile(str(thumb_path)) if thumb_path and thumb_path.is_file() else None,
            caption=caption,
        )

        if status_msg:
            try:
                await status_msg.delete()
            except Exception:
                pass
    except Exception as e:
        log.exception("Music download failed for chat %s", chat_id)
        if status_msg:
            try:
                await status_msg.edit_text(
                    f'<tg-emoji emoji-id="5454350746407419714">❌</tg-emoji> <b>Download failed:</b> <code>{html.escape(str(e)[:160])}</code>'
                )
            except Exception:
                pass
    finally:
        for f in temp_files:
            try:
                if f and f.is_file():
                    f.unlink(missing_ok=True)
            except Exception:
                pass


async def handle_music_reel_request(
    chat_id: int,
    user: User,
    message: Message,
    duration_arg: int = 30,
) -> None:
    status_msg = None
    temp_files: list[Path] = []
    try:
        async with music_locks[chat_id]:
            current_track = music_current.get(chat_id)
            track = dict(current_track) if current_track else None

        if not track:
            await message.reply(
                "❌ <b>Currently voice chat me koi song play nahi ho raha hai!</b>\n\n"
                "Pehle <code>/play [song name]</code> karke gaana lagayein, phir <code>/edit 30</code> tag/reply karein."
            )
            return

        duration = max(10, min(60, duration_arg))
        started_at = music_started_at.get(chat_id)
        track_dur = max(30, int(track.get("duration") or 240))
        if started_at:
            elapsed = max(0, int(time.monotonic() - started_at))
        else:
            elapsed = 0

        if elapsed + duration > track_dur:
            start_sec = max(0, track_dur - duration)
        else:
            start_sec = elapsed

        song_title = str(track.get("title") or "Unknown Song")
        status_msg = await message.reply(
            f"🎬 <b>Generating Real 9:16 Instagram Reel...</b>\n\n"
            f"🎵 <b>Song:</b> <code>{html.escape(song_title)}</code>\n"
            f"⏱ <b>Clip:</b> <code>{start_sec}s - {start_sec + duration}s ({duration}s)</code>\n"
            f"✨ <i>Downloading official video & rendering vertical HD Reel...</i>"
        )

        track_clean_id = re.sub(r"[^A-Za-z0-9_-]+", "", str(track.get("id") or song_title))[:28]
        cache_path = REELS_CACHE_DIRECTORY / f"reel_{track_clean_id}_{start_sec}_{duration}.mp4"

        if not (cache_path.is_file() and cache_path.stat().st_size > 100000):
            # 1. Determine YouTube Video URL
            youtube_url = None
            raw_id = str(track.get("id") or "").strip()
            if re.fullmatch(r"[A-Za-z0-9_-]{11}", raw_id):
                youtube_url = f"https://www.youtube.com/watch?v={raw_id}"
            else:
                wp = str(track.get("webpage_url") or track.get("url") or "")
                if "youtube.com" in wp or "youtu.be" in wp:
                    youtube_url = wp
                else:
                    q = clean_song_title_for_lyrics(song_title)
                    youtube_url = f"ytsearch1:{q}"

            # 2. Download Real Video
            raw_vid_handle, raw_vid_path = tempfile.mkstemp(prefix="reel-src-", suffix=".mp4", dir=MUSIC_BUFFER_DIRECTORY)
            os.close(raw_vid_handle)
            raw_video = Path(raw_vid_path)
            temp_files.append(raw_video)

            def dl_video():
                ydl_opts = {
                    "format": "best[height<=480][ext=mp4]/best[height<=480]/best[ext=mp4]/best",
                    "outtmpl": str(raw_video),
                    "quiet": True,
                    "no_warnings": True,
                    "noplaylist": True,
                    "extractor_args": {"youtube": {"player_client": ["android"]}},
                    "socket_timeout": 15,
                    "retries": 2,
                }
                with YoutubeDL(ydl_opts) as ydl:
                    ydl.download([youtube_url])

            await run_music_blocking(dl_video)

            if not (raw_video.is_file() and raw_video.stat().st_size > 10000):
                raise RuntimeError("Could not download YouTube video stream for this song.")

            # 3. Optional Subtitles / Lyrics (safe with timeout)
            ass_path = None
            try:
                lrc_text = await asyncio.wait_for(
                    fetch_synced_lyrics(song_title, str(track.get("artist") or "")),
                    timeout=2.0,
                )
                if lrc_text:
                    handle_ass, path_ass = tempfile.mkstemp(prefix="reel-sub-", suffix=".ass", dir=MUSIC_BUFFER_DIRECTORY)
                    os.close(handle_ass)
                    ass_path = Path(path_ass)
                    temp_files.append(ass_path)
                    if not parse_lrc_to_ass(lrc_text, float(start_sec), float(duration), ass_path):
                        ass_path = None
            except Exception:
                ass_path = None

            # 4. Render with FFmpeg (real video 9:16 vertical)
            handle_out, path_out = tempfile.mkstemp(prefix="reel-out-", suffix=".mp4", dir=MUSIC_BUFFER_DIRECTORY)
            os.close(handle_out)
            temp_out = Path(path_out)
            temp_files.append(temp_out)

            def render_clip():
                filter_complex = (
                    "[0:v]split=2[bg_in][fg_in];"
                    "[bg_in]scale=720:1280:force_original_aspect_ratio=increase,crop=720:1280,boxblur=20:5,eq=brightness=-0.12:saturation=1.2[bg];"
                    "[fg_in]scale=720:-2:force_original_aspect_ratio=decrease[fg];"
                    "[bg][fg]overlay=x=(W-w)/2:y=(H-h)/2[v1]"
                )
                if ass_path and ass_path.is_file():
                    escaped_path = str(ass_path.resolve()).replace("\\", "/").replace(":", "\\:")
                    filter_complex += f";[v1]ass='{escaped_path}'[vout]"
                else:
                    filter_complex += ";[v1]copy[vout]"

                cmd = [
                    "ffmpeg", "-y",
                    "-ss", str(start_sec),
                    "-i", str(raw_video),
                    "-t", str(duration),
                    "-filter_complex", filter_complex,
                    "-map", "[vout]", "-map", "0:a",
                    "-c:v", "libx264", "-preset", "ultrafast", "-crf", "24", "-pix_fmt", "yuv420p",
                    "-c:a", "aac", "-b:a", "192k",
                    str(temp_out),
                ]
                res = subprocess.run(cmd, capture_output=True, text=True, timeout=120)
                if res.returncode != 0:
                    raise RuntimeError(f"FFmpeg failed: {res.stderr[-300:]}")

            await run_music_blocking(render_clip)

            if temp_out.is_file() and temp_out.stat().st_size > 50000:
                shutil.copyfile(temp_out, cache_path)

        # 5. Send Video
        user_name = html.escape(user.full_name or user.first_name)
        user_link = f'<a href="tg://user?id={user.id}">{user_name}</a>'
        clean_reel_title = html.escape(clean_music_title(song_title, max_len=60))
        seyuki_brand = f'<a href="https://t.me/{bot_username}">˹Dᴇsᴛʀᴏʏᴇʀ ꭙ ᴍᴜsɪᴄ ᴀssɪsᴛᴀɴᴛ</a>' if bot_username else "˹Dᴇsᴛʀᴏʏᴇʀ ꭙ ᴍᴜsɪᴄ ᴀssɪsᴛᴀɴᴛ"
        caption = (
            f'<tg-emoji emoji-id="5462956611033117422">🎬</tg-emoji> <b>Generated Music Reel</b> <tg-emoji emoji-id="4958489311726011319">✨</tg-emoji>\n\n'
            f'<tg-emoji emoji-id="5462956611033117422">🎬</tg-emoji> <b>Track :</b> {clean_reel_title}\n\n'
            f'<blockquote>'
            f'<tg-emoji emoji-id="5373236586760651455">⏱️</tg-emoji> <b>Duration :</b> <code>{duration}s (HD 9:16)</code>\n'
            f'<tg-emoji emoji-id="6266995104687330978">👑</tg-emoji> <b>Created For :</b> {user_link}\n'
            f'<tg-emoji emoji-id="6267107057304868214">⚡️</tg-emoji> <b>Quality :</b> <i>1080p FHD • {seyuki_brand}</i>'
            f'</blockquote>'
        )

        await message.reply_video(
            video=FSInputFile(str(cache_path), filename=f"reel_{track_clean_id}.mp4"),
            caption=caption,
            width=720,
            height=1280,
            supports_streaming=True,
        )
        if status_msg:
            try:
                await status_msg.delete()
            except Exception:
                pass
    except Exception as e:
        log.exception("Music reel creation failed for chat %s", chat_id)
        if status_msg:
            try:
                await status_msg.edit_text(f"❌ <b>Reel generate nahi ho payi:</b> {html.escape(str(e))}")
            except Exception:
                pass
    finally:
        for p in temp_files:
            try:
                if p.is_file():
                    p.unlink(missing_ok=True)
            except Exception:
                pass
        music_reel_tasks.pop(chat_id, None)




def clean_music_title(raw_title: str, max_len: int = 65) -> str:
    t = str(raw_title or "Unknown Track").strip()
    cleaned = t

    # Remove brackets containing promo/junk keywords
    cleaned = re.sub(
        r"(?i)\s*[\(\[\{][^\)\]\}]*(?:official|lyric|lyrics?|4k|hd\b|remix|slowed|reverb)[^\)\]\}]*[\)\]\}]",
        "",
        cleaned,
    )

    # Remove phrases like 'full video song', 'official music video'
    cleaned = re.sub(
        r"(?i)\b(?:full\s*video(?:\s*song)?|full\s*(?:audio|song)|official\s*(?:video|audio|music\s*video)|lyric\s*video)\b",
        "",
        cleaned,
    )

    # Clean trailing noise, dashes, dots, pipes
    cleaned = re.sub(r"[\s\-_:•|/]+$", "", cleaned).strip()

    if len(cleaned) < 2:
        cleaned = t

    if len(cleaned) > max_len:
        cleaned = cleaned[:max_len].rsplit(" ", 1)[0] + "…"

    return cleaned


