        f'<tg-emoji emoji-id="6266995104687330978">👑</tg-emoji> <b>Requested By :</b> {requester}\n'
        f'<tg-emoji emoji-id="6267107057304868214">⚡️</tg-emoji> <b>{media_label} :</b> <i>{media_val}</i>'
