music_recently_played_artists: dict[int, deque[str]] = defaultdict(lambda: deque(maxlen=15))


async def get_next_autoplay_track(chat_id: int) -> dict[str, object] | None:
    recent_songs = music_recently_played[chat_id]
    recent_artists = music_recently_played_artists[chat_id]

    # Tier 1: 100% Dynamic Random YouTube Search for completely fresh & infinite variety!
    search_queries = list(AUTOPLAY_SEARCH_SEEDS)
    random.shuffle(search_queries)

    current_track = music_current.get(chat_id)
    if current_track:
        current_artist = str(current_track.get("artist") or "").strip()
        if current_artist and current_artist.casefold() not in [a.casefold() for a in recent_artists]:
            search_queries.insert(0, f"{current_artist} best popular songs official")

    for seed in search_queries[:4]:
        try:
            entries = await run_music_blocking(music_flat_search, "ytsearch", seed, 12)
            if entries:
                valid_candidates = []
                for entry in entries:
                    if not isinstance(entry, dict):
                        continue
                    title = str(entry.get("title") or "").strip()
                    if not title:
                        continue
                    norm_title = music_normalize(title)
                    # Filter out long compilations/jukeboxes (>12 mins)
                    duration = entry.get("duration")
                    if isinstance(duration, (int, float)) and (duration > 12 * 60 or duration < 30):
                        continue
                    if any(w in norm_title for w in ("jukebox", "compilation", "full album", "nonstop", "1 hour", "2 hour", "podcast")):
                        continue
                    # Skip if played recently
                    if any(r in norm_title or norm_title in r for r in recent_songs):
                        continue
                    valid_candidates.append(entry)

                if valid_candidates:
                    random.shuffle(valid_candidates)
                    for candidate in valid_candidates[:3]:
                        cand_title = str(candidate.get("title") or "").strip()
                        track = await resolve_music_track(
                            cand_title,
                            0,
                            "˹Dᴇsᴛʀᴏʏᴇʀ ꭙ ᴍᴜsɪᴄ ᴀssɪsᴛᴀɴᴛ",
                            is_video=False,
                        )
                        if track:
                            track["is_video"] = False
                            track.pop("_prefetch_event", None)
                            track_title = str(track.get("title") or cand_title)
                            recent_songs.append(music_normalize(track_title))
                            track_artist = str(track.get("artist") or "")
                            if track_artist:
                                recent_artists.append(track_artist.casefold())
                            track["requested_name"] = "˹Dᴇsᴛʀᴏʏᴇʀ ꭙ ᴍᴜsɪᴄ ᴀssɪsᴛᴀɴᴛ"
                            track["_chat_id"] = chat_id
                            return track
        except Exception as err:
            log.warning("Autoplay dynamic search error for '%s': %s", seed, err)

    # Tier 2: Fallback to the expanded catalog if dynamic search had no valid tracks
    available = [
        item for item in AUTOPLAY_HITS_CATALOG
        if item["song"].casefold() not in recent_songs
        and not any(item["song"].casefold() in s for s in recent_songs)
    ]
    if not available:
        recent_songs.clear()
        available = list(AUTOPLAY_HITS_CATALOG)

    diverse = [
        item for item in available
        if item["artist"].casefold() not in [a.casefold() for a in recent_artists]
    ]
    candidates = diverse if diverse else available
    pool = list(candidates)
    random.shuffle(pool)

    for item in pool[:6]:
        song_query = item["song"]
        artist_name = item["artist"]
        try:
            track = await resolve_music_track(
                song_query,
                0,
                "˹Dᴇsᴛʀᴏʏᴇʀ ꭙ ᴍᴜsɪᴄ ᴀssɪsᴛᴀɴᴛ",
                is_video=False,
            )
            if track:
                track["is_video"] = False
                track.pop("_prefetch_event", None)
                recent_songs.append(song_query.casefold())
                recent_artists.append(artist_name.casefold())
                track["requested_name"] = "˹Dᴇsᴛʀᴏʏᴇʀ ꭙ ᴍᴜsɪᴄ ᴀssɪsᴛᴀɴᴛ"
                track["_chat_id"] = chat_id
                return track
        except Exception as err:
            log.warning("Autoplay track resolve error for '%s': %s", song_query, err)
    return None


