@router.message(Command("stop", ignore_case=True))
async def stop_music(message: Message) -> None:
    if message.chat.type not in {ChatType.GROUP, ChatType.SUPERGROUP}:
        await message.answer("Use this command in a group.")
        return
    if not message.from_user:
        return
    if not await music_action_allowed_for_user(
        message.chat.id,
        message.from_user.id,
    ):
        await message.answer(
            "<b>Music access is restricted in this group.</b>\n"
            "Ask a group admin to authorize you with <code>/auth on</code>."
        )
        return
    queue_id = await save_vc_queue_snapshot(message.chat.id)
    if await stop_music_session(message.chat.id):
        if queue_id:
            markup = InlineKeyboardMarkup(
                inline_keyboard=[
                    [
                        InlineKeyboardButton(
                            text="🔄 Resume Queue",
                            callback_data=f"music:restore:{message.chat.id}:{queue_id}",
                        )
                    ]
                ]
            )
            await message.answer(
                f'''<tg-emoji emoji-id="5453921696354419743">📻</tg-emoji> <b>Music Stopped & Queue Saved!</b>\n\n<blockquote><tg-emoji emoji-id="5462956611033117422">💿</tg-emoji> <b>Saved Queue ID:</b> <code>{queue_id}</code>\n⏱️ <i>30 minutes ke andar resume karne ke liye:</i>\n👉 <code>/que {queue_id}</code></blockquote>''',
                reply_markup=markup,
            )
        else:
            await message.answer(
                "Music stopped, the queue was cleared, and the Voice Chat was left."
            )
    else:
        await message.answer("No music session is currently active.")


