def locate_font(family: str, fallback: str) -> str:
    try:
        result = subprocess.run(
            ["fc-match", "-f", "%{file}", family],
            capture_output=True,
            text=True,
            timeout=2,
            check=True,
        )
        return result.stdout.strip() or fallback
    except (OSError, subprocess.SubprocessError):
        return fallback


