def sticker_font_family_for_char(
    char: str,
    previous_family: str | None = None,
) -> str:
    codepoint = ord(char)
    category = unicodedata.category(char)
    if (
        previous_family
        and (category.startswith("M") or codepoint in {0x200C, 0x200D, 0xFE0E, 0xFE0F})
    ):
        return previous_family
    if codepoint >= 0x1F000 or category in {"So", "Sk"}:
        return "Noto Sans Symbols 2"
    character_name = unicodedata.name(char, "")
    for marker, family in STICKER_FONT_RULES:
        if marker in character_name:
            return family
    return "Noto Sans"


@lru_cache(maxsize=128)
def sticker_font_path_for_family(family: str) -> str:
    fallback = (
        STICKER_FALLBACK_FONT_PATH
        if family == "Noto Sans"
        else locate_font("Noto Sans Living", STICKER_FALLBACK_FONT_PATH)
    )
    return locate_font(family, fallback)


def sticker_font_runs(text: str) -> list[tuple[str, str]]:
    runs: list[tuple[str, str]] = []
    current_family: str | None = None
    current_text = ""
    for char in text:
        family = sticker_font_family_for_char(char, current_family)
        if current_text and family != current_family:
            runs.append((current_text, current_family or "Noto Sans"))
            current_text = ""
        current_text += char
        current_family = family
    if current_text:
        runs.append((current_text, current_family or "Noto Sans"))
    return runs


def sticker_font_objects(
    text: str,
    size: int,
) -> list[tuple[str, ImageFont.FreeTypeFont]]:
    return [
        (run, ImageFont.truetype(sticker_font_path_for_family(family), size))
        for run, family in sticker_font_runs(text)
    ]


def measure_sticker_rich_text(
    probe: ImageDraw.ImageDraw,
    text: str,
    size: int,
    stroke_width: int = 0,
) -> float:
    return sum(
        (
            lambda box: box[2] - box[0]
        )(probe.textbbox((0, 0), run, font=font, stroke_width=stroke_width))
        for run, font in sticker_font_objects(text, size)
    )


def fit_sticker_name(
    text: str,
    max_width: int,
    probe: ImageDraw.ImageDraw,
) -> tuple[str, int]:
    text = normalize_sticker_text(re.sub(r"\s+", " ", text).strip()) or "User"
    for size in range(24, 11, -1):
        if measure_sticker_rich_text(probe, text, size, stroke_width=1) <= max_width:
            return text, size
        for end in range(len(text), 0, -1):
            candidate = text[:end].rstrip() + "..."
            if measure_sticker_rich_text(probe, candidate, size, stroke_width=1) <= max_width:
                return candidate, size
    return "User", 12


def draw_sticker_rich_text(
    image: Image.Image,
    draw: ImageDraw.ImageDraw,
    position: tuple[float, float],
    text: str,
    size: int,
    fill: tuple[int, int, int, int],
    stroke_width: int = 0,
    stroke_fill: tuple[int, int, int, int] | None = None,
) -> None:
    x, y = position
    probe = ImageDraw.Draw(Image.new("RGBA", (1, 1)))
    for run, font in sticker_font_objects(text, size):
        with Pilmoji(image, draw=draw) as emoji_draw:
            emoji_draw.text(
                (x, y),
                run,
                font=font,
                fill=fill,
                stroke_width=stroke_width,
                stroke_fill=stroke_fill,
                embedded_color=True,
            )
        x += probe.textlength(run, font=font)


DEVANAGARI_FONT_PATH = locate_font(
    "Noto Sans Devanagari",
    "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
)
DEVANAGARI_FONT_PATHS = list(dict.fromkeys([
    DEVANAGARI_FONT_PATH,
    locate_font(
        "Noto Serif Devanagari",
        "/usr/share/fonts/truetype/dejavu/DejaVuSerif-Bold.ttf",
    ),
    "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
]))
LATIN_FONT_PATHS = list(dict.fromkeys([
    locate_font("Noto Sans", "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"),
    locate_font("Noto Serif", "/usr/share/fonts/truetype/dejavu/DejaVuSerif-Bold.ttf"),
    locate_font("Noto Sans Mono", "/usr/share/fonts/truetype/dejavu/DejaVuSansMono-Bold.ttf"),
    locate_font("Noto Serif Display", "/usr/share/fonts/truetype/dejavu/DejaVuSerif-Bold.ttf"),
    locate_font("DejaVu Sans", "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"),
    locate_font("DejaVu Serif", "/usr/share/fonts/truetype/dejavu/DejaVuSerif-Bold.ttf"),
    locate_font("DejaVu Sans Mono", "/usr/share/fonts/truetype/dejavu/DejaVuSansMono-Bold.ttf"),
]))
TEMPLATE_NAMES = [
    "dots", "sunset", "grid", "hearts", "waves", "confetti", "neon", "paper",
    "bubbles", "diagonal", "leaves", "checker", "flowers", "roses", "galaxy",
    "stars", "moon", "butterflies", "clouds", "rainbow",
]
BASE_STICKER_STYLES = [
    (
        LATIN_FONT_PATHS[index % len(LATIN_FONT_PATHS)],
        color,
        outline,
        TEMPLATE_NAMES[index],
    )
    for index, (_, color, outline, _) in enumerate(
        (STICKER_FONT_PATHS * 2)[:len(TEMPLATE_NAMES)]
    )
]
# 100 combinations: 20 clean, decorative backgrounds × 5 color/layout variants.
STICKER_STYLES = [
    (font, color, outline, template, variant)
    for variant in range(5)
    for font, color, outline, template in BASE_STICKER_STYLES
]


def draw_sticker_background(draw: ImageDraw.ImageDraw, template: str, variant: int = 0) -> None:
    """Draw one of several playful templates behind the text."""
    palettes = {
        "dots": ((238, 225, 255, 255), (185, 145, 230, 120)),
        "sunset": ((255, 218, 190, 255), (240, 140, 150, 150)),
        "grid": ((205, 245, 235, 255), (50, 155, 130, 100)),
        "hearts": ((255, 220, 230, 255), (225, 90, 135, 150)),
        "waves": ((255, 238, 185, 255), (235, 170, 60, 130)),
        "confetti": ((218, 225, 255, 255), (100, 120, 220, 130)),
        "neon": ((45, 40, 65, 255), (230, 100, 255, 160)),
        "paper": ((246, 225, 196, 255), (180, 125, 80, 110)),
        "bubbles": ((195, 240, 255, 255), (70, 175, 220, 130)),
        "diagonal": ((235, 215, 250, 255), (150, 90, 190, 130)),
        "leaves": ((210, 245, 205, 255), (80, 160, 75, 130)),
        "checker": ((255, 220, 205, 255), (220, 100, 90, 120)),
        "flowers": ((255, 235, 246, 255), (225, 120, 175, 150)),
        "roses": ((255, 220, 225, 255), (185, 45, 80, 150)),
        "galaxy": ((35, 35, 92, 255), (125, 160, 255, 180)),
        "stars": ((35, 55, 115, 255), (255, 225, 95, 180)),
        "moon": ((215, 225, 255, 255), (70, 90, 160, 150)),
        "butterflies": ((225, 245, 255, 255), (85, 150, 210, 150)),
        "clouds": ((220, 240, 255, 255), (125, 180, 225, 130)),
        "rainbow": ((255, 240, 205, 255), (220, 90, 120, 150)),
    }
    base, accent = palettes[template]
    shift = (variant * 17) % 42
    base_rgb = tuple(max(0, min(255, channel + shift - 20)) for channel in base[:3])
    accent_rgb = tuple(max(0, min(255, channel - shift // 2)) for channel in accent[:3])
    # Full-canvas dark gradient: no inner card/rectangle competing with text.
    gradient_bases = {
        "dots": (24, 28, 78), "sunset": (82, 18, 38), "grid": (7, 65, 62),
        "hearts": (78, 15, 58), "waves": (80, 48, 10), "confetti": (24, 32, 95),
        "neon": (15, 7, 42), "paper": (72, 34, 15), "bubbles": (7, 58, 90),
        "diagonal": (52, 16, 88), "leaves": (12, 62, 32), "checker": (75, 20, 30),
        "flowers": (78, 14, 58), "roses": (88, 8, 25), "galaxy": (7, 9, 48),
        "stars": (9, 23, 76), "moon": (32, 42, 100), "butterflies": (7, 54, 82),
        "clouds": (22, 57, 92), "rainbow": (78, 28, 10),
    }
    dark_rgb = gradient_bases.get(
        template, tuple(max(12, int(channel * 0.38)) for channel in base_rgb)
    )
    for y in range(512):
        # Never wrap the gradient: wrapping created the visible hard "cut"
        # band seen on some red/pink templates.
        ratio = y / 511 if variant % 2 == 0 else 1 - (y / 511)
        color = tuple(
            int(dark_rgb[index] * (1 - ratio) + accent_rgb[index] * ratio * 0.62)
            for index in range(3)
        )
        draw.line((0, y, 512, y), fill=(*color, 255))
    base = (*dark_rgb, 255)
    # Keep decorative strokes opaque so Telegram never shows a grey
    # transparency band; their opacity is simulated by blending the color.
    accent = tuple(
        int(dark_rgb[index] * 0.42 + accent_rgb[index] * 0.58)
        for index in range(3)
    ) + (255,)
    if template == "dots":
        for x in range(40, 500, 58):
            for y in range(38, 500, 58):
                draw.ellipse((x, y, x + 18, y + 18), fill=accent)
    elif template == "grid":
        for x in range(20, 512, 45):
            draw.line((x, 0, x - 90, 512), fill=accent, width=4)
        for y in range(20, 512, 45):
            draw.line((0, y, 512, y + 100), fill=accent, width=4)
    elif template == "hearts":
        for x, y in [(55, 70), (430, 80), (65, 420), (440, 410)]:
            draw.text((x, y), "♥", fill=accent, font=ImageFont.truetype(
                "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", 42
            ))
    elif template == "waves":
        for y in range(80, 500, 55):
            points = [(0, y)]
            for x in range(0, 513, 32):
                points.append((x, y + int(12 * ((x // 32) % 2))))
            draw.line(points, fill=accent, width=8)
    elif template == "confetti":
        for x, y, color in [(55, 70, accent), (440, 65, accent), (65, 430, accent), (430, 420, accent)]:
            draw.rectangle((x, y, x + 28, y + 9), fill=color)
            draw.ellipse((x + 10, y + 24, x + 30, y + 44), fill=color)
    elif template == "neon":
        for inset in (28, 44, 60):
            draw.rounded_rectangle((inset, inset, 512 - inset, 512 - inset), radius=35,
                                   outline=accent, width=5)
    elif template == "paper":
        for y in range(55, 500, 42):
            draw.line((30, y, 480, y), fill=accent, width=3)
    elif template == "bubbles":
        for x, y, size in [(48, 65, 30), (430, 70, 44), (65, 420, 48), (440, 420, 25)]:
            draw.ellipse((x, y, x + size, y + size), outline=accent, width=7)
    elif template == "diagonal":
        for x in range(-500, 600, 55):
            draw.line((x, 0, x + 500, 500), fill=accent, width=12)
    elif template == "leaves":
        for x, y in [(45, 55), (435, 70), (55, 425), (430, 420)]:
            draw.ellipse((x, y, x + 28, y + 55), fill=accent)
            draw.ellipse((x + 20, y + 18, x + 58, y + 42), fill=accent)
    elif template == "checker":
        for x in range(20, 500, 52):
            for y in range(20, 500, 52):
                if ((x + y) // 52) % 2 == 0:
                    draw.rectangle((x, y, x + 52, y + 52), fill=accent)
    elif template in {"flowers", "roses"}:
        for x, y in [(42, 42), (430, 42), (42, 420), (430, 420)]:
            for dx, dy in [(0, -13), (-13, 0), (13, 0), (0, 13)]:
                draw.ellipse((x + dx - 14, y + dy - 20, x + dx + 14, y + dy + 20), fill=accent)
            draw.ellipse((x - 10, y - 10, x + 10, y + 10), fill=(255, 205, 70, 255))
    elif template in {"galaxy", "stars"}:
        rng = random.Random(variant * 101 + len(template))
        for _ in range(48):
            x, y = rng.randint(25, 487), rng.randint(25, 487)
            radius = rng.choice([2, 3, 4])
            draw.ellipse((x - radius, y - radius, x + radius, y + radius), fill=accent)
        if template == "galaxy":
            draw.ellipse((355, 42, 445, 132), outline=(240, 220, 255, 150), width=5)
    elif template == "moon":
        draw.ellipse((40, 35, 120, 115), fill=accent)
        draw.ellipse((68, 22, 130, 90), fill=base)
        draw.ellipse((405, 400, 475, 470), fill=accent)
    elif template == "butterflies":
        for x, y in [(42, 42), (430, 42), (42, 420), (430, 420)]:
            draw.ellipse((x - 28, y - 18, x, y + 18), fill=accent)
            draw.ellipse((x, y - 18, x + 28, y + 18), fill=accent)
            draw.line((x, y - 12, x, y + 20), fill=(70, 80, 120, 200), width=4)
    elif template == "clouds":
        for x, y in [(25, 55), (390, 55), (25, 410), (390, 410)]:
            draw.ellipse((x, y, x + 55, y + 38), fill=accent)
            draw.ellipse((x + 32, y - 18, x + 92, y + 38), fill=accent)
            draw.rounded_rectangle((x - 5, y + 10, x + 96, y + 40), radius=18, fill=accent)
    elif template == "rainbow":
        for inset, color in [(0, (240, 90, 100, 150)), (12, (245, 170, 65, 150)),
                             (24, (80, 170, 100, 150)), (36, (80, 135, 220, 150))]:
            draw.arc((inset - 30, inset - 120, 542 - inset, 550 - inset),
                     200, 340, fill=color, width=10)


def normalize_sticker_text(text: str) -> str:
    """Normalize styled Unicode while keeping emoji and script marks intact."""
    # NFKC converts Telegram's mathematical bold/script/fraktur/monospace and
    # full-width letters to readable base characters before font selection.
    return unicodedata.normalize("NFKC", text)


def sticker_time_text(now: datetime | None = None) -> str:
    current = (
        now.astimezone(STICKER_TIMEZONE)
        if now is not None
        else datetime.now(STICKER_TIMEZONE)
    )
    return current.strftime("%I:%M %p").lstrip("0")


def render_text_sticker(text: str, user_id: int = 0) -> bytes:
    """Render text using a rotating style and a Telegram-compatible WebP sticker."""
    text = normalize_sticker_text(text)
    text = re.sub(r"\s+", " ", text).strip()[:MAX_STICKER_TEXT]
    choices = list(range(len(STICKER_STYLES)))
    previous = last_sticker_style.get(user_id)
    if previous in choices and len(choices) > 1:
        choices.remove(previous)
    style_index = random.choice(choices)
    last_sticker_style[user_id] = style_index
    font_path, text_color, outline_color, template, variant = STICKER_STYLES[style_index]
    if re.search(r"[\u0900-\u097f]", text):
        font_path = random.choice(DEVANAGARI_FONT_PATHS)
    probe = ImageDraw.Draw(Image.new("RGBA", (1, 1)))
    # Keep the larger readable text size; only the outline is intentionally light.
    compact_length = len(re.sub(r"\s+", "", text))
    word_count = len(text.split())
    if compact_length <= 10 and word_count <= 2:
        font_size = random.choice([96, 104, 112])
    elif compact_length <= 28 and word_count <= 5:
        font_size = random.choice([80, 88, 96])
    else:
        font_size = random.choice([68, 76, 84])
    while True:
        font = ImageFont.truetype(font_path, font_size)
        words = text.split()
        lines: list[str] = []
        line = ""
        for word in words:
            candidate = f"{line} {word}".strip()
            if line and probe.textbbox((0, 0), candidate, font=font, stroke_width=0)[2] > 420:
                lines.append(line)
                line = word
            else:
                line = candidate
        if line:
            lines.append(line)
        widest = max(
            (probe.textbbox((0, 0), current, font=font, stroke_width=0)[2] for current in lines),
            default=0,
        )
        if (
            widest <= 440
            and len(lines) <= 5
            and len(lines) * (font_size + 18) <= 300
        ) or font_size <= 28:
            break
        font_size -= 4
    lines = lines[:6] or [" "]
    line_height = font_size + 18
    height = 512
    image = Image.new("RGBA", (512, height), (0, 0, 0, 0))
    draw = ImageDraw.Draw(image)
    draw_sticker_background(draw, template, variant)
    y = (height - len(lines) * line_height) // 2
    for line in lines:
        box = draw.textbbox((0, 0), line, font=font, stroke_width=4)
        x = (512 - (box[2] - box[0])) // 2
        with Pilmoji(image, draw=draw) as emoji_draw:
            emoji_draw.text(
                (x + 4, y + 7),
                line,
                font=font,
                fill=(0, 0, 0, 90),
                stroke_width=4,
                stroke_fill=(0, 0, 0, 60),
                embedded_color=True,
            )
            emoji_draw.text(
                (x, y),
                line,
                font=font,
                fill=(*text_color, 255),
                stroke_width=4,
                stroke_fill=(*outline_color, 255),
                embedded_color=True,
            )
        y += line_height
    # Telegram stickers should have soft curved corners, not a hard square.
    corner_mask = Image.new("L", image.size, 0)
    mask_draw = ImageDraw.Draw(corner_mask)
    mask_draw.rounded_rectangle((4, 4, 508, 508), radius=58, fill=255)
    image.putalpha(corner_mask)
    output = io.BytesIO()
    image.save(output, format="WEBP", lossless=True, method=6)
    return output.getvalue()


def render_image_sticker(image_bytes: bytes, text: str, user_id: int = 0) -> bytes:
    """Crop around the largest face/subject and add readable overlay text."""
    # Add occasional all-caps English treatment for a stronger poster-like
    # look. Hindi/mixed text is always preserved exactly.
    if re.search(r"[A-Za-z]", text) and not re.search(r"[\u0900-\u097f]", text):
        if random.random() < 0.35:
            text = text.upper()
    source = Image.open(io.BytesIO(image_bytes)).convert("RGB")
    source.thumbnail((1200, 1200), Image.Resampling.LANCZOS)
    frame = cv2.cvtColor(__import__("numpy").array(source), cv2.COLOR_RGB2GRAY)
    faces = []
    # OpenCV builds differ: use Haar detection when the legacy API is present,
    # otherwise keep the safe center/main-subject crop below.
    if hasattr(cv2, "CascadeClassifier"):
        detector = cv2.CascadeClassifier(
            cv2.data.haarcascades + "haarcascade_frontalface_default.xml"
        )
        faces = detector.detectMultiScale(
            frame, scaleFactor=1.1, minNeighbors=5, minSize=(50, 50)
        )
    if len(faces):
        x, y, width, height = max(faces, key=lambda item: item[2] * item[3])
        center_x, center_y = x + width // 2, y + height // 2
        crop_size = max(width, height) * 3
        left = max(0, int(center_x - crop_size / 2))
        top = max(0, int(center_y - crop_size / 2))
        right = min(source.width, int(center_x + crop_size / 2))
        bottom = min(source.height, int(center_y + crop_size / 2))
        source = source.crop((left, top, right, bottom))
    side = min(source.width, source.height)
    left = (source.width - side) // 2
    top = (source.height - side) // 2
    image = source.crop((left, top, left + side, top + side)).resize(
        (512, 512), Image.Resampling.LANCZOS
    ).convert("RGBA")
    # A transparent-to-dark lower gradient keeps text readable without a card.
    overlay = Image.new("RGBA", image.size, (0, 0, 0, 0))
    overlay_draw = ImageDraw.Draw(overlay)
    for y in range(250, 512):
        alpha = int(155 * ((y - 250) / 262))
        overlay_draw.line((0, y, 512, y), fill=(0, 0, 0, alpha))
    image = Image.alpha_composite(image, overlay)
    draw = ImageDraw.Draw(image)
    choices = list(range(len(STICKER_STYLES)))
    previous = last_sticker_style.get(user_id)
    if previous in choices and len(choices) > 1:
        choices.remove(previous)
    style_index = random.choice(choices)
    last_sticker_style[user_id] = style_index
    font_path, text_color, outline_color, _, _ = STICKER_STYLES[style_index]
    if re.search(r"[\u0900-\u097f]", text):
        font_path = random.choice(DEVANAGARI_FONT_PATHS)
    compact_length = len(re.sub(r"\s+", "", text))
    font_size = 68 if compact_length <= 16 else 56
    font = ImageFont.truetype(font_path, font_size)
    words = text.split()
    lines: list[str] = []
    line = ""
    for word in words:
        candidate = f"{line} {word}".strip()
        if line and draw.textbbox((0, 0), candidate, font=font)[2] > 440:
            lines.append(line)
            line = word
        else:
            line = candidate
    if line:
        lines.append(line)
    lines = lines[:4] or [" "]
    line_height = font_size + 14
    y = 390 - (len(lines) * line_height) // 2
    gradient_stroke = random.random() < 0.3
    for line in lines:
        box = draw.textbbox((0, 0), line, font=font, stroke_width=3)
        x = (512 - (box[2] - box[0])) // 2
        with Pilmoji(image, draw=draw) as emoji_draw:
            emoji_draw.text(
                (x + 3, y + 5), line, font=font, fill=(0, 0, 0, 170),
                stroke_width=3, stroke_fill=(0, 0, 0, 190), embedded_color=True,
            )
            if gradient_stroke:
                middle_outline = tuple(
                    int(outline_color[index] * 0.55 + text_color[index] * 0.45)
                    for index in range(3)
                )
                for width, stroke_color in (
                    (3, outline_color), (2, middle_outline), (1, text_color)
                ):
                    emoji_draw.text(
                        (x, y), line, font=font, fill=(*text_color, 255),
                        stroke_width=width, stroke_fill=(*stroke_color, 255),
                        embedded_color=True,
                    )
                emoji_draw.text(
                    (x, y), line, font=font, fill=(*text_color, 255),
                    stroke_width=0, embedded_color=True,
                )
            else:
                emoji_draw.text(
                    (x, y), line, font=font, fill=(*text_color, 255),
                    stroke_width=3, stroke_fill=(*outline_color, 255),
                    embedded_color=True,
                )
        y += line_height
    mask = Image.new("L", image.size, 0)
    ImageDraw.Draw(mask).rounded_rectangle((4, 4, 508, 508), radius=58, fill=255)
    image.putalpha(mask)
    output = io.BytesIO()
    image.save(output, format="WEBP", quality=90, method=6)
    return output.getvalue()


def _render_chat_template_sticker(
    message_text: str,
    display_name: str,
    avatar_bytes: bytes | None = None,
    user_id: int = 0,
) -> bytes:
    """Render the supplied neon quote PNG with text and avatar overlaid."""
    message_text = normalize_sticker_text(re.sub(r"\s+", " ", message_text).strip())
    display_name = normalize_sticker_text(re.sub(r"\s+", " ", display_name).strip()) or "User"
    if not CHAT_QUOTE_TEMPLATE_PATH.exists():
        raise FileNotFoundError(f"Chat quote template missing: {CHAT_QUOTE_TEMPLATE_PATH}")
    image = Image.open(CHAT_QUOTE_TEMPLATE_PATH).convert("RGBA")
    # The supplied PNG contains editor-colored 1–10 alpha speckles outside
    # the bubble. Remove those without affecting the opaque neon edge.
    alpha = image.getchannel("A").point(lambda value: 0 if value < 24 else value)
    image.putalpha(alpha)
    pixels = __import__("numpy").array(image)
    near_white = (
        (pixels[:, :, 0] > 175)
        & (pixels[:, :, 1] > 175)
        & (pixels[:, :, 2] > 175)
        & (pixels[:, :, 3] > 0)
    )
    pixels[near_white, 3] = 0
    image = Image.fromarray(pixels, "RGBA")
    draw = ImageDraw.Draw(image)
    width, height = image.size
    name_font_path = "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"
    text_font_path = "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"
    if re.search(r"[\u0900-\u097f]", display_name):
        name_font_path = DEVANAGARI_FONT_PATHS[0]
    if re.search(r"[\u0900-\u097f]", message_text):
        text_font_path = DEVANAGARI_FONT_PATHS[0]
    name_font = ImageFont.truetype(name_font_path, 106)
    text_font = ImageFont.truetype(text_font_path, 112)
    content_left, content_right = 330, width - 175
    probe = ImageDraw.Draw(Image.new("RGBA", (1, 1)))
    lines: list[str] = []
    line = ""
    for word in message_text.split() or [" "]:
        candidate = f"{line} {word}".strip()
        if line and probe.textbbox((0, 0), candidate, font=text_font)[2] > content_right - content_left:
            lines.append(line)
            line = word
        else:
            line = candidate
    if line:
        lines.append(line)
    lines = lines[:2]
    if len(lines) == 2:
        lines[-1] = lines[-1][:42].rstrip() + ("..." if len(lines[-1]) > 42 else "")
    colors = (
        (102, 226, 207, 255), (164, 133, 255, 255), (255, 157, 129, 255),
        (92, 180, 255, 255), (255, 126, 172, 255), (178, 220, 112, 255),
    )
    name_color = colors[(abs(int(user_id)) // 7) % len(colors)]
    draw.text((content_left, 145), display_name[:28], font=name_font, fill=name_color)
    for index, line in enumerate(lines):
        with Pilmoji(image, draw=draw) as emoji_draw:
            emoji_draw.text(
                (content_left, 270 + index * 126), line, font=text_font,
                fill=(245, 244, 255, 255), embedded_color=True,
            )
    avatar_size, avatar_x, avatar_y = 220, 70, 245
    if avatar_bytes:
        try:
            avatar = Image.open(io.BytesIO(avatar_bytes)).convert("RGB")
            side = min(avatar.width, avatar.height)
            avatar = avatar.crop((
                (avatar.width - side) // 2, (avatar.height - side) // 2,
                (avatar.width + side) // 2, (avatar.height + side) // 2,
            )).resize((avatar_size, avatar_size), Image.Resampling.LANCZOS).convert("RGBA")
            avatar_mask = Image.new("L", (avatar_size, avatar_size), 0)
            ImageDraw.Draw(avatar_mask).ellipse((0, 0, avatar_size - 1, avatar_size - 1), fill=255)
            image.paste(avatar, (avatar_x, avatar_y), avatar_mask)
        except Exception:
            avatar_bytes = None
    if not avatar_bytes:
        initials = "".join(part[0] for part in display_name.split()[:2]).upper() or "?"
        draw.ellipse(
            (avatar_x, avatar_y, avatar_x + avatar_size, avatar_y + avatar_size),
            fill=(30, 22, 55, 255), outline=(111, 166, 255, 255), width=8,
        )
        initial_font = ImageFont.truetype(name_font_path, 92)
        box = draw.textbbox((0, 0), initials, font=initial_font)
        draw.text(
            (avatar_x + avatar_size / 2 - (box[2] - box[0]) / 2,
             avatar_y + avatar_size / 2 - (box[3] - box[1]) / 2 - 12),
            initials, font=initial_font, fill=(255, 255, 255, 255),
        )
    time_font = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", 66)
    time_text = sticker_time_text()
    time_box = draw.textbbox((0, 0), time_text, font=time_font)
    draw.text(
        (width - 180 - (time_box[2] - time_box[0]), height - 150),
        time_text, font=time_font, fill=(222, 226, 245, 225),
    )
    image = image.resize((512, max(1, round(height * 512 / width))), Image.Resampling.LANCZOS)
    final_pixels = __import__("numpy").array(image)
    final_white_edge = (
        (final_pixels[:, :, 0] > 175)
        & (final_pixels[:, :, 1] > 175)
        & (final_pixels[:, :, 2] > 175)
        & (final_pixels[:, :, 3] < 220)
    )
    final_pixels[final_white_edge, 3] = 0
    image = Image.fromarray(final_pixels, "RGBA")
    output = io.BytesIO()
    image.save(output, format="WEBP", lossless=True, method=6)
    return output.getvalue()


def get_quote_sticker_font(size: int, bold: bool = False):
    filenames = (
        r"C:\Windows\Fonts\segoeuib.ttf" if bold else r"C:\Windows\Fonts\segoeui.ttf",
        r"C:\Windows\Fonts\arialbd.ttf" if bold else r"C:\Windows\Fonts\arial.ttf",
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        "DejaVuSans-Bold.ttf" if bold else "DejaVuSans.ttf",
    )
    for fn in filenames:
        try:
            return ImageFont.truetype(fn, size)
        except Exception:
            pass
    try:
        return ImageFont.truetype("arial.ttf", size)
    except Exception:
        return ImageFont.load_default()


def create_quotly_bubble_mask(w: int, h: int, r: int = 24, bl_r: int = 6) -> Image.Image:
    scale = 3
    sw, sh = w * scale, h * scale
    sr = r * scale
    sbl = bl_r * scale
    mask = Image.new("L", (sw, sh), 0)
    draw = ImageDraw.Draw(mask)
    draw.rounded_rectangle((0, 0, sw, sh), radius=sr, fill=255)
    draw.rectangle((0, sh - sr, sr, sh), fill=0)
    draw.rectangle((sbl, sh - sr, sr, sh), fill=255)
    draw.rectangle((0, sh - sr, sr, sh - sbl), fill=255)
    draw.pieslice((0, sh - 2 * sbl, 2 * sbl, sh), 90, 180, fill=255)
    return mask.resize((w, h), Image.Resampling.LANCZOS)


def render_chat_sticker(
    message_text: str,
    display_name: str,
    avatar_bytes: bytes | None = None,
    user_id: int = 0,
) -> bytes:
    """Render a full-size pixel-perfect Quotly Telegram chat bubble sticker."""
    font_name = get_quote_sticker_font(24, bold=True)
    font_text = get_quote_sticker_font(28, bold=False)

    palette = [
        (216, 126, 154),  # Telegram Mauve Pink (Signature ˹Dᴇsᴛʀᴏʏᴇʀ ꭙ Bʜꫝɪ color)
        (75, 179, 219),   # Telegram Cyan
        (89, 157, 246),   # Telegram Blue
        (84, 187, 137),   # Telegram Green
        (235, 153, 62),   # Telegram Orange
        (170, 116, 222),  # Telegram Purple
        (235, 99, 107),   # Telegram Red
    ]
    name_color = palette[abs(int(user_id)) % len(palette)]
    bubble_bg = (33, 33, 44, 255)

    clean_text = (message_text or "").strip()
    clean_name = (display_name or "User").strip()
    if len(clean_name) > 36:
        clean_name = clean_name[:33] + "..."

    max_content_w = 380
    paragraphs = clean_text.split("\n")
    dummy_img = Image.new("RGBA", (1, 1))

    lines: list[str] = []
    with Pilmoji(dummy_img) as pilmoji:
        for p in paragraphs:
            if not p.strip():
                lines.append("")
                continue
            words = p.split()
            curr: list[str] = []
            for w in words:
                cand = " ".join(curr + [w])
                cw, _ = pilmoji.getsize(cand, font=font_text)
                if curr and cw > max_content_w:
                    lines.append(" ".join(curr))
                    curr = [w]
                else:
                    curr.append(w)
            if curr:
                lines.append(" ".join(curr))

    if not lines:
        lines = [""]

    lines = lines[:12]
    line_h = 36
    text_w = 0
    with Pilmoji(dummy_img) as pilmoji:
        for l in lines:
            if l:
                lw, _ = pilmoji.getsize(l, font=font_text)
                text_w = max(text_w, lw)

    probe = ImageDraw.Draw(dummy_img)
    name_w = probe.textbbox((0, 0), clean_name, font=font_name)[2]

    # Rectangular chat size bada: generous width & clearance for telegram time pill
    content_w = max(name_w + 50, text_w + 60, 280)
    pad_x = 26
    pad_top = 20
    # Generous pad_bot ensures text is comfortably ABOVE Telegram's timestamp badge
    pad_bot = 38
    gap_name_text = 8
    line_h = 38

    bubble_w = content_w + pad_x * 2
    bubble_h = pad_top + 26 + gap_name_text + max(1, len(lines)) * line_h + pad_bot

    # Profile logo small (46px)
    avatar_size = 46
    gap_av_bubble = 12
    margin = 8

    total_w = margin + avatar_size + gap_av_bubble + bubble_w + margin
    total_h = margin + max(avatar_size, bubble_h) + margin

    canvas = Image.new("RGBA", (total_w, total_h), (0, 0, 0, 0))

    # Avatar placed at top-left (aligned with bubble top with subtle 2px offset)
    avatar_x = margin
    avatar_y = margin + 2

    av = None
    if avatar_bytes:
        try:
            av = Image.open(io.BytesIO(avatar_bytes)).convert("RGBA")
            side = min(av.width, av.height)
            left = (av.width - side) // 2
            top = (av.height - side) // 2
            av = av.crop((left, top, left + side, top + side)).resize((avatar_size, avatar_size), Image.Resampling.LANCZOS)
        except Exception:
            av = None

    if av is None:
        av = Image.new("RGBA", (avatar_size, avatar_size), (0, 0, 0, 0))
        av_draw = ImageDraw.Draw(av)
        av_draw.ellipse((0, 0, avatar_size - 1, avatar_size - 1), fill=name_color)
        initial = (clean_name[:1] or "?").upper()
        font_init = get_quote_sticker_font(24, bold=True)
        ibox = av_draw.textbbox((0, 0), initial, font=font_init)
        av_draw.text(((avatar_size - (ibox[2] - ibox[0])) / 2, (avatar_size - (ibox[3] - ibox[1])) / 2 - 2), initial, font=font_init, fill=(255, 255, 255))

    mask = Image.new("L", (avatar_size, avatar_size), 0)
    ImageDraw.Draw(mask).ellipse((0, 0, avatar_size - 1, avatar_size - 1), fill=255)
    canvas.paste(av, (avatar_x, avatar_y), mask)

    bx0 = margin + avatar_size + gap_av_bubble
    by0 = margin
    bubble_mask = create_quotly_bubble_mask(bubble_w, bubble_h, r=24, bl_r=6)
    bubble_layer = Image.new("RGBA", (bubble_w, bubble_h), bubble_bg)
    canvas.paste(bubble_layer, (bx0, by0), bubble_mask)

    draw = ImageDraw.Draw(canvas)
    name_x = bx0 + pad_x
    name_y = by0 + pad_top
    draw.text((name_x, name_y), clean_name, font=font_name, fill=name_color)

    start_text_y = name_y + 26 + gap_name_text
    with Pilmoji(canvas) as pilmoji:
        for idx, l in enumerate(lines):
            if l:
                ly = start_text_y + idx * line_h
                pilmoji.text((name_x, ly), l, (255, 255, 255), font=font_text)

    # Scale to Telegram sticker bounding box (512px max dimension for full-size display)
    scale = 512.0 / max(total_w, total_h)
    sticker_w = max(1, int(total_w * scale))
    sticker_h = max(1, int(total_h * scale))
    sticker_img = canvas.resize((sticker_w, sticker_h), Image.Resampling.LANCZOS)

    output = io.BytesIO()
    sticker_img.save(output, format="WEBP", quality=95, method=0)
    return output.getvalue()


async def enter_sticker_queue() -> int:
    """Return a one-based queue position before waiting for a render slot."""
    global sticker_jobs_in_system
    async with sticker_queue_lock:
        sticker_jobs_in_system += 1
        position = sticker_jobs_in_system
    try:
        await sticker_render_gate.acquire()
    except BaseException:
        async with sticker_queue_lock:
            sticker_jobs_in_system = max(0, sticker_jobs_in_system - 1)
        raise
    return position


async def leave_sticker_queue() -> None:
    global sticker_jobs_in_system
    sticker_render_gate.release()
    async with sticker_queue_lock:
        sticker_jobs_in_system = max(0, sticker_jobs_in_system - 1)


async def wait_for_sticker_slot(progress: Message, label: str) -> None:
    """Show queue position and a rough wait estimate while waiting for a slot."""
    task = asyncio.create_task(enter_sticker_queue())
    acquired = False
    try:
        await asyncio.sleep(0)
        if task.done():
            await task
            acquired = True
            return
        async with sticker_queue_lock:
            initial_position = sticker_jobs_in_system
        if initial_position <= STICKER_RENDER_CONCURRENCY:
            await task
            acquired = True
            return
        started = time.monotonic()
        last_update = 0.0
        updates_enabled = True
        while not task.done():
            async with sticker_queue_lock:
                position = max(STICKER_RENDER_CONCURRENCY + 1, sticker_jobs_in_system)
            wait_seconds = max(1, (position - STICKER_RENDER_CONCURRENCY) * 3)
            percent = min(
                95,
                int(10 + ((time.monotonic() - started) / wait_seconds) * 85),
            )
            filled = min(10, percent // 10)
            bar = "█" * filled + "░" * (10 - filled)
            if updates_enabled and time.monotonic() - last_update >= 2.0:
                try:
                    await progress.edit_text(
                        f"{label}\nYou are in the queue — your position: {position}\n"
                        f"Approx wait: {wait_seconds} sec\n[{bar}] waiting"
                        f" {percent}%"
                    )
                    last_update = time.monotonic()
                except (TelegramBadRequest, TelegramRetryAfter):
                    updates_enabled = False
            await asyncio.sleep(0.5)
        await task
        acquired = True
    except BaseException:
        if not task.done():
            task.cancel()
            try:
                await task
            except BaseException:
                pass
        elif not task.cancelled():
            try:
                task.exception()
            except BaseException:
                pass
            else:
                acquired = True
        if acquired:
            await leave_sticker_queue()
        raise


async def send_sticker_with_retry(
    message: Message,
    sticker_bytes: bytes,
    filename: str,
    markup: InlineKeyboardMarkup | None,
    progress: Message,
    label: str,
) -> Message:
    """Retry Telegram flood-control responses instead of abandoning a rendered sticker."""
    last_error: Exception | None = None
    for attempt in range(5):
        try:
            async with sticker_delivery_gate:
                return await asyncio.wait_for(
                    message.answer_sticker(
                        BufferedInputFile(sticker_bytes, filename=filename),
                        reply_markup=markup,
                    ),
                    timeout=STICKER_TELEGRAM_TIMEOUT,
                )
        except TelegramRetryAfter as error:
            last_error = error
            delay = min(max(1, int(error.retry_after)) + 1, 120)
            try:
                await progress.edit_text(
                    f"{label}\nTelegram is busy — retrying in {delay} seconds."
                )
            except (TelegramBadRequest, TelegramRetryAfter):
                pass
            await asyncio.sleep(delay)
        except asyncio.TimeoutError as error:
            last_error = error
            if attempt < 4:
                await asyncio.sleep(2)
    if last_error:
        raise last_error
    raise RuntimeError("Sticker upload failed")


def sticker_pack_name(user_id: int, pack_number: int = 1) -> str:
    username = re.sub(r"[^a-zA-Z0-9_]", "", bot_username or "seyuki_bot").lower()
    suffix = "" if pack_number == 1 else f"_{pack_number}"
    return f"seyuki_{user_id}{suffix}_by_{username}"[:64]


def sticker_pack_title(first_name: str, username: str | None) -> str:
    owner = first_name.strip() or (username or "").strip().lstrip("@") or "User"
    return f"˹Dᴇsᴛʀᴏʏᴇʀ ꭙ ᴍᴜsɪᴄ ᴀssɪsᴛᴀɴᴛ - {owner}"[:64]


async def add_sticker_to_user_pack(
    user_id: int,
    sticker_bytes: bytes,
    first_name: str,
    username: str | None,
) -> str | None:
    """Keep each user's stickers in their own pack, creating numbered packs when full."""
    sticker = InputSticker(
        sticker=BufferedInputFile(sticker_bytes, filename="seyuki.webp"),
        format="static",
        emoji_list=["✨"],
    )
    title = sticker_pack_title(first_name, username)
    async with sticker_locks[user_id]:
        for pack_number in range(1, 100):
            pack_name = sticker_pack_name(user_id, pack_number)
            try:
                sticker_set = await bot.get_sticker_set(pack_name)
                if len(sticker_set.stickers) >= 120:
                    continue
                await bot.add_sticker_to_set(user_id=user_id, name=pack_name, sticker=sticker)
                return pack_name
            except TelegramBadRequest:
                try:
                    await bot.create_new_sticker_set(
                        user_id=user_id,
                        name=pack_name,
                        title=title if pack_number == 1 else f"{title} {pack_number}",
                        stickers=[sticker],
                        sticker_type="regular",
                        sticker_format="static",
                    )
                    return pack_name
                except TelegramBadRequest:
                    # A missing pack is expected; another API error should move on
                    # to the next name so a previous partial creation cannot block use.
                    continue
    log.warning("Could not add sticker to any pack for user %s", user_id)
    return None


SOCIAL_PAGE_SIZE = 20
INDIA_TZ = ZoneInfo("Asia/Kolkata")


def afk_india_time(value: datetime) -> str:
    local_time = value.astimezone(INDIA_TZ)
    return f"{local_time.strftime('%I:%M %p').lstrip('0')} IST"


def afk_duration_text(started_at: datetime) -> str:
    total_seconds = max(0, int((datetime.now(timezone.utc) - started_at).total_seconds()))
    total_minutes = total_seconds // 60
    if total_minutes < 1:
        return "less than a minute"
    days = total_minutes // (24 * 60)
    hours = (total_minutes % (24 * 60)) // 60
    minutes = total_minutes % 60
    parts: list[str] = []
    if days > 0:
        parts.append(f"{days} day" if days == 1 else f"{days} days")
        if hours > 0:
            parts.append(f"{hours} hour" if hours == 1 else f"{hours} hours")
        elif minutes > 0:
            parts.append(f"{minutes} minute" if minutes == 1 else f"{minutes} minutes")
    elif hours > 0:
        parts.append(f"{hours} hour" if hours == 1 else f"{hours} hours")
        if minutes > 0:
            parts.append(f"{minutes} minute" if minutes == 1 else f"{minutes} minutes")
    else:
        parts.append(f"{minutes} minute" if minutes == 1 else f"{minutes} minutes")
    return " ".join(parts)


def afk_mention(user_id: int, display_name: str) -> str:
    return f'<a href="tg://user?id={user_id}">{html.escape(display_name)}</a>'


async def ensure_afk_chat_loaded(chat_id: int) -> None:
    if chat_id in afk_loaded_chats:
        return
    cursor = await db.execute(
        "SELECT user_id, display_name, started_at FROM group_afk WHERE chat_id=?",
        (chat_id,),
    )
    active: dict[int, tuple[datetime, str]] = {}
    for row in await cursor.fetchall():
        try:
            started_at = datetime.fromisoformat(str(row["started_at"]))
            if started_at.tzinfo is None:
                started_at = started_at.replace(tzinfo=timezone.utc)
            active[int(row["user_id"])] = (
                started_at.astimezone(timezone.utc),
                str(row["display_name"] or "User"),
            )
        except (TypeError, ValueError):
            log.warning("Ignoring invalid AFK timestamp in group %s", chat_id)
    afk_cache[chat_id] = active
    afk_loaded_chats.add(chat_id)


async def mark_group_afk(message: Message) -> None:
    user = message.from_user
    if not user:
        return
    chat_id = message.chat.id
    user_id = user.id
    display_name = user.full_name or user.first_name or user.username or "User"
    started_at = datetime.now(timezone.utc)
    async with afk_state_lock:
        await ensure_afk_chat_loaded(chat_id)
        afk_cache.setdefault(chat_id, {})[user_id] = (started_at, display_name)
        await db.execute(
            """INSERT INTO group_afk(chat_id, user_id, display_name, started_at)
            VALUES(?,?,?,?)
            ON CONFLICT(chat_id,user_id) DO UPDATE SET
            display_name=excluded.display_name, started_at=excluded.started_at""",
            (chat_id, user_id, display_name, started_at.isoformat()),
        )
        await db.commit()
    await message.reply(
        f"{afk_mention(user_id, display_name)} has gone offline at "
        f"<b>{afk_india_time(started_at)}</b>."
    )


async def process_group_afk_activity(message: Message) -> None:
    if (
        message.chat.type not in {ChatType.GROUP, ChatType.SUPERGROUP}
        or not message.from_user
        or message.from_user.is_bot
    ):
        return
    if message.text:
        command = message.text.split(maxsplit=1)[0].casefold().split("@", 1)[0]
        if command == "/afky":
            return
    chat_id = message.chat.id
    sender_id = message.from_user.id
    notification = ""
    async with afk_state_lock:
        await ensure_afk_chat_loaded(chat_id)
        active = afk_cache.setdefault(chat_id, {})
        afk_record = active.pop(sender_id, None)
        if afk_record:
            started_at, display_name = afk_record
            notification = (
                f"{afk_mention(sender_id, display_name)} is back online after "
                f"<b>{afk_duration_text(started_at)}</b>."
            )
            await db.execute(
                "DELETE FROM group_afk WHERE chat_id=? AND user_id=?",
                (chat_id, sender_id),
            )
            await db.commit()
    if notification:
        await message.answer(notification)


def social_user_name(row) -> str:
    return str(
        row["custom_name"] or row["first_name"] or row["username"] or "User"
    ).strip() or "User"


async def resolve_social_target(message: Message, args: list[str]) -> int | None:
    if message.reply_to_message and message.reply_to_message.from_user:
        return message.reply_to_message.from_user.id
    for entity in message.entities or []:
        if entity.type == "text_mention" and getattr(entity, "user", None):
            return int(entity.user.id)
    if not args:
        return None
    token = args[0].strip()
    if token.lstrip("-").isdigit():
        return int(token)
    if not token.startswith("@"):
        return None
    username = token[1:].casefold()
    cursor = await db.execute(
        "SELECT user_id FROM users WHERE lower(username)=? LIMIT 1", (username,)
    )
    row = await cursor.fetchone()
    if row:
        return int(row["user_id"])
    try:
        target = await bot.get_chat(token)
        if target.id:
            await db.execute(
                """INSERT INTO users(user_id, first_name, username)
                VALUES(?,?,?) ON CONFLICT(user_id) DO UPDATE SET
                first_name=excluded.first_name, username=excluded.username,
                last_seen_at=CURRENT_TIMESTAMP""",
                (target.id, target.first_name or target.full_name or "", target.username or username),
            )
            await db.commit()
            return int(target.id)
    except TelegramBadRequest:
        return None
    return None


def normalized_chat_pair(first_id: int, second_id: int) -> tuple[int, int]:
    return (first_id, second_id) if first_id < second_id else (second_id, first_id)


async def social_command_allowed(message: Message) -> bool:
    if await group_command_is_locked(message):
        return False
    await remember_user(message)
    return True


async def follow_action(message: Message, action: str) -> None:
    if not await social_command_allowed(message):
        return
    target_id = await resolve_social_target(message, (message.text or "").split()[1:])
    if not target_id:
        await message.answer("Reply to a user or use a username or numeric user ID.")
        return
    user_id = message.from_user.id
    if target_id == user_id:
        await message.answer("You cannot follow yourself.")
        return
    if action == "follow":
        cursor = await db.execute(
            "INSERT OR IGNORE INTO follows(follower_id, following_id) VALUES(?,?)",
            (user_id, target_id),
        )
        await db.commit()
        await message.answer(
            "You are now following this user."
            if cursor.rowcount
            else "You already follow this user."
        )
    elif action == "unfollow":
        cursor = await db.execute(
            "DELETE FROM follows WHERE follower_id=? AND following_id=?",
            (user_id, target_id),
        )
        await db.commit()
        await message.answer(
            "You have unfollowed this user."
            if cursor.rowcount
            else "You do not follow this user."
        )


@router.message(Command("follow"))
async def follow_command(message: Message) -> None:
    await follow_action(message, "follow")


@router.message(Command("unfollow"))
async def unfollow_command(message: Message) -> None:
    await follow_action(message, "unfollow")


@router.message(Command("rmchat"))
async def remove_chat_command(message: Message) -> None:
    if not await social_command_allowed(message):
        return
    args = (message.text or "").split()[1:]
    target_id = await resolve_social_target(message, args)
    if not target_id:
        await message.answer(
            "Reply to a user or use /rmchat @username or /rmchat user_id."
        )
        return
    if target_id == message.from_user.id:
        await message.answer("You cannot remove a chat with yourself.")
        return
    pair = normalized_chat_pair(message.from_user.id, target_id)
    cursor = await db.execute(
        "SELECT 1 FROM private_chats WHERE user_a=? AND user_b=?", pair
    )
    if not await cursor.fetchone():
        await message.answer("This user is not in Your Chats.")
        return
    await db.execute(
        "DELETE FROM private_chat_messages WHERE user_a=? AND user_b=?", pair
    )
    await db.execute(
        "DELETE FROM private_chats WHERE user_a=? AND user_b=?", pair
    )
    await db.commit()
    active_chats.pop(message.from_user.id, None)
    active_chats.pop(target_id, None)
    try:
        await bot.send_message(
            target_id,
            "Your private chat connection was removed. "
            "A new chat request is required to chat again.",
        )
    except (TelegramBadRequest, TelegramForbiddenError):
        pass
    await message.answer(
        "This user was removed from Your Chats. "
        "A new chat request must be approved before chatting again."
    )


@router.message(Command("followers"))
async def followers_count_command(message: Message) -> None:
    if not await social_command_allowed(message):
        return
    args = (message.text or "").split()[1:]
    target_id = await resolve_social_target(message, args) if args or message.reply_to_message else message.from_user.id
    if not target_id:
        await message.answer(
            "Use /followers @username, /followers user_id, or reply to a user's message."
        )
        return
    cursor = await db.execute(
        "SELECT COUNT(*) AS count FROM follows WHERE following_id=?",
        (target_id,),
    )
    total = int((await cursor.fetchone())["count"])
    profile = await get_profile(target_id)
    display_name = html.escape(
        str(profile.get("custom_name") or profile.get("first_name") or "This user")
    )
    await message.answer(
        f"<b>{display_name}</b> has <b>{total}</b> follower"
        f"{'' if total == 1 else 's'}."
    )


async def render_followers(target, user_id: int, page: int = 0) -> None:
    count_cursor = await db.execute(
        "SELECT COUNT(*) AS count FROM follows WHERE following_id=?", (user_id,)
    )
    total = int((await count_cursor.fetchone())["count"])
    max_page = max(0, (total - 1) // SOCIAL_PAGE_SIZE)
    page = max(0, min(page, max_page))
    cursor = await db.execute(
        """SELECT f.follower_id, f.followed_at, u.first_name, u.username,
        p.custom_name FROM follows f LEFT JOIN users u ON u.user_id=f.follower_id
        LEFT JOIN profiles p ON p.user_id=f.follower_id
        WHERE f.following_id=? ORDER BY f.followed_at DESC, f.follower_id DESC
        LIMIT ? OFFSET ?""",
        (user_id, SOCIAL_PAGE_SIZE, page * SOCIAL_PAGE_SIZE),
    )
    rows = await cursor.fetchall()
    lines = [
        f"{page * SOCIAL_PAGE_SIZE + index}. {html.escape(social_user_name(row))} "
        f"(<code>{row['follower_id']}</code>)"
        for index, row in enumerate(rows, 1)
    ]
    text = (
        "<blockquote>"
        f'<tg-emoji emoji-id="5463256910851546817">👥</tg-emoji> <b>Your Followers</b>\n\n'
        f"Total followers: <b>{total}</b>  •  Page {page + 1} of {max_page + 1}\n"
        "━━━━━━━━━━━━━━━━━━━━\n"
        + ("\n".join(lines) if lines else "You do not have any followers yet.")
        + "</blockquote>"
    )
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="Previous", callback_data=f"followers:{page - 1}"))
    if page < max_page:
        nav.append(InlineKeyboardButton(text="Next", callback_data=f"followers:{page + 1}"))
    rows_markup = [nav] if nav else []
    rows_markup += [[
        InlineKeyboardButton(text="Download TXT", callback_data="followers_export"),
    ], [
        InlineKeyboardButton(text="Back to Main Menu", callback_data="home"),
    ]]
    markup = InlineKeyboardMarkup(inline_keyboard=rows_markup)
    if isinstance(target, CallbackQuery):
        if target.message:
            await target.message.edit_text(text, reply_markup=markup)
    else:
        await target.answer(text, reply_markup=markup)


