@router.callback_query(F.data == "followers_export")
async def followers_export(callback: CallbackQuery) -> None:
    if not await group_menu_callback_allowed(callback):
        return
    await callback.answer("Preparing your followers file...")
    cursor = await db.execute(
        """SELECT f.follower_id, f.followed_at, u.first_name, u.username,
        p.custom_name FROM follows f LEFT JOIN users u ON u.user_id=f.follower_id
        LEFT JOIN profiles p ON p.user_id=f.follower_id
        WHERE f.following_id=? ORDER BY f.followed_at DESC, f.follower_id DESC""",
        (callback.from_user.id,),
    )
    rows = await cursor.fetchall()
    output = ["Your Followers", "================", ""]
    for index, row in enumerate(rows, 1):
        try:
            followed = datetime.fromisoformat(str(row["followed_at"])).replace(
                tzinfo=timezone.utc
            ).astimezone(INDIA_TZ)
            followed_text = followed.strftime("%d %B %Y, %I:%M %p IST")
        except ValueError:
            followed_text = str(row["followed_at"])
        username = f"@{row['username']}" if row["username"] else "Not set"
        output.extend([
            f"{index}. {social_user_name(row)}",
            f"User ID: {row['follower_id']}",
            f"Username: {username}",
            f"Followed on: {followed_text}",
            "",
        ])
    document = BufferedInputFile(
        "\n".join(output).encode("utf-8"),
        filename="your_followers.txt",
    )
    await bot.send_document(
        callback.from_user.id, document, caption=f"Your followers: {len(rows)}"
    )


async def create_chat_request(message: Message, target_id: int) -> None:
    sender_id = message.from_user.id
    if sender_id == target_id:
        await message.answer("You cannot send a chat request to yourself.")
        return
    cursor = await db.execute(
        """SELECT id, status FROM chat_requests
        WHERE sender_id=? AND recipient_id=? ORDER BY id DESC LIMIT 1""",
        (sender_id, target_id),
    )
    previous = await cursor.fetchone()
    if previous and previous["status"] == "pending":
        await message.answer("A chat request is already pending.")
        return
    pair = normalized_chat_pair(sender_id, target_id)
    cursor = await db.execute(
        "SELECT 1 FROM private_chats WHERE user_a=? AND user_b=?", pair
    )
    if await cursor.fetchone():
        await message.answer("You already have an accepted chat with this user.")
        return
    await db.execute(
        """INSERT INTO chat_requests(sender_id, recipient_id, status)
        VALUES(?,?, 'pending')""",
        (sender_id, target_id),
    )
    await db.commit()
    await message.answer("Chat request sent.")
    try:
        await bot.send_message(
            target_id,
            f"<b>New chat request</b>\nFrom: {html.escape(message.from_user.full_name)}",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
                InlineKeyboardButton(text="View Requests", callback_data="chat_requests:0")
            ]]),
        )
    except (TelegramBadRequest, TelegramForbiddenError):
        pass


