@router.callback_query(F.data.startswith("request_decide:"))
async def request_decide(callback: CallbackQuery) -> None:
    if not await group_menu_callback_allowed(callback):
        return
    _, request_raw, decision, page_raw = callback.data.split(":")
    if decision not in {"approved", "rejected"}:
        return
    cursor = await db.execute(
        "SELECT sender_id FROM chat_requests WHERE id=? AND recipient_id=? AND status='pending'",
        (int(request_raw), callback.from_user.id),
    )
    row = await cursor.fetchone()
    if not row:
        await callback.answer("This request is no longer available.", show_alert=True)
        return
    sender_id = int(row["sender_id"])
    await db.execute(
        "UPDATE chat_requests SET status=?, updated_at=CURRENT_TIMESTAMP WHERE id=?",
        (decision, int(request_raw)),
    )
    if decision == "approved":
        await db.execute(
            "INSERT OR IGNORE INTO private_chats(user_a, user_b) VALUES(?,?)",
            normalized_chat_pair(sender_id, callback.from_user.id),
        )
    await db.commit()
    try:
        await bot.send_message(
            sender_id,
            "Your chat request was approved." if decision == "approved"
            else "Your chat request was rejected.",
        )
    except (TelegramBadRequest, TelegramForbiddenError):
        pass
    await callback.answer("Request updated.")
    await render_requests(callback, int(page_raw))


