@router.callback_query(F.data.startswith("chat_select:"))
async def chat_select(callback: CallbackQuery) -> None:
    if not await group_menu_callback_allowed(callback):
        return
    callback_parts = callback.data.split(":")
    partner_id = int(callback_parts[1])
    chats_page_number = (
        int(callback_parts[2]) if len(callback_parts) > 2 else 0
    )
    cursor = await db.execute(
        "SELECT 1 FROM private_chats WHERE user_a=? AND user_b=?",
        normalized_chat_pair(callback.from_user.id, partner_id),
    )
    if not await cursor.fetchone():
        await callback.answer("This chat is no longer available.", show_alert=True)
        return
    active_chats[callback.from_user.id] = partner_id
    await db.execute(
        "DELETE FROM private_chat_messages WHERE created_at < datetime('now', '-7 days')"
    )
    await db.commit()
    history_cursor = await db.execute(
        """SELECT sender_id, content_type, content
        FROM private_chat_messages
        WHERE user_a=? AND user_b=? ORDER BY id DESC LIMIT 20""",
        normalized_chat_pair(callback.from_user.id, partner_id),
    )
    history = list(reversed(await history_cursor.fetchall()))
    partner_profile = await get_profile(partner_id)
    partner_name = html.escape(str(
        partner_profile.get("custom_name")
        or partner_profile.get("first_name")
        or partner_profile.get("username")
        or "User"
    ))
    history_lines = []
    for row in history:
        speaker = "You" if row["sender_id"] == callback.from_user.id else partner_name
        content = row["content"] or f"[{row['content_type']}]"
        history_lines.append(f"<b>{speaker}</b>: {html.escape(str(content))}")
    history_text = (
        "<b>Recent chat history:</b>\n" + "\n".join(history_lines) + "\n\n"
        if history else "No previous messages in this chat.\n\n"
    )
    await callback.answer()
    await callback.message.edit_text(
        "<b>Chat Mode Active</b>\n\n"
        + history_text
        + "Reply here or tag the user to send text, photos, videos, audio, documents, or stickers.\n"
        + "Personal chat history is automatically cleared every 7 days for both users.",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(
                text="Remove User",
                callback_data=f"chat_remove:{partner_id}:{chats_page_number}",
            ),
        ], [
            InlineKeyboardButton(
                text="Back to Chats",
                callback_data=f"your_chats:{chats_page_number}",
            ),
        ], [
            InlineKeyboardButton(text="Back to Main Menu", callback_data="home"),
        ]]),
    )


@router.callback_query(F.data.startswith("chat_remove:"))
async def chat_remove(callback: CallbackQuery) -> None:
    if not await group_menu_callback_allowed(callback):
        return
    callback_parts = callback.data.split(":")
    partner_id = int(callback_parts[1])
    chats_page_number = (
        int(callback_parts[2]) if len(callback_parts) > 2 else 0
    )
    pair = normalized_chat_pair(callback.from_user.id, partner_id)
    cursor = await db.execute(
        "SELECT 1 FROM private_chats WHERE user_a=? AND user_b=?", pair
    )
    if not await cursor.fetchone():
        await callback.answer("This user is not in Your Chats.", show_alert=True)
        return
    await db.execute(
        "DELETE FROM private_chat_messages WHERE user_a=? AND user_b=?", pair
    )
    await db.execute(
        "DELETE FROM private_chats WHERE user_a=? AND user_b=?", pair
    )
    await db.execute(
        """DELETE FROM chat_requests
        WHERE (sender_id=? AND recipient_id=?)
           OR (sender_id=? AND recipient_id=?)""",
        (pair[0], pair[1], pair[1], pair[0]),
    )
    await db.commit()
    active_chats.pop(callback.from_user.id, None)
    active_chats.pop(partner_id, None)
    try:
        await bot.send_message(
            partner_id,
            "Your private chat connection was removed. "
            "A new chat request is required to chat again.",
        )
    except (TelegramBadRequest, TelegramForbiddenError):
        pass
    await callback.answer("User removed from Your Chats.")
    await callback.message.edit_text(
        "<b>User removed</b>\n\n"
        "The chat, history, and connection were removed for both users. "
        "A new chat request is required to chat again.",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(
                text="Back to Chats",
                callback_data=f"your_chats:{chats_page_number}",
            ),
        ], [
            InlineKeyboardButton(text="Back to Main Menu", callback_data="home"),
        ]]),
    )


