async def relay_active_chat(message: Message) -> bool:
    if message.chat.type != ChatType.PRIVATE or message.from_user is None:
        return False
    partner_id = active_chats.get(message.from_user.id)
    if not partner_id:
        return False
    pair = normalized_chat_pair(message.from_user.id, partner_id)
    cursor = await db.execute(
        "SELECT 1 FROM private_chats WHERE user_a=? AND user_b=?", pair
    )
    if not await cursor.fetchone():
        active_chats.pop(message.from_user.id, None)
        await message.answer("This chat is no longer available.")
        return True
    sender_name = html.escape(message.from_user.full_name or "User")
    try:
        if message.text:
            await bot.send_message(
                partner_id,
                f"<b>Message from {sender_name}</b>\n{html.escape(message.text)}",
            )
        else:
            await bot.send_message(
                partner_id,
                f"<b>Media from {sender_name}</b>",
            )
            await bot.copy_message(
                chat_id=partner_id,
                from_chat_id=message.chat.id,
                message_id=message.message_id,
            )
        if message.text:
            content_type, content = "text", message.text
        elif message.caption:
            content_type, content = "media", message.caption
        elif message.photo:
            content_type, content = "photo", None
        elif message.video:
            content_type, content = "video", None
        elif message.audio:
            content_type, content = "audio", None
        elif message.document:
            content_type, content = "document", None
        elif message.sticker:
            content_type, content = "sticker", None
        else:
            content_type, content = "media", None
        await db.execute(
            """INSERT INTO private_chat_messages
            (user_a, user_b, sender_id, content_type, content)
            VALUES(?,?,?,?,?)""",
            (*pair, message.from_user.id, content_type, content),
        )
        await db.execute(
            """DELETE FROM private_chat_messages WHERE id NOT IN
            (SELECT id FROM private_chat_messages
             WHERE user_a=? AND user_b=? ORDER BY id DESC LIMIT 200)
            AND user_a=? AND user_b=?""",
            (*pair, *pair),
        )
        active_chats[partner_id] = message.from_user.id
        await db.execute(
            """UPDATE private_chats SET last_message_at=CURRENT_TIMESTAMP
            WHERE user_a=? AND user_b=?""",
            pair,
        )
        await db.commit()
        partner_profile = await get_profile(partner_id)
        partner_name = html.escape(str(
            partner_profile.get("custom_name")
            or partner_profile.get("first_name")
            or partner_profile.get("username")
            or "user"
        ))
        await message.answer(f"Message sent to <b>{partner_name}</b>.")
        return True
    except (TelegramBadRequest, TelegramForbiddenError):
        await message.answer("This user cannot receive messages right now.")
        return True


ARCADE_MAX_PLAYERS: int | None = None
UNLIMITED_PLAYERS_LABEL = "Unlimited"
ARCADE_ROUND_SECONDS = 15
MATHBATTLE_ROUND_SECONDS = 10
MATHBATTLE_LEVEL_SECONDS = {"basic": 15, "medium": 25, "hard": 30}
_MATHBATTLE_BANK: dict[str, list[tuple[str, int]]] | None = None
_MATHBATTLE_UNUSED: dict[str, list[tuple[str, int]]] = {}


def mathbattle_file_bank() -> dict[str, list[tuple[str, int]]]:
    global _MATHBATTLE_BANK
    if _MATHBATTLE_BANK is not None:
        return _MATHBATTLE_BANK
    bank: dict[str, list[tuple[str, int]]] = {"basic": [], "medium": [], "hard": []}
    try:
        path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "mathbattle.txt")
        level = question = None
        with open(path, encoding="utf-8") as fh:
            for raw in fh:
                line = raw.strip()
                if line.startswith("Level:"):
                    level = line[6:].strip().lower()
                elif line.startswith("Question:"):
                    question = line[9:].strip()
                elif line.startswith("Answer:"):
                    ans = line[7:].strip()
                    if level in bank and question and re.fullmatch(r"-?\d+", ans):
                        bank[level].append((question, int(ans)))
                    level = question = None
    except Exception:
        pass
    _MATHBATTLE_BANK = bank
    return bank


def mathbattle_file_pick(level: str) -> tuple[str, int] | None:
    bank = mathbattle_file_bank().get(level) or []
    if not bank:
        return None
    pool = _MATHBATTLE_UNUSED.get(level)
    if not pool:
        pool = list(bank)
        random.shuffle(pool)
        _MATHBATTLE_UNUSED[level] = pool
    return pool.pop()


TBATTLE_LEVEL_SECONDS = {"basic": 20, "medium": 20, "hard": 30}
_TBATTLE_UNUSED: dict[str, list] = {}


def mathbattle_seconds(session) -> int:
    lvl = str((session or {}).get("difficulty", "basic"))
    if (session or {}).get("game") == "tbattle":
        return TBATTLE_LEVEL_SECONDS.get(lvl, 15)
    return MATHBATTLE_LEVEL_SECONDS.get(lvl, 15)


def tbattle_pick(level: str):
    bank = translation_file_bank().get(level) or []
    if not bank:
        return None
    pool = _TBATTLE_UNUSED.get(level)
    if not pool:
        pool = list(bank)
        random.shuffle(pool)
        _TBATTLE_UNUSED[level] = pool
    return pool.pop()


def timed_level_game(session) -> bool:
    return bool(session) and session.get("game") in {"mathbattle", "tbattle"}


def format_math_question(question: str) -> str:
    """Display common plain-text powers as readable superscripts in Telegram."""
    superscript = str.maketrans("0123456789+-", "⁰¹²³⁴⁵⁶⁷⁸⁹⁺⁻")
    return re.sub(
        r"\^\s*\(?([+-]?\d+)\)?",
        lambda match: match.group(1).translate(superscript),
        question,
    )
