def arcade_player_data(user: object) -> dict[str, object]:
    return {
        "id": int(getattr(user, "id")),
        "first_name": str(getattr(user, "first_name", None) or "Player")[:80],
        "username": str(getattr(user, "username", None) or "")[:64],
    }


def arcade_player_name(player: dict[str, object]) -> str:
    return html.escape(str(player.get("first_name") or "Player"))


def arcade_players(session: dict[str, object]) -> dict[int, dict[str, object]]:
    return {int(player["id"]): player for player in session["players"]}


def arcade_player_label(session: dict[str, object], user_id: int) -> str:
    return arcade_player_name(
        arcade_players(session).get(user_id, {"first_name": "Player"})
    )


def arcade_register_player(
    session: dict[str, object], user: object, chat_id: int
) -> bool:
    """Add an answerer once, without requiring a second start command."""
    user_id = int(getattr(user, "id"))
    if user_id in arcade_players(session):
        return True
    if (
        ARCADE_MAX_PLAYERS is not None
        and len(session["players"]) >= ARCADE_MAX_PLAYERS
    ):
        return False
    owned_chat_id = arcade_player_sessions.get(user_id)
    if owned_chat_id is not None and owned_chat_id != chat_id:
        owned_emoji = emoji_rush_sessions.get(owned_chat_id)
        owned_arcade = arcade_sessions.get(owned_chat_id)
        if owned_emoji or owned_arcade:
            return False
        arcade_player_sessions.pop(user_id, None)
    session["players"].append(arcade_player_data(user))
    session["scores"][user_id] = 0
    arcade_player_sessions[user_id] = chat_id
    return True


def arcade_spec(session_or_game: dict[str, object] | str) -> dict[str, object]:
    game = (
        str(session_or_game)
        if isinstance(session_or_game, str)
        else str(session_or_game["game"])
    )
    return ARCADE_SPECS[game]


def group_active_games(chat_id: int) -> list[tuple[str, str]]:
    """Return every active game/setup in a group with a readable title."""
    active: list[tuple[str, str]] = []
    if mathbattle_setups.get(chat_id):
        active.append(("mathbattle_setup", "Translation Battle setup" if mathbattle_setups[chat_id].get("kind") == "tbattle" else "Math Battle setup"))
    arcade_session = arcade_sessions.get(chat_id)
    if arcade_session:
        active.append((
            str(arcade_session.get("game", "arcade")),
            str(arcade_spec(arcade_session)["title"]),
        ))
    if emoji_rush_sessions.get(chat_id):
        active.append(("emoji", "Emoji Rush"))
    if codebreaker_sessions.get(chat_id):
        active.append(("codebreaker", "Code Breaker"))
    if sequencemaster_sessions.get(chat_id):
        active.append(("sequencemaster", "Sequence Master"))
    if crossgrid_sessions.get(chat_id):
        active.append(("crossgrid", "Cross Grid"))
    quiz_session = quiz_sessions.get(chat_id)
    if quiz_session:
        active.append(("quiz", quiz_title(quiz_session)))
    if tictac_sessions.get(chat_id):
        active.append(("tictac", "Tic Tac Toe"))
    if mafia_sessions.get(chat_id):
        active.append(("mafia", "Mafia"))
    if death_note_sessions.get(chat_id):
        active.append(("deathnote", "Death Note"))
    return active


def other_active_group_game(chat_id: int, starting_game: str) -> str | None:
    # Tic Tac Toe is independent from the other games. Its lobby/match can
    # stay active while users start Quiz, Arcade, or any other group game.
    return next(
        (
            title
            for game, title in group_active_games(chat_id)
            if game != starting_game and game != "tictac"
        ),
        None,
    )


def group_game_conflict_text(active_game: str, starting_game: str) -> str:
    return (
        f"<b>{html.escape(active_game)}</b> is already active in this group.\n"
        f"To end {html.escape(active_game)} game use "
        f"<code>/end {_end_cmd_for_title(active_game)}</code>"
    )


def _end_cmd_for_title(title: str) -> str:
    t = title.lower()
    for key, cmd in (("translation battle", "translation"), ("math", "mathbattle"), ("tic", "tictac"), ("mafia", "mafia"),
                     ("death", "deathnote"), ("code", "codebreaker"), ("sequence", "sequencemaster"),
                     ("cross", "crossgrid"), ("emoji", "emoji"), ("quiz", "quiz"),
                     ("scramble", "scramble"), ("high", "highlow"), ("reaction", "reaction")):
        if key in t:
            return cmd
    return "games"


REMOVED_GAME_MESSAGE = (
    "This game has been removed from ˹Dᴇsᴛʀᴏʏᴇʀ ꭙ ᴍᴜsɪᴄ ᴀssɪsᴛᴀɴᴛ Games. "
    "Please choose another game from the Games menu."
)


async def removed_game_command(message: Message) -> None:
    await message.answer(REMOVED_GAME_MESSAGE)


def emoji_rush_normalize(value: str) -> str:
    normalized = re.sub(r"[^a-z0-9]+", " ", value.casefold()).strip()
    if normalized.startswith("the "):
        normalized = normalized[4:]
    return normalized


async def select_emoji_rush_questions(chat_id: int) -> list[dict[str, str]]:
    recent_cursor = await db.execute(
        """SELECT question_id FROM emoji_rush_question_usage
           WHERE chat_id=? ORDER BY used_at DESC LIMIT ?""",
        (chat_id, len(EMOJI_RUSH_QUESTIONS) // 2),
    )
    recent_ids = {str(row[0]) for row in await recent_cursor.fetchall()}
    usage_cursor = await db.execute(
        """SELECT question_id, COUNT(*), MAX(used_at)
           FROM emoji_rush_question_usage
           GROUP BY question_id"""
    )
    global_usage = {
        str(row[0]): (int(row[1]), float(row[2] or 0))
        for row in await usage_cursor.fetchall()
    }
    random_order = {question[0]: random.random() for question in EMOJI_RUSH_QUESTIONS}
    ordered = sorted(
        EMOJI_RUSH_QUESTIONS,
        key=lambda question: (
            question[0] in recent_ids,
            global_usage.get(question[0], (0, 0))[0],
            global_usage.get(question[0], (0, 0))[1],
            random_order[question[0]],
        ),
    )
    selected = ordered[:EMOJI_RUSH_TOTAL_QUESTIONS]
    used_at = time.time()
    for question_id, _emojis, _answer, _hint in selected:
        await db.execute(
            """INSERT INTO emoji_rush_question_usage(chat_id, question_id, used_at)
               VALUES(?,?,?)
               ON CONFLICT(chat_id, question_id) DO UPDATE SET used_at=excluded.used_at""",
            (chat_id, question_id, used_at),
        )
    await db.commit()
    return [
        {
            "id": question_id,
            "emojis": emojis,
            "answer": answer,
            "hint": hint,
        }
        for question_id, emojis, answer, hint in selected
    ]


def emoji_rush_equation_parts(emojis: str) -> str:
    tokens = str(emojis).split()
    return " + ".join(
        f"{token} {EMOJI_RUSH_EMOJI_NAMES.get(token, 'Emoji')}"
        for token in tokens
    )


def emoji_rush_board_text(
    session: dict[str, object],
    final: bool = False,
    update: str | None = None,
) -> str:
    title = "FINAL ANSWERS" if final else ("UPDATED BOARD" if update else "LIVE")
    lines = []
    for index, question in enumerate(session["questions"], 1):
        equation = emoji_rush_equation_parts(str(question["emojis"]))
        solved_by = session["solved_by"].get(index)
        if solved_by:
            lines.append(
                f"<b>{index:02d}. {equation} = "
                f"{html.escape(str(question['answer']))} ✅</b>"
            )
        else:
            lines.append(
                f"<b>{index:02d}. {equation} = ❓</b>\n"
                f"<i>💡 <b>Hint:</b> {html.escape(str(question['hint']))}</i>"
            )
    header = (
        "<b>🎭 EMOJI RUSH</b>\n"
        "<i>✨ Solve the emoji puzzle</i>\n"
        "<b>━━━━━━━━━━━━━━━━━━</b>\n"
        f"<b>🔟 {EMOJI_RUSH_TOTAL_QUESTIONS} CLUES  •  ⏳ NO TIMER</b>\n\n"
    )
    board = (
        header
        + f"<b>📌 {title}</b>\n\n"
        + "\n\n".join(lines)
        + (
            "\n\n<b>All 10 clues are solved.</b>"
            if final else ""
        )
    )
    return f"{update}\n\n{board}" if update else board


async def finish_emoji_rush(
    session: dict[str, object], reason: str = "completed"
) -> None:
    chat_id = int(session["chat_id"])
    session["state"] = "finished"
    ranking = sorted(
        ((int(user_id), int(score)) for user_id, score in session["scores"].items()),
        key=lambda item: (-item[1], item[0]),
    )
    awarded = await arcade_award_rewards(
        session,
        [(user_id, score) for user_id, score in ranking if score > 0],
    )
    correct_counts = {
        int(user_id): list(session["solved_by"].values()).count(int(user_id))
        for user_id in session["scores"]
    }
    answer_lines = []
    for index, question in enumerate(session["questions"], 1):
        equation = emoji_rush_equation_parts(str(question["emojis"]))
        answer_lines.append(
            f"<b>{index:02d}. {equation} = "
            f"{html.escape(str(question['answer']))} ✅</b>"
        )
    player_lines = [
        f"<b>{rank}. {arcade_player_label(session, user_id)}</b>\n"
        f"<b>✅ Correct:</b> {correct_counts.get(user_id, 0)}/"
        f"{EMOJI_RUSH_TOTAL_QUESTIONS}\n"
        f"<b>⭐ Score:</b> {score} pts\n"
        f"<b>Reward:</b> {awarded.get(user_id, 0)} Seyu Gems"
        for rank, (user_id, score) in enumerate(ranking, 1)
    ]
    status = (
        "All 10 clues were solved."
        if reason == "completed"
        else "The game was ended manually. Unsolved clues are still revealed below."
    )
    await bot.send_message(
        chat_id,
        "<b>🎭 EMOJI RUSH — FINAL RESULTS</b>\n\n"
        f"<b>Status:</b> {status}\n\n"
        "<b>📚 ALL ANSWERS</b>\n"
        + "\n".join(answer_lines)
        + "\n\n<b>🏆 LEADERBOARD</b>\n"
        + ("\n".join(player_lines) if player_lines else "No scores yet.")
        + "\n\nStart a new board with <code>/emojirush</code>.",
    )
    clear_arcade_players(chat_id, session)
    emoji_rush_sessions.pop(chat_id, None)


async def start_emoji_rush(message: Message) -> None:
    if message.chat.type not in {ChatType.GROUP, ChatType.SUPERGROUP}:
        await message.answer("Emoji Rush can only be played in a group.")
        return
    if not message.from_user or message.from_user.is_bot:
        return
    if await group_command_is_locked(message):
        return
    chat_id = message.chat.id
    user_id = message.from_user.id
    async with emoji_rush_locks[chat_id]:
        session = emoji_rush_sessions.get(chat_id)
        if session:
            if session["state"] != "live":
                await message.answer("Emoji Rush is finishing. Start a new board in a moment.")
                return
            if user_id in arcade_players(session):
                await message.answer(
                    "⚠️ Live Emoji Rush is already on. You are already playing it."
                )
                return
            await message.answer(
                "⚠️ Live Emoji Rush is already on in this group.\n"
                "No join command is needed. Send your answer directly.\n"
                "To end it and reveal all answers, use <code>/end emojirush</code>."
            )
            return
        active_game = other_active_group_game(chat_id, "emoji")
        if active_game:
            await message.answer(
                group_game_conflict_text(active_game, "Emoji Rush")
            )
            return
        questions = await select_emoji_rush_questions(chat_id)
        player = arcade_player_data(message.from_user)
        session = {
            "session_id": secrets.token_hex(8),
            "chat_id": chat_id,
            "game": "emoji",
            "state": "live",
            "players": [player],
            "questions": questions,
            "solved_by": {},
            "scores": {user_id: 0},
            "message_id": 0,
        }
        board = await message.answer(
            emoji_rush_board_text(session),
        )
        session["message_id"] = board.message_id
        emoji_rush_sessions[chat_id] = session
        arcade_player_sessions[user_id] = chat_id


async def handle_emoji_rush_guess(message: Message) -> bool | None:
    if not message.from_user or message.from_user.is_bot:
        return None
    chat_id = message.chat.id
    user_id = message.from_user.id
    async with emoji_rush_locks[chat_id]:
        session = emoji_rush_sessions.get(chat_id)
        if not session or session["state"] != "live":
            return None
        is_player = user_id in arcade_players(session)
        raw_answer = (message.text or "").strip()
        if not raw_answer or raw_answer.startswith("/"):
            return True
        question_index = next(
            (
                index
                for index, question in enumerate(session["questions"], 1)
                if index not in session["solved_by"]
                and emoji_rush_normalize(raw_answer)
                == emoji_rush_normalize(str(question["answer"]))
            ),
            None,
        )
        if question_index is None:
            return True if is_player else None
        if not arcade_register_player(session, message.from_user, chat_id):
            await message.answer(
                "This game is full, or you are already playing a game in another group."
            )
            return True
        points = max(5, 21 - len(session["solved_by"]))
        session["solved_by"][question_index] = user_id
        session["scores"][user_id] += points
        await message.answer(
            emoji_rush_board_text(
                session,
                update=(
                    f"<b>✅ QUESTION {question_index:02d} SOLVED</b>\n"
                    f"<b>⭐ Points Earned:</b> +{points}"
                ),
            )
        )
        completed = len(session["solved_by"]) == EMOJI_RUSH_TOTAL_QUESTIONS
        if completed:
            session["state"] = "finishing"
    if completed:
        await finish_emoji_rush(session)
    return True


async def end_emoji_rush(message: Message) -> None:
    if message.chat.type not in {ChatType.GROUP, ChatType.SUPERGROUP}:
        return
    if not message.from_user:
        return
    chat_id = message.chat.id
    async with emoji_rush_locks[chat_id]:
        session = emoji_rush_sessions.get(chat_id)
        if not session:
            await message.answer("No live Emoji Rush is running in this group.")
            return
        if (
            message.from_user.id not in ADMIN_IDS
            and message.from_user.id != int(session["players"][0]["id"])
            and not await group_admin(chat_id, message.from_user.id)
        ):
            await message.answer("Only the game starter or a group admin can end Emoji Rush.")
            return
        await finish_emoji_rush(session, reason="manual")


def arcade_make_round(
    game: str,
    round_number: int,
    difficulty: str = "basic",
) -> dict[str, object]:
    if game == "emoji":
        clue, options, correct = random.choice(ARCADE_EMOJI_QUESTIONS)
        return {
            "prompt": f"<b>Decode this:</b> {clue}",
            "options": options,
            "correct": correct,
        }
    if game == "scramble":
        word, clue = random.choice(ARCADE_WORDS)
        letters = list(word)
        random.shuffle(letters)
        scrambled = "".join(letters)
        options = [word]
        decoys = [item[0] for item in ARCADE_WORDS if item[0] != word]
        options.extend(random.sample(decoys, 3))
        random.shuffle(options)
        return {
            "prompt": (
                f"<b>Unscramble:</b> <code>{scrambled}</code>\n"
                f"Hint: {html.escape(clue)}"
            ),
            "options": options,
            "correct": options.index(word),
        }
    if game == "tbattle":
        level = difficulty if difficulty in {"basic", "medium", "hard"} else "basic"
        item = tbattle_pick(level)
        if item:
            question, answer, options = item
            hindi, _, tense = question.partition("\nTense: ")
            hindi = re.sub(r"^\s*translate\s*:\s*", "", hindi, flags=re.I)
            return {
                "prompt": (
                    f"<b>Translate into English:</b>\n{html.escape(hindi)}\n"
                    + (f"<b>Tense:</b> {html.escape(tense)}\n" if tense else "")
                ),
                "answer": str(answer),
                "options": [str(answer)],
                "correct": 0,
                "difficulty": level,
            }
        return {"prompt": "<b>Translate into English:</b>\nमैं घर जाता हूँ।",
                "answer": "I go home.", "options": ["I go home."],
                "correct": 0, "difficulty": level}
    if game == "mathbattle":
        level = difficulty if difficulty in {"basic", "medium", "hard"} else "basic"
        _picked = mathbattle_file_pick(level)
        if _picked:
            _q, _a = _picked
            return {
                "prompt": f"<b>Solve:</b> {html.escape(format_math_question(_q))}",
                "answer": int(_a),
                "options": [str(_a)],
                "correct": 0,
                "difficulty": level,
            }
        if level == "basic":
            maximum = 20
            operator = random.choice(["+", "-", "×", "÷"])
        elif level == "medium":
            maximum = 60
            operator = random.choice(["+", "-", "×", "÷"])
        else:
            maximum = 150
            operator = random.choice(["+", "-", "×", "÷"])
        if operator == "÷":
            right_max = min(12 if level == "basic" else 20, maximum // 2)
            right = random.randint(2, right_max)
            correct = random.randint(2, maximum // max(2, right))
            left = right * correct
        elif operator == "-":
            left = random.randint(maximum // 2, maximum)
            right = random.randint(2, max(2, left - 1))
            correct = left - right
        elif operator == "×":
            left = random.randint(2, 12 if level == "basic" else 20)
            right = random.randint(2, 10 if level == "basic" else 15)
            correct = left * right
        else:
            left = random.randint(2, maximum)
            right = random.randint(2, maximum)
            correct = left + right
        return {
            "prompt": f"<b>Solve:</b> {left} {operator} {right} = ?",
            "answer": int(correct),
            "options": [str(correct)],
            "correct": 0,
            "difficulty": level,
        }
    if game == "reaction":
        colors = ["🔴 Red", "🔵 Blue", "🟢 Green", "🟡 Yellow"]
        target = random.choice(colors)
        options = list(colors)
        random.shuffle(options)
        return {
            "prompt": (
                f"<b>Reaction target:</b> {target}\n"
                "Tap the matching color as fast as you can."
            ),
            "options": options,
            "correct": options.index(target),
        }
    first = random.randint(1, 13)
    second = random.randint(1, 13)
    correct = 0 if second > first else 1 if second < first else 2
    return {
        "prompt": (
            f"<b>Card {round_number}</b>\n"
            f"Current card: <b>{first}</b>\n"
            "What will the next card be?"
        ),
        "options": ["⬆️ Higher", "⬇️ Lower", "🟰 Equal"],
        "correct": correct,
    }


def arcade_round_text(session: dict[str, object]) -> str:
    spec = arcade_spec(session)
    round_seconds = (
        mathbattle_seconds(session)
        if timed_level_game(session)
        else ARCADE_ROUND_SECONDS
    )
    difficulty_line = (
        f"<b>Difficulty:</b> {str(session.get('difficulty', 'basic')).title()}\n"
        if timed_level_game(session)
        else ""
    )
    return (
        f"<b>{spec['icon']} {spec['title']} — ROUND {session['round']}/"
        f"{ARCADE_ROUNDS}</b>\n\n"
        f"{difficulty_line}"
        f"{session['current']['prompt']}\n\n"
        f"Time: <b>{round_seconds} seconds</b>"
    )


def cancel_arcade_task(chat_id: int) -> None:
    task = arcade_tasks.pop(chat_id, None)
    if task and task is not asyncio.current_task():
        task.cancel()


def clear_arcade_players(chat_id: int, session: dict[str, object]) -> None:
    for player in session["players"]:
        user_id = int(player["id"])
        if arcade_player_sessions.get(user_id) == chat_id:
            arcade_player_sessions.pop(user_id, None)


async def arcade_award_rewards(
    session: dict[str, object], ranking: list[tuple[int, int]]
) -> dict[int, int]:
    rewards = {1: 100, 2: 80, 3: 70, 4: 60, 5: 50}
    positive_ranking = [
        (user_id, score) for user_id, score in ranking if score > 0
    ][: len(rewards)]
    awarded: dict[int, int] = {}
    for rank, (user_id, _score) in enumerate(positive_ranking, 1):
        amount = rewards[rank]
        cursor = await db.execute(
            """INSERT OR IGNORE INTO arcade_reward_claims
            (session_id,user_id,rank,amount) VALUES(?,?,?,?)""",
            (str(session["session_id"]), user_id, rank, amount),
        )
        if cursor.rowcount:
            await db.execute(
                """INSERT INTO users(user_id, first_name, username, seyu_gems)
                VALUES(?,?,?,?)
                ON CONFLICT(user_id) DO UPDATE SET
                seyu_gems=users.seyu_gems+excluded.seyu_gems""",
                (
                    user_id,
                    str(arcade_players(session)[user_id]["first_name"]),
                    str(arcade_players(session)[user_id].get("username") or ""),
                    amount,
                ),
            )
            awarded[user_id] = amount
    try:
        c_id = int(session.get("chat_id", 0))
        if c_id:
            note_group_feature_activity(c_id, "game")
    except Exception:
        pass
    await db.commit()
    return awarded


async def finish_arcade_game(
    session: dict[str, object], reason: str = "completed"
) -> None:
    chat_id = int(session["chat_id"])
    session["state"] = "finishing"
    cancel_arcade_task(chat_id)
    ranking = sorted(
        ((int(user_id), int(score)) for user_id, score in session["scores"].items()),
        key=lambda item: (-item[1], item[0]),
    )
    awarded = await arcade_award_rewards(session, ranking)
    lines = []
    for rank, (user_id, score) in enumerate(ranking, 1):
        reward = awarded.get(user_id, 0)
        lines.append(
            f"{rank}. {arcade_player_label(session, user_id)} — "
            f"<b>{score}</b> pts (+{reward} Seyu Gems)"
        )
    spec = arcade_spec(session)
    status = (
        "All rounds were completed."
        if reason == "completed"
        else "The game was ended manually. Scores earned so far are shown below."
    )
    await bot.send_message(
        chat_id,
        f"<b>{spec['icon']} {spec['title']} — FINAL RESULTS</b>\n\n"
        f"<b>Status:</b> {status}\n\n"
        + "\n".join(lines)
        + "\n\nTop 5 players with positive scores receive 100, 80, 70, 60, and 50 Seyu Gems.\n"
        "Start another match with the game command.",
    )
    session["state"] = "finished"
    clear_arcade_players(chat_id, session)
    arcade_sessions.pop(chat_id, None)


async def resolve_arcade_round(chat_id: int, round_number: int) -> None:
    async with arcade_locks[chat_id]:
        session = arcade_sessions.get(chat_id)
        if (
            not session
            or session["state"] != "round"
            or int(session["round"]) != round_number
        ):
            return
        answers = session["answers"]
        correct_index = int(session["current"]["correct"])
        correct_answers = sorted(
            (
                (int(user_id), data)
                for user_id, data in answers.items()
                if int(data["choice"]) == correct_index
            ),
            key=lambda item: float(item[1]["elapsed"]),
        )
        gains: dict[int, int] = {}
        for position, (user_id, _data) in enumerate(correct_answers):
            gain = max(8, 22 - position * 5)
            session["scores"][user_id] += gain
            gains[user_id] = gain
        wrong_count = len(answers) - len(correct_answers)
        result_lines = [
            f"• {arcade_player_label(session, user_id)} +{gain} pts"
            for user_id, gain in gains.items()
        ]
        if session.get("game") == "tbattle":
            for _uid, _gain in gains.items():
                try:
                    await tbattle_add_global_points(_uid, session, _gain)
                except Exception:
                    log.exception("tbattle points save failed")
        answer_line = ""
        if session.get("game") in {"mathbattle", "tbattle"}:
            answer_line = (
                f"\n\nAnswer: <b>{html.escape(str(session['current']['answer']))}</b>"
            )
        result_text = (
            f"<b>ROUND {round_number} RESULT</b>\n\n"
            + ("\n".join(result_lines) if result_lines else "Nobody found the answer.")
            + answer_line
            + f"\n\nCorrect answers: <b>{len(correct_answers)}</b> • "
            f"Wrong/missed: <b>{wrong_count}</b>"
        )
        await bot.send_message(chat_id, result_text)
        if round_number >= ARCADE_ROUNDS:
            await finish_arcade_game(session)
            return
        await asyncio.sleep(1)
        session["round"] = round_number + 1
        session["answers"] = {}
        session["current"] = arcade_make_round(
            str(session["game"]),
            int(session["round"]),
            str(session.get("difficulty", "basic")),
        )
        session["round_started"] = time.monotonic()
        await bot.send_message(
            chat_id,
            arcade_round_text(session),
        )
        arcade_tasks[chat_id] = asyncio.create_task(
            arcade_round_timer(chat_id, int(session["round"]))
        )


async def safe_resolve_arcade_round(chat_id: int, round_number: int) -> None:
    try:
        await resolve_arcade_round(chat_id, round_number)
    except asyncio.CancelledError:
        raise
    except Exception:
        log.exception("Arcade round failed for chat %s", chat_id)
        session = arcade_sessions.pop(chat_id, None)
        arcade_tasks.pop(chat_id, None)
        if session:
            clear_arcade_players(chat_id, session)
            try:
                await bot.send_message(
                    chat_id,
                    "This quick game stopped safely because of an internal error. "
                    "No Seyu Gems were charged.",
                )
            except Exception:
                pass


async def arcade_round_timer(chat_id: int, round_number: int) -> None:
    try:
        session = arcade_sessions.get(chat_id)
        round_seconds = (
            mathbattle_seconds(session)
            if timed_level_game(session)
            else ARCADE_ROUND_SECONDS
        )
        await asyncio.sleep(round_seconds)
        if arcade_tasks.get(chat_id) is asyncio.current_task():
            arcade_tasks.pop(chat_id, None)
        await safe_resolve_arcade_round(chat_id, round_number)
    except asyncio.CancelledError:
        raise


async def create_arcade_live_game(message: Message, game: str) -> None:
    if message.chat.type not in {ChatType.GROUP, ChatType.SUPERGROUP}:
        await message.answer("These games can only be played in a group.")
        return
    if not message.from_user or message.from_user.is_bot:
        return
    if await group_command_is_locked(message):
        return
    chat_id = message.chat.id
    async with arcade_locks[chat_id]:
        if emoji_rush_sessions.get(chat_id):
            await message.answer(
                "⚠️ Emoji Rush is already live in this group. "
                "No join command is needed; send an Emoji Rush answer directly."
            )
            return
        active_session = arcade_sessions.get(chat_id)
        if active_session:
            if active_session["game"] != game or active_session["state"] != "round":
                await message.answer(
                    f"<b>{arcade_spec(active_session)['title']}</b> is already live "
                    "in this group. Join after it finishes."
                )
                return
            await message.answer(
                f"<b>{arcade_spec(game)['title']}</b> is already live.\n"
                "No join command is needed. Send your answer directly for "
                f"round {active_session['round']}/{ARCADE_ROUNDS}."
            )
            return
        active_game = other_active_group_game(chat_id, game)
        if active_game:
            await message.answer(
                group_game_conflict_text(active_game, arcade_spec(game)["title"])
            )
            return
        owned_chat_id = arcade_player_sessions.get(message.from_user.id)
        if owned_chat_id and owned_chat_id != chat_id:
            await message.answer("You already have a live game active in another group.")
            return
        player = arcade_player_data(message.from_user)
        spec = arcade_spec(game)
        session = {
            "session_id": secrets.token_hex(8),
            "chat_id": chat_id,
            "game": game,
            "state": "round",
            "creator_id": message.from_user.id,
            "players": [player],
            "round": 1,
            "answers": {},
            "scores": {message.from_user.id: 0},
            "current": arcade_make_round(game, 1),
            "round_started": time.monotonic(),
        }
        arcade_sessions[chat_id] = session
        arcade_player_sessions[message.from_user.id] = chat_id
        await message.answer(
            f"<b>{spec['icon']} {spec['title']}</b>\n\n"
            f"{spec['description']}\n"
            "Live game started immediately.\n"
            "Everyone in the group can answer directly; no join command is needed.\n\n"
            + arcade_round_text(session),
        )
        arcade_tasks[chat_id] = asyncio.create_task(arcade_round_timer(chat_id, 1))


