async def mathbattle_setup_allowed(
    callback: CallbackQuery, setup: dict[str, object]
) -> bool:
    if not callback.from_user:
        return False
    if int(callback.from_user.id) == int(setup["creator_id"]):
        return True
    return await group_admin(callback.message.chat.id, callback.from_user.id)


@router.callback_query(F.data == "mathbattle:cancel")
async def mathbattle_cancel_callback(callback: CallbackQuery) -> None:
    chat_id = callback.message.chat.id if callback.message else 0
    setup = mathbattle_setups.get(chat_id)
    if not setup:
        await callback.answer("This Math Battle setup has expired.", show_alert=True)
        return
    if not await mathbattle_setup_allowed(callback, setup):
        await callback.answer(
            "Only the game starter or a group admin can do this.",
            show_alert=True,
        )
        return
    mathbattle_setups.pop(chat_id, None)
    await callback.answer("Math Battle setup cancelled.")
    if callback.message:
        await callback.message.edit_text(
            "<b>Math Battle setup cancelled.</b>\n\n"
            "Use /mathbattle whenever you want to play."
        )


@router.callback_query(F.data.startswith("mathbattle:level:"))
async def mathbattle_level_callback(callback: CallbackQuery) -> None:
    parts = callback.data.split(":")
    level = parts[2] if len(parts) == 3 else ""
    chat_id = callback.message.chat.id if callback.message else 0
    setup = mathbattle_setups.get(chat_id)
    if level not in {"basic", "medium", "hard"} or not setup:
        await callback.answer(
            "This Math Battle setup has expired.",
            show_alert=True,
        )
        return
    if not await mathbattle_setup_allowed(callback, setup):
        await callback.answer(
            "Only the game starter or a group admin can choose the level.",
            show_alert=True,
        )
        return
    if not callback.message or not callback.from_user:
        return
    async with mathbattle_setup_locks[chat_id]:
        async with arcade_locks[chat_id]:
            active_game = other_active_group_game(chat_id, "mathbattle_setup")
            if active_game:
                mathbattle_setups.pop(chat_id, None)
                await callback.answer(
                    f"{active_game} is already active in this group.",
                    show_alert=True,
                )
                await callback.message.edit_text(
                    group_game_conflict_text(active_game, "Math Battle")
                )
                return
            user = callback.from_user
            player = arcade_player_data(user)
            _kind = str(setup.get("kind", "mathbattle"))
            _title = "🔤 TRANSLATION BATTLE" if _kind == "tbattle" else "⚡ MATH BATTLE"
            session = {
                "session_id": secrets.token_hex(8),
                "chat_id": chat_id,
                "game": _kind,
                "difficulty": level,
                "state": "round",
                "creator_id": int(user.id),
                "players": [player],
                "round": 1,
                "answers": {},
                "scores": {int(user.id): 0},
                "current": arcade_make_round(_kind, 1, level),
                "round_started": time.monotonic(),
            }
            arcade_sessions[chat_id] = session
            arcade_player_sessions[int(user.id)] = chat_id
            mathbattle_setups.pop(chat_id, None)
            await callback.answer(f"{level.title()} mode selected.")
            await callback.message.edit_text(
                f"<b>{_title} — {level.title()} mode selected.</b>\n\n"
                "The first question is being sent below."
            )
            await bot.send_message(chat_id, arcade_round_text(session))
            arcade_tasks[chat_id] = asyncio.create_task(
                arcade_round_timer(chat_id, 1)
            )


