async def force_end_group_games(chat_id: int, only: set[str] | None = None) -> list[tuple[str, str]]:
    active_games = [
        (g, t) for g, t in group_active_games(chat_id)
        if only is None or g in only
    ]
    if not active_games:
        return []
    keys = {g for g, _t in active_games}
    def _want(*names):
        return any(n in keys for n in names)
    arcade_keys = {g for g in keys if g in ("scramble", "mathbattle", "tbattle", "highlow", "reaction", "arcade")}

    arcade_session = arcade_sessions.get(chat_id) if bool(arcade_keys) else None
    emoji_session = emoji_rush_sessions.get(chat_id) if _want("emoji") else None
    tictac_session = tictac_sessions.get(chat_id) if _want("tictac") else None
    quiz_session = quiz_sessions.get(chat_id) if _want("quiz") else None
    mafia_session = mafia_sessions.get(chat_id) if _want("mafia") else None
    death_note_session = death_note_sessions.get(chat_id) if _want("deathnote") else None
    codebreaker_session = codebreaker_sessions.get(chat_id) if _want("codebreaker") else None
    sequence_session = sequencemaster_sessions.get(chat_id) if _want("sequencemaster") else None

    # Clear session state before awaiting cancellation, so workers cannot accept more answers.
    pending_tasks: list[asyncio.Task] = []
    for task_map, tkeys in (
        (arcade_tasks, arcade_keys),
        (crossgrid_tasks, {"crossgrid"}),
        (tictac_expiry_tasks, {"tictac"}),
        (quiz_tasks, {"quiz"}),
        (mafia_tasks, {"mafia"}),
        (death_note_tasks, {"deathnote"}),
        (codebreaker_tasks, {"codebreaker"}),
        (sequencemaster_tasks, {"sequencemaster"}),
    ):
        if not (keys & tkeys):
            continue
        task = task_map.pop(chat_id, None)
        if task and task is not asyncio.current_task():
            task.cancel()
            pending_tasks.append(task)

    if _want("mathbattle_setup"):
        mathbattle_setups.pop(chat_id, None)
    if arcade_keys:
        arcade_sessions.pop(chat_id, None)
    if _want("emoji"):
        emoji_rush_sessions.pop(chat_id, None)
    if _want("crossgrid"):
        crossgrid_sessions.pop(chat_id, None)
    if _want("tictac"):
        tictac_sessions.pop(chat_id, None)
    if _want("quiz"):
        quiz_sessions.pop(chat_id, None)
    if _want("mafia"):
        mafia_sessions.pop(chat_id, None)
    if _want("deathnote"):
        death_note_sessions.pop(chat_id, None)
    if _want("codebreaker"):
        codebreaker_sessions.pop(chat_id, None)
    if _want("sequencemaster"):
        sequencemaster_sessions.pop(chat_id, None)

    if arcade_session:
        arcade_session["state"] = "finished"
        clear_arcade_players(chat_id, arcade_session)
    if emoji_session:
        emoji_session["state"] = "finished"
        clear_arcade_players(chat_id, emoji_session)
    if tictac_session:
        tictac_session["state"] = "finished"
        clear_tictac_player_sessions(chat_id, tictac_session)
    if quiz_session:
        quiz_session["state"] = "finished"
        clear_quiz_player_sessions(chat_id, quiz_session)
        poll_id = quiz_session.get("poll_id")
        if poll_id:
            quiz_poll_sessions.pop(str(poll_id), None)
    if mafia_session:
        mafia_session["state"] = "finished"
        clear_mafia_player_sessions(chat_id, mafia_session)
    if death_note_session:
        death_note_session["state"] = "finished"
        clear_death_note_player_sessions(chat_id, death_note_session)
    if codebreaker_session:
        codebreaker_session["state"] = "finished"
    if sequence_session:
        sequence_session["state"] = "finished"

    if pending_tasks:
        await asyncio.gather(*pending_tasks, return_exceptions=True)

    if tictac_session:
        try:
            await delete_persisted_tictac_session(chat_id)
        except Exception:
            log.exception("Could not clear persisted Tic Tac Toe session for %s", chat_id)
        try:
            await bot.edit_message_text(
                chat_id=chat_id,
                message_id=int(tictac_session["message_id"]),
                text="<b>Tic Tac Toe ended.</b>",
                reply_markup=tictac_game_over_markup(),
            )
        except (TelegramBadRequest, TelegramForbiddenError, TelegramRetryAfter):
            pass

    if quiz_session:
        poll_message_id = quiz_session.get("poll_message_id")
        if poll_message_id:
            try:
                await bot.stop_poll(
                    chat_id=chat_id,
                    message_id=int(poll_message_id),
                )
            except (TelegramBadRequest, TelegramForbiddenError, TelegramRetryAfter):
                pass
        try:
            await delete_persisted_quiz_session(chat_id)
        except Exception:
            log.exception("Could not clear persisted Quiz session for %s", chat_id)
        try:
            await bot.edit_message_text(
                chat_id=chat_id,
                message_id=int(quiz_session["message_id"]),
                text="<b>Quiz ended.</b>",
            )
        except (TelegramBadRequest, TelegramForbiddenError, TelegramRetryAfter):
            pass

    for g, _t in active_games:
        game_started_at.pop((chat_id, g), None)
    return active_games


game_started_at: dict[tuple[int, str], float] = {}
GAME_STUCK_TIMEOUT = 15 * 60

GAME_END_ALIASES = {
    "tictac": "tictac", "tictactoe": "tictac", "ttt": "tictac",
    "quiz": "quiz", "mafia": "mafia", "deathnote": "deathnote",
    "codebreaker": "codebreaker", "sequence": "sequencemaster",
    "sequencemaster": "sequencemaster", "crossgrid": "crossgrid",
    "emoji": "emoji", "emojirush": "emoji",
    "mathbattle": "mathbattle", "scramble": "scramble",
    "translation": "tbattle", "tbattle": "tbattle",
    "highlow": "highlow", "reaction": "reaction",
}


async def end_one_group_game(message: Message, name: str) -> None:
    if message.chat.type not in {ChatType.GROUP, ChatType.SUPERGROUP}:
        await message.answer("/end only works inside a group.")
        return
    actor = message.from_user
    if not actor:
        return
    if False:
        await message.answer("Only a group admin or the bot owner can end a game.")
        return
    key = GAME_END_ALIASES[name]
    only = {key}
    if key == "mathbattle":
        only = {"mathbattle", "mathbattle_setup"}
    if key == "tbattle":
        only = {"tbattle", "mathbattle_setup"}
    ended = await force_end_group_games(int(message.chat.id), only)
    if not ended:
        await message.answer(f"No live <b>{html.escape(name)}</b> game is active in this group.")
        return
    titles = ", ".join(html.escape(t) for _g, t in ended)
    await message.answer(f"<b>{titles}</b> has been stopped. Now you can start another game.")


async def game_stuck_watchdog() -> None:
    import time as _t
    while True:
        try:
            await asyncio.sleep(60)
            now = _t.time()
            chats = set()
            for mp in (mathbattle_setups, arcade_sessions, emoji_rush_sessions,
                       codebreaker_sessions, sequencemaster_sessions, crossgrid_sessions,
                       quiz_sessions, tictac_sessions, mafia_sessions, death_note_sessions):
                chats.update(k for k in list(mp.keys()) if isinstance(k, int))
            live = set()
            for cid in chats:
                for g, _t2 in group_active_games(cid):
                    live.add((cid, g))
                    game_started_at.setdefault((cid, g), now)
            for k in list(game_started_at):
                if k not in live:
                    game_started_at.pop(k, None)
            for (cid, g), started in list(game_started_at.items()):
                if now - started >= GAME_STUCK_TIMEOUT:
                    ended = await force_end_group_games(cid, {g})
                    game_started_at.pop((cid, g), None)
                    if ended:
                        try:
                            await bot.send_message(cid, f"⏰ <b>{html.escape(ended[0][1])}</b> auto-ended after 15 minutes. You can start a new game now.")
                        except Exception:
                            pass
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("game watchdog error")


async def end_all_group_games(message: Message) -> None:
    if message.chat.type not in {ChatType.GROUP, ChatType.SUPERGROUP}:
        await message.answer("/end games only works inside a group.")
        return
    actor = message.from_user
    if not actor:
        return
    if actor.id not in ADMIN_IDS and not await group_admin(
        message.chat.id, actor.id
    ):
        await message.answer(
            "Only a group admin or the bot owner can end every game."
        )
        return

    chat_id = int(message.chat.id)
    active_games = await force_end_group_games(chat_id)
    if not active_games:
        await message.answer("No live games or game setups are active in this group.")
        return
    titles = "\n".join(
        f"• {html.escape(title)}" for _game, title in active_games
    )
    await message.answer(
        "<b>All active games have been stopped:</b>\n"
        f"{titles}\n\n"
        "Unfinished scores and rewards were not finalized."
    )


@router.message(Command("end"))
async def end_game_command(message: Message) -> None:
    args = (message.text or "").split(maxsplit=1)
    if len(args) != 2:
        return
    game = args[1].strip().casefold()
    game = game.lstrip("/").replace(" ", "").replace("_", "")
    if game in {"games", "all"}:
        await end_all_group_games(message)
    elif game in {"emoji", "emojirush"}:
        await end_emoji_rush(message)
    elif game in {"scramble", "mathbattle", "highlow", "reaction"}:
        await end_arcade_game(message, game)
    elif game == "crossgrid":
        await end_crossgrid_game(message)
    elif game == "codebreaker":
        await end_codebreaker_game(message)
    elif game in {"sequence", "sequencemaster"}:
        await end_sequence_master_game(message)
    elif game in GAME_END_ALIASES:
        await end_one_group_game(message, game)


