async def chess_rank(message: Message) -> None:
    await chess_rank_setup()
    cur = await db.execute(
        "SELECT c.user_id, "
        "COALESCE(NULLIF(c.first_name, ''), NULLIF(u.first_name, ''), 'Player') AS first_name, "
        "COALESCE(NULLIF(c.username, ''), NULLIF(u.username, ''), '') AS username, "
        "c.total_matches, "
        "COALESCE(c.total_wins, 0) AS total_wins, "
        "COALESCE(c.total_losses, 0) AS total_losses "
        "FROM chess_user_stats c "
        "LEFT JOIN users u ON u.user_id = c.user_id "
        "WHERE (COALESCE(c.total_wins, 0) + COALESCE(c.total_losses, 0)) > 0 AND c.user_id > 1000000 "
        "ORDER BY total_wins DESC, (total_wins * 1.0 / (total_wins + total_losses)) DESC, (total_wins + total_losses) DESC LIMIT 10"
    )
    rows = await cur.fetchall()
    if not rows:
        empty_msg = (
            "<blockquote>"
            '<tg-emoji emoji-id="5440539497383087970">🏆</tg-emoji> <b>GLOBAL LEADERBOARD</b>\n'
            '<tg-emoji emoji-id="5229011542011299168">♟️</tg-emoji> <b>CHESS MASTERS (COMPLETED MATCHES)</b>\n'
            "━━━━━━━━━━━━━━━━━━━━\n"
            "No completed matches recorded yet!\n\n"
            "Play and finish a <b>Chess</b> match in the Mini App to claim a rank. ♟️"
            "</blockquote>"
        )
        try:
            await message.reply(empty_msg, parse_mode="HTML", link_preview_options=LinkPreviewOptions(is_disabled=True))
        except Exception:
            await message.answer(empty_msg, parse_mode="HTML")
        return
    medals = {1: '<tg-emoji emoji-id="6265004494719816749">🥇</tg-emoji>', 2: "🥈", 3: "🥉"}
    lines = [
        "<blockquote>",
        '<tg-emoji emoji-id="5440539497383087970">🏆</tg-emoji> <b>GLOBAL LEADERBOARD</b>',
        '<tg-emoji emoji-id="5229011542011299168">♟️</tg-emoji> <b>CHESS MASTERS (COMPLETED MATCHES)</b>',
        "━━━━━━━━━━━━━━━━━━━━",
    ]
    for i, r in enumerate(rows, 1):
        mention = format_rank_user_mention(r)
        wins = int(r["total_wins"])
        losses = int(r["total_losses"])
        completed = wins + losses
        winrate = round((wins / completed * 100), 1) if completed > 0 else 0
        if i == 1:
            lines.append(f"👑 {medals[i]} {mention}\n      <tg-emoji emoji-id=\"6266969287638913443\">⭐️</tg-emoji> <b>{wins} WINS</b>  •  <b>{losses} LOSSES</b>  •  {completed} FINISHED ({winrate}%)")
        elif i <= 3:
            lines.append(f"{medals[i]} {mention}\n      <tg-emoji emoji-id=\"6264925819508888658\">⭐</tg-emoji> <b>{wins} WINS</b>  •  <b>{losses} LOSSES</b>  •  {completed} Finished ({winrate}%)")
        else:
            if i == 4:
                lines.append("━━━━━━━━━━━━━━━━━━")
            lines.append(f"<b>#{i}</b>  {mention}\n      {wins} wins  •  {losses} losses  •  {completed} finished ({winrate}%)")
    me = message.from_user
    if me:
        cur = await db.execute("SELECT total_matches, COALESCE(total_wins, 0) AS total_wins, COALESCE(total_losses, 0) AS total_losses FROM chess_user_stats WHERE user_id=?", (me.id,))
        row = await cur.fetchone()
        if row and (int(row["total_wins"]) + int(row["total_losses"])) > 0:
            my_wins = int(row["total_wins"])
            my_losses = int(row["total_losses"])
            my_completed = my_wins + my_losses
            cur = await db.execute(
                "SELECT COUNT(*) + 1 FROM chess_user_stats WHERE (COALESCE(total_wins, 0) + COALESCE(total_losses, 0)) > 0 AND (total_wins > ? OR (total_wins = ? AND (total_wins * 1.0 / (total_wins + total_losses)) > ?))",
                (my_wins, my_wins, (my_wins * 1.0 / my_completed))
            )
            pos = (await cur.fetchone())[0]
            lines.append("━━━━━━━━━━━━━━━━━━")
            lines.append(f'<tg-emoji emoji-id="5463406036410969564">🎯</tg-emoji> <b>YOUR RANK: #{pos}</b>\n     {my_wins} wins  •  {my_losses} losses  •  {my_completed} finished')
    lines.append("</blockquote>")
    try:
        await message.reply("\n".join(lines), parse_mode="HTML", disable_web_page_preview=True, link_preview_options=LinkPreviewOptions(is_disabled=True))
    except Exception:
        await message.answer("\n".join(lines), parse_mode="HTML", disable_web_page_preview=True)


