@router.message(Command("addchess"))
async def add_chess_stat_admin(message: Message) -> None:
    if not message.from_user or message.from_user.id not in ADMIN_IDS:
        return
    parts = (message.text or "").split()
    target_id = None
    target_name = "Player"
    target_uname = ""
    matches = 1
    wins = 1
    if message.reply_to_message and message.reply_to_message.from_user:
        target_id = message.reply_to_message.from_user.id
        target_name = message.reply_to_message.from_user.first_name or "Player"
        target_uname = message.reply_to_message.from_user.username or ""
        if len(parts) >= 3:
            matches = int(parts[1]) if parts[1].isdigit() else 1
            wins = int(parts[2]) if parts[2].isdigit() else 1
        elif len(parts) >= 2:
            wins = int(parts[1]) if parts[1].isdigit() else 1
            matches = wins
    elif len(parts) >= 4:
        target_id = int(parts[1]) if parts[1].isdigit() else None
        matches = int(parts[2]) if parts[2].isdigit() else 1
        wins = int(parts[3]) if parts[3].isdigit() else 1
    if not target_id:
        await message.reply("Usage: Reply to user with <code>/addchess &lt;matches&gt; &lt;wins&gt;</code> or <code>/addchess &lt;user_id&gt; &lt;matches&gt; &lt;wins&gt;</code>", parse_mode="HTML")
        return
    await chess_rank_setup()
    losses = max(0, matches - wins)
    await db.execute(
        """INSERT INTO chess_user_stats(user_id, first_name, username, total_matches, total_wins, total_losses, updated_at)
           VALUES(?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
           ON CONFLICT(user_id) DO UPDATE SET
             total_matches=total_matches + excluded.total_matches,
             total_wins=total_wins + excluded.total_wins,
             total_losses=total_losses + excluded.total_losses,
             updated_at=CURRENT_TIMESTAMP""",
        (target_id, target_name, target_uname, matches, wins, losses),
    )
    await db.commit()
    await message.reply(f"✅ Added {matches} matches & {wins} wins ({losses} losses) to Chess stats for user <code>{target_id}</code>.", parse_mode="HTML")


