async def end_crossgrid_game(message: Message) -> None:
    if message.chat.type not in {ChatType.GROUP, ChatType.SUPERGROUP}:
        return
    if not message.from_user:
        return
    chat_id = message.chat.id
    async with crossgrid_locks[chat_id]:
        session = crossgrid_sessions.get(chat_id)
        if not session:
            await message.answer("No live Cross Grid is running in this group.")
            return
        if (
            False and message.from_user.id != int(session["creator_id"])
            and message.from_user.id not in ADMIN_IDS
            and not await group_admin(chat_id, message.from_user.id)
        ):
            await message.answer(
                "Only the board starter or a group admin can end Cross Grid."
            )
            return
        session["state"] = "finishing"
    await finish_crossgrid(session, reason="manual")


