async def process_voice_change(
    bot: Bot,
    message: Message,
    media: object,
    mode: str,
    file_unique_id: str,
    file_id: str,
    duration: int,
    preset: dict[str, str] | None = None,
) -> None:
    if preset is None:
        if mode == "male":
            preset = random.choice(MALE_VOICE_PRESETS)
        else:
            preset = random.choice(FEMALE_VOICE_PRESETS)

    preset_id = str(preset["id"])
    preset_name = str(preset["name"])
    preset_emoji = str(preset.get("emoji", "🎙️"))
    cache_key = f"{file_unique_id}_{preset_id}"
    gender_label = f"Male Voice 👨" if mode == "male" else f"Female Voice 👩"

    caption_text = (
        f"<blockquote>"
        f"<b>{preset_emoji} {gender_label}</b>\n"
        f"✨ <i>Profile: {preset_name}</i>\n"
        f"⏱️ <i>Duration: {duration}s</i>"
        f"</blockquote>"
    )

    # Level 1 Cache: In-memory Telegram file_id (0.05s resend)
    cached_file_id = VOICE_TELEGRAM_CACHE.get(cache_key)
    if cached_file_id:
        try:
            await bot.send_chat_action(message.chat.id, ChatAction.RECORD_VOICE)
            await message.reply_voice(
                cached_file_id,
                caption=caption_text,
                parse_mode="HTML",
            )
            return
        except Exception:
            VOICE_TELEGRAM_CACHE.pop(cache_key, None)

    # Level 2 Cache: Local Disk File (~0.15s)
    cached_file_path = VOICE_CACHE_DIR / f"{cache_key}.ogg"
    if cached_file_path.exists() and cached_file_path.stat().st_size > 0:
        try:
            await bot.send_chat_action(message.chat.id, ChatAction.RECORD_VOICE)
            sent = await message.reply_voice(
                FSInputFile(str(cached_file_path)),
                caption=caption_text,
                parse_mode="HTML",
            )
            if sent and sent.voice:
                VOICE_TELEGRAM_CACHE[cache_key] = sent.voice.file_id
            return
        except Exception as e:
            log.warning("Failed to send from disk voice cache: %s", e)

    # Level 3: Process via FFmpeg (~0.25s)
    await bot.send_chat_action(message.chat.id, ChatAction.RECORD_VOICE)
    processing_msg = None
    try:
        processing_msg = await message.reply(
            f"<blockquote>🎙️ <i>Crafting {preset_name} ({gender_label})…</i></blockquote>",
            parse_mode="HTML",
        )
    except Exception:
        pass

    with tempfile.TemporaryDirectory() as tmp_dir:
        tmp_in = Path(tmp_dir) / f"input_{file_unique_id}"
        tmp_out = Path(tmp_dir) / f"output_{cache_key}.ogg"
        try:
            tg_file = await bot.get_file(file_id)
            if not tg_file.file_path:
                if processing_msg:
                    await processing_msg.edit_text(
                        "<blockquote>⚠️ Could not download audio from Telegram. Please try again.</blockquote>",
                        parse_mode="HTML",
                    )
                return
            with open(str(tmp_in), "wb") as target:
                await bot.download_file(tg_file.file_path, target)

            af_filter = preset["filter"]
            af_fallback = preset.get("fallback", "aresample=48000")

            cmd = [
                "ffmpeg", "-y", "-i", str(tmp_in),
                "-af", af_filter,
                "-c:a", "libopus", "-b:a", "64k", "-ar", "48000", "-ac", "1",
                str(tmp_out),
            ]
            proc = await asyncio.create_subprocess_exec(
                *cmd,
                stdout=asyncio.subprocess.DEVNULL,
                stderr=asyncio.subprocess.DEVNULL,
            )
            try:
                code = await asyncio.wait_for(proc.wait(), timeout=25.0)
            except asyncio.TimeoutError:
                proc.kill()
                code = -1

            if code != 0 or not tmp_out.exists() or tmp_out.stat().st_size == 0:
                cmd_fb = [
                    "ffmpeg", "-y", "-i", str(tmp_in),
                    "-af", af_fallback,
                    "-c:a", "libopus", "-b:a", "64k", "-ar", "48000", "-ac", "1",
                    str(tmp_out),
                ]
                proc_fb = await asyncio.create_subprocess_exec(
                    *cmd_fb,
                    stdout=asyncio.subprocess.DEVNULL,
                    stderr=asyncio.subprocess.DEVNULL,
                )
                try:
                    code_fb = await asyncio.wait_for(proc_fb.wait(), timeout=20.0)
                except asyncio.TimeoutError:
                    proc_fb.kill()
                    code_fb = -1
                if code_fb != 0 or not tmp_out.exists() or tmp_out.stat().st_size == 0:
                    if processing_msg:
                        await processing_msg.edit_text(
                            "<blockquote>⚠️ Failed to convert audio voice. Please try another audio file.</blockquote>",
                            parse_mode="HTML",
                        )
                    return

            import shutil
            shutil.copy2(str(tmp_out), str(cached_file_path))

            if processing_msg:
                try:
                    await processing_msg.delete()
                except Exception:
                    pass

            sent = await message.reply_voice(
                FSInputFile(str(cached_file_path)),
                caption=caption_text,
                parse_mode="HTML",
            )
            if sent and sent.voice:
                VOICE_TELEGRAM_CACHE[cache_key] = sent.voice.file_id
        except Exception as e:
            log.exception("Voice change error: %s", e)
            if processing_msg:
                try:
                    await processing_msg.edit_text(
                        "<blockquote>⚠️ An error occurred while converting audio. Please try again.</blockquote>",
                        parse_mode="HTML",
                    )
                except Exception:
                    pass


