@router.callback_query(F.data.regexp(
    r"^deathnote:(kira|investigate|protect|special):"
))
async def death_note_action_callback(callback: CallbackQuery) -> None:
    if not callback.from_user:
        return
    parts = callback.data.split(":")
    if len(parts) != 4:
        await callback.answer("Invalid Death Note action.", show_alert=True)
        return
    _, action, chat_id_raw, target_raw = parts
    chat_id, target_id = int(chat_id_raw), int(target_raw)
    session = death_note_sessions.get(chat_id)
    if not session or session["state"] != "night":
        await callback.answer("Night actions are closed.", show_alert=True)
        return
    user_id = callback.from_user.id
    role = str(session["roles"].get(str(user_id), ""))
    if user_id not in session["alive"] or target_id not in session["alive"]:
        await callback.answer("That player is no longer alive.", show_alert=True)
        return
    allowed = {
        "kira": "kira",
        "investigate": "l",
        "protect": "bodyguard",
        "special": "kira",
    }
    if role != allowed[action] or target_id == user_id:
        await callback.answer("This action is not available to your role.", show_alert=True)
        return
    if action == "protect" and target_id == session.get("last_protected"):
        await callback.answer(
            "You cannot protect the same player two nights in a row.",
            show_alert=True,
        )
        return
    if action == "special":
        if int(session["round"]) < 3 or session.get("special_used"):
            await callback.answer("Final Note is not available.", show_alert=True)
            return
        key = "special_target"
    else:
        key = {
            "kira": "kira_target",
            "investigate": "l_target",
            "protect": "bodyguard_target",
        }[action]
    if session["actions"].get(key) is not None:
        await callback.answer("Your decision is already recorded.", show_alert=True)
        return
    session["actions"][key] = target_id
    if action == "special":
        await callback.answer("Final Note locked.")
    else:
        await callback.answer("Your decision has been recorded.")
    await death_note_send_action(
        session,
        user_id,
        f"✅ <b>{'TARGET LOCKED' if action != 'protect' else 'PROTECTION LOCKED'}</b>\n\n"
        f"Selected: {death_note_player_label(session, target_id)}",
    )


@router.callback_query(F.data.startswith("deathnote:analyse:"))
async def death_note_analysis_callback(callback: CallbackQuery) -> None:
    if not callback.from_user:
        return
    parts = callback.data.split(":")
    if len(parts) != 4:
        await callback.answer("Invalid analysis.", show_alert=True)
        return
    _, _, chat_id_raw, field = parts
    chat_id = int(chat_id_raw)
    session = death_note_sessions.get(chat_id)
    user_id = callback.from_user.id
    if (
        not session
        or session["state"] != "night"
        or str(session["roles"].get(str(user_id))) != "l"
        or user_id not in session["alive"]
        or int(session["round"]) < 3
        or int(session["l_points"]) <= 0
    ):
        await callback.answer("Evidence analysis is not available.", show_alert=True)
        return
    if session["actions"].get("analysis"):
        await callback.answer("You already analysed evidence this night.")
        return
    session["actions"]["analysis"] = field
    session["l_points"] = int(session["l_points"]) - 1
    links = {
        "location": "The location matches the witness timeline.",
        "time": "The time is connected to the recovered object.",
        "object": "The object was handled by someone at the scene.",
    }
    await callback.answer("Evidence analysed.")
    await death_note_send_action(
        session,
        user_id,
        "🧩 <b>ANALYSIS RESULT</b>\n\n"
        f"{links.get(field, 'The evidence is inconclusive')}\n"
        "It does not directly identify Kira.\n\n"
        f"Investigation points left: {session['l_points']}",
    )


@router.callback_query(F.data.startswith("deathnote:trial:"))
async def death_note_trial_callback(callback: CallbackQuery) -> None:
    if not callback.from_user:
        return
    parts = callback.data.split(":")
    if len(parts) != 4:
        await callback.answer("Invalid trial vote.", show_alert=True)
        return
    chat_id, target_id = int(parts[2]), int(parts[3])
    session = death_note_sessions.get(chat_id)
    user_id = callback.from_user.id
    if not session or session["state"] != "trial":
        await callback.answer("Trial voting is closed.", show_alert=True)
        return
    if user_id not in session["alive"] or target_id not in session["alive"]:
        await callback.answer("You cannot vote in this case.", show_alert=True)
        return
    if user_id in session["votes"]:
        await callback.answer("You already submitted your trial vote.", show_alert=True)
        return
    session["votes"][user_id] = target_id
    await callback.answer("Secret vote recorded.")


@router.callback_query(F.data.startswith("deathnote:verdict:"))
async def death_note_verdict_callback(callback: CallbackQuery) -> None:
    if not callback.from_user:
        return
    parts = callback.data.split(":")
    if len(parts) != 4 or parts[3] not in {"execute", "release"}:
        await callback.answer("Invalid verdict.", show_alert=True)
        return
    chat_id, decision = int(parts[2]), parts[3]
    session = death_note_sessions.get(chat_id)
    user_id = callback.from_user.id
    if not session or session["state"] != "defense":
        await callback.answer("The verdict is closed.", show_alert=True)
        return
    if user_id not in session["alive"]:
        await callback.answer("Eliminated players cannot vote.", show_alert=True)
        return
    if user_id in session["verdict_votes"]:
        await callback.answer("You already submitted your verdict.", show_alert=True)
        return
    session["verdict_votes"][user_id] = decision
    await callback.answer("Verdict recorded.")


@router.callback_query(F.data.startswith("deathnote:final:"))
async def death_note_final_vote_callback(callback: CallbackQuery) -> None:
    if not callback.from_user:
        return
    parts = callback.data.split(":")
    if len(parts) != 4:
        await callback.answer("Invalid final accusation.", show_alert=True)
        return
    chat_id, target_id = int(parts[2]), int(parts[3])
    session = death_note_sessions.get(chat_id)
    user_id = callback.from_user.id
    if not session or session["state"] != "final_vote":
        await callback.answer("The final vote is closed.", show_alert=True)
        return
    if user_id not in session["alive"]:
        await callback.answer("You cannot vote in this case.", show_alert=True)
        return
    if target_id != 0 and target_id not in session["alive"]:
        await callback.answer("That player is no longer alive.", show_alert=True)
        return
    if user_id in session["final_votes"]:
        await callback.answer("You already submitted your accusation.", show_alert=True)
        return
    session["final_votes"][user_id] = target_id
    await callback.answer("Final accusation recorded.")


@router.callback_query(F.data.startswith("deathnote:noop:"))
async def death_note_noop_callback(callback: CallbackQuery) -> None:
    await callback.answer("There are no valid targets for this action.", show_alert=True)


@router.callback_query(F.data == "deathnote:over")
async def death_note_over_callback(callback: CallbackQuery) -> None:
    await callback.answer("The Death Note case is closed.")


