def quiz_round_count(session: dict[str, object]) -> int:
    try:
        rounds = int(session.get("rounds", QUIZ_ROUNDS))
    except (TypeError, ValueError):
        rounds = QUIZ_ROUNDS
    return rounds if rounds in QUIZ_ROUND_CHOICES else QUIZ_ROUNDS


def quiz_topic_slug(topic_key: str) -> str:
    return re.sub(r"[^a-z0-9]+", "_", topic_key.casefold()).strip("_")


def quiz_category_from_slug(slug: str) -> tuple[str, str, str]:
    topic_key = slug.replace("_", " ").strip().casefold()
    return normalize_quiz_topic(topic_key)


def quiz_bank_category(session: dict[str, object]) -> str:
    topic_kind = str(session.get("topic_kind", "general"))
    topic_key = str(session.get("topic_key", "general")).casefold()
    if topic_kind == "state":
        return f"state:{topic_key}"
    if topic_kind == "math":
        return "math"
    if topic_kind == "translation":
        return "translation"
    return "gk"


