def format_bot_uptime() -> str:
    total_seconds = max(0, int(time.monotonic() - BOT_STARTED_AT))
    days, remainder = divmod(total_seconds, 86400)
    hours, remainder = divmod(remainder, 3600)
    minutes, seconds = divmod(remainder, 60)
    parts: list[str] = []
    if days:
        parts.append(f"{days}d")
    if hours or days:
        parts.append(f"{hours}h")
    if minutes or hours or days:
        parts.append(f"{minutes}m")
    parts.append(f"{seconds}s")
    return " ".join(parts)


def ping_quality(milliseconds: float) -> str:
    if milliseconds < 250:
        return "OPTIMAL"
    if milliseconds < 600:
        return "GOOD"
    if milliseconds < 1200:
        return "SLOW"
    return "HIGH LATENCY"


async def build_ping_status_text() -> str:
    telegram_ping_ms: float | None = None
    telegram_status = "RESPONSIVE"
    telegram_started = time.perf_counter()
    try:
        await bot.get_me()
        telegram_ping_ms = (time.perf_counter() - telegram_started) * 1000
    except Exception:
        telegram_status = "CHECK FAILED"

    database_status = "ONLINE"
    database_ping_ms: float | None = None
    database_started = time.perf_counter()
    try:
        cursor = await db.execute("SELECT 1")
        await cursor.fetchone()
        database_ping_ms = (time.perf_counter() - database_started) * 1000
    except Exception:
        database_status = "CHECK FAILED"

    ready_assistants = sum(
        1
        for runtime in voice_runtimes.values()
        if runtime.get("healthy") and runtime.get("call") is not None
    )
    active_voice_chats = len(music_current)
    queued_tracks = sum(len(queue) for queue in music_queues.values())
    ping_text = (
        f"{telegram_ping_ms:.2f} ms"
        if telegram_ping_ms is not None
        else "UNAVAILABLE"
    )
    database_text = (
        f"{database_status} ({database_ping_ms:.2f} ms)"
        if database_ping_ms is not None
        else database_status
    )
    response_text = (
        ping_quality(telegram_ping_ms)
        if telegram_ping_ms is not None
        else "CHECK FAILED"
    )

    text = (
        "<b>˹Dᴇsᴛʀᴏʏᴇʀ ꭙ ᴍᴜsɪᴄ ᴀssɪsᴛᴀɴᴛ Status</b>\n"
        "━━━━━━━━━━━━━━━━━━━━\n\n"
        f"<b>Database:</b> {database_text}\n"
        f"<b>Telegram API:</b> {telegram_status}\n"
        "<b>Bot Server:</b> RUNNING\n"
        f"<b>Response Time:</b> {response_text}\n"
        f"<b>API Ping:</b> {ping_text}\n"
        f"<b>Voice Assistants:</b> {ready_assistants} ready\n"
        f"<b>Active Voice Chats:</b> {active_voice_chats}\n"
        f"<b>Queued Tracks:</b> {queued_tracks}\n"
        f"<b>Uptime:</b> {format_bot_uptime()}\n\n"
        "<i>API Ping is measured with a fresh Telegram API request.</i>"
    )
    return text


@router.message(Command("ping"))
async def ping_command(message: Message) -> None:
    await message.reply(await build_ping_status_text())


def is_mentioned_ping(message: Message) -> bool:
    if (
        message.chat.type not in {ChatType.GROUP, ChatType.SUPERGROUP}
        or not message.text
        or not bot_username
    ):
        return False
    pattern = (
        rf"^\s*@{re.escape(bot_username)}\s+"
        rf"/ping(?:@{re.escape(bot_username)})?\s*$"
    )
    return bool(re.fullmatch(pattern, message.text, flags=re.IGNORECASE))


@router.message(is_mentioned_ping)
async def mentioned_ping_command(message: Message) -> None:
    await message.reply(await build_ping_status_text())


