def admin_group_markup(page: int, total: int) -> InlineKeyboardMarkup:
    last_page = max(0, (total - 1) // 25)
    navigation: list[InlineKeyboardButton] = []
    if page > 0:
        navigation.append(InlineKeyboardButton(
            text="Previous", callback_data=f"adm:groups:{page - 1}"
        ))
    if page < last_page:
        navigation.append(InlineKeyboardButton(
            text="Next", callback_data=f"adm:groups:{page + 1}"
        ))
    rows: list[list[InlineKeyboardButton]] = []
    if navigation:
        rows.append(navigation)
    rows.append([
        InlineKeyboardButton(text="Download all as TXT", callback_data="adm:groups_export")
    ])
    rows.append([InlineKeyboardButton(text="Back", callback_data="admin_panel")])
    return InlineKeyboardMarkup(inline_keyboard=rows)


async def admin_groups_text(page: int) -> tuple[str, int]:
    total_cursor = await db.execute(
        "SELECT COUNT(*) AS total FROM managed_groups"
    )
    total_row = await total_cursor.fetchone()
    total = int(total_row["total"] if total_row else 0)
    rows = await db.execute_fetchall(
        """SELECT chat_id, title, username, added_at, admin_since
           FROM managed_groups
           ORDER BY title COLLATE NOCASE, chat_id
           LIMIT 25 OFFSET ?""",
        (max(0, page) * 25,),
    )
    async def currently_admin(row: aiosqlite.Row) -> aiosqlite.Row | None:
        try:
            member = await bot.get_chat_member(int(row["chat_id"]), bot.id)
        except (TelegramBadRequest, TelegramForbiddenError):
            return None
        return row if member.status in {"administrator", "creator"} else None

    checked_rows = await asyncio.gather(*(currently_admin(row) for row in rows))
    rows = [row for row in checked_rows if row is not None]
    if not rows:
        return "<b>Groups where I am admin</b>\n\nNo managed groups found.", total
    lines = [
        f"<b>Groups where I am admin</b> — page {page + 1}/"
        f"{max(1, (total + 24) // 25)}",
        f"Total recorded groups: {total}\n",
    ]
    for index, row in enumerate(rows, start=page * 25 + 1):
        title = html.escape(str(row["title"] or "Untitled group"))
        username = str(row["username"] or "").strip()
        username_text = f"@{html.escape(username.lstrip('@'))}" if username else "not public"
        recorded_at = row["admin_since"] or row["added_at"] or "unknown"
        lines.append(
            f"<b>{index}. {title}</b>\n"
            f"Username: {username_text}\n"
            f"Group ID: <code>{int(row['chat_id'])}</code>\n"
            f"Bot admin since: {html.escape(str(recorded_at))}\n"
        )
    return "\n".join(lines).strip(), total


async def admin_groups_export() -> BufferedInputFile:
    rows = await db.execute_fetchall(
        """SELECT chat_id, title, username, added_at, admin_since
           FROM managed_groups
           ORDER BY title COLLATE NOCASE, chat_id
           LIMIT 10000"""
    )
    lines = [
        "˹Dᴇsᴛʀᴏʏᴇʀ ꭙ ᴍᴜsɪᴄ ᴀssɪsᴛᴀɴᴛ managed groups",
        f"Exported at: {datetime.now(timezone.utc).isoformat()}",
        f"Groups: {len(rows)}",
        "",
    ]
    for index, row in enumerate(rows, start=1):
        username = str(row["username"] or "").strip()
        username_text = f"@{username.lstrip('@')}" if username else "not public"
        lines.extend([
            f"{index}. {str(row['title'] or 'Untitled group')}",
            f"Username: {username_text}",
            f"Group ID: {int(row['chat_id'])}",
            f"Bot admin since: {row['admin_since'] or row['added_at'] or 'unknown'}",
            "",
        ])
    return BufferedInputFile("\n".join(lines).encode("utf-8"), filename="seyuki-groups.txt")


