async def stop_voice_assistant(assistant_id: int) -> None:
    affected = [
        chat_id for chat_id, owner_id in music_group_assistant.items()
        if owner_id == assistant_id
    ]
    for chat_id in affected:
        await stop_music_session(chat_id)
    runtime = voice_runtimes.pop(assistant_id, None)
    music_assistant_reservations.pop(assistant_id, None)
    if not runtime:
        return
    call = runtime.get("call")
    client = runtime.get("client")
    try:
        if call is not None:
            active_calls = getattr(call, "group_calls", {}) or {}
            for active_chat_id in list(active_calls):
                try:
                    await call.leave_call(int(active_chat_id))
                except Exception:
                    pass
    except Exception:
        pass
    try:
        if client is not None and client.is_connected():
            await client.disconnect()
    except Exception:
        pass


async def refresh_mtproto_stack() -> None:
    """Apply newly entered Telegram API credentials to active MTProto clients."""
    global mtproto_client, music_assistant_label
    for assistant_id in list(voice_runtimes):
        await stop_voice_assistant(assistant_id)
    if mtproto_client is not None and mtproto_client.is_connected():
        try:
            await mtproto_client.disconnect()
        except Exception:
            pass
    mtproto_client = None
    music_assistant_label = "voice assistant"
    if not TELEGRAM_API_ID or not TELEGRAM_API_HASH:
        return
    await start_enabled_voice_assistants()
    available = eligible_voice_runtimes()
    if available:
        mtproto_client = available[0][1]["client"]
        music_assistant_label = str(available[0][1]["label"])


async def start_voice_assistant(row: aiosqlite.Row) -> bool:
    assistant_id = int(row["id"])
    if not bool(row["enabled"]) or assistant_id in voice_runtimes:
        return assistant_id in voice_runtimes
    if not VOICE_CALLS_AVAILABLE or not TELEGRAM_API_ID or not TELEGRAM_API_HASH:
        return False
    client: TelegramClient | None = None
    try:
        session = assistant_session_path(str(row["session_basename"]))
        client = TelegramClient(str(session), TELEGRAM_API_ID, TELEGRAM_API_HASH)
        await client.connect()
        if not await client.is_user_authorized():
            raise RuntimeError("authorization revoked")
        account = await client.get_me()
        if account is None or getattr(account, "bot", False):
            raise RuntimeError("normal user account required")
        call = PyTgCalls(
            client,
            workers=MUSIC_VOICE_WORKERS,
            cache_duration=MUSIC_VOICE_CACHE_SECONDS,
        )

        async def owned_stream_end(
            event_client: PyTgCalls,
            update: StreamEnded,
            owner_id: int = assistant_id,
        ) -> None:
            await music_stream_ended(event_client, update, owner_id)

        call.on_update(call_filters.stream_end(StreamEnded.Type.AUDIO))(owned_stream_end)
        await call.start()
        voice_runtimes[assistant_id] = {
            "client": client,
            "call": call,
            "healthy": True,
            "priority": int(row["priority"]),
            "label": f"@{account.username}" if getattr(account, "username", None) else "Telegram user",
            "telegram_user_id": int(account.id),
        }
        await db.execute(
            """UPDATE voice_assistants SET health='ready', last_error='',
            telegram_user_id=?, username=?, updated_at=CURRENT_TIMESTAMP WHERE id=?""",
            (int(account.id), getattr(account, "username", None), assistant_id),
        )
        await db.commit()
        return True
    except Exception as error:
        await db.execute(
            """UPDATE voice_assistants SET health='error', last_error=?,
            updated_at=CURRENT_TIMESTAMP WHERE id=?""",
            (voice_error_diagnostic(error), assistant_id),
        )
        await db.commit()
        runtime = voice_runtimes.pop(assistant_id, None)
        if runtime and runtime.get("client"):
            await runtime["client"].disconnect()
        elif client is not None and client.is_connected():
            await client.disconnect()
        return False


async def start_enabled_voice_assistants() -> None:
    if not VOICE_CALLS_AVAILABLE:
        log.warning(
            "pytgcalls is unavailable on this Python runtime; "
            "voice-call music features are disabled."
        )
        return
    VOICE_SESSION_DIRECTORY.mkdir(parents=True, exist_ok=True)
    for row in await assistant_rows():
        if row["enabled"]:
            await start_voice_assistant(row)


def remove_session_files(basename: str) -> None:
    base = assistant_session_path(basename)
    for path in base.parent.glob(f"{base.name}.session*"):
        if path.is_file():
            path.unlink(missing_ok=True)


async def run_qr_login(owner_id: int, chat_id: int, basename: str) -> None:
    client: TelegramClient | None = None
    try:
        VOICE_SESSION_DIRECTORY.mkdir(parents=True, exist_ok=True)
        client = TelegramClient(
            str(assistant_session_path(basename)),
            TELEGRAM_API_ID,
            TELEGRAM_API_HASH,
        )
        qr_login_clients[owner_id] = client
        await asyncio.wait_for(client.connect(), timeout=15.0)
        login = await asyncio.wait_for(client.qr_login(), timeout=15.0)
        image = qrcode.make(login.url)
        output = io.BytesIO()
        image.save(output, format="PNG")
        await bot.send_photo(
            chat_id,
            BufferedInputFile(output.getvalue(), filename="telegram-login.png"),
            caption=(
                "Scan this QR in Telegram Settings > Devices > Link Desktop Device. "
                f"It expires in about {QR_LOGIN_TIMEOUT_SECONDS} seconds. "
                "The login URL is intentionally not shown."
            ),
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
                InlineKeyboardButton(text="Cancel login", callback_data="adm:qr_cancel")
            ]]),
        )
        await asyncio.wait_for(login.wait(), timeout=QR_LOGIN_TIMEOUT_SECONDS)
        account = await client.get_me()
        if account is None or getattr(account, "bot", False):
            raise ValueError("Bot accounts cannot be voice assistants.")
        priority_row = await db.execute_fetchall(
            "SELECT COALESCE(MAX(priority), 0) + 10 AS priority FROM voice_assistants"
        )
        await db.execute(
            """INSERT INTO voice_assistants
            (session_basename, display_name, telegram_user_id, username, priority, health)
            VALUES(?,?,?,?,?,'offline')""",
            (
                basename,
                (getattr(account, "first_name", None) or "Voice assistant")[:80],
                int(account.id),
                getattr(account, "username", None),
                int(priority_row[0]["priority"]),
            ),
        )
        await db.commit()
        row = await db.execute_fetchall(
            "SELECT * FROM voice_assistants WHERE session_basename=?", (basename,)
        )
        await client.disconnect()
        client = None
        if row:
            await start_voice_assistant(row[0])
        await bot.send_message(
            chat_id,
            "Voice assistant authorized and enabled. No session credential was displayed.",
            reply_markup=assistants_markup(await assistant_rows()),
        )
    except SessionPasswordNeededError:
        remove_session_files(basename)
        await bot.send_message(
            chat_id,
            "This account requires 2FA. The incomplete login was deleted. "
            "Run bot/create_user_session.py in Shell; never send the password here.",
            reply_markup=admin_back("assist"),
        )
    except asyncio.TimeoutError:
        remove_session_files(basename)
        await bot.send_message(chat_id, "QR login expired; incomplete session deleted.")
    except asyncio.CancelledError:
        remove_session_files(basename)
        raise
    except Exception as error:
        remove_session_files(basename)
        await bot.send_message(
            chat_id,
            f"QR login failed safely ({html.escape(type(error).__name__)}); incomplete session deleted.",
        )
    finally:
        if client is not None and client.is_connected():
            await client.disconnect()
        qr_login_clients.pop(owner_id, None)
        qr_login_tasks.pop(owner_id, None)


