def is_menu_media_message(message: Message) -> bool:
    return bool(
        message.photo
        or message.animation
        or message.video
        or message.document
        or message.audio
        or message.voice
        or message.sticker
        or message.video_note
    )


async def edit_menu_surface(
    message: Message,
    text: str,
    reply_markup: InlineKeyboardMarkup,
) -> bool:
    media_message = is_menu_media_message(message)
    if media_message and not text:
        try:
            await message.edit_reply_markup(reply_markup=reply_markup)
            return True
        except TelegramBadRequest:
            pass
    if media_message and len(text) <= 1024:
        try:
            await message.edit_caption(caption=text, reply_markup=reply_markup)
            return True
        except TelegramBadRequest:
            pass
    if message.text:
        try:
            await message.edit_text(text, reply_markup=reply_markup)
            return True
        except TelegramBadRequest:
            pass
    return False


class MenuMessageProxy:
    def __init__(self, message: Message) -> None:
        self._message = message

    def __getattr__(self, name: str):
        return getattr(self._message, name)

    async def edit_text(
        self,
        text: str,
        reply_markup: InlineKeyboardMarkup | None = None,
        **kwargs,
    ):
        if is_menu_media_message(self._message):
            return await menu_media_to_text(
                self._message,
                text,
                reply_markup,
            )
        try:
            return await self._message.edit_text(
                text,
                reply_markup=reply_markup,
                **kwargs,
            )
        except TelegramBadRequest as e:
            if "message is not modified" not in str(e).lower():
                return await self._message.answer(text, reply_markup=reply_markup, **kwargs)


def unwrap_menu_message(message: Message) -> Message:
    return message._message if isinstance(message, MenuMessageProxy) else message


async def menu_media_to_text(
    message: Message,
    text: str,
    reply_markup: InlineKeyboardMarkup | None,
) -> Message | None:
    """Delete the one-time welcome media, then continue navigation in text."""
    message = unwrap_menu_message(message)
    try:
        await message.delete()
        return await message.answer(text or MAIN_TEXT, reply_markup=reply_markup, link_preview_options=LinkPreviewOptions(is_disabled=True))
    except TelegramBadRequest:
        try:
            await message.edit_reply_markup(reply_markup=None)
        except TelegramBadRequest:
            pass
        if message.photo or message.animation or message.video or message.document or message.audio:
            try:
                await message.edit_caption(caption=None, reply_markup=None)
            except TelegramBadRequest:
                pass
    return await message.answer(text or MAIN_TEXT, reply_markup=reply_markup, link_preview_options=LinkPreviewOptions(is_disabled=True))


async def render_main_menu(callback: CallbackQuery) -> None:
    if not callback.message:
        return
    message = unwrap_menu_message(callback.message)
    markup = main_menu(
        callback.from_user.id in ADMIN_IDS,
        private_context=message.chat.type == ChatType.PRIVATE,
    )
    root_message = admin_root_messages.pop(callback.from_user.id, None)
    if root_message and root_message != (
        message.chat.id,
        message.message_id,
    ):
        try:
            await bot.edit_message_reply_markup(
                chat_id=root_message[0],
                message_id=root_message[1],
                reply_markup=markup,
            )
            return
        except TelegramBadRequest:
            log.debug("Admin root menu message is no longer editable.")
    if getattr(message, "invoice", None):
        try:
            await message.delete()
        except TelegramBadRequest:
            pass
        await message.answer(MAIN_TEXT, reply_markup=markup)
        return
    if is_menu_media_message(message):
        await menu_media_to_text(message, MAIN_TEXT, markup)
        return
    if message.text:
        try:
            await message.edit_text(MAIN_TEXT, reply_markup=markup)
            return
        except TelegramBadRequest as e:
            if "message is not modified" not in str(e).lower():
                await message.answer(MAIN_TEXT, reply_markup=markup)
    else:
        await message.answer(MAIN_TEXT, reply_markup=markup)


async def render_menu_text(
    callback: CallbackQuery,
    text: str,
    reply_markup: InlineKeyboardMarkup,
) -> None:
    if not callback.message:
        return
    message = unwrap_menu_message(callback.message)
    if is_menu_media_message(message):
        await menu_media_to_text(message, text, reply_markup)
        return
    _lpo = LinkPreviewOptions(is_disabled=True)
    if message.text:
        try:
            await message.edit_text(text, reply_markup=reply_markup, link_preview_options=_lpo)
            return
        except TelegramBadRequest as e:
            if "message is not modified" in str(e).lower():
                return
    await message.answer(text, reply_markup=reply_markup, link_preview_options=_lpo)


async def mafia_handle_role_deep_link(message: Message, payload: str) -> bool:
    if message.chat.type != ChatType.PRIVATE or not message.from_user:
        return False
    if not payload.casefold().startswith("mafia_"):
        return False
    try:
        chat_id = int(payload.split("_", 1)[1])
    except (IndexError, ValueError):
        await message.answer("This Mafia role link is invalid or expired.")
        return True
    session = mafia_sessions.get(chat_id)
    if not session or session["state"] == "finished":
        await message.answer("This Mafia game is no longer active.")
        return True
    user_id = message.from_user.id
    if user_id not in {int(player["id"]) for player in session["players"]}:
        await message.answer("You are not a player in this Mafia game.")
        return True
    role = str(session["roles"].get(str(user_id), "citizen"))
    await message.answer(
        mafia_role_card(session, user_id),
        reply_markup=mafia_role_action_markup(chat_id, session, user_id),
    )
    return True


async def death_note_handle_role_deep_link(
    message: Message, payload: str
) -> bool:
    if message.chat.type != ChatType.PRIVATE or not message.from_user:
        return False
    if not payload.casefold().startswith("deathnote_"):
        return False
    try:
        chat_id = int(payload.split("_", 1)[1])
    except (IndexError, ValueError):
        await message.answer("This Death Note role link is invalid or expired.")
        return True
    session = death_note_sessions.get(chat_id)
    if not session or session["state"] == "finished":
        await message.answer("This Death Note case is no longer active.")
        return True
    user_id = message.from_user.id
    if user_id not in {int(player["id"]) for player in session["players"]}:
        await message.answer("You are not a player in this Death Note case.")
        return True
    await message.answer(
        death_note_role_card(session, user_id),
        reply_markup=death_note_role_check_markup(chat_id),
    )
    return True


@router.message(CommandStart())
async def start(message: Message) -> None:
    u = message.from_user
    uid = u.id if u else 0
    uname = f"@{u.username} " if u and u.username else ""
    log.info("🚀 [/START RECEIVED] User: %s(ID: %s) | Chat: %s (%s)", uname, uid, message.chat.id, message.chat.type)
    if message.chat.type == ChatType.PRIVATE and message.from_user:
        admin_root_messages.pop(message.from_user.id, None)
        start_payload = (message.text or "").split(maxsplit=1)
        if (
            len(start_payload) == 2
            and start_payload[1].strip().casefold() == "admin_panel"
        ):
            await remember_user(message)
            if message.from_user.id not in ADMIN_IDS:
                await message.answer("This private Admin Panel link is not available to you.")
                return
            await message.answer(
                "Admin Panel\n\nControl bot systems from here.",
                reply_markup=admin_menu(),
            )
            return
        if len(start_payload) == 2 and await mafia_handle_role_deep_link(
            message, start_payload[1].strip()
        ):
            await remember_user(message)
            return
        if len(start_payload) == 2 and start_payload[1].strip().startswith("unlock_"):
            raw_gid = start_payload[1].strip()[7:]
            if raw_gid.isdigit():
                await remember_user(message)
                await handle_surprise_unlock_prompt(message, int(raw_gid))
                return
        if len(start_payload) == 2 and start_payload[1].strip().startswith("claim_"):
            code = start_payload[1].strip()[6:]
            await remember_user(message)
            await deliver_surprise_gift_deep_link(message, code)
            return
        if len(start_payload) == 2 and await death_note_handle_role_deep_link(
            message, start_payload[1].strip()
        ):
            await remember_user(message)
            return
    if message.chat.type in {ChatType.GROUP, ChatType.SUPERGROUP}:
        user_id = message.from_user.id if message.from_user else None
        if user_id is None:
            return
        if user_id not in ADMIN_IDS and not await group_admin(message.chat.id, user_id):
            log.info("ℹ️ [/START IGNORED] User %s is not group admin in %s", user_id, message.chat.id)
            return
    if message.from_user:
        active_chats.pop(message.from_user.id, None)
        social_waiting.pop(message.from_user.id, None)
    await remember_user(message)
    await remember_group(message)
    is_admin = bool(message.from_user and message.from_user.id in ADMIN_IDS)
    log.info("📤 [/START SENDING MENU] Sending main menu to %s (is_admin=%s)", uid, is_admin)
    await send_main_menu(message, is_admin)


