@router.callback_query(F.data == "your_groups")
async def your_groups(callback: CallbackQuery) -> None:
    if not await group_menu_callback_allowed(callback):
        return
    await callback.answer()
    user_id = int(callback.from_user.id)
    cached_groups = your_groups_cache.get(user_id)
    if (
        cached_groups
        and time.monotonic() - cached_groups[0] < YOUR_GROUPS_CACHE_SECONDS
    ):
        visible = list(cached_groups[1])
    else:
        cursor = await db.execute(
            "SELECT chat_id, title, username FROM managed_groups ORDER BY title COLLATE NOCASE"
        )
        rows = await cursor.fetchall()

        async def eligible_group(row) -> tuple[int, str, str | None] | None:
            async with group_lookup_gate:
                try:
                    user_is_admin, bot_is_admin = await asyncio.gather(
                        group_admin(int(row["chat_id"]), user_id),
                        bot_is_group_admin(int(row["chat_id"])),
                    )
                    if user_is_admin and bot_is_admin:
                        return (int(row["chat_id"]), str(row["title"]), row["username"])
                except (TelegramBadRequest, TelegramForbiddenError):
                    return None
                except Exception:
                    log.debug(
                        "Could not check group %s for Your Groups",
                        row["chat_id"],
                        exc_info=True,
                    )
            return None

        checked_groups = await asyncio.gather(
            *(eligible_group(row) for row in rows)
        )
        visible = [group for group in checked_groups if group is not None]
        your_groups_cache[user_id] = (time.monotonic(), visible)
    if visible:
        text = (
            "<blockquote>"
            '<tg-emoji emoji-id="5465154440287757794">🛡️</tg-emoji> <b>Your Groups</b>\n\n'
            "Groups where you are an admin and ˹Dᴇsᴛʀᴏʏᴇʀ ꭙ ᴍᴜsɪᴄ ᴀssɪsᴛᴀɴᴛ is active. Select a group to configure:"
            "</blockquote>"
        )
        markup = InlineKeyboardMarkup(
            inline_keyboard=[
                [InlineKeyboardButton(
                    text=(title or str(chat_id))[:60],
                    callback_data=f"group_select:{chat_id}",
                )]
                for chat_id, title, _ in visible[:50]
            ] + [
                [InlineKeyboardButton(text="Back to Group Management", callback_data="group_management")],
                [InlineKeyboardButton(text="Back to Main Menu", callback_data="home")],
            ]
        )
    else:
        text = (
            "<blockquote>"
            '<tg-emoji emoji-id="5465154440287757794">🛡️</tg-emoji> <b>Your Groups</b>\n\n'
            "No eligible groups found yet.\n\n"
            "Add ˹Dᴇsᴛʀᴏʏᴇʀ ꭙ ᴍᴜsɪᴄ ᴀssɪsᴛᴀɴᴛ to your group, make her an admin, and send any message there to get started."
            "</blockquote>"
        )
        markup = group_back_menu()
    await render_menu_text(callback, text, markup)


async def authorized_group_callback(callback: CallbackQuery, chat_id: int) -> bool:
    # Stop Telegram's loading spinner immediately, before the admin API lookup.
    await acknowledge_callback(callback)
