@router.callback_query(F.data.startswith("gf_toggle:"))
async def feature_toggle(callback: CallbackQuery) -> None:
    _, feature, chat_id_raw = callback.data.split(":")
    chat_id = int(chat_id_raw)
    if not await authorized_group_callback(callback, chat_id):
        return
    settings = await get_group_features(chat_id)
    await update_group_feature(chat_id, f"{feature}_enabled", int(not settings[f"{feature}_enabled"]))
    if feature == "spam":
        await render_spam_feature(callback, chat_id)
        return
    if feature == "banned":
        await render_banned_feature(callback, chat_id)
        return
    callback.data = f"gf_{feature}:{chat_id}"
    await group_feature_callback(callback)


@router.callback_query(F.data.startswith("gf_action:"))
async def feature_action(callback: CallbackQuery) -> None:
    parts = callback.data.split(":")
    feature = parts[1]
    chat_id = int(parts[2])
    if not await authorized_group_callback(callback, chat_id):
        return
    settings = await get_group_features(chat_id)
    if feature == "spam" and len(parts) == 4:
        action = parts[3]
        # Anti-Spam uses one escalation action at a time. Selecting a new
        # action automatically turns the previous action off.
        await update_group_feature(chat_id, "spam_action", json.dumps([action]))
        await render_spam_feature(callback, chat_id)
        return
    if feature == "banned" and len(parts) == 4:
        preset = parts[3]
        actions = BANNED_ACTION_PRESETS.get(preset)
        if not actions:
            return
        await update_group_feature(chat_id, "banned_action", json.dumps(actions))
        await render_banned_feature(callback, chat_id)
        return
    choices = ["delete", "warn", "mute", "kick", "ban"] if feature in {"banned", "adult"} else ["delete", "warn", "mute"]
    current = str(settings[f"{feature}_action"])
    await update_group_feature(chat_id, f"{feature}_action", choices[(choices.index(current) + 1) % len(choices)])
    callback.data = f"gf_{feature}:{chat_id}"
    await group_feature_callback(callback)


