@router.callback_query(F.data.startswith("gf_cancel_input:"))
async def cancel_group_feature_input(callback: CallbackQuery) -> None:
    parts = callback.data.split(":")
    chat_id = int(parts[1])
    feature = parts[2] if len(parts) > 2 else "welcome"
    if not await authorized_group_callback(callback, chat_id):
        return
    group_feature_waiting.pop(callback.from_user.id, None)
    if feature == "commands":
        if callback.message:
            await callback.message.edit_text(
                "Editing cancelled.",
                reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
                    InlineKeyboardButton(
                        text="Back to Custom Commands",
                        callback_data=f"gf_commands:{chat_id}",
                    )
                ]]),
            )
        return
    if feature != "welcome":
        settings = await get_group_features(chat_id)
        label = {"spam": "Anti-Spam", "adult": "Adult Content", "banned": "Banned Words"}.get(
            feature, feature.title()
        )
        if callback.message:
            await callback.message.edit_text(
                f"<b>{label}</b>\n\nEditing cancelled.\n"
                f"Status: {'ON' if settings[f'{feature}_enabled'] else 'OFF'}",
                reply_markup=feature_action_keyboard(
                    chat_id, feature, bool(settings[f"{feature}_enabled"]),
                    str(settings[f"{feature}_action"]),
                ),
            )
        return
    if callback.message:
        await callback.message.edit_text(
            "Editing cancelled.",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(text="Back to Welcome", callback_data=f"gf_welcome:{chat_id}")],
                [InlineKeyboardButton(text="Back to Group", callback_data=f"group_select:{chat_id}")],
            ]),
        )


