@router.callback_query(F.data.startswith("gf_preview:"))
async def preview_welcome(callback: CallbackQuery) -> None:
    chat_id = int(callback.data.split(":")[1])
    if not await authorized_group_callback(callback, chat_id):
        return
    settings = await get_group_features(chat_id)
    preview = expand_welcome_text(str(settings["welcome_text"]), callback.from_user, chat_id, "Preview Group")
    await callback.answer()
    markup = welcome_buttons_markup(str(settings["welcome_buttons"]))
    try:
        media_id = settings["welcome_media_id"]
        media_type = settings["welcome_media_type"]
        if media_id and media_type == "photo":
            await bot.send_photo(callback.from_user.id, media_id, caption=preview, reply_markup=markup)
        elif media_id and media_type == "video":
            await bot.send_video(callback.from_user.id, media_id, caption=preview, reply_markup=markup)
        elif media_id and media_type == "animation":
            await bot.send_animation(callback.from_user.id, media_id, caption=preview, reply_markup=markup)
        elif media_id and media_type == "document":
            await bot.send_document(callback.from_user.id, media_id, caption=preview, reply_markup=markup)
        elif media_id and media_type == "audio":
            await bot.send_audio(callback.from_user.id, media_id, caption=preview, reply_markup=markup)
        elif media_id and media_type == "voice":
            await bot.send_voice(callback.from_user.id, media_id, caption=preview, reply_markup=markup)
        elif media_id and media_type == "sticker":
            await bot.send_sticker(callback.from_user.id, media_id)
            await bot.send_message(callback.from_user.id, preview, reply_markup=markup)
        elif media_id and media_type == "video_note":
            await bot.send_video_note(callback.from_user.id, media_id)
            await bot.send_message(callback.from_user.id, preview, reply_markup=markup)
        else:
            await bot.send_message(callback.from_user.id, preview, reply_markup=markup)
    except TelegramBadRequest:
        await bot.send_message(
            callback.from_user.id,
            "Preview could not be rendered. Check your HTML tags and try again.",
        )


@router.message(F.new_chat_members)
async def welcome_new_members(message: Message) -> None:
    await remember_group(message)
    settings = await get_group_features(message.chat.id)
    if not settings["welcome_enabled"]:
        return
    markup = welcome_buttons_markup(str(settings["welcome_buttons"]))
    for user in message.new_chat_members or []:
        text = expand_welcome_text(
            str(settings["welcome_text"]), user, message.chat.id,
            message.chat.title or "the group",
        )
        media_id = settings["welcome_media_id"]
        try:
            if media_id and settings["welcome_media_type"] == "photo":
                await message.answer_photo(media_id, caption=text, reply_markup=markup)
            elif media_id and settings["welcome_media_type"] == "video":
                await message.answer_video(media_id, caption=text, reply_markup=markup)
            elif media_id and settings["welcome_media_type"] == "animation":
                await message.answer_animation(media_id, caption=text, reply_markup=markup)
            elif media_id and settings["welcome_media_type"] == "document":
                await message.answer_document(media_id, caption=text, reply_markup=markup)
            elif media_id and settings["welcome_media_type"] == "audio":
                await message.answer_audio(media_id, caption=text, reply_markup=markup)
            elif media_id and settings["welcome_media_type"] == "voice":
                await message.answer_voice(media_id, caption=text, reply_markup=markup)
            elif media_id and settings["welcome_media_type"] == "sticker":
                await message.answer_sticker(media_id)
                await message.answer(text, reply_markup=markup)
            elif media_id and settings["welcome_media_type"] == "video_note":
                await message.answer_video_note(media_id)
                await message.answer(text, reply_markup=markup)
            else:
                await message.answer(text, reply_markup=markup)
        except TelegramBadRequest:
            log.exception("Welcome message failed in group %s", message.chat.id)


