@router.callback_query(
    F.data.in_({
        "leaderboard:aichat",
        "leaderboard:aichat:refresh",
        "leaderboard:groups",
        "leaderboard:groups:refresh",
        "leaderboard:people",
        "leaderboard:people:refresh",
        "leaderboard:chess",
        "leaderboard:chess:refresh",
        "leaderboard:ludo",
        "leaderboard:ludo:refresh",
        "leaderboard:crossgrid",
        "leaderboard:crossgrid:refresh",
    })
)
async def leaderboard_category(callback: CallbackQuery) -> None:
    if not await group_menu_callback_allowed(callback):
        return
    await callback.answer()
    data = callback.data or ""
    uid = callback.from_user.id if callback.from_user else None
    try:
        if data.startswith("leaderboard:aichat") or data.startswith("leaderboard:groups"):
            text, markup = await leaderboard_ai_chat_view()
        elif data.startswith("leaderboard:people"):
            text, markup = await leaderboard_people_view()
        elif data.startswith("leaderboard:chess"):
            text, markup = await leaderboard_chess_view(uid)
        elif data.startswith("leaderboard:ludo"):
            text, markup = await leaderboard_ludo_view(uid)
        elif data.startswith("leaderboard:crossgrid"):
            text, markup = await leaderboard_crossgrid_view(uid)
        else:
            return
        await render_menu_text(callback, text, markup)
    except TelegramBadRequest as error:
        if "message is not modified" in str(error).casefold():
            return
        log.exception("Leaderboard message update failed: %s", error)
    except Exception:
        log.exception("Leaderboard view failed")


@router.message(Command("setimage"))
async def set_image_command(message: Message) -> None:
    if not message.from_user or message.chat.type not in {ChatType.GROUP, ChatType.SUPERGROUP}:
        return
    if await group_command_is_locked(message):
        return
    await remember_group(message)
    command_text = (message.text or message.caption or "").partition(" ")[2].strip()
    source = message.reply_to_message
    photo = (message.photo or (source.photo if source else None))
    if not photo:
        await message.reply(
            "Please reply to a photo with /setimage followed by your text."
        )
        return
    if not command_text:
        await message.reply(
            "Please add text after /setimage, for example: /setimage Hello"
        )
        return
    sticker_text = re.sub(r"\s+", " ", command_text).strip()
    if len(sticker_text.split()) > MAX_STICKER_WORDS:
        await message.reply(
            f"Too many words. Please use {MAX_STICKER_WORDS} words or fewer."
        )
        return
    if len(sticker_text) > MAX_STICKER_TEXT:
        await message.reply(
            f"Text is too long. Please use {MAX_STICKER_TEXT} characters or fewer."
        )
        return
    progress = await message.reply("Creating your image sticker...\n[░░░░░░░░░░] 0%")

    async def update_progress(percent: int) -> None:
        filled = min(10, percent // 10)
        bar = "█" * filled + "░" * (10 - filled)
        try:
            await progress.edit_text(
                f"Creating your image sticker...\n[{bar}] {percent}%"
            )
        except (TelegramBadRequest, TelegramRetryAfter):
            pass

    try:
        await update_progress(10)
        photo_size = photo[-1]
        telegram_file = await bot.get_file(photo_size.file_id)
        source_buffer = io.BytesIO()
        await bot.download_file(telegram_file.file_path, source_buffer)
        await update_progress(35)
        await wait_for_sticker_slot(progress, "Creating your image sticker...")
        try:
            sticker_bytes = await asyncio.to_thread(
                render_image_sticker, source_buffer.getvalue(), sticker_text,
                message.from_user.id,
            )
        finally:
            await leave_sticker_queue()
        await update_progress(75)
        duplicate_key = f"image:{message.from_user.id}:{sticker_text.casefold()}:{photo_size.file_unique_id}"
        content_hash = hashlib.sha256(duplicate_key.encode("utf-8")).hexdigest()[:32]
        pending_stickers[content_hash] = (
            sticker_bytes,
            message.from_user.id,
            message.from_user.first_name,
            message.from_user.username,
        )
        markup = None
        sticker_message = await send_sticker_with_retry(
            message, sticker_bytes, "seyuki-image.webp", markup, progress,
            "Creating your image sticker...",
        )
        pending_sticker_messages[content_hash] = (
            message.chat.id, sticker_message.message_id
        )
        await asyncio.wait_for(
            persist_pending_sticker(
                content_hash, pending_stickers[content_hash],
                (message.chat.id, sticker_message.message_id),
            ),
            timeout=STICKER_TELEGRAM_TIMEOUT,
        )
        await update_progress(100)
        await asyncio.sleep(0.2)
        await progress.delete()
    except Exception:
        log.exception("Image sticker generation failed for user %s", message.from_user.id)
        try:
            await progress.edit_text(
                "Could not create the image sticker. Please try another photo."
            )
        except (TelegramBadRequest, TelegramRetryAfter):
            pass


quote_file_id_cache: dict[str, str] = {}


@router.message(Command("setchat", "q", "quote"))
async def set_chat_command(message: Message) -> None:
    """Turn a replied-to message or text into an instant Quotly-style quote sticker."""
    if not message.from_user or message.chat.type not in {ChatType.GROUP, ChatType.SUPERGROUP}:
        return
    if await group_command_is_locked(message):
        return
    await remember_group(message)

    try:
        await bot.send_chat_action(message.chat.id, "choose_sticker")
    except Exception:
        pass

    command_text = (message.text or message.caption or "").partition(" ")[2].strip()
    source = message.reply_to_message
    target_user = source.from_user if source and source.from_user else None
    target_text = ""

    if source and target_user:
        target_text = (source.text or source.caption or "").strip()
    elif command_text:
        match = re.search(r"@([A-Za-z0-9_]{5,32})", command_text)
        if match:
            username = match.group(1)
            tagged_text = command_text[match.end():].strip()
            if tagged_text:
                target_text = tagged_text
                try:
                    target_id = await resolve_social_target(message, [f"@{username}"])
                    if target_id:
                        cursor = await db.execute(
                            "SELECT user_id, first_name, username FROM users WHERE user_id=?",
                            (target_id,),
                        )
                        known_user = await cursor.fetchone()
                        if known_user:
                            target_user = SimpleNamespace(
                                id=int(known_user["user_id"]),
                                first_name=str(known_user["first_name"] or ""),
                                full_name=str(known_user["first_name"] or ""),
                                username=str(known_user["username"] or username),
                            )
                except Exception:
                    pass
        if not target_text:
            target_text = command_text
            target_user = message.from_user

    if not target_text:
        await message.reply(
            "Reply to any message with <code>/q</code> to create an instant quote sticker!",
            parse_mode="HTML",
        )
        return

    if len(target_text) > MAX_STICKER_TEXT:
        target_text = target_text[:MAX_STICKER_TEXT - 3].rstrip() + "..."

    display_name = (
        getattr(target_user, "full_name", None)
        or getattr(target_user, "first_name", None)
        or getattr(target_user, "username", None)
        or "User"
    )

    target_id = int(getattr(target_user, "id", 0) or 0)
    quote_cache_key = hashlib.sha256(f"{target_id}:{target_text}:{display_name}".encode("utf-8")).hexdigest()

    started_at = time.monotonic()
    cached_fid = quote_file_id_cache.get(quote_cache_key)
    if cached_fid:
        try:
            await message.reply_sticker(sticker=cached_fid)
            log.info("/q served from Telegram file_id cache in %.3fs for chat %s", time.monotonic() - started_at, message.chat.id)
            return
        except Exception:
            quote_file_id_cache.pop(quote_cache_key, None)

    avatar_bytes: bytes | None = None
    cached_avatar = avatar_cache.get(target_id)
    if cached_avatar and time.monotonic() - cached_avatar[0] < AVATAR_CACHE_TTL:
        avatar_bytes = cached_avatar[1]
    else:
        disk_av_path = Path("data/avatars") / f"{target_id}.jpg"
        if disk_av_path.exists():
            try:
                avatar_bytes = disk_av_path.read_bytes()
                avatar_cache[target_id] = (time.monotonic(), avatar_bytes)
            except Exception:
                pass

        if avatar_bytes is None and target_id:
            try:
                photos = await bot.get_user_profile_photos(target_id, limit=1)
                if photos.total_count and photos.photos:
                    thumb = photos.photos[0][0]
                    photo_file = await bot.get_file(thumb.file_id)
                    buf = io.BytesIO()
                    await bot.download_file(photo_file.file_path, buf)
                    avatar_bytes = buf.getvalue()
                    try:
                        disk_av_path.write_bytes(avatar_bytes)
                    except Exception:
                        pass
            except Exception:
                pass
            avatar_cache[target_id] = (time.monotonic(), avatar_bytes)

    try:
        sticker_bytes = await asyncio.to_thread(
            render_chat_sticker,
            target_text,
            display_name,
            avatar_bytes,
            target_id or message.from_user.id,
        )
        sent_sticker = await message.reply_sticker(
            sticker=BufferedInputFile(sticker_bytes, filename="quote.webp")
        )
        if sent_sticker.sticker and sent_sticker.sticker.file_id:
            quote_file_id_cache[quote_cache_key] = sent_sticker.sticker.file_id
            if len(quote_file_id_cache) > 2000:
                quote_file_id_cache.pop(next(iter(quote_file_id_cache)))

        log.info(
            "/q sticker generated in %.3fs for user %s in chat %s",
            time.monotonic() - started_at,
            target_id,
            message.chat.id,
        )
    except Exception as exc:
        log.exception("Chat quote sticker generation failed for user %s: %s", target_id, exc)
        await message.reply("⚠️ Sticker generate karne me error aaya. Please try again.")


async def chat_sticker_markup(content_hash: str) -> InlineKeyboardMarkup:
    cursor = await db.execute(
        "SELECT COALESCE(SUM(CASE WHEN vote=1 THEN 1 ELSE 0 END),0) AS likes, "
        "COALESCE(SUM(CASE WHEN vote=-1 THEN 1 ELSE 0 END),0) AS dislikes "
        "FROM chat_sticker_votes WHERE content_hash=?",
        (content_hash,),
    )
    row = await cursor.fetchone()
    likes = int(row["likes"] or 0)
    dislikes = int(row["dislikes"] or 0)
    return InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text=f"Like {likes}", callback_data=f"chat_like:{content_hash}"),
        InlineKeyboardButton(text=f"Dislike {dislikes}", callback_data=f"chat_dislike:{content_hash}"),
    ]])


async def record_chat_sticker_vote(
    callback: CallbackQuery, vote: int, content_hash: str
) -> None:
    pending = pending_stickers.get(content_hash)
    if not pending:
        restored = await restore_pending_sticker(content_hash)
        if restored:
            pending, reference = restored
            pending_stickers[content_hash] = pending
            pending_sticker_messages[content_hash] = reference
    if not pending:
        await callback.answer("This sticker is no longer available.", show_alert=True)
        return
    cursor = await db.execute(
        "SELECT vote FROM chat_sticker_votes WHERE content_hash=? AND user_id=?",
        (content_hash, callback.from_user.id),
    )
    existing = await cursor.fetchone()
    if existing and int(existing["vote"]) == vote:
        await callback.answer("Your vote has already been counted.")
    else:
        await db.execute(
            "INSERT INTO chat_sticker_votes(content_hash,user_id,vote) VALUES(?,?,?) "
            "ON CONFLICT(content_hash,user_id) DO UPDATE SET vote=excluded.vote",
            (content_hash, callback.from_user.id, vote),
        )
        await db.commit()
        await callback.answer("Like count updated." if vote == 1 else "Dislike count updated.")
    if callback.message:
        await callback.message.edit_reply_markup(
            reply_markup=await chat_sticker_markup(content_hash)
        )


@router.callback_query(F.data.startswith("chat_like:"))
async def chat_sticker_like(callback: CallbackQuery) -> None:
    await record_chat_sticker_vote(callback, 1, callback.data.split(":", 1)[1])


@router.callback_query(F.data.startswith("chat_dislike:"))
async def chat_sticker_dislike(callback: CallbackQuery) -> None:
    await record_chat_sticker_vote(callback, -1, callback.data.split(":", 1)[1])


@router.message(Command("setsticker"))
async def set_sticker_command(message: Message) -> None:
    if not message.from_user or message.chat.type not in {ChatType.GROUP, ChatType.SUPERGROUP}:
        return
    if await group_command_is_locked(message):
        return
    await remember_group(message)
    command_text = (message.text or "").partition(" ")[2].strip()
    source = message.reply_to_message
    source_text = ""
    if source:
        source_text = (source.text or source.caption or "").strip()
    sticker_text = command_text or source_text
    if not sticker_text:
        await message.reply(
            "Reply to a text message and send /setsticker, "
            "or add text after /setsticker."
        )
        return
    sticker_text = re.sub(r"\s+", " ", sticker_text).strip()
    if len(sticker_text.split()) > MAX_STICKER_WORDS:
        await message.reply(
            f"Too many words. Please use {MAX_STICKER_WORDS} words or fewer."
        )
        return
    if len(sticker_text) > MAX_STICKER_TEXT:
        await message.reply(
            f"Text is too long. Please use {MAX_STICKER_TEXT} characters or fewer."
        )
        return
    progress = await message.reply("Creating your sticker...\n[░░░░░░░░░░] 0%")

    async def update_progress(percent: int) -> None:
        filled = min(10, percent // 10)
        bar = "█" * filled + "░" * (10 - filled)
        try:
            await progress.edit_text(f"Creating your sticker...\n[{bar}] {percent}%")
        except (TelegramBadRequest, TelegramRetryAfter):
            pass

    try:
        await update_progress(10)
        await wait_for_sticker_slot(progress, "Creating your sticker...")
        try:
            sticker_bytes = await asyncio.to_thread(
                render_text_sticker, sticker_text, message.from_user.id
            )
        finally:
            await leave_sticker_queue()
        await update_progress(60)
        # Hash the normalized source text, not the random visual style. This
        # prevents the same user from saving the same sticker twice.
        duplicate_key = f"{message.from_user.id}:{sticker_text.casefold()}"
        content_hash = hashlib.sha256(duplicate_key.encode("utf-8")).hexdigest()[:32]
        pending_stickers[content_hash] = (
            sticker_bytes,
            message.from_user.id,
            message.from_user.first_name,
            message.from_user.username,
        )
        while len(pending_stickers) > 5000:
            pending_stickers.pop(next(iter(pending_stickers)))
        markup = None
        await update_progress(90)
        sticker_message = await send_sticker_with_retry(
            message, sticker_bytes, "seyuki.webp", markup, progress,
            "Creating your sticker...",
        )
        pending_sticker_messages[content_hash] = (
            message.chat.id,
            sticker_message.message_id,
        )
        while len(pending_sticker_messages) > 5000:
            pending_sticker_messages.pop(next(iter(pending_sticker_messages)))
        await asyncio.wait_for(
            persist_pending_sticker(
                content_hash,
                pending_stickers[content_hash],
                (message.chat.id, sticker_message.message_id),
            ),
            timeout=STICKER_TELEGRAM_TIMEOUT,
        )
        await update_progress(100)
        await asyncio.sleep(0.2)
        await progress.delete()
    except Exception:
        log.exception("Sticker generation failed for user %s", message.from_user.id)
        try:
            await progress.edit_text("The sticker could not be created. Try using shorter text.")
        except (TelegramBadRequest, TelegramRetryAfter):
            pass


async def finalize_sticker_callback(callback: CallbackQuery, liked: bool, content_hash: str) -> None:
    pending = pending_stickers.get(content_hash)
    if not pending:
        restored = await restore_pending_sticker(content_hash)
        if restored:
            pending, reference = restored
            pending_stickers[content_hash] = pending
            pending_sticker_messages[content_hash] = reference
    if not pending:
        await callback.answer("This sticker is no longer active.")
        if callback.message:
            await callback.message.edit_reply_markup(reply_markup=None)
        return
    sticker_bytes, owner_id, first_name, username = pending
    if callback.from_user.id != owner_id:
        await callback.answer("Only the sticker creator can save this sticker.", show_alert=True)
        return
    # Acknowledge immediately; saving to Telegram's pack can take a few seconds.
    await callback.answer("Saving to your pack..." if liked else "Removing sticker...")
    if not liked:
        pending_stickers.pop(content_hash, None)
        sticker_reference = pending_sticker_messages.pop(content_hash, None)
        if callback.message:
            await callback.message.edit_reply_markup(reply_markup=None)
        if sticker_reference:
            chat_id, sticker_message_id = sticker_reference
            try:
                await bot.delete_message(chat_id, sticker_message_id)
            except TelegramBadRequest:
                pass
        await delete_pending_sticker_files(content_hash)
        return
    save_progress = None
    if callback.message:
        save_progress = await callback.message.answer("Saving sticker to your pack...\n[░░░░░░░░░░] 0%")

    async def update_save_progress(percent: int) -> None:
        if not save_progress:
            return
        filled = min(10, percent // 10)
        bar = "█" * filled + "░" * (10 - filled)
        try:
            await save_progress.edit_text(
                f"Saving sticker to your pack...\n[{bar}] {percent}%"
            )
        except TelegramBadRequest:
            pass

    await update_save_progress(20)
    cursor = await db.execute(
        "SELECT pack_name FROM saved_stickers WHERE user_id=? AND content_hash=?",
        (owner_id, content_hash),
    )
    existing = await cursor.fetchone()
    if existing:
        pending_stickers.pop(content_hash, None)
        pending_sticker_messages.pop(content_hash, None)
        await update_save_progress(100)
        if callback.message:
            await callback.message.edit_reply_markup(reply_markup=None)
        if save_progress:
            await asyncio.sleep(0.2)
            await save_progress.delete()
        await delete_pending_sticker_files(content_hash)
        return
    await update_save_progress(40)
    pack_name = await add_sticker_to_user_pack(owner_id, sticker_bytes, first_name, username)
    if not pack_name:
        pending_stickers[content_hash] = pending
        await update_save_progress(100)
        if save_progress:
            await asyncio.sleep(0.2)
            await save_progress.delete()
        return
    await update_save_progress(80)
    pending_stickers.pop(content_hash, None)
    pending_sticker_messages.pop(content_hash, None)
    await db.execute(
        "INSERT OR IGNORE INTO saved_stickers(user_id, content_hash, pack_name) VALUES(?,?,?)",
        (owner_id, content_hash, pack_name),
    )
    await db.commit()
    await update_save_progress(100)
    if callback.message:
        await callback.message.edit_reply_markup(reply_markup=None)
    if save_progress:
        await asyncio.sleep(0.2)
        await save_progress.delete()
    await delete_pending_sticker_files(content_hash)


@router.callback_query(F.data.startswith("sticker_like:"))
async def sticker_like(callback: CallbackQuery) -> None:
    await finalize_sticker_callback(callback, True, callback.data.split(":", 1)[1])


