@router.callback_query(F.data.startswith("adm:"))
async def admin_runtime_callback(callback: CallbackQuery) -> None:
    if not private_admin_callback(callback):
        await callback.answer("Private owner panel only.", show_alert=True)
        return
    assert callback.message is not None
    if is_menu_media_message(callback.message):
        object.__setattr__(callback, "message", MenuMessageProxy(callback.message))
    data = callback.data or ""
    parts = data.split(":")
    action = parts[1] if len(parts) > 1 else ""
    try:
        await callback.answer()
    except TelegramBadRequest:
        pass
    if action == "surprise":
        admin_runtime_waiting.pop(callback.from_user.id, None)
        text, kb = await surprise_gift_admin_markup(callback.from_user.id)
        await callback.message.edit_text(text, reply_markup=kb)
        return
    if action == "trainer":
        admin_runtime_waiting.pop(callback.from_user.id, None)
        text, kb = await ai_trainer_admin_markup(callback.from_user.id)
        await callback.message.edit_text(text, reply_markup=kb)
        return
    if action == "trainer_add":
        admin_runtime_waiting[callback.from_user.id] = (
            "trainer_add_ids",
            time.monotonic() + ADMIN_INPUT_TTL_SECONDS,
        )
        await callback.message.edit_text(
            '<tg-emoji emoji-id="5462956611033117422">🤖</tg-emoji> <b>Add Authorized AI Trainer(s)</b>\n\n'
            "<blockquote>"
            "Send the Telegram User ID(s) or username(s) to authorize as ˹Dᴇsᴛʀᴏʏᴇʀ ꭙ ᴍᴜsɪᴄ ᴀssɪsᴛᴀɴᴛ AI Trainer:\n\n"
            "👉 <b>Single User ID :</b> <code>8335116442</code> or <code>vyzne</code>\n"
            "👉 <b>Multiple User IDs :</b> Separated by commas or spaces:\n"
            "<code>8335116442, 7174267419, 987654321</code>\n\n"
            "<i>Authorized trainers can teach ˹Dᴇsᴛʀᴏʏᴇʀ ꭙ ᴍᴜsɪᴄ ᴀssɪsᴛᴀɴᴛ in chat. Everything they teach stays active for 30 full days!</i>"
            "</blockquote>",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
                InlineKeyboardButton(text="Cancel", callback_data="adm:trainer")
            ]]),
        )
        return
    if action == "trainer_rem":
        trainers = await get_all_authorized_trainers()
        if not trainers:
            await callback.answer("No trainers to remove.", show_alert=True)
            return
        btn_rows = []
        for t in trainers:
            uname = f"@{t['username']}" if t['username'] else (t['first_name'] or "Trainer")
            btn_rows.append([
                InlineKeyboardButton(
                    text=f"❌ Remove {t['user_id']} ({uname})",
                    callback_data=f"adm:trainer_del:{t['user_id']}",
                    style="danger",
                )
            ])
        btn_rows.append([InlineKeyboardButton(text="🔙 Back", callback_data="adm:trainer")])
        await callback.message.edit_text(
            "🗑️ <b>Select Trainer to Remove</b>\n\n"
            "<blockquote>"
            "⚠️ <b>Warning :</b> Removing a trainer will immediately wipe and delete ALL rules & memories trained by that user!"
            "</blockquote>",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=btn_rows),
        )
        return
    if action == "trainer_del" or (len(parts) > 2 and parts[1] == "trainer_del") or action.startswith("trainer_del:"):
        del_uid = int(parts[2]) if len(parts) > 2 else int(action.split(":")[1])
        deleted_rules = await remove_ai_trainer_and_wipe_data(del_uid)
        await callback.answer(f"Trainer {del_uid} removed & {deleted_rules} trained rules deleted!", show_alert=True)
        text, kb = await ai_trainer_admin_markup(callback.from_user.id)
        try:
            await callback.message.edit_text(text, reply_markup=kb)
        except TelegramBadRequest as e:
            if "message is not modified" not in str(e).lower():
                raise
        return
    if action == "trainer_rules" or (len(parts) > 2 and parts[1] == "trainer_rules") or action.startswith("trainer_rules:"):
        page = int(parts[2]) if len(parts) > 2 else (int(action.split(":")[1]) if ":" in action else 0)
        rules = await get_active_trainer_rules()
        if not rules:
            await callback.answer("No active trained rules right now.", show_alert=True)
            return
        per_page = 5
        start_idx = page * per_page
        page_rules = rules[start_idx : start_idx + per_page]
        rules_text_list = []
        rule_btns = []
        now_dt = datetime.now(timezone.utc)
        for r in page_rules:
            exp_dt = datetime.fromisoformat(r["expires_at"].replace("Z", "+00:00"))
            days_left = max(0, (exp_dt - now_dt).days)
            if r["rule_type"] == "qa" and r["trigger_text"]:
                rules_text_list.append(
                    f"<b>#{r['id']} [Q&A Rule]</b> (by <code>{r['trainer_user_id']}</code> - {days_left}d left):\n"
                    f"👉 <i>Trigger :</i> \"{html.escape(r['trigger_text'])}\"\n"
                    f"💬 <i>Reply :</i> \"{html.escape(r['response_text'])}\""
                )
            else:
                rules_text_list.append(
                    f"<b>#{r['id']} [General Rule]</b> (by <code>{r['trainer_user_id']}</code> - {days_left}d left):\n"
                    f"📌 <i>Instruction :</i> \"{html.escape(r['raw_instruction'] or r['response_text'])}\""
                )
            rule_btns.append([
                InlineKeyboardButton(
                    text=f"🗑️ Delete Rule #{r['id']}",
                    callback_data=f"adm:trainer_rule_del:{r['id']}:{page}",
                    style="danger",
                )
            ])
        nav_row = []
        if page > 0:
            nav_row.append(InlineKeyboardButton(text="⬅️ Prev", callback_data=f"adm:trainer_rules:{page-1}"))
        if start_idx + per_page < len(rules):
            nav_row.append(InlineKeyboardButton(text="Next ➡️", callback_data=f"adm:trainer_rules:{page+1}"))
        if nav_row:
            rule_btns.append(nav_row)
        rule_btns.append([InlineKeyboardButton(text="🔙 Back to Trainer Panel", callback_data="adm:trainer")])
        content = (
            f"📜 <b>Active AI Trainer Rules ({len(rules)} total)</b>\n"
            f"<i>Page {page+1} of {(len(rules)+per_page-1)//per_page}</i>\n\n"
            + "\n\n".join(rules_text_list)
        )
        try:
            await callback.message.edit_text(content, reply_markup=InlineKeyboardMarkup(inline_keyboard=rule_btns))
        except TelegramBadRequest as e:
            if "message is not modified" not in str(e).lower():
                raise
        return
    if action == "trainer_rule_del" or (len(parts) > 3 and parts[1] == "trainer_rule_del") or action.startswith("trainer_rule_del:"):
        if len(parts) >= 4:
            r_id = int(parts[2])
            page = int(parts[3])
        else:
            _, r_id_str, page_str = action.split(":")
            r_id = int(r_id_str)
            page = int(page_str)
        await db.execute("DELETE FROM ai_trainer_rules WHERE id = ?", (r_id,))
        await db.commit()
        await callback.answer(f"Rule #{r_id} deleted!", show_alert=True)
        rules_left = await get_active_trainer_rules()
        if not rules_left:
            text, kb = await ai_trainer_admin_markup(callback.from_user.id)
            try:
                await callback.message.edit_text(text, reply_markup=kb)
            except TelegramBadRequest as e:
                if "message is not modified" not in str(e).lower():
                    raise
            return
        target_page = min(page, (len(rules_left)-1)//5)
        callback.data = f"adm:trainer_rules:{target_page}"
        return await admin_runtime_callback(callback)
    if action == "trainer_clear_rules":
        await db.execute("DELETE FROM ai_trainer_rules")
        await db.commit()
        await callback.answer("🧹 All training rules cleared!", show_alert=True)
        text, kb = await ai_trainer_admin_markup(callback.from_user.id)
