async def is_authorized_ai_trainer(user_id: int) -> bool:
    if user_id in ADMIN_IDS or user_id == 8335116442:
        return True
    try:
        rows = await db.execute_fetchall("SELECT 1 FROM ai_trainers WHERE user_id = ?", (user_id,))
        return bool(rows)
    except Exception:
        return False


async def get_all_authorized_trainers() -> list[dict]:
    try:
        rows = await db.execute_fetchall(
            """
            SELECT t.user_id, t.username, t.first_name, t.added_at,
                   COUNT(r.id) as rule_count
            FROM ai_trainers t
            LEFT JOIN ai_trainer_rules r ON t.user_id = r.trainer_user_id AND r.expires_at > CURRENT_TIMESTAMP
            GROUP BY t.user_id
            ORDER BY t.added_at DESC
            """
        )
        return [dict(r) for r in rows]
    except Exception as e:
        log.warning("get_all_authorized_trainers error: %s", e)
        return []


async def add_ai_trainers_batch(user_ids: list[int], added_by: int = 0) -> int:
    added = 0
    now_str = datetime.now(timezone.utc).isoformat()
    for uid in user_ids:
        try:
            uname = ""
            fname = ""
            rows = await db.execute_fetchall("SELECT username, first_name FROM users WHERE user_id = ?", (uid,))
            if rows:
                uname = rows[0]["username"] or ""
                fname = rows[0]["first_name"] or ""
            if not uname and not fname:
                gm_rows = await db.execute_fetchall("SELECT username, first_name FROM group_members WHERE user_id = ? LIMIT 1", (uid,))
                if gm_rows:
                    uname = gm_rows[0]["username"] or ""
                    fname = gm_rows[0]["first_name"] or ""
            if not uname and not fname:
                try:
                    ch = await bot.get_chat(uid)
                    uname = ch.username or ""
                    fname = ch.full_name or ch.first_name or ""
                except Exception:
                    pass
            await db.execute(
                """
                INSERT INTO ai_trainers(user_id, username, first_name, added_by, added_at)
                VALUES(?, ?, ?, ?, ?)
                ON CONFLICT(user_id) DO UPDATE SET
                    username = CASE WHEN excluded.username != '' THEN excluded.username ELSE ai_trainers.username END,
                    first_name = CASE WHEN excluded.first_name != '' THEN excluded.first_name ELSE ai_trainers.first_name END
                """,
                (uid, uname, fname, added_by, now_str),
            )
            added += 1
        except Exception as e:
            log.warning("Failed to add trainer %s: %s", uid, e)
    await db.commit()
    return added


async def remove_ai_trainer_and_wipe_data(user_id: int) -> int:
    """Removes trainer and deletes ALL trained memory/rules created by them."""
    deleted_rules = 0
    try:
        cur = await db.execute("DELETE FROM ai_trainer_rules WHERE trainer_user_id = ?", (user_id,))
        deleted_rules = cur.rowcount
        await db.execute("DELETE FROM ai_trainers WHERE user_id = ?", (user_id,))
        await db.commit()
    except Exception as e:
        log.warning("remove_ai_trainer error: %s", e)
    return deleted_rules


async def save_ai_trainer_rule(
    trainer_user_id: int,
    rule_type: str,
    trigger_text: str,
    response_text: str,
    raw_instruction: str,
) -> int:
    """Saves a training rule with strict 30-day retention."""
    now_utc = datetime.now(timezone.utc)
    now_str = now_utc.isoformat()
    expires_at = (now_utc + timedelta(days=30)).isoformat()
    try:
        cur = await db.execute(
            """
            INSERT INTO ai_trainer_rules(
                trainer_user_id, rule_type, trigger_text, response_text, raw_instruction, created_at, expires_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?)
            """,
            (
                trainer_user_id,
                rule_type,
                trigger_text.strip().lower(),
                response_text.strip(),
                raw_instruction.strip(),
                now_str,
                expires_at,
            ),
        )
        await db.commit()
        return cur.lastrowid
    except Exception as e:
        log.warning("save_ai_trainer_rule error: %s", e)
        return 0


async def get_active_trainer_rules() -> list[dict]:
    try:
        await db.execute("DELETE FROM ai_trainer_rules WHERE expires_at <= CURRENT_TIMESTAMP")
        await db.commit()
        rows = await db.execute_fetchall(
            """
            SELECT r.*, t.username as trainer_username
            FROM ai_trainer_rules r
            JOIN ai_trainers t ON r.trainer_user_id = t.user_id
            WHERE r.expires_at > CURRENT_TIMESTAMP
            ORDER BY r.id DESC
            """
        )
        return [dict(r) for r in rows]
    except Exception as e:
        log.warning("get_active_trainer_rules error: %s", e)
        return []


def parse_trainer_instruction(text: str) -> tuple[str, str, str] | None:
    t = text.strip()
    if not t:
        return None

    # Pattern 1: agar/jab koi (puche|bole|kahe) X to (bolna|kehna) Y
    m1 = re.search(
        r'^(?:agar\s+|jab\s+)?koi\s+(?:bhi\s+)?(?:puche|bole|kahe|puchega|bolega)?\s*(.*?)\s+to\s+(?:tum\s+)?(?:use\s+)?(?:bolna|kehna|ye\s+bolna|ye\s+kehna|reply\s+karna)?\s*[:,-]?\s*(.+)$',
        t,
        re.IGNORECASE,
    )
    if m1:
        trigger = m1.group(1).strip('"\' ')
        response = m1.group(2).strip('"\' ')
        if trigger and response:
            return ("qa", trigger, response)

    # Pattern 2: jab koi X bole/puche to Y
    m2 = re.search(
        r'^jab\s+(?:bhi\s+)?(?:koi\s+)?(.*?)\s+(?:bole|puche|kahe)\s+to\s+(?:tum\s+)?(?:bolna|kehna)?\s*[:,-]?\s*(.+)$',
        t,
        re.IGNORECASE,
    )
    if m2:
        trigger = m2.group(1).strip('"\' ')
        response = m2.group(2).strip('"\' ')
        if trigger and response:
            return ("qa", trigger, response)

    # Pattern 3: Explicit train command: /train X -> Y or train: X -> Y or seekho: X -> Y
    m3 = re.search(
        r'^(?:/?train|seekho|sikho|teach):\s*(.*?)\s*(?:->|=>|=)\s*(.+)$',
        t,
        re.IGNORECASE,
    )
    if m3:
        trigger = m3.group(1).strip('"\' ')
        response = m3.group(2).strip('"\' ')
        if trigger and response:
            return ("qa", trigger, response)

    # Pattern 4: X bole to Y bolna
    m4 = re.search(
        r'^(?:koi\s+)?(.*?)\s+bole\s+to\s+(.+?)(?:\s+bolna|\s+kehna)?$',
        t,
        re.IGNORECASE,
    )
    if m4:
        trigger = m4.group(1).strip('"\' ')
        response = m4.group(2).strip('"\' ')
        if len(trigger) > 2 and len(response) > 1:
            return ("qa", trigger, response)

    # Pattern 5: General memory/behavior: yaad rakhna / remember / tum hamesha ...
    m5 = re.search(
        r'^(?:yaad\s+rakhna|remember|hamesha\s+yaad\s+rakhna|aaj\s+se\s+tum|tumhe\s+aise\s+baat\s+karni\s+hai)\s*[:,-]?\s*(.+)$',
        t,
        re.IGNORECASE,
    )
    if m5:
        instruction = m5.group(1).strip('"\' ')
        if instruction:
            return ("rule", "", instruction)

    return None


async def match_trained_rule_reply(text: str) -> str | None:
    clean = re.sub(r"[^\w\s]", " ", text.lower()).strip()
    if not clean:
        return None
    rules = await get_active_trainer_rules()
    for r in rules:
        if r.get("rule_type") == "qa":
            trig = re.sub(r"[^\w\s]", " ", (r.get("trigger_text") or "").lower()).strip()
            if not trig:
                continue
            if trig == clean or trig in clean or clean in trig:
                return str(r.get("response_text") or "")
    return None


async def format_trained_rules_for_prompt() -> str:
    rules = await get_active_trainer_rules()
    if not rules:
        return ""
    lines = [
        "MANDATORY ACTIVE AI TRAINER RULES (30-DAY RETENTION):",
        "The following instructions were taught by authorized AI trainers. You MUST follow them strictly:",
    ]
    for idx, r in enumerate(rules[:25], 1):
        if r.get("rule_type") == "qa" and r.get("trigger_text"):
            lines.append(f"{idx}. When anyone asks/says '{r['trigger_text']}', you MUST reply: '{r['response_text']}'")
        else:
            lines.append(f"{idx}. Rule: {r.get('raw_instruction') or r.get('response_text')}")
    return "\n".join(lines)


