async def try_claim_surprise_gift_by_code(message: Message, entered_code: str) -> bool:
    code_clean = entered_code.strip().upper()
    rows = await db.execute_fetchall("SELECT * FROM surprise_gifts WHERE UPPER(access_code) = ?", (code_clean,))
    if not rows:
        pending_gid = user_waiting_surprise_code.get(message.from_user.id)
        if pending_gid:
            await message.answer(
                "❌ <b>Invalid Access Code!</b>\n\n"
                "<blockquote>"
                "The code you entered does not match your surprise gift. "
                "Please check the Access Code shown in your group and send it again!"
                "</blockquote>"
            )
            return True
        return False

    row = rows[0]
    target_user_id = int(row["target_user_id"])
    if message.from_user.id != target_user_id:
        await message.answer(
            "❌ <b>Access Denied!</b>\n\n"
            "<blockquote>"
            "This Access Code belongs to another designated recipient. "
            "You do not have permission to unlock this gift! 🔒"
            "</blockquote>"
        )
        return True

    if row["is_claimed"]:
        await message.answer(
            "ℹ️ <b>Already Unlocked!</b>\n\n"
            "<blockquote>You have already unlocked this surprise gift earlier! Here is your gift again:</blockquote>"
        )
        row_dict = dict(row)
        await deliver_gift_media_dm(message.from_user.id, row_dict)
        return True

    now_str = datetime.now(timezone.utc).isoformat()
    await db.execute(
        "UPDATE surprise_gifts SET is_claimed = 1, claimed_by = ?, claimed_at = ? WHERE id = ?",
        (message.from_user.id, now_str, row["id"]),
    )
    await db.commit()

    # Convert row to dict for safe indexing and delivery
    row_dict = dict(row)
    row_dict["is_claimed"] = 1
    row_dict["claimed_by"] = message.from_user.id
    row_dict["claimed_at"] = now_str

    # Deliver gift exclusively to recipient in DM
    await deliver_gift_media_dm(message.from_user.id, row_dict)

    # Broadcast claimed update to target groups and REMOVE all inline buttons!
    try:
        chat_ids = json.loads(row_dict.get("target_chat_ids") or "[]")
    except Exception:
        chat_ids = []

    try:
        sent_msg_map = json.loads(row_dict.get("sent_message_ids") or "{}")
    except Exception:
        sent_msg_map = {}

    recipient_name = html.escape(message.from_user.full_name or message.from_user.first_name)
    recipient_link = f'<a href="tg://user?id={message.from_user.id}">{recipient_name}</a>'
    bot_username = (await bot.get_me()).username or "SeyukiBot"

    group_announcement = (
        f'<tg-emoji emoji-id="6044206019943338663">🎁</tg-emoji> <a href="https://t.me/{bot_username}"><b>˹Dᴇsᴛʀᴏʏᴇʀ ꭙ ᴍᴜsɪᴄ ᴀssɪsᴛᴀɴᴛ Surprise Gift Unlocked!</b></a> <tg-emoji emoji-id="4958489311726011319">✨</tg-emoji>\n\n'
        f"<blockquote>"
        f'<tg-emoji emoji-id="6046363553814810278">✅</tg-emoji> <b><a href="https://t.me/{bot_username}">Status</a> :</b> <i>Successfully Unlocked & Claimed!</i>\n'
        f'<tg-emoji emoji-id="6266995104687330978">👑</tg-emoji> <b><a href="https://t.me/{bot_username}">Recipient</a> :</b> {recipient_link}\n'
        f'<tg-emoji emoji-id="6267107057304868214">⚡️</tg-emoji> <b><a href="https://t.me/{bot_username}">Access Code</a> :</b> <code>{row_dict["access_code"]}</code>\n'
        f'<tg-emoji emoji-id="5440539497383087970">🛡️</tg-emoji> <b><a href="https://t.me/{bot_username}">Delivery</a> :</b> <i><a href="https://t.me/{bot_username}">Dispatched privately in DM (100% Confidential)</a></i>\n'
        f'<tg-emoji emoji-id="4958489311726011319">✨</tg-emoji> <i>The secret surprise was delivered securely to {recipient_link}!</i>'
        f"</blockquote>"
    )

    for cid in chat_ids:
        mid = sent_msg_map.get(str(cid))
        edited = False
        if mid:
            try:
                await bot.edit_message_text(
                    group_announcement,
                    chat_id=int(cid),
                    message_id=int(mid),
                    reply_markup=None,
                )
                edited = True
            except Exception as e:
                log.warning("Could not edit existing gift card in %s: %s", cid, e)
                try:
                    await bot.edit_message_reply_markup(
                        chat_id=int(cid),
                        message_id=int(mid),
                        reply_markup=None,
                    )
                    edited = True
                except Exception:
                    pass
        if not edited:
            try:
                await bot.send_message(cid, group_announcement, reply_markup=None)
            except Exception as e:
                log.warning("Could not send gift claimed announcement to chat %s: %s", cid, e)

    return True


async def deliver_surprise_gift_deep_link(message: Message, access_code: str) -> None:
    await try_claim_surprise_gift_by_code(message, access_code)


@router.callback_query(F.data.startswith("gift:"))
async def surprise_gift_claim_callback(callback: CallbackQuery) -> None:
    parts = (callback.data or "").split(":")
    if len(parts) != 3:
        await callback.answer("Invalid gift action.", show_alert=True)
        return
    _, action, raw_id = parts
    try:
        gift_id = int(raw_id)
    except ValueError:
        await callback.answer("Invalid gift ID.", show_alert=True)
        return

    rows = await db.execute_fetchall(
        "SELECT * FROM surprise_gifts WHERE id = ?", (gift_id,)
    )
    row = rows[0] if rows else None
    if not row:
        await callback.answer("❌ This surprise gift does not exist or has expired.", show_alert=True)
        return

    target_user_id = int(row["target_user_id"])
    access_code = str(row["access_code"])
    caller_id = callback.from_user.id
    caller_name = html.escape(callback.from_user.full_name or callback.from_user.first_name)

    if action == "info":
        if row["is_claimed"]:
            try:
                await callback.message.edit_reply_markup(reply_markup=None)
            except Exception:
                pass
            await callback.answer("✅ This gift has already been claimed and unlocked!", show_alert=True)
            return

        if caller_id == target_user_id:
            await callback.answer(
                f"✅ ACCESS GRANTED!\n\nThis confidential gift is reserved exclusively for YOU! 🎁\nClick 'Open Surprise' and enter Access Code: {access_code} in Private DM!",
                show_alert=True,
            )
        else:
            await callback.answer(
                "🔒 ACCESS DENIED!\n\nThis gift is strictly confidential and locked for the designated recipient only. You do not have permission to view it.",
                show_alert=True,
            )
        return

    if action == "open":
        if row["is_claimed"]:
            try:
                await callback.message.edit_reply_markup(reply_markup=None)
            except Exception:
                pass
            await callback.answer("❌ This surprise gift has already been claimed and unlocked!", show_alert=True)
            return

        if caller_id != target_user_id:
            await callback.answer(
                "❌ ACCESS DENIED!\n\nThis surprise gift is strictly locked for the designated recipient only. 🔒",
                show_alert=True,
            )
            return

        # It IS the designated recipient!
        user_waiting_surprise_code[caller_id] = gift_id

        # Proactively send prompt in DM if user has started bot
        try:
            await bot.send_message(
                caller_id,
                f'<tg-emoji emoji-id="6044206019943338663">🎁</tg-emoji> <a href="https://t.me/{bot_username}"><b>˹Dᴇsᴛʀᴏʏᴇʀ ꭙ ᴍᴜsɪᴄ ᴀssɪsᴛᴀɴᴛ Secret Gift Vault</b></a> <tg-emoji emoji-id="4958489311726011319">✨</tg-emoji>\n\n'
                f"<blockquote>"
                f'<tg-emoji emoji-id="6266995104687330978">👑</tg-emoji> <b>Welcome, {caller_name}!</b>\n'
                f'<tg-emoji emoji-id="5440539497383087970">🔒</tg-emoji> <i>A confidential surprise gift is locked and waiting for you!</i>\n\n'
                f'<tg-emoji emoji-id="6267107057304868214">⚡️</tg-emoji> <b><a href="https://t.me/{bot_username}">Please send your Access Code to unlock it</a>:</b>\n'
                f"👉 <i>Type or paste:</i> <code>{access_code}</code>"
                f"</blockquote>",
            )
        except Exception:
            pass

        unlock_dm_url = f"https://t.me/{bot_username}?start=unlock_{gift_id}"
        await callback.answer(
            f"✅ Access Verified!\n\nPlease open Private DM and enter your Access Code ({access_code}) to unlock your secret gift! 🎁",
            show_alert=True,
        )

        open_dm_kb = InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(
                text="Unlock in Private DM",
                url=unlock_dm_url,
                icon_custom_emoji_id="6266864696595323855",
                style="success",
            ),
            InlineKeyboardButton(
                text="Check Access",
                callback_data=f"gift:info:{gift_id}",
                icon_custom_emoji_id="6266781064992134926",
                style="primary",
            ),
        ]])
        try:
            await callback.message.edit_reply_markup(reply_markup=open_dm_kb)
        except Exception:
            pass
        return


