def admin_delivery_message_supported(message: Message) -> bool:
    return bool(message.text or message.caption or media_from_message(message))


def daily_zone_caption_kwargs(message: Message) -> dict[str, object]:
    caption = message.caption
    if caption is None:
        return {}
    return {
        "caption": caption,
        "caption_entities": message.caption_entities or [],
        "parse_mode": None,
    }


def daily_zone_today_key() -> str:
    return datetime.now(INDIA_TZ).date().isoformat()


def is_daily_zone_request(text: str | None) -> bool:
    value = (text or "").strip()
    if not value:
        return False
    username = re.escape(bot_username.lstrip("@"))
    command = rf"/m(?:@{username})?"
    mention = rf"(?:@?{username}|@?{re.escape(BOT_NAME)})"
    return bool(
        re.fullmatch(command, value, re.IGNORECASE)
        or re.fullmatch(rf"{mention}\s+{command}", value, re.IGNORECASE)
        or re.fullmatch(rf"{command}\s+{mention}", value, re.IGNORECASE)
    )


async def activate_daily_zone_cache(
    source_chat_id: int,
    source_message_id: int,
) -> None:
    global daily_zone_active_cache
    active_date = daily_zone_today_key()
    async with daily_zone_cache_lock:
        await db.execute(
            """
            INSERT INTO daily_zone_cache(
                id, active_date, source_chat_id, source_message_id
            ) VALUES(1, ?, ?, ?)
            ON CONFLICT(id) DO UPDATE SET
                active_date=excluded.active_date,
                source_chat_id=excluded.source_chat_id,
                source_message_id=excluded.source_message_id,
                created_at=CURRENT_TIMESTAMP
            """,
            (active_date, source_chat_id, source_message_id),
        )
        await db.commit()
        daily_zone_active_cache = (
            active_date,
            source_chat_id,
            source_message_id,
        )


async def get_daily_zone_cache() -> tuple[str, int, int] | None:
    global daily_zone_active_cache
    active_date = daily_zone_today_key()
    cached = daily_zone_active_cache
    if cached and cached[0] == active_date:
        return cached
    async with daily_zone_cache_lock:
        cached = daily_zone_active_cache
        if cached and cached[0] == active_date:
            return cached
        cursor = await db.execute(
            """
            SELECT active_date, source_chat_id, source_message_id
            FROM daily_zone_cache
            WHERE id=1
            """
        )
        row = await cursor.fetchone()
        await cursor.close()
        if not row or str(row["active_date"]) != active_date:
            if row:
                await db.execute("DELETE FROM daily_zone_cache WHERE id=1")
                await db.commit()
            daily_zone_active_cache = None
            return None
        daily_zone_active_cache = (
            str(row["active_date"]),
            int(row["source_chat_id"]),
            int(row["source_message_id"]),
        )
        return daily_zone_active_cache


async def clear_daily_zone_cache() -> None:
    global daily_zone_active_cache
    async with daily_zone_cache_lock:
        await db.execute("DELETE FROM daily_zone_cache WHERE id=1")
        await db.commit()
        daily_zone_active_cache = None


async def replay_daily_zone_for_group(message: Message) -> None:
    cached = await get_daily_zone_cache()
    if not cached:
        await message.reply(
            "Today's Daily Zone is not available yet. "
            "Please wait for the admin to post today's media."
        )
        return
    _, source_chat_id, source_message_id = cached
    try:
        await paced_copy_message(
            message.chat.id,
            source_chat_id,
            source_message_id,
        )
    except (TelegramBadRequest, TelegramForbiddenError):
        log.exception("Cached Daily Zone post is no longer available")
        await clear_daily_zone_cache()
        await message.reply(
            "Today's Daily Zone post is no longer available. "
            "Please wait for a new admin post."
        )
    except Exception:
        log.exception("Cached Daily Zone replay failed for group %s", message.chat.id)


def daily_zone_template_path() -> Path | None:
    configured = str(
        runtime_settings.get("daily_zone_template_path", str(DAILY_ZONE_TEMPLATE_PATH))
        or ""
    ).strip()
    if configured == "__disabled__":
        return None
    # An empty value can remain from the earlier template migration. Treat
    # that legacy state as the new bundled template; explicit deletion uses
    # the separate __disabled__ marker below.
    if not configured:
        configured = str(DAILY_ZONE_TEMPLATE_PATH)
    path = Path(configured)
    return path if path.is_file() else None


