def daily_zone_template_status() -> str:
    path = daily_zone_template_path()
    if not path:
        return "No template configured"
    try:
        with Image.open(path) as template:
            size = f"{template.width}×{template.height}"
    except (OSError, ValueError):
        size = "size unavailable"
    return f"Active: <code>{html.escape(path.name)}</code> ({size})"


def daily_zone_template_geometry(
    template_size: tuple[int, int],
) -> tuple[tuple[int, int], tuple[int, int, int, int]]:
    template_width, template_height = template_size
    canvas_size = (
        max(2, template_width - template_width % 2),
        max(2, template_height - template_height % 2),
    )
    # The active portrait template has one tall black media window. Keep
    # these proportions for replacements so landscape, portrait, and reel
    # videos all fit inside the same window without changing the template.
    left = int(round(canvas_size[0] * 0.056))
    top = int(round(canvas_size[1] * 0.250))
    width = max(2, int(round(canvas_size[0] * 0.888)))
    height = max(2, int(round(canvas_size[1] * 0.660)))
    width -= width % 2
    height -= height % 2
    return canvas_size, (left, top, width, height)


def daily_zone_round_mask(size: tuple[int, int]) -> Image.Image:
    width, height = size
    radius = max(12, min(width, height) // 28)
    mask = Image.new("L", size, 0)
    ImageDraw.Draw(mask).rounded_rectangle(
        (0, 0, width - 1, height - 1),
        radius=radius,
        fill=255,
    )
    return mask


def daily_zone_layout() -> tuple[Path | None, tuple[int, int], tuple[int, int, int, int]]:
    template_path = daily_zone_template_path()
    if template_path:
        with Image.open(template_path) as template:
            canvas_size, content_box = daily_zone_template_geometry(template.size)
        return template_path, canvas_size, content_box
    return None, (1024, 1024), (0, 0, 1024, 1024)


def render_daily_zone_photo(source_bytes: bytes) -> bytes:
    with Image.open(io.BytesIO(source_bytes)) as source_image:
        source = source_image.convert("RGBA")
    template_path, canvas_size, content_box = daily_zone_layout()
    if template_path:
        with Image.open(template_path) as template_image:
            template = template_image.convert("RGBA").resize(
                canvas_size,
                Image.Resampling.LANCZOS,
            )
    else:
        canvas_size = (
            max(2, source.width - source.width % 2),
            max(2, source.height - source.height % 2),
        )
        content_box = (0, 0, canvas_size[0], canvas_size[1])
        template = Image.new("RGBA", canvas_size, (0, 0, 0, 255))
    left, top, width, height = content_box
    source.thumbnail((max(2, width), max(2, height)), Image.Resampling.LANCZOS)
    x = left + (width - source.width) // 2
    y = top + (height - source.height) // 2
    template.paste(source, (x, y), daily_zone_round_mask(source.size))
    output = io.BytesIO()
    template.convert("RGB").save(output, format="JPEG", quality=92, optimize=True)
    return output.getvalue()


def daily_zone_video_dimensions(source_path: Path) -> tuple[int, int]:
    result = subprocess.run(
        [
            "ffprobe",
            "-v",
            "error",
            "-select_streams",
            "v:0",
            "-show_entries",
            "stream=width,height",
            "-of",
            "csv=p=0:s=x",
            str(source_path),
        ],
        check=True,
        capture_output=True,
        text=True,
        timeout=30,
    )
    width, height = result.stdout.strip().split("x", 1)
    return int(width), int(height)


def daily_zone_video_template(
    source_path: Path,
) -> tuple[Path, Path, Path, tuple[int, int, int, int]]:
    template_source, canvas_size, content_box = daily_zone_layout()
    template_handle, template_name = tempfile.mkstemp(
        prefix="seyuki-daily-zone-template-",
        suffix=".png",
    )
    os.close(template_handle)
    template_path = Path(template_name)
    if template_source:
        with Image.open(template_source) as base_image:
            base_image.convert("RGBA").resize(
                canvas_size,
                Image.Resampling.LANCZOS,
            ).save(template_path, format="PNG")
    else:
        Image.new("RGBA", canvas_size, (0, 0, 0, 255)).save(
            template_path,
            format="PNG",
        )
    mask_handle, mask_name = tempfile.mkstemp(
        prefix="seyuki-daily-zone-mask-",
        suffix=".png",
    )
    os.close(mask_handle)
    mask_path = Path(mask_name)
    daily_zone_round_mask((content_box[2], content_box[3])).save(
        mask_path,
        format="PNG",
    )
    return template_path, mask_path, source_path, content_box


def render_daily_zone_video(source_path: Path, output_path: Path) -> None:
    try:
        daily_zone_video_dimensions(source_path)
    except (OSError, subprocess.SubprocessError, ValueError):
        pass
    template_path, mask_path, _, content_box = daily_zone_video_template(source_path)
    left, top, content_width, content_height = content_box
    try:
        command = [
            "ffmpeg",
            "-hide_banner",
            "-loglevel",
            "error",
            "-y",
            "-i",
            str(source_path),
            "-loop",
            "1",
            "-i",
            str(template_path),
            "-loop",
            "1",
            "-i",
            str(mask_path),
            "-filter_complex",
            (
                f"[0:v]scale={content_width}:{content_height}:"
                "force_original_aspect_ratio=decrease,"
                f"pad={content_width}:{content_height}:(ow-iw)/2:(oh-ih)/2:"
                "color=black,setsar=1,format=rgba[content];"
                "[2:v]format=gray[mask];"
                "[content][mask]alphamerge[rounded];"
                f"[1:v]format=rgba[frame];"
                f"[frame][rounded]overlay={left}:{top}:shortest=1[v]"
            ),
            "-map",
            "[v]",
            "-map",
            "0:a?",
            "-c:v",
            "libx264",
            "-preset",
            "veryfast",
            "-crf",
            "23",
            "-pix_fmt",
            "yuv420p",
            "-c:a",
            "aac",
            "-b:a",
            "128k",
            "-shortest",
            "-movflags",
            "+faststart",
            str(output_path),
        ]
        subprocess.run(command, check=True, timeout=300)
    finally:
        template_path.unlink(missing_ok=True)
        mask_path.unlink(missing_ok=True)


async def prepare_daily_zone_source(
    message: Message,
) -> tuple[int, int, list[Path]]:
    media_type = media_from_message(message)
    if not media_type or media_type[0] not in {"photo", "video"}:
        return message.chat.id, message.message_id, []
    media_kind, file_id = media_type
    telegram_file = await bot.get_file(file_id)
    cleanup_paths: list[Path] = []
    if media_kind == "photo":
        source_buffer = io.BytesIO()
        await bot.download_file(telegram_file.file_path, source_buffer)
        rendered = await asyncio.to_thread(
            render_daily_zone_photo,
            source_buffer.getvalue(),
        )
        staged = await bot.send_photo(
            message.chat.id,
            BufferedInputFile(rendered, filename="seyuki-daily-zone.jpg"),
            reply_markup=daily_zone_draft_markup(),
            **daily_zone_caption_kwargs(message),
        )
        return message.chat.id, staged.message_id, cleanup_paths

    source_handle, source_name = tempfile.mkstemp(
        prefix="seyuki-daily-zone-source-",
        suffix=".mp4",
    )
    os.close(source_handle)
    source_path = Path(source_name)
    output_path = source_path.with_name(f"{source_path.stem}-framed.mp4")
    cleanup_paths.extend([source_path, output_path])
    with source_path.open("wb") as source_file:
        await bot.download_file(telegram_file.file_path, source_file)
    await asyncio.to_thread(render_daily_zone_video, source_path, output_path)
    staged = await bot.send_video(
        message.chat.id,
        FSInputFile(str(output_path)),
        supports_streaming=True,
        reply_markup=daily_zone_draft_markup(),
        **daily_zone_caption_kwargs(message),
    )
    return message.chat.id, staged.message_id, cleanup_paths


