async def broadcast_one(user_id: int, text: str) -> bool:
    global last_broadcast_send
    async with broadcast_gate:
        async with broadcast_lock:
            delay = (1 / BROADCAST_RATE) - (time.monotonic() - last_broadcast_send)
            if delay > 0:
                await asyncio.sleep(delay)
            last_broadcast_send = time.monotonic()
        for attempt in range(4):
            try:
                await bot.send_message(user_id, text)
                return True
            except TelegramRetryAfter as error:
                await asyncio.sleep(error.retry_after + 0.2)
            except (TelegramForbiddenError, TelegramBadRequest):
                await db.execute("UPDATE users SET blocked=1 WHERE user_id=?", (user_id,))
                await db.commit()
                if str(user_id) in users_json:
                    users_json[str(user_id)]["blocked"] = True
                    await save_users_json()
                return False
            except Exception:
                if attempt == 3:
                    return False
                await asyncio.sleep(0.5 * (attempt + 1))
    return False


async def broadcast(text: str) -> None:
    cursor = await db.execute("SELECT user_id FROM users WHERE blocked=0")
    user_ids = [int(row["user_id"]) for row in await cursor.fetchall()]
    for start_at in range(0, len(user_ids), 500):
        await asyncio.gather(*(broadcast_one(uid, text) for uid in user_ids[start_at : start_at + 500]))
        await asyncio.sleep(0.2)
    log.info("Broadcast completed for %s users", len(user_ids))


@router.message(Command("broadcast"))
async def broadcast_command(message: Message) -> None:
    if (
        not message.from_user
        or message.from_user.id not in ADMIN_IDS
        or message.chat.type != ChatType.PRIVATE
        or message.chat.id != message.from_user.id
    ):
        return
    text = (message.text or "").partition(" ")[2].strip()
    if not text:
        await message.answer("Use the Broadcast button or: /broadcast message")
        return
    await message.answer("Broadcast queued.")
    asyncio.create_task(broadcast(text))


async def execute_custom_media_command(
    message: Message,
    command_name: str,
    media: dict[str, str],
    args: list[str],
) -> None:
    target_id = await resolve_group_target(message, args)
    if not target_id:
        await message.reply(
            f"Reply to a user, tag them, or provide their numeric ID: "
            f"/{html.escape(command_name)} @username"
        )
        return
    target_user = None
    if (
        message.reply_to_message
        and message.reply_to_message.from_user
        and message.reply_to_message.from_user.id == target_id
    ):
        target_user = message.reply_to_message.from_user
    if target_user is None:
        try:
            target_user = (await bot.get_chat_member(message.chat.id, target_id)).user
        except TelegramBadRequest:
            try:
                target_user = await bot.get_chat(target_id)
            except TelegramBadRequest:
                target_user = None
    if target_user is None or not hasattr(target_user, "mention_html"):
        await message.reply("I couldn't load that user. Reply to their message or use a valid group member ID.")
        return
    sent = await send_custom_command_media(
        message, command_name, media, message.from_user, target_user
    )
    if sent:
        await group_log(
            message.chat.id,
            message.from_user.id,
            "custom_command",
            target_id,
            f"/{command_name}",
        )


def parse_duration(value: str, default_minutes: int = 60) -> int | None:
    if not value:
        return default_minutes
    match = re.fullmatch(r"(\d+)([mhd]?)", value.casefold())
    if not match:
        return None
    amount = int(match.group(1))
    multiplier = {"": 1, "m": 1, "h": 60, "d": 1440}[match.group(2)]
    minutes = amount * multiplier
    return minutes if 1 <= minutes <= 60 * 24 * 30 else None


@router.message(Command("afky"))
async def afky_command(message: Message) -> None:
    if message.chat.type not in {ChatType.GROUP, ChatType.SUPERGROUP}:
        await message.answer("Use /afky in a group chat to mark yourself as offline.")
        return
    if not message.from_user or message.from_user.is_bot:
        return
    await mark_group_afk(message)


@router.message(F.chat.type.in_({ChatType.GROUP, ChatType.SUPERGROUP}), F.text.startswith("/"))
async def group_management_command(message: Message) -> None:
    if not message.from_user or message.from_user.is_bot:
        return
    # Daily Zone replay must run before generic command locks and supported
    # command routing, otherwise an unlisted /m command is consumed here.
    if is_daily_zone_request(message.text):
        await remember_group(message)
        await remember_user(message)
        await replay_daily_zone_for_group(message)
        return
    command_settings = await get_group_features(message.chat.id)
    if (
        command_settings["commands_locked"]
        and not await group_admin(message.chat.id, message.from_user.id)
    ):
        if await bot_can(message.chat.id, "can_delete_messages"):
            try:
                await message.delete()
            except TelegramBadRequest:
                pass
        return
    raw = message.text or ""
    command, _, remainder = raw.partition(" ")
    name = command.split("@", 1)[0].casefold()
    if name == "/codebreaker":
        raise SkipHandler
    supported = {
        "/ban", "/dban", "/unban", "/kick", "/mute", "/dmute", "/unmute",
        "/tempban", "/promote", "/demote", "/adminlist", "/warn", "/dwarn", "/removewarn",
        "/lock", "/unlock",
        "/pin", "/unpin",
        "/info",
        "/report", "/filter", "/filters", "/rmfilter", "/removefilter",
        "/addblaclist", "/addblacklist", "/rmblacklist", "/blacklists",
    }
    if name not in supported:
        custom_commands = parse_custom_commands(
            runtime_settings.get("global_custom_commands", "{}")
        )
        custom_command_name = name.removeprefix("/")
        if custom_command_name in custom_commands:
            await execute_custom_media_command(
                message,
                custom_command_name,
                custom_commands[custom_command_name],
                remainder.split(),
            )
        return
    action = name.removeprefix("/")
    args = remainder.split()
    if action == "info":
        await send_group_user_info(message, args)
        return
    if action == "report":
        await report_group_message(message)
        return
    required = (
        "can_delete_messages"
        if action == "dwarn"
        else "can_restrict_members"
        if action in {"ban", "dban", "kick", "mute", "dmute", "unmute", "tempban", "warn", "removewarn"}
        else "can_pin_messages"
        if action in {"pin", "unpin"}
        else "can_delete_messages"
        if action in {"lock", "unlock"} and args
        else "can_promote_members"
    )
    target_actions = {
        "ban", "dban", "unban", "kick", "mute", "dmute", "unmute",
        "tempban", "promote", "demote", "warn", "dwarn",
        "removewarn", "clearwarns", "resetwarns", "admininfo", "warns",
    }
    fast_target_id: int | None = None
    if action in target_actions:
        if message.reply_to_message and message.reply_to_message.from_user:
            fast_target_id = message.reply_to_message.from_user.id
        elif args and args[0].lstrip("-").isdigit():
            fast_target_id = int(args[0])
        elif args and args[0].startswith("@"):
            u_clean = args[0].lstrip("@").strip().casefold()
            fast_target_id = group_username_to_user_id.get((message.chat.id, u_clean)) or username_to_user_id.get(u_clean)
    target_member_task = (
        asyncio.create_task(
            bot.get_chat_member(message.chat.id, fast_target_id)
        )
        if fast_target_id is not None
        else None
    )
    # These checks are independent network calls. Run them together so a
    # moderation command does not pay multiple Telegram round trips in sequence.
    admin_task = asyncio.create_task(group_admin(message.chat.id, message.from_user.id))
    bot_permission_task = (
        asyncio.create_task(bot_can(message.chat.id, required))
        if action not in {
            "adminlist", "report", "filter", "filters", "rmfilter", "removefilter",
            "addblaclist", "addblacklist", "rmblacklist", "blacklists",
        }
        else None
    )
    if bot_permission_task is None:
        is_admin = await admin_task
        bot_allowed = True
    else:
        is_admin, bot_allowed = await asyncio.gather(admin_task, bot_permission_task)
    if not is_admin:
        if target_member_task is not None:
            target_member_task.cancel()
            await asyncio.gather(target_member_task, return_exceptions=True)
        await message.reply("Only group admins can use this command.")
        return
    if not bot_allowed:
        if target_member_task is not None:
            target_member_task.cancel()
            await asyncio.gather(target_member_task, return_exceptions=True)
        await message.reply(f"I need {required} permission for this command.")
        return
    if action in {"filter", "filters", "rmfilter", "removefilter"}:
        if action == "filters":
            filters = parse_group_filters((await get_group_features(message.chat.id))["filters"])
            if not filters:
                await message.reply("No filters are configured in this group.")
            else:
                lines = [f"• <code>{html.escape(trigger)}</code> → {html.escape(response[:200])}"
                         for trigger, response in sorted(filters.items())]
                await message.reply("<b>Active filters</b>\n" + "\n".join(lines))
            return
        trigger = " ".join(args).strip().casefold()
        if not trigger or len(trigger) > 100:
            await message.reply(f"Usage: /{action} word")
            return
        if action in {"rmfilter", "removefilter"}:
            settings = await get_group_features(message.chat.id)
            filters = parse_group_filters(settings["filters"])
            if trigger not in filters:
                await message.reply(f"No filter found for <code>{html.escape(trigger)}</code>.")
                return
            filters.pop(trigger)
            await update_group_feature(message.chat.id, "filters", json.dumps(filters, ensure_ascii=False))
            await group_log(message.chat.id, message.from_user.id, "remove_filter", details=trigger)
            await message.reply(f"Filter removed for <code>{html.escape(trigger)}</code>.")
            return
        source = message.reply_to_message
        response = (source.text or source.caption or "").strip() if source else ""
        if not source or not response:
            await message.reply("Reply to a text message with /filter word.")
            return
        settings = await get_group_features(message.chat.id)
        filters = parse_group_filters(settings["filters"])
        filters[trigger] = response[:2000]
        await update_group_feature(message.chat.id, "filters", json.dumps(filters, ensure_ascii=False))
        await group_log(message.chat.id, message.from_user.id, "set_filter", details=trigger)
        await message.reply(
            f"Filter set: <code>{html.escape(trigger)}</code> → {html.escape(response[:200])}"
        )
        return
    if action in {"addblaclist", "addblacklist", "rmblacklist", "blacklists"}:
        settings = await get_group_features(message.chat.id)
        try:
            blacklist = [
                str(word).casefold().strip()
                for word in json.loads(str(settings["blacklist_words"] or "[]"))
                if str(word).strip()
            ]
        except json.JSONDecodeError:
            blacklist = []
        if action == "blacklists":
            if not blacklist:
                await message.reply("Blacklist is empty.")
            else:
                words = "\n".join(
                    f"• <code>{html.escape(word)}</code>"
                    for word in sorted(set(blacklist))
                )
                await message.reply("<b>Blacklisted words</b>\n" + words)
            return
        word = " ".join(args).strip().casefold()
        if not word or len(word) > 100:
            await message.reply(f"Usage: /{action} word")
            return
        if action in {"addblaclist", "addblacklist"}:
            if word in blacklist:
                await message.reply(f"<code>{html.escape(word)}</code> is already blacklisted.")
                return
            blacklist.append(word)
            await update_group_feature(
                message.chat.id, "blacklist_words",
                json.dumps(sorted(set(blacklist)), ensure_ascii=False),
            )
            await group_log(message.chat.id, message.from_user.id, "add_blacklist", details=word)
            await message.reply(f"<code>{html.escape(word)}</code> added to blacklist.")
            return
        if word not in blacklist:
            await message.reply(f"<code>{html.escape(word)}</code> is not in the blacklist.")
            return
        blacklist.remove(word)
        await update_group_feature(
            message.chat.id, "blacklist_words",
            json.dumps(blacklist, ensure_ascii=False),
        )
        await group_log(message.chat.id, message.from_user.id, "remove_blacklist", details=word)
        await message.reply(f"<code>{html.escape(word)}</code> removed from blacklist.")
        return
    target_id = fast_target_id or await resolve_group_target(message, args)
    if target_id and args and not message.reply_to_message and (
        args[0].lstrip("-").isdigit() or args[0].startswith("@")
    ):
        args = args[1:]
    if action in {"adminlist", "adminlog"}:
        if action == "adminlist":
            admins = await bot.get_chat_administrators(message.chat.id)
            owner = next((admin for admin in admins if admin.status == "creator"), None)
            regular_admins = [admin for admin in admins if admin.status != "creator"]

            def admin_label(admin) -> str:
                label = html.escape(admin.user.full_name)
                if admin.user.username:
                    label += f" (@{html.escape(admin.user.username)})"
                return f"• {label}"

            owner_text = admin_label(owner) if owner else "• Not available"
            admins_text = (
                "\n".join(admin_label(admin) for admin in regular_admins)
                if regular_admins
                else "• No other admins"
            )
            text = (
                "<b>Owner</b>\n"
                f"{owner_text}\n\n"
                "<b>Admins</b>\n"
                f"{admins_text}"
            )
        else:
            cursor = await db.execute(
                """SELECT actor_id, action, target_id, details, created_at
                FROM group_admin_logs WHERE chat_id=? ORDER BY id DESC LIMIT 20""",
                (message.chat.id,),
            )
            rows = await cursor.fetchall()
            text = "<b>Recent Admin Log</b>\n\n" + (
                "\n".join(
                    f"• <code>{row['actor_id']}</code> {html.escape(row['action'])}"
                    + (f" → <code>{row['target_id']}</code>" if row["target_id"] else "")
                    + (f" ({html.escape(row['details'])})" if row["details"] else "")
                    for row in rows
                ) or "No admin actions recorded yet."
            )
        await message.reply(text)
        return
    if action in {"lock", "unlock"}:
        lock_name = args[0].casefold() if args else ""
        lock_fields = {
            "botlink": "botlink_locked",
            "botlinks": "botlink_locked",
            "bot_link": "botlink_locked",
            "forwarding": "forwarding_locked",
            "forward": "forwarding_locked",
            "report": "report_enabled",
            "filters": "filters_enabled",
            "url": "url_locked",
            "mention": "mention_locked",
            "commands": "commands_locked",
            "command": "commands_locked",
        }
        if lock_name in lock_fields:
            field = lock_fields[lock_name]
            enabled = action == "lock"
            settings = await get_group_features(message.chat.id)
            if bool(settings[field]) == enabled:
                state = "already ON" if enabled else "already OFF"
                await message.reply(
                    f"{message.from_user.mention_html()}, "
                    f"{lock_name.title()} lock is {state}."
                )
                return
            await update_group_feature(message.chat.id, field, int(enabled))
            await group_log(
                message.chat.id, message.from_user.id,
                f"lock_{'on' if enabled else 'off'}", details=lock_name,
            )
            await message.reply(
                f"{message.from_user.mention_html()}, "
                f"{lock_name.title()} lock {'enabled' if enabled else 'disabled'}."
            )
            return
        if args:
            await message.reply(
                "Use /lock botlink, /unlock botlink, /lock forwarding, "
                "/lock commands, or /unlock commands."
            )
            return
        if not await bot_can(message.chat.id, "can_restrict_members"):
            await message.reply("I need permission to restrict members before I can change the group lock.")
            return
        locked = action == "lock"
        await bot.set_chat_permissions(
            message.chat.id,
            permissions=ChatPermissions(can_send_messages=not locked),
        )
        await db.execute(
            "INSERT INTO group_settings(chat_id, locked) VALUES(?,?) "
            "ON CONFLICT(chat_id) DO UPDATE SET locked=excluded.locked",
            (message.chat.id, int(locked)),
        )
        await db.commit()
        await group_log(message.chat.id, message.from_user.id, action)
        await message.reply(f"Group messages are now {'locked' if locked else 'unlocked'}.")
        return
    if action == "purge":
        if not await bot_can(message.chat.id, "can_delete_messages"):
            await message.reply("I need permission to delete messages for /purge.")
            return
        count = int(args[0]) if args and args[0].isdigit() else 0
        if not 1 <= count <= 100:
            await message.reply("Usage: /purge <count> — choose a number from 1 to 100.")
            return
        for message_id in range(message.message_id, max(0, message.message_id - count - 1), -1):
            try:
                await bot.delete_message(message.chat.id, message_id)
            except TelegramBadRequest:
                pass
        await group_log(message.chat.id, message.from_user.id, action, details=str(count))
        return
    if action == "del":
        if not await bot_can(message.chat.id, "can_delete_messages"):
            await message.reply("I need permission to delete messages for /del.")
            return
        if not message.reply_to_message:
            await message.reply("Reply to a message with /del.")
            return
        try:
            await bot.delete_message(message.chat.id, message.reply_to_message.message_id)
            await bot.delete_message(message.chat.id, message.message_id)
        except TelegramBadRequest:
            pass
        await group_log(message.chat.id, message.from_user.id, action)
        return
    if action == "pin":
        if not message.reply_to_message:
            await message.reply("Reply to a post or message with /pin.")
            return
        try:
            await bot.pin_chat_message(
                message.chat.id,
                message.reply_to_message.message_id,
                disable_notification=True,
            )
        except TelegramBadRequest:
            await message.reply("I could not pin that message. Check my pin permissions.")
            return
        await group_log(message.chat.id, message.from_user.id, action)
        await message.reply("Message pinned.")
        return
    if action == "unpin":
        if not await bot_can(message.chat.id, "can_pin_messages"):
            await message.reply("I need permission to manage pinned messages.")
            return
        if not message.reply_to_message:
            await message.reply("Reply to the pinned message with /unpin.")
            return
        await bot.unpin_chat_message(message.chat.id, message.reply_to_message.message_id)
        await group_log(message.chat.id, message.from_user.id, action)
        await message.reply("Message unpinned.")
        return
    if action in {"admininfo", "warns"}:
        if not target_id:
            await message.reply(f"Reply to a user or provide their numeric ID: /{action} user")
            return
        if target_member_task is not None and target_id == fast_target_id:
            member = await target_member_task
        else:
            member = await bot.get_chat_member(message.chat.id, target_id)
        if action == "admininfo":
            await message.reply(
                f"<b>Admin Info</b>\nUser: {html.escape(member.user.full_name)}\n"
                f"ID: <code>{target_id}</code>\nStatus: {html.escape(member.status)}"
            )
        else:
            cursor = await db.execute(
                "SELECT count, last_reason FROM group_warnings WHERE chat_id=? AND user_id=?",
                (message.chat.id, target_id),
            )
            row = await cursor.fetchone()
            await message.reply(
                f"{html.escape(member.user.full_name)} has {row['count'] if row else 0} warning(s)."
            )
        return
    if action in {"warn", "removewarn", "clearwarns", "resetwarns"}:
        if not target_id:
            await message.reply("Reply to a user or provide their numeric ID.")
            return
        if target_member_task is not None and target_id == fast_target_id:
            warning_target = await target_member_task
        else:
            warning_target = await bot.get_chat_member(message.chat.id, target_id)
        if warning_target.status in {"administrator", "creator"}:
            await message.reply(
                "<b>Admins and the group owner cannot be warned or have warnings changed.</b>"
            )
            return
        reason = " ".join(args)[:300]
        if action == "warn":
            target_member = warning_target
            if target_member.status == "creator":
                await message.reply("<b>You don't have permission to warn the group owner.</b>")
                return
            settings = await get_group_features(message.chat.id)
            await issue_warning(
                message.chat.id,
                target_id,
                target_member.user.mention_html(),
                int(settings["spam_warn_limit"]),
                reason or "manual_warning",
            )
        elif action == "removewarn":
            cursor = await db.execute(
                "SELECT count FROM group_warnings WHERE chat_id=? AND user_id=?",
                (message.chat.id, target_id),
            )
            row = await cursor.fetchone()
            current_count = int(row["count"]) if row else 0
            if current_count <= 0:
                await message.reply("<b>This user has no warnings.</b>")
                return
            if current_count == 1:
                await db.execute(
                    "DELETE FROM group_warnings WHERE chat_id=? AND user_id=?",
                    (message.chat.id, target_id),
                )
                new_count = 0
            else:
                await db.execute(
                    "UPDATE group_warnings SET count=count-1, updated_at=CURRENT_TIMESTAMP "
                    "WHERE chat_id=? AND user_id=?",
                    (message.chat.id, target_id),
                )
                new_count = current_count - 1
            await db.commit()
            target_member = warning_target
            await message.reply(
                f"<b>One warning removed from {target_member.user.mention_html()}.</b>\n"
                f"Current warnings: <b>{new_count}</b>"
            )
        else:
            await db.execute(
                "DELETE FROM group_warnings WHERE chat_id=? AND user_id=?",
                (message.chat.id, target_id),
            )
            await message.reply("Warnings cleared.")
        await db.commit()
        await group_log(message.chat.id, message.from_user.id, action, target_id, reason)
        return
    if action == "dwarn":
        if not target_id:
            await message.reply(
                "Reply to the user's message or tag them with /dwarn @username [reason]."
            )
            return
        if target_member_task is not None and target_id == fast_target_id:
            warning_target = await target_member_task
        else:
            warning_target = await bot.get_chat_member(message.chat.id, target_id)
        if warning_target.status in {"administrator", "creator"}:
            await message.reply("<b>Admins and owners can't be warned.</b>")
            return
        if not await bot_can(message.chat.id, "can_delete_messages"):
            await message.reply("I also need permission to delete messages for /dwarn.")
            return

        settings = await get_group_features(message.chat.id)
        reason = " ".join(args)[:300]
        await issue_warning(
            message.chat.id,
            target_id,
            warning_target.user.mention_html(),
            int(settings["spam_warn_limit"]),
            reason or "manual_delete_warning",
        )
        # 1. If replied to a message, delete that replied message
        if message.reply_to_message:
            try:
                await bot.delete_message(message.chat.id, message.reply_to_message.message_id)
            except TelegramBadRequest:
                pass
        # 2. If command was used with a tag or ID without reply, delete user's last known message
        elif target_id:
            last_mid = last_user_message_id.get((message.chat.id, target_id))
            if last_mid:
                try:
                    await bot.delete_message(message.chat.id, last_mid)
                except TelegramBadRequest:
                    pass

        # 3. Always delete the admin's command message (/dwarn)
        try:
            await bot.delete_message(message.chat.id, message.message_id)
        except TelegramBadRequest:
            pass
        await group_log(message.chat.id, message.from_user.id, "dwarn", target_id, reason)
        return
    if action in {
        "ban", "dban", "unban", "kick", "mute", "dmute", "unmute",
        "tempban", "promote", "demote",
    }:
        if not target_id:
            await message.reply(
                f"That username could not be resolved. Reply to the user's message, "
                f"select the Telegram mention, or provide a numeric ID: /{action} user"
            )
            return
        if target_id == message.from_user.id or target_id == bot.id:
            await message.reply("That target cannot be managed.")
            return
        if target_member_task is not None and target_id == fast_target_id:
            current_member = await target_member_task
        else:
            current_member = await bot.get_chat_member(message.chat.id, target_id)
        target_name = format_target_name(current_member)
        was_muted = member_is_muted(current_member)
        if current_member.status == "creator":
            await message.reply(
                "<b>You don't have permission to use this command on the group owner.</b>"
            )
            return
        protected_actions = {
            "ban", "dban", "kick", "mute", "dmute", "unmute", "tempban",
        }
        if action in protected_actions and current_member.status == "administrator":
            await message.reply(
                "<b>Admins cannot be banned, kicked, muted, or unmuted.</b>"
            )
            return
        if (
            action in {"ban", "dban", "tempban"}
            and current_member.status == "kicked"
        ):
            await message.reply(f"<b>{target_name} is already banned.</b>")
            return
        if action in {"dban", "dmute"}:
            if not await bot_can(message.chat.id, "can_delete_messages"):
                await message.reply("I also need permission to delete messages for this command.")
                return
            # 1. If command is a reply to a message, delete that replied message
            if message.reply_to_message:
                try:
                    await bot.delete_message(message.chat.id, message.reply_to_message.message_id)
                except TelegramBadRequest:
                    pass
            # 2. If command was used with a tag or ID without reply, delete user's last known message
            elif target_id:
                last_mid = last_user_message_id.get((message.chat.id, target_id))
                if last_mid:
                    try:
                        await bot.delete_message(message.chat.id, last_mid)
                    except TelegramBadRequest:
                        pass
            # 3. Always delete the admin's command message (/dban, /dmute)
            try:
                await bot.delete_message(message.chat.id, message.message_id)
            except TelegramBadRequest:
                pass
        if action == "promote" and current_member.status in {"administrator", "creator"}:
            await message.reply(f"<b>{target_name} is already promoted.</b>")
            return
        if action == "demote":
            if current_member.status == "creator":
                await message.reply(f"<b>{target_name} is the group owner and cannot be demoted.</b>")
                return
            if current_member.status != "administrator":
                await message.reply(f"<b>{target_name} is already demoted.</b>")
                return
            caller_member = await bot.get_chat_member(message.chat.id, message.from_user.id)
            if caller_member.status != "creator":
                cursor = await db.execute(
                    """SELECT actor_id FROM group_admin_logs
                    WHERE chat_id=? AND action='promote' AND target_id=?
                    ORDER BY id DESC LIMIT 1""",
                    (message.chat.id, target_id),
                )
                promotion = await cursor.fetchone()
                if not promotion or int(promotion["actor_id"]) != message.from_user.id:
                    await message.reply(
                        "<b>You don't have permission to demote this admin.</b>\n"
                        "Only the group owner or the admin who promoted them can demote them."
                    )
                    return
        if action == "unban":
            if current_member.status != "kicked":
                await message.reply(f"<b>{target_name} is not banned.</b>")
                return
            await bot.unban_chat_member(message.chat.id, target_id, only_if_banned=True)
            result_text = f"<b>Unbanned: {target_name}</b>"
        elif action in {"ban", "dban", "tempban"}:
            minutes = parse_duration(args[0] if action == "tempban" and args else "", 60)
            if action == "tempban" and minutes is None:
                await message.reply("Usage: /tempban <user> <minutes>")
                return
            await bot.ban_chat_member(
                message.chat.id, target_id,
                until_date=(datetime.now(timezone.utc) + timedelta(minutes=minutes))
                if action == "tempban" else None,
            )
            if action == "tempban":
                result_text = f"<b>Temporarily banned: {target_name}</b>"
            elif action == "dban":
                result_text = f"<b>Banned: {target_name} (Message deleted)</b>"
            else:
                result_text = f"<b>Banned: {target_name}</b>"
        elif action == "kick":
            await bot.ban_chat_member(message.chat.id, target_id)
            await bot.unban_chat_member(message.chat.id, target_id, only_if_banned=True)
            result_text = f"<b>Kicked: {target_name}</b>"
        elif action in {"mute", "dmute", "unmute"}:
            if action == "unmute" and not was_muted:
                await message.reply(f"<b>{target_name} is already unmuted.</b>")
                return
            if action in {"mute", "dmute"} and was_muted:
                await message.reply(
                    f"<b>{target_name} is already muted for "
                    f"{remaining_mute_duration(current_member)}.</b>"
                )
                return
            minutes = parse_duration(args[0] if action in {"mute", "dmute"} and args else "", 60)
            if action == "unmute":
                # Restore all normal member permissions. Setting only
                # can_send_messages leaves old media/sticker/poll restrictions
                # behind as a Telegram "exception".
                permissions = ChatPermissions(
                    can_send_messages=True,
                    can_send_audios=True,
                    can_send_documents=True,
                    can_send_photos=True,
                    can_send_videos=True,
                    can_send_video_notes=True,
                    can_send_voice_notes=True,
                    can_send_polls=True,
                    can_send_other_messages=True,
                    can_add_web_page_previews=True,
                    can_react_to_messages=True,
                    can_edit_tag=True,
                    can_change_info=False,
                    can_invite_users=True,
                    can_pin_messages=False,
                    can_manage_topics=False,
                )
            else:
                permissions = ChatPermissions(can_send_messages=False)
            await bot.restrict_chat_member(
                message.chat.id, target_id,
                permissions=permissions,
                until_date=(datetime.now(timezone.utc) + timedelta(minutes=minutes))
                if action in {"mute", "dmute"} and minutes else None,
            )
            if action == "unmute":
                # Bot API has already restored the member permissions. The
                # MTProto cleanup removes any stale exception without holding
                # up the visible moderation response.
                asyncio.create_task(
                    clear_telegram_restriction(message.chat.id, target_id)
                )
            if action == "unmute":
                result_text = f"<b>Unmuted: {target_name}</b>"
            elif action == "dmute":
                result_text = f"<b>Muted: {target_name} for {format_duration(minutes)}. (Message deleted)</b>"
            else:
                result_text = f"<b>Muted: {target_name} for {format_duration(minutes)}.</b>"
        else:
            if action in {"promote", "setadmin"}:
                # Match the selected ON permissions from the requested
                # Telegram admin-rights screen. Explicit flags also make
                # re-promoting an existing admin update their rights.
                await bot.promote_chat_member(
                    message.chat.id,
                    target_id,
                    is_anonymous=False,
                    can_manage_chat=False,
                    can_delete_messages=True,
                    can_manage_video_chats=False,
                    can_restrict_members=True,
                    can_promote_members=False,
                    can_change_info=False,
                    can_invite_users=True,
                    can_post_stories=True,
                    can_edit_stories=True,
                    can_delete_stories=True,
                    can_post_messages=False,
                    can_edit_messages=False,
                    can_pin_messages=True,
                    can_manage_topics=False,
                    can_manage_direct_messages=False,
                    can_manage_tags=True,
                )
            else:
                await bot.promote_chat_member(
                    message.chat.id,
                    target_id,
                    is_anonymous=False,
                    can_manage_chat=False,
                    can_delete_messages=False,
                    can_manage_video_chats=False,
                    can_restrict_members=False,
                    can_promote_members=False,
                    can_change_info=False,
                    can_invite_users=False,
                    can_post_stories=False,
                    can_edit_stories=False,
                    can_delete_stories=False,
                    can_post_messages=False,
                    can_edit_messages=False,
                    can_pin_messages=False,
                    can_manage_topics=False,
                    can_manage_direct_messages=False,
                    can_manage_tags=False,
                )
        if action == "promote":
            try:
                await message.reply(f"<b>Promoted: {target_name}</b>")
            except TelegramBadRequest:
                await message.answer(f"<b>Promoted: {target_name}</b>")
        elif action == "demote":
            try:
                await message.reply(f"<b>Demoted: {target_name}</b>")
            except TelegramBadRequest:
                await message.answer(f"<b>Demoted: {target_name}</b>")
        else:
            try:
                await message.reply(result_text)
            except TelegramBadRequest:
                await message.answer(result_text)
        await group_log(
            message.chat.id,
            message.from_user.id,
            action,
            target_id,
            " ".join(args),
        )


def arcade_normalize_answer(value: str) -> str:
    normalized = re.sub(r"\s+", " ", value.casefold().strip())
    normalized = re.sub(r"^[^\w]+", "", normalized)
    return normalized.strip()


def arcade_answer_choice(
    game: str, options: list[object], raw_answer: str
) -> int | None:
    answer = arcade_normalize_answer(raw_answer)
    if not answer:
        return None
    aliases = {
        "higher": {"higher", "high", "up", "above"},
        "lower": {"lower", "low", "down", "below"},
        "equal": {"equal", "same", "tie", "draw"},
    }
    if game == "highlow":
        for index, option in enumerate(options):
            label = arcade_normalize_answer(str(option))
            for key, values in aliases.items():
                if key in label and answer in values:
                    return index
    for index, option in enumerate(options):
        label = arcade_normalize_answer(str(option))
        if answer == label:
            return index
    return None


@router.message(F.chat.type.in_({ChatType.GROUP, ChatType.SUPERGROUP}), F.text)
async def arcade_text_answer(message: Message) -> None:
    if not message.from_user or message.from_user.is_bot:
        return
    raw_answer = (message.text or "").strip()
    if not raw_answer:
        return
    if raw_answer.startswith("/"):
        command_name = raw_answer.split(maxsplit=1)[0].split("@", 1)[0].casefold()
        if command_name == "/codebreaker":
            raise SkipHandler
        return
    emoji_handled = await handle_emoji_rush_guess(message)
    if emoji_handled is not None:
        return
    chat_id = message.chat.id
    user_id = message.from_user.id
    async with arcade_locks[chat_id]:
        session = arcade_sessions.get(chat_id)
        if not session or session["state"] != "round":
            raise SkipHandler
        if user_id in session["answers"]:
            await message.reply("Your answer for this round is already recorded.")
            return
        if session["game"] == "tbattle":
            # Manual typed answer, like Math Battle. Punctuation (commas,
            # full stops), extra spaces and letter case are ignored, so a
            # missed comma never costs a correct translation.
            _norm = lambda t: " ".join(re.sub(r"[^a-z0-9' ]", " ", t.casefold()).split())
            _given = _norm(raw_answer)
            if not _given or len(_given) < 2 or not re.search(r"[a-z]", _given):
                raise SkipHandler
            _expected = _norm(str(session["current"]["answer"]))
            choice = 0 if _given == _expected else -1
        elif session["game"] == "mathbattle":
            if not re.fullmatch(r"-?\d[\d,]*", raw_answer):
                raise SkipHandler
            answer_value = int(raw_answer.replace(",", ""))
            choice = 0 if answer_value == int(session["current"]["answer"]) else -1
        else:
            choice = arcade_answer_choice(
                str(session["game"]),
                list(session["current"]["options"]),
                raw_answer,
            )
            if choice is None:
                raise SkipHandler
        if not arcade_register_player(session, message.from_user, chat_id):
            await message.answer(
                "This game is full, or you are already playing a game in another group."
            )
            return
        session["answers"][user_id] = {
            "choice": choice,
            "value": (
                int(raw_answer.replace(",", ""))
                if session["game"] == "mathbattle"
                else None
            ),
            "elapsed": time.monotonic() - float(session["round_started"]),
        }
    # The round always stays open for its full timer. Players are discovered
    # from valid answers, so the first answer must not end the round early.


def validate_daily_zone_template_file(path: Path) -> tuple[int, int]:
    with Image.open(path) as image:
        width, height = image.size
        if width < 256 or height < 256:
            raise ValueError("Template image must be at least 256×256 pixels.")
        image.convert("RGBA").save(path, format="PNG")
    return width, height


def validate_music_template_file(path: Path) -> tuple[int, int]:
    with Image.open(path) as image:
        width, height = image.size
        if width < 256 or height < 256:
            raise ValueError("Music template image must be at least 256×256 pixels.")
        if width / max(1, height) < 1.25:
            raise ValueError("Music template must be a landscape image.")
        image.convert("RGBA").save(path, format="PNG")
    return width, height


async def save_daily_zone_template_upload(message: Message) -> tuple[int, int]:
    media = media_from_message(message)
    if not media or media[0] not in {"photo", "document"}:
        raise ValueError("Send a photo or an image document for the template.")
    telegram_file = await bot.get_file(media[1])
    DAILY_ZONE_CUSTOM_TEMPLATE_PATH.parent.mkdir(parents=True, exist_ok=True)
    temp_handle, temp_name = tempfile.mkstemp(
        dir=str(DAILY_ZONE_CUSTOM_TEMPLATE_PATH.parent),
        prefix="seyuki-daily-zone-template-upload-",
        suffix=".png",
    )
    os.close(temp_handle)
    temp_path = Path(temp_name)
    try:
        with temp_path.open("wb") as target:
            await bot.download_file(telegram_file.file_path, target)
        size = await asyncio.to_thread(validate_daily_zone_template_file, temp_path)
        temp_path.replace(DAILY_ZONE_CUSTOM_TEMPLATE_PATH)
        await set_runtime_setting(
            "daily_zone_template_path",
            str(DAILY_ZONE_CUSTOM_TEMPLATE_PATH),
        )
        return size
    finally:
        temp_path.unlink(missing_ok=True)


async def save_music_template_upload(message: Message) -> tuple[int, int]:
    media = media_from_message(message)
    if not media or media[0] not in {"photo", "document"}:
        raise ValueError("Send a photo or an image document for the music template.")
    telegram_file = await bot.get_file(media[1])
    MUSIC_CUSTOM_TEMPLATE_PATH.parent.mkdir(parents=True, exist_ok=True)
    temp_handle, temp_name = tempfile.mkstemp(
        dir=str(MUSIC_CUSTOM_TEMPLATE_PATH.parent),
        prefix="seyuki-music-template-upload-",
        suffix=".png",
    )
    os.close(temp_handle)
    temp_path = Path(temp_name)
    try:
        with temp_path.open("wb") as target:
            await bot.download_file(telegram_file.file_path, target)
        size = await asyncio.to_thread(validate_music_template_file, temp_path)
        temp_path.replace(MUSIC_CUSTOM_TEMPLATE_PATH)
        await set_runtime_setting(
            "music_template_path",
            str(MUSIC_CUSTOM_TEMPLATE_PATH),
        )
        await clear_music_title_card_cache()
        return size
    finally:
        temp_path.unlink(missing_ok=True)


@router.message()
async def message_handler(message: Message) -> None:
    global API_KEY, runtime_router_key_source
    global TELEGRAM_API_ID, TELEGRAM_API_HASH, runtime_telegram_credentials_source
    global MONGO_URL, MONGO_PASSWORD, SHRUTI_API_KEY
    if await should_preserve_linked_channel_message(message):
        return
    if not message.from_user or message.from_user.is_bot:
        return

    if message.chat.type == ChatType.PRIVATE and message.text and not message.text.startswith("/"):
        txt_raw = message.text.strip()
        is_code_pattern = bool(re.fullmatch(r"GIFT-[A-Z0-9]+", txt_raw, re.IGNORECASE))
        is_waiting = (message.from_user.id in user_waiting_surprise_code)
        if is_code_pattern or is_waiting:
            claimed = await try_claim_surprise_gift_by_code(message, txt_raw)
            if claimed:
                user_waiting_surprise_code.pop(message.from_user.id, None)
                return

    if message.from_user.id in admin_media_waiting:
        if (
            message.chat.type != ChatType.PRIVATE
            or message.chat.id != message.from_user.id
            or message.from_user.id not in ADMIN_IDS
        ):
            return
        media_mode, expires_at = admin_media_waiting.pop(message.from_user.id)
        if time.monotonic() >= expires_at:
            await message.answer(
                "The admin media session expired. Start again from the Admin Panel.",
                reply_markup=admin_menu(),
            )
            return
        if message.text and message.text.strip().casefold() == "/cancel":
            await message.answer("Media editing cancelled.", reply_markup=admin_menu())
            return
        media = media_from_message(message)
        if not media:
            admin_media_waiting[message.from_user.id] = (
                media_mode,
                time.monotonic() + ADMIN_INPUT_TTL_SECONDS,
            )
            await message.answer(
                "Please send a photo, GIF, sticker, video, document, audio, "
                "voice note, or video note."
            )
            return
        if media_mode == "daily_zone_template":
            if media[0] not in {"photo", "document"}:
                admin_media_waiting[message.from_user.id] = (
                    media_mode,
                    time.monotonic() + ADMIN_INPUT_TTL_SECONDS,
                )
                await message.answer(
                    "Template must be a photo or an image document. "
                    "Send the template image or use /cancel."
                )
                return
            try:
                width, height = await save_daily_zone_template_upload(message)
            except (OSError, ValueError, TelegramBadRequest):
                log.exception("Daily Zone template upload failed")
                await message.answer(
                    "That template could not be saved. Send a valid image "
                    "at least 256×256 pixels, then try again."
                )
                admin_media_waiting[message.from_user.id] = (
                    media_mode,
                    time.monotonic() + ADMIN_INPUT_TTL_SECONDS,
                )
                return
            await message.answer(
                f"Daily Zone template saved ({width}×{height}). "
                "This is now the only active template.",
                reply_markup=daily_zone_panel_markup(),
            )
            return
        if media_mode == "music_template":
            if media[0] not in {"photo", "document"}:
                admin_media_waiting[message.from_user.id] = (
                    media_mode,
                    time.monotonic() + ADMIN_INPUT_TTL_SECONDS,
                )
                await message.answer(
                    "Music template must be a photo or an image document. "
                    "Send the template image or use /cancel."
                )
                return
            try:
                width, height = await save_music_template_upload(message)
            except (OSError, ValueError, TelegramBadRequest):
                log.exception("Music title-card template upload failed")
                await message.answer(
                    "That music template could not be saved. Send a valid "
                    "landscape image at least 256×256 pixels, then try again."
                )
                admin_media_waiting[message.from_user.id] = (
                    media_mode,
                    time.monotonic() + ADMIN_INPUT_TTL_SECONDS,
                )
                return
            await message.answer(
                f"Music title-card template saved ({width}×{height}). "
                "New music cards will use it immediately.",
                reply_markup=daily_zone_panel_markup(),
            )
            return
        if media_mode.startswith("global_command_media_"):
            command_name = media_mode.rsplit(":", 1)[1]
            commands = parse_custom_commands(
                runtime_settings.get("global_custom_commands", "{}")
            )
            commands[command_name] = {"type": media[0], "id": media[1]}
            await set_runtime_setting(
                "global_custom_commands",
                json.dumps(commands, ensure_ascii=False),
            )
            await message.answer(
                f"Global command <code>/{command_name}</code> saved with "
                f"{custom_media_label(media[0])}.",
                reply_markup=admin_menu(),
            )
            return
    if message.from_user.id in admin_runtime_waiting:
        if (
            message.chat.type != ChatType.PRIVATE
            or message.chat.id != message.from_user.id
            or message.from_user.id not in ADMIN_IDS
        ):
            return
        key, expires_at = admin_runtime_waiting.pop(message.from_user.id)
        if time.monotonic() >= expires_at:
            await message.answer(
                "The admin input session expired. Start editing again from the Admin Panel.",
                reply_markup=admin_menu(),
            )
            return

        if key == "trainer_add_ids":
            val = (message.text or "").strip()
            raw_tokens = re.split(r"[\s,;]+", val)
            user_ids_to_add: list[int] = []
            not_found = []

            # Check forwarded user
            if message.forward_from and not message.forward_from.is_bot:
                user_ids_to_add.append(message.forward_from.id)

            for token in raw_tokens:
                token = token.strip()
                if not token:
                    continue
                if token.isdigit():
                    user_ids_to_add.append(int(token))
                elif token.startswith("@") or token.isalnum():
                    uname = token.lstrip("@").strip()
                    cached_id = username_to_user_id.get(uname.casefold())
                    if cached_id:
                        user_ids_to_add.append(cached_id)
                        continue
                    rows = await db.execute_fetchall("SELECT user_id FROM users WHERE LOWER(username) = LOWER(?)", (uname,))
                    if rows:
                        user_ids_to_add.append(int(rows[0]["user_id"]))
                        continue
                    gm_rows = await db.execute_fetchall("SELECT user_id FROM group_members WHERE LOWER(username) = LOWER(?)", (uname,))
                    if gm_rows:
                        user_ids_to_add.append(int(gm_rows[0]["user_id"]))
                        continue
                    try:
                        chat_obj = await bot.get_chat(f"@{uname}")
                        if chat_obj and chat_obj.id:
                            user_ids_to_add.append(int(chat_obj.id))
                            continue
                    except Exception:
                        pass
                    not_found.append(token)
            if not user_ids_to_add and not_found:
                admin_runtime_waiting[message.from_user.id] = (key, time.monotonic() + ADMIN_INPUT_TTL_SECONDS)
                await message.answer(f"⚠️ Could not find user(s): {', '.join(not_found)}. Please send numeric Telegram User IDs.")
                return
            if not user_ids_to_add:
                admin_runtime_waiting[message.from_user.id] = (key, time.monotonic() + ADMIN_INPUT_TTL_SECONDS)
                await message.answer("⚠️ No valid User IDs found. Please send numeric Telegram User IDs (e.g. <code>8335116442, 7174267419</code>).")
                return

            added_count = await add_ai_trainers_batch(user_ids_to_add, added_by=message.from_user.id)
            report = f"✅ <b>Successfully authorized {added_count} AI Trainer(s)!</b>\n"
            if not_found:
                report += f"⚠️ <i>Not found in DB: {', '.join(not_found)}</i>\n"
            txt, kb = await ai_trainer_admin_markup(message.from_user.id)
            await message.answer(report + "\n" + txt, reply_markup=kb)
            return

        if key == "surprise_target_user":
            val = (message.text or "").strip()
            if val.startswith("@"):
                uname = val.lstrip("@").strip()
                rows = await db.execute_fetchall("SELECT user_id, username FROM users WHERE LOWER(username) = LOWER(?)", (uname,))
                row = rows[0] if rows else None
                if row:
                    uid_val = int(row["user_id"])
                    draft = get_surprise_draft(message.from_user.id)
                    draft["target_user_id"] = uid_val
                    draft["target_username"] = str(row["username"] or uname)
                    txt, kb = await surprise_gift_admin_markup(message.from_user.id)
                    await message.answer(f"✅ Target User set to <b>@{draft['target_username']}</b> (ID: <code>{uid_val}</code>)!\n\n" + txt, reply_markup=kb)
                    return
                else:
                    admin_runtime_waiting[message.from_user.id] = (key, time.monotonic() + ADMIN_INPUT_TTL_SECONDS)
                    await message.answer(f"⚠️ User @{uname} not found in database. Please send numeric Telegram User ID directly (e.g. <code>8335116442</code>).")
                    return
            elif re.fullmatch(r"\d{5,15}", val):
                uid_val = int(val)
                draft = get_surprise_draft(message.from_user.id)
                draft["target_user_id"] = uid_val
