if __name__ == "__main__":
    if sys.platform == "win32":
        asyncio.set_event_loop_policy(asyncio.WindowsSelectorEventLoopPolicy())
        import subprocess as _sp
        class _WindowsAsyncProcess:
            def __init__(self, proc: _sp.Popen):
                self._proc = proc
                self.pid = proc.pid
                self.stdin = proc.stdin
                self.stdout = proc.stdout
                self.stderr = proc.stderr
            @property
            def returncode(self):
                return self._proc.returncode
            async def communicate(self, input=None):
                loop = asyncio.get_running_loop()
                return await loop.run_in_executor(None, self._proc.communicate, input)
            async def wait(self):
                loop = asyncio.get_running_loop()
                return await loop.run_in_executor(None, self._proc.wait)
            def kill(self):
                try:
                    self._proc.kill()
                except Exception:
                    pass
            def terminate(self):
                try:
                    self._proc.terminate()
                except Exception:
                    pass
            def send_signal(self, sig):
                try:
                    self._proc.send_signal(sig)
                except Exception:
                    pass
            def poll(self):
                return self._proc.poll()

        async def _win_create_subprocess_exec(*args, **kwargs):
            loop = asyncio.get_running_loop()
            proc = await loop.run_in_executor(None, lambda: _sp.Popen(args, **kwargs))
            return _WindowsAsyncProcess(proc)

        async def _win_create_subprocess_shell(cmd, **kwargs):
            loop = asyncio.get_running_loop()
            proc = await loop.run_in_executor(None, lambda: _sp.Popen(cmd, shell=True, **kwargs))
            return _WindowsAsyncProcess(proc)

        asyncio.create_subprocess_exec = _win_create_subprocess_exec
        asyncio.create_subprocess_shell = _win_create_subprocess_shell
        if hasattr(asyncio, "subprocess"):
            asyncio.subprocess.create_subprocess_exec = _win_create_subprocess_exec
            asyncio.subprocess.create_subprocess_shell = _win_create_subprocess_shell
    asyncio.run(main())
